a3i l\\u00e0 m\\u1ed9t"}, {"index": 9, "start": 35.96, "end": 38.12, "text": "ng\\u01b0\\u1eddi ch\\u01a1i c\\u1edd gi\\u1ecfi."}, {"index": 10, "start": 38.12, "end": 42.88, "text": "Nh\\u1eefng g\\u00ec \\u00f4ng l\\u00e0m l\\u00e0 l\\u1eadp tr\\u00ecnh m\\u00e1y t\\u00ednh ch\\u01a1i c\\u00f3 th\\u1ec3 h\\u00e0ng ch\\u1ee5c ngh\\u00ecn v\\u00e1n c\\u1edd"}, {"index": 11, "start": 42.88, "end": 44.32, "text": "ch\\u1ed1ng l\\u1ea1i ch\\u00ednh m\\u00ecnh."}, {"index": 12, "start": 44.32, "end": 48.76, "text": "V\\u00e0 b\\u1eb1ng c\\u00e1ch theo d\\u00f5i c\\u00e1c v\\u1ecb tr\\u00ed b\\u00e0n c\\u1edd n\\u00e0o th\\u01b0\\u1eddng d\\u1eabn \\u0111\\u1ebfn chi\\u1ebfn th\\u1eafng, v\\u00e0 v\\u1ecb tr\\u00ed n\\u00e0o"}, {"index": 13, "start": 48.76, "end": 54.04, "text": "th\\u01b0\\u1eddng d\\u1eabn \\u0111\\u1ebfn th\\u1ea5t b\\u1ea1i, ch\\u01b0\\u01a1ng tr\\u00ecnh ch\\u01a1i c\\u1edd \\u0111\\u00e3 h\\u1ecdc theo th\\u1eddi gian nh\\u1eefng v\\u1ecb tr\\u00ed n\\u00e0o l\\u00e0 t\\u1ed1t"}, {"index": 14, "start": 54.04, "end": 56.08, "text": "hay x\\u1ea5u."}, {"index": 15, "start": 56.08, "end": 61.96, "text": "B\\u1eb1ng c\\u00e1ch c\\u1ed1 g\\u1eafng \\u0111\\u1ea1t \\u0111\\u01b0\\u1ee3c nh\\u1eefng v\\u1ecb tr\\u00ed t\\u1ed1t v\\u00e0 tr\\u00e1nh nh\\u1eefng v\\u1ecb tr\\u00ed x\\u1ea5u, ch\\u01b0\\u01a1ng tr\\u00ecnh c\\u1ee7a \\u00f4ng \\u0111\\u00e3 h\\u1ecdc \\u0111\\u1ec3 tr\\u1edf n\\u00ean ng\\u00e0y c\\u00e0ng"}, {"index": 16, "start": 61.96, "end": 64.02, "text": "gi\\u1ecfi h\\u01a1n trong vi\\u1ec7c ch\\u01a1i c\\u1edd."}, {"index": 17, "start": 64.02, "end": 68.0, "text": "V\\u00ec m\\u00e1y t\\u00ednh c\\u00f3 s\\u1ef1 ki\\u00ean nh\\u1eabn \\u0111\\u1ec3 ch\\u01a1i h\\u00e0ng ch\\u1ee5c ngh\\u00ecn v\\u00e1n c\\u1edd ch\\u1ed1ng l\\u1ea1i ch\\u00ednh n\\u00f3,"}, {"index": 18, "start": 68.0, "end": 73.8, "text": "n\\u00f3 \\u0111\\u00e3 t\\u00edch l\\u0169y \\u0111\\u01b0\\u1ee3c r\\u1ea5t nhi\\u1ec1u kinh nghi\\u1ec7m ch\\u01a1i c\\u1edd \\u0111\\u1ebfn m\\u1ee9c cu\\u1ed1i c\\u00f9ng n\\u00f3 tr\\u1edf th\\u00e0nh m\\u1ed9t ng\\u01b0\\u1eddi ch\\u01a1i c\\u1edd gi\\u1ecfi h\\u01a1n"}, {"index": 19, "start": 73.8, "end": 77.16, "text": "h\\u01a1n c\\u1ea3 Arthur Samuel."}, {"index": 20, "start": 77.16, "end": 82.28, "text": "B\\u00e2y gi\\u1edd, trong su\\u1ed1t nh\\u1eefng video n\\u00e0y, b\\u00ean c\\u1ea1nh vi\\u1ec7c t\\u00f4i c\\u1ed1 g\\u1eafng n\\u00f3i v\\u1ec1 nh\\u1eefng \\u0111i\\u1ec1u, th\\u1ec9nh tho\\u1ea3ng t\\u00f4i s\\u1ebd"}, {"index": 21, "start": 82.32, "end": 86.6, "text": "h\\u1ecfi b\\u1ea1n m\\u1ed9t c\\u00e2u \\u0111\\u1ec3 gi\\u00fap \\u0111\\u1ea3m b\\u1ea3o r\\u1eb1ng b\\u1ea1n hi\\u1ec3u n\\u1ed9i dung."}, {"index": 22, "start": 86.6, "end": 91.44, "text": "\\u0110\\u00e2y l\\u00e0 c\\u00e2u h\\u1ecfi v\\u1ec1 vi\\u1ec7c \\u0111i\\u1ec1u g\\u00ec s\\u1ebd x\\u1ea3y ra n\\u1ebfu m\\u00e1y t\\u00ednh ch\\u01a1i \\u00edt tr\\u00f2 ch\\u01a1i h\\u01a1n r\\u1ea5t nhi\\u1ec1u."}, {"index": 23, "start": 91.44, "end": 94.84, "text": "Xin h\\u00e3y xem qua v\\u00e0 ch\\u1ecdn c\\u00e2u tr\\u1ea3 l\\u1eddi n\\u00e0o m\\u00e0 b\\u1ea1n ngh\\u0129 l\\u00e0 t\\u1ed1t h\\u01a1n."}, {"index": 24, "start": 98.72, "end": 100.68, "text": "C\\u1ea3m \\u01a1n b\\u1ea1n \\u0111\\u00e3 xem qua b\\u00e0i ki\\u1ec3m tra."}, {"index": 25, "start": 100.68, "end": 108.88, "text": "V\\u00e0 n\\u1ebfu b\\u1ea1n \\u0111\\u00e3 ch\\u1ecdn c\\u00e2u tr\\u1ea3 l\\u1eddi n\\u00e0y, cho d\\u00f9 n\\u00f3 c\\u00f3 l\\u00e0m m\\u1ecdi th\\u1ee9 t\\u1ec7 h\\u01a1n hay kh\\u00f4ng, th\\u00ec b\\u1ea1n \\u0111\\u00e3 \\u0111\\u00fang."}, {"index": 26, "start": 108.88, "end": 112.96, "text": "N\\u00f3i chung, c\\u00e0ng c\\u00f3 nhi\\u1ec1u c\\u01a1 h\\u1ed9i \\u0111\\u1ec3 m\\u1ed9t thu\\u1eadt to\\u00e1n h\\u1ecdc t\\u1eadp h\\u1ecdc h\\u1ecfi,"}, {"index": 27, "start": 112.96, "end": 114.92, "text": "n\\u00f3 s\\u1ebd ho\\u1ea1t \\u0111\\u1ed9ng t\\u1ed1t h\\u01a1n."}, {"index": 28, "start": 114.92, "end": 119.48, "text": "N\\u1ebfu b\\u1ea1n kh\\u00f4ng ch\\u1ecdn c\\u00e2u tr\\u1ea3 l\\u1eddi \\u0111\\u00fang l\\u1ea7n \\u0111\\u1ea7u ti\\u00ean, c\\u0169ng kh\\u00f4ng sao c\\u1ea3."}, {"index": 29, "start": 119.48, "end": 123.08, "text": "M\\u1ee5c ti\\u00eau c\\u1ee7a nh\\u1eefng c\\u00e2u h\\u1ecfi ki\\u1ec3m tra n\\u00e0y kh\\u00f4ng ph\\u1ea3i l\\u00e0 xem li\\u1ec7u b\\u1ea1n c\\u00f3 th\\u1ec3 l\\u00e0m \\u0111\\u00fang t\\u1ea5t c\\u1ea3 hay kh\\u00f4ng"}, {"index": 30, "start": 123.08, "end": 124.76, "text": "\\u0111\\u00fang ngay t\\u1eeb l\\u1ea7n \\u0111\\u1ea7u ti\\u00ean."}, {"index": 31, "start": 124.76, "end": 129.32, "text": "Nh\\u1eefng c\\u00e2u h\\u1ecfi n\\u00e0y ch\\u1ec9 \\u0111\\u1ec3 gi\\u00fap b\\u1ea1n th\\u1ef1c h\\u00e0nh c\\u00e1c kh\\u00e1i ni\\u1ec7m m\\u00e0 b\\u1ea1n \\u0111ang h\\u1ecdc."}, {"index": 32, "start": 129.32, "end": 133.56, "text": "\\u0110\\u1ecbnh ngh\\u0129a c\\u1ee7a Arthur Samuel l\\u00e0 kh\\u00e1 kh\\u00f4ng ch\\u00ednh th\\u1ee9c, nh\\u01b0ng trong hai"}, {"index": 33, "start": 133.56, "end": 138.0, "text": "video ti\\u1ebfp theo, ch\\u00fang ta s\\u1ebd kh\\u00e1m ph\\u00e1 s\\u00e2u h\\u01a1n v\\u1ec1 c\\u00e1c lo\\u1ea1i m\\u00e1y"}, {"index": 34, "start": 138.04, "end": 141.04, "text": "h\\u1ecdc thu\\u1eadt."}, {"index": 35, "start": 141.04, "end": 145.04, "text": "Trong l\\u1edbp h\\u1ecdc n\\u00e0y, b\\u1ea1n s\\u1ebd t\\u00ecm hi\\u1ec3u v\\u1ec1 nhi\\u1ec1u thu\\u1eadt to\\u00e1n h\\u1ecdc kh\\u00e1c nhau."}, {"index": 36, "start": 145.04, "end": 150.6, "text": "Hai lo\\u1ea1i ch\\u00ednh c\\u1ee7a h\\u1ecdc m\\u00e1y l\\u00e0 h\\u1ecdc c\\u00f3 gi\\u00e1m s\\u00e1t v\\u00e0 kh\\u00f4ng c\\u00f3 gi\\u00e1m s\\u00e1t."}, {"index": 37, "start": 150.6, "end": 151.64, "text": "h\\u1ecdc."}, {"index": 38, "start": 151.64, "end": 156.64, "text": "Ch\\u00fang ta s\\u1ebd \\u0111\\u1ecbnh ngh\\u0129a nh\\u1eefng thu\\u1eadt ng\\u1eef n\\u00e0y c\\u00f3 ngh\\u0129a l\\u00e0 g\\u00ec trong v\\u00e0i video ti\\u1ebfp theo."}, {"index": 39, "start": 156.64, "end": 161.48, "text": "Trong hai lo\\u1ea1i n\\u00e0y, h\\u1ecdc c\\u00f3 gi\\u00e1m s\\u00e1t l\\u00e0 lo\\u1ea1i h\\u1ecdc m\\u00e1y \\u0111\\u01b0\\u1ee3c s\\u1eed d\\u1ee5ng"}, {"index": 40, "start": 161.48, "end": 166.88, "text": "h\\u1ea7u h\\u1ebft trong nhi\\u1ec1u \\u1ee9ng d\\u1ee5ng th\\u1ef1c t\\u1ebf v\\u00e0 \\u0111\\u00e3 ch\\u1ee9ng ki\\u1ebfn s\\u1ef1 ph\\u00e1t tri\\u1ec3n nhanh nh\\u1ea5t"}, {"index": 41, "start": 166.88, "end": 169.12, "text": "v\\u00e0 \\u0111\\u1ed5i m\\u1edbi."}, {"index": 42, "start": 169.12, "end": 174.32, "text": "Trong chuy\\u00ean ng\\u00e0nh n\\u00e0y, c\\u00f3 t\\u1ed5ng c\\u1ed9ng ba nguy\\u00ean nh\\u00e2n, nguy\\u00ean nh\\u00e2n th\\u1ee9 nh\\u1ea5t v\\u00e0 th\\u1ee9 hai"}, {"index": 43, "start": 174.32, "end": 179.24, "text": "s\\u1ebd t\\u1eadp trung v\\u00e0o h\\u1ecdc c\\u00f3 gi\\u00e1m s\\u00e1t v\\u00e0 nguy\\u00ean nh\\u00e2n th\\u1ee9 ba s\\u1ebd t\\u1eadp trung v\\u00e0o h\\u1ecdc kh\\u00f4ng gi\\u00e1m s\\u00e1t"}, {"index": 44, "start": 179.24, "end": 183.44, "text": "h\\u1ecdc, h\\u1ec7 th\\u1ed1ng g\\u1ee3i \\u00fd v\\u00e0 h\\u1ecdc t\\u0103ng c\\u01b0\\u1eddng."}, {"index": 45, "start": 183.44, "end": 188.04, "text": "Cho \\u0111\\u1ebfn nay, c\\u00e1c lo\\u1ea1i thu\\u1eadt to\\u00e1n h\\u1ecdc \\u0111\\u01b0\\u1ee3c s\\u1eed d\\u1ee5ng nhi\\u1ec1u nh\\u1ea5t hi\\u1ec7n nay l\\u00e0 h\\u1ecdc c\\u00f3 gi\\u00e1m s\\u00e1t"}, {"index": 46, "start": 188.04, "end": 192.36, "text": "h\\u1ecdc kh\\u00f4ng gi\\u00e1m s\\u00e1t v\\u00e0 h\\u1ec7 th\\u1ed1ng g\\u1ee3i \\u00fd."}, {"index": 47, "start": 192.36, "end": 195.92, "text": "\\u0110i\\u1ec1u kh\\u00e1c m\\u00e0 ch\\u00fang ta s\\u1ebd d\\u00e0nh nhi\\u1ec1u th\\u1eddi gian trong chuy\\u00ean ng\\u00e0nh n\\u00e0y"}, {"index": 48, "start": 195.92, "end": 200.44, "text": "l\\u00e0 nh\\u1eefng l\\u1eddi khuy\\u00ean th\\u1ef1c ti\\u1ec5n v\\u1ec1 vi\\u1ec7c \\u00e1p d\\u1ee5ng c\\u00e1c thu\\u1eadt to\\u00e1n h\\u1ecdc."}, {"index": 49, "start": 200.44, "end": 202.88, "text": "\\u0110\\u00e2y l\\u00e0 \\u0111i\\u1ec1u m\\u00e0 t\\u00f4i c\\u1ea3m th\\u1ea5y r\\u1ea5t m\\u1ea1nh m\\u1ebd."}, {"index": 50, "start": 202.88, "end": 207.64, "text": "D\\u1ea1y v\\u1ec1 c\\u00e1c thu\\u1eadt to\\u00e1n h\\u1ecdc gi\\u1ed1ng nh\\u01b0 vi\\u1ec7c \\u0111\\u01b0a cho ai \\u0111\\u00f3 m\\u1ed9t b\\u1ed9 c\\u00f4ng c\\u1ee5"}, {"index": 51, "start": 207.64, "end": 212.12, "text": "v\\u00e0 \\u0111i\\u1ec1u n\\u00e0y quan tr\\u1ecdng kh\\u00f4ng k\\u00e9m ho\\u1eb7c th\\u1eadm ch\\u00ed c\\u00f2n quan tr\\u1ecdng h\\u01a1n l\\u00e0 \\u0111\\u1ea3m b\\u1ea3o b\\u1ea1n c\\u00f3"}, {"index": 52, "start": 212.12, "end": 216.24, "text": "nh\\u1eefng c\\u00f4ng c\\u1ee5 tuy\\u1ec7t v\\u1eddi nh\\u01b0ng c\\u00f2n quan tr\\u1ecdng h\\u01a1n l\\u00e0 b\\u1ea1n bi\\u1ebft c\\u00e1ch \\u00e1p d\\u1ee5ng ch\\u00fang."}, {"index": 53, "start": 216.24, "end": 219.84, "text": "B\\u1edfi v\\u00ec, b\\u1ea1n bi\\u1ebft \\u0111\\u1ea5y, c\\u00e1i g\\u00ec s\\u1ebd t\\u1ed1t n\\u1ebfu ai \\u0111\\u00f3 trao cho b\\u1ea1n m\\u1ed9t"}, {"index": 54, "start": 219.84, "end": 223.56, "text": "chi\\u1ebfc b\\u00faa t\\u1ed1i t\\u00e2n ho\\u1eb7c m\\u1ed9t c\\u00e1i khoan c\\u1ea7m tay t\\u1ed1i t\\u00e2n v\\u00e0 n\\u00f3i,"}, {"index": 55, "start": 223.56, "end": 227.4, "text": "ch\\u00fac may m\\u1eafn, gi\\u1edd th\\u00ec b\\u1ea1n \\u0111\\u00e3 c\\u00f3 t\\u1ea5t c\\u1ea3 c\\u00f4ng c\\u1ee5 c\\u1ea7n thi\\u1ebft \\u0111\\u1ec3 x\\u00e2y d\\u1ef1ng m\\u1ed9t ng\\u00f4i nh\\u00e0 ba t\\u1ea7ng."}, {"index": 56, "start": 227.4, "end": 229.36, "text": "Th\\u1ef1c s\\u1ef1 kh\\u00f4ng ho\\u1ea1t \\u0111\\u1ed9ng nh\\u01b0 v\\u1eady."}, {"index": 57, "start": 229.36, "end": 235.0, "text": "V\\u00e0 c\\u0169ng nh\\u01b0 v\\u1eady trong h\\u1ecdc m\\u00e1y, vi\\u1ec7c \\u0111\\u1ea3m b\\u1ea3o b\\u1ea1n c\\u00f3 c\\u00f4ng c\\u1ee5 l\\u00e0 r\\u1ea5t quan tr\\u1ecdng"}, {"index": 58, "start": 235.0, "end": 239.2, "text": "v\\u00e0 c\\u0169ng quan tr\\u1ecdng kh\\u00f4ng k\\u00e9m l\\u00e0 \\u0111\\u1ea3m b\\u1ea3o r\\u1eb1ng b\\u1ea1n bi\\u1ebft c\\u00e1ch \\u00e1p d\\u1ee5ng c\\u00e1c c\\u00f4ng c\\u1ee5 c\\u1ee7a m\\u00e1y"}, {"index": 59, "start": 239.2, "end": 240.84, "text": "h\\u1ecdc m\\u1ed9t c\\u00e1ch hi\\u1ec7u qu\\u1ea3."}, {"index": 60, "start": 240.84, "end": 244.48, "text": "V\\u1eady n\\u00ean, nh\\u1eefng g\\u00ec b\\u1ea1n nh\\u1eadn \\u0111\\u01b0\\u1ee3c trong l\\u1edbp h\\u1ecdc n\\u00e0y l\\u00e0 c\\u1ea3 c\\u00f4ng c\\u1ee5 l\\u1eabn k\\u1ef9 n\\u0103ng"}, {"index": 61, "start": 244.48, "end": 247.04, "text": "\\u0111\\u1ec3 \\u00e1p d\\u1ee5ng ch\\u00fang m\\u1ed9t c\\u00e1ch hi\\u1ec7u qu\\u1ea3."}, {"index": 62, "start": 247.04, "end": 250.48, "text": "T\\u00f4i th\\u01b0\\u1eddng xuy\\u00ean g\\u1eb7p g\\u1ee1 b\\u1ea1n b\\u00e8 v\\u00e0 c\\u00e1c nh\\u00f3m t\\u1ea1i m\\u1ed9t s\\u1ed1"}, {"index": 63, "start": 250.52, "end": 251.76, "text": "c\\u00f4ng ty c\\u00f4ng ngh\\u1ec7 h\\u00e0ng \\u0111\\u1ea7u."}, {"index": 64, "start": 251.76, "end": 256.44, "text": "V\\u00e0 ngay c\\u1ea3 h\\u00f4m nay, t\\u00f4i th\\u1ea5y c\\u00e1c \\u0111\\u1ed9i ng\\u0169 m\\u00e1y h\\u1ecdc d\\u00e0y d\\u1ea1n kinh nghi\\u1ec7m \\u0111ang \\u00e1p d\\u1ee5ng"}, {"index": 65, "start": 256.44, "end": 258.92, "text": "c\\u00e1c thu\\u1eadt to\\u00e1n m\\u00e1y h\\u1ecdc cho m\\u1ed9t s\\u1ed1 v\\u1ea5n \\u0111\\u1ec1."}, {"index": 66, "start": 258.92, "end": 263.64, "text": "\\u0110\\u00f4i khi h\\u1ecd \\u0111\\u00e3 l\\u00e0m vi\\u1ec7c trong s\\u00e1u th\\u00e1ng m\\u00e0 kh\\u00f4ng \\u0111\\u1ea1t \\u0111\\u01b0\\u1ee3c nhi\\u1ec1u th\\u00e0nh c\\u00f4ng."}, {"index": 67, "start": 263.64, "end": 267.16, "text": "V\\u00e0 khi t\\u00f4i nh\\u00ecn v\\u00e0o nh\\u1eefng g\\u00ec h\\u1ecd \\u0111ang l\\u00e0m, t\\u00f4i \\u0111\\u00f4i khi c\\u1ea3m th\\u1ea5y m\\u00ecnh \\u0111\\u00e3 c\\u00f3 th\\u1ec3"}, {"index": 68, "start": 267.16, "end": 270.36, "text": "n\\u00f3i v\\u1edbi h\\u1ecd t\\u1eeb s\\u00e1u th\\u00e1ng tr\\u01b0\\u1edbc r\\u1eb1ng ph\\u01b0\\u01a1ng ph\\u00e1p hi\\u1ec7n t\\u1ea1i s\\u1ebd kh\\u00f4ng hi\\u1ec7u qu\\u1ea3."}, {"index": 69, "start": 270.36, "end": 273.52, "text": "V\\u00e0 c\\u00f3 m\\u1ed9t c\\u00e1ch kh\\u00e1c \\u0111\\u1ec3 s\\u1eed d\\u1ee5ng nh\\u1eefng c\\u00f4ng c\\u1ee5 n\\u00e0y s\\u1ebd mang l\\u1ea1i"}, {"index": 70, "start": 273.52, "end": 275.84, "text": "cho h\\u1ecd c\\u01a1 h\\u1ed9i th\\u00e0nh c\\u00f4ng t\\u1ed1t h\\u01a1n r\\u1ea5t nhi\\u1ec1u."}, {"index": 71, "start": 275.84, "end": 279.4, "text": "V\\u00ec v\\u1eady, trong l\\u1edbp h\\u1ecdc n\\u00e0y, m\\u1ed9t trong nh\\u1eefng \\u0111i\\u1ec1u t\\u01b0\\u01a1ng \\u0111\\u1ed1i \\u0111\\u1ed9c \\u0111\\u00e1o m\\u00e0 b\\u1ea1n s\\u1ebd h\\u1ecdc"}, {"index": 72, "start": 279.4, "end": 282.92, "text": "l\\u00e0 b\\u1ea1n s\\u1ebd bi\\u1ebft nhi\\u1ec1u v\\u1ec1 nh\\u1eefng th\\u1ef1c h\\u00e0nh t\\u1ed1t nh\\u1ea5t \\u0111\\u1ec3 th\\u1ef1c s\\u1ef1"}, {"index": 73, "start": 282.92, "end": 287.36, "text": "ph\\u00e1t tri\\u1ec3n m\\u1ed9t h\\u1ec7 th\\u1ed1ng m\\u00e1y h\\u1ecdc th\\u1ef1c ti\\u1ec5n v\\u00e0 c\\u00f3 gi\\u00e1 tr\\u1ecb."}, {"index": 74, "start": 287.36, "end": 290.2, "text": "B\\u1eb1ng c\\u00e1ch n\\u00e0y, b\\u1ea1n s\\u1ebd \\u00edt c\\u00f3 kh\\u1ea3 n\\u0103ng r\\u01a1i v\\u00e0o m\\u1ed9t trong nh\\u1eefng \\u0111\\u1ed9i"}, {"index": 75, "start": 290.2, "end": 294.48, "text": "c\\u00f3 kh\\u1ea3 n\\u0103ng d\\u1eabn \\u0111\\u1ebfn vi\\u1ec7c t\\u1ed1n s\\u00e1u th\\u00e1ng \\u0111i sai h\\u01b0\\u1edbng."}, {"index": 76, "start": 294.48, "end": 297.96, "text": "Trong l\\u1edbp h\\u1ecdc n\\u00e0y, b\\u1ea1n s\\u1ebd hi\\u1ec3u c\\u00e1ch m\\u00e0 nh\\u1eefng k\\u1ef9 s\\u01b0 m\\u00e1y h\\u1ecdc t\\u00e0i n\\u0103ng nh\\u1ea5t"}, {"index": 77, "start": 297.96, "end": 299.72, "text": "x\\u00e2y d\\u1ef1ng h\\u1ec7 th\\u1ed1ng."}, {"index": 78, "start": 299.72, "end": 304.04, "text": "V\\u00e0 t\\u00f4i hy v\\u1ecdng b\\u1ea1n s\\u1ebd k\\u1ebft th\\u00fac l\\u1edbp h\\u1ecdc n\\u00e0y nh\\u01b0 m\\u1ed9t trong nh\\u1eefng ng\\u01b0\\u1eddi r\\u1ea5t hi\\u1ebfm hoi"}, {"index": 79, "start": 304.04, "end": 307.8, "text": "trong th\\u1ebf gi\\u1edbi ng\\u00e0y nay bi\\u1ebft c\\u00e1ch thi\\u1ebft k\\u1ebf v\\u00e0 x\\u00e2y d\\u1ef1ng nh\\u1eefng h\\u1ec7 th\\u1ed1ng nghi\\u00eam t\\u00fac"}, {"index": 80, "start": 307.8, "end": 309.68, "text": "c\\u00e1c h\\u1ec7 th\\u1ed1ng h\\u1ecdc m\\u00e1y."}, {"index": 81, "start": 309.68, "end": 311.88, "text": "V\\u1eady l\\u00e0, h\\u1ecdc m\\u00e1y g\\u1ea7n \\u0111\\u00e2y."}, {"index": 82, "start": 311.88, "end": 315.16, "text": "Trong video ti\\u1ebfp theo, h\\u00e3y c\\u00f9ng t\\u00ecm hi\\u1ec3u s\\u00e2u h\\u01a1n v\\u1ec1 vi\\u1ec7c"}, {"index": 83, "start": 315.16, "end": 319.92, "text": "h\\u1ecdc c\\u00f3 gi\\u00e1m s\\u00e1t v\\u00e0 c\\u1ea3 h\\u1ecdc kh\\u00f4ng c\\u00f3 gi\\u00e1m s\\u00e1t."}, {"index": 84, "start": 319.92, "end": 323.56, "text": "Ngo\\u00e0i ra, b\\u1ea1n s\\u1ebd bi\\u1ebft khi n\\u00e0o b\\u1ea1n c\\u00f3 th\\u1ec3 mu\\u1ed1n s\\u1eed d\\u1ee5ng t\\u1eebng lo\\u1ea1i,"}, {"index": 85, "start": 323.56, "end": 326.08, "text": "h\\u1ecdc c\\u00f3 gi\\u00e1m s\\u00e1t v\\u00e0 h\\u1ecdc kh\\u00f4ng c\\u00f3 gi\\u00e1m s\\u00e1t."}, {"index": 86, "start": 326.08, "end": 328.68, "text": "H\\u1eb9n g\\u1eb7p b\\u1ea1n trong video ti\\u1ebfp theo."}], "segments_by_language": {"en": [{"index": 0, "start": 0.0, "end": 2.94, "text": "So, what is machine learning?"}, {"index": 1, "start": 2.94, "end": 7.84, "text": "In this video, you learn the definition of what it is, and also get a sense of when you"}, {"index": 2, "start": 7.84, "end": 9.36, "text": "might want to apply it."}, {"index": 3, "start": 9.36, "end": 10.84, "text": "Let's take a look together."}, {"index": 4, "start": 10.84, "end": 17.36, "text": "Here's a definition of what is machine learning that is attributed to Arthur Samuel."}, {"index": 5, "start": 17.36, "end": 22.2, "text": "He defined machine learning as the few studies that gives computers people to learn"}, {"index": 6, "start": 22.2, "end": 25.04, "text": "without being explicitly programmed."}, {"index": 7, "start": 25.04, "end": 30.84, "text": "Arthur's claim to fame was that back in the 1950s, he wrote a checkers playing program."}, {"index": 8, "start": 30.84, "end": 35.96, "text": "And the amazing thing about this program was that Arthur Samuel himself wasn't a very good"}, {"index": 9, "start": 35.96, "end": 38.12, "text": "checkers player."}, {"index": 10, "start": 38.12, "end": 42.88, "text": "What he did was, he had programmed the computer to play maybe tens of thousands of games"}, {"index": 11, "start": 42.88, "end": 44.32, "text": "against himself."}, {"index": 12, "start": 44.32, "end": 48.76, "text": "And by watching what sorts of board positions tended to lead to wins, and what positions"}, {"index": 13, "start": 48.76, "end": 54.04, "text": "tended to lead to losses, the checkers playing program learned over time what a good or"}, {"index": 14, "start": 54.04, "end": 56.08, "text": "bad board positions."}, {"index": 15, "start": 56.08, "end": 61.96, "text": "By trying to get to good and avoid bad positions, his program learned to get better and better"}, {"index": 16, "start": 61.96, "end": 64.02, "text": "at playing checkers."}, {"index": 17, "start": 64.02, "end": 68.0, "text": "Because the computer had the patience to play tens of thousands of games against itself,"}, {"index": 18, "start": 68.0, "end": 73.8, "text": "it was able to get so much checkers playing experience that eventually it became a better"}, {"index": 19, "start": 73.8, "end": 77.16, "text": "checkers player than Arthur Samuel himself."}, {"index": 20, "start": 77.16, "end": 82.28, "text": "Now, throughout these videos, besides me trying to talk about stuff, I occasionally"}, {"index": 21, "start": 82.32, "end": 86.6, "text": "ask you a question to help make sure you understand the content."}, {"index": 22, "start": 86.6, "end": 91.44, "text": "Here's the one about what happens if the computer had played far fewer games."}, {"index": 23, "start": 91.44, "end": 94.84, "text": "Please take a look and pick whichever you think is a better answer."}, {"index": 24, "start": 98.72, "end": 100.68, "text": "Thanks for looking at the quiz."}, {"index": 25, "start": 100.68, "end": 108.88, "text": "And so if you had selected this answer, whether it made it worse, then you got it right."}, {"index": 26, "start": 108.88, "end": 112.96, "text": "In general, the more opportunities you give a learning algorithm to learn,"}, {"index": 27, "start": 112.96, "end": 114.92, "text": "the better it will perform."}, {"index": 28, "start": 114.92, "end": 119.48, "text": "If you didn't select the correct answer the first time, that's totally OK too."}, {"index": 29, "start": 119.48, "end": 123.08, "text": "The point of these quiz questions isn't to see if you can get them all"}, {"index": 30, "start": 123.08, "end": 124.76, "text": "correctly in the first try."}, {"index": 31, "start": 124.76, "end": 129.32, "text": "These questions are here just to help you practice the concepts you're learning."}, {"index": 32, "start": 129.32, "end": 133.56, "text": "Arthur Samuel's definition was a rather informal one, but in the next two"}, {"index": 33, "start": 133.56, "end": 138.0, "text": "videos we'll dive deeper together into what are the major types of machine"}, {"index": 34, "start": 138.04, "end": 141.04, "text": "learning algorithms."}, {"index": 35, "start": 141.04, "end": 145.04, "text": "In this class, you learn about many different learning algorithms."}, {"index": 36, "start": 145.04, "end": 150.6, "text": "The two main types of machine learning are supervised learning and unsupervised"}, {"index": 37, "start": 150.6, "end": 151.64, "text": "learning."}, {"index": 38, "start": 151.64, "end": 156.64, "text": "We'll define what these terms mean more in the next couple of videos."}, {"index": 39, "start": 156.64, "end": 161.48, "text": "Of these two, supervised learning is the type of machine learning that is used"}, {"index": 40, "start": 161.48, "end": 166.88, "text": "most in many real-world applications and that has seen the most rapid"}, {"index": 41, "start": 166.88, "end": 169.12, "text": "advancement and innovation."}, {"index": 42, "start": 169.12, "end": 174.32, "text": "In this specialization, which has three causes in total, the first and second"}, {"index": 43, "start": 174.32, "end": 179.24, "text": "causes will focus on supervised learning and the third will focus on unsupervised"}, {"index": 44, "start": 179.24, "end": 183.44, "text": "learning, recommended systems and reinforcement learning."}, {"index": 45, "start": 183.44, "end": 188.04, "text": "By far the most used types of learning algorithms today are supervised"}, {"index": 46, "start": 188.04, "end": 192.36, "text": "learning, unsupervised learning and recommended systems."}, {"index": 47, "start": 192.36, "end": 195.92, "text": "The other thing we're going to spend a lot of time on in this specialization"}, {"index": 48, "start": 195.92, "end": 200.44, "text": "is practical advice for applying learning algorithms."}, {"index": 49, "start": 200.44, "end": 202.88, "text": "This is something I feel pretty strongly about."}, {"index": 50, "start": 202.88, "end": 207.64, "text": "Teaching about learning algorithms is like giving someone a set of tools"}, {"index": 51, "start": 207.64, "end": 212.12, "text": "and equally important or even more important than making sure you have"}, {"index": 52, "start": 212.12, "end": 216.24, "text": "great tools is making sure you know how to apply them."}, {"index": 53, "start": 216.24, "end": 219.84, "text": "Because, you know, what good is it if someone were to give you a"}, {"index": 54, "start": 219.84, "end": 223.56, "text": "state-of-the-art hammer or a state-of-the-art hand drill and say,"}, {"index": 55, "start": 223.56, "end": 227.4, "text": "good luck, now you have all the tools you need to build a three-storey house."}, {"index": 56, "start": 227.4, "end": 229.36, "text": "Doesn't really work like that."}, {"index": 57, "start": 229.36, "end": 235.0, "text": "And so too in machine learning, making sure you have the tools is really important"}, {"index": 58, "start": 235.0, "end": 239.2, "text": "and so is making sure that you know how to apply the tools of machine"}, {"index": 59, "start": 239.2, "end": 240.84, "text": "learning effectively."}, {"index": 60, "start": 240.84, "end": 244.48, "text": "So that's what you get in this class, the tools as well as the skills"}, {"index": 61, "start": 244.48, "end": 247.04, "text": "of applying them effectively."}, {"index": 62, "start": 247.04, "end": 250.48, "text": "I regularly visit with friends and teams in some of the top"}, {"index": 63, "start": 250.52, "end": 251.76, "text": "tech companies."}, {"index": 64, "start": 251.76, "end": 256.44, "text": "And even today, I see experienced machine learning teams apply machine"}, {"index": 65, "start": 256.44, "end": 258.92, "text": "learning algorithms to some problems."}, {"index": 66, "start": 258.92, "end": 263.64, "text": "And sometimes they've been going at it for six months without much success."}, {"index": 67, "start": 263.64, "end": 267.16, "text": "And when I look at what they're doing, I sometimes feel like I could have"}, {"index": 68, "start": 267.16, "end": 270.36, "text": "told them six months ago that the current approach won't work."}, {"index": 69, "start": 270.36, "end": 273.52, "text": "And there's a different way of using these tools that will give"}, {"index": 70, "start": 273.52, "end": 275.84, "text": "them a much better chance of success."}, {"index": 71, "start": 275.84, "end": 279.4, "text": "So in this class, one of the relatively unique things you learn"}, {"index": 72, "start": 279.4, "end": 282.92, "text": "is you learn a lot about the best practices for how to actually"}, {"index": 73, "start": 282.92, "end": 287.36, "text": "develop a practical, valuable machine learning system."}, {"index": 74, "start": 287.36, "end": 290.2, "text": "This way, you're less likely to end up in one of those teams"}, {"index": 75, "start": 290.2, "end": 294.48, "text": "that end up losing six ones going in the wrong direction."}, {"index": 76, "start": 294.48, "end": 297.96, "text": "In this class, you gain a sense of how the most skilled machine"}, {"index": 77, "start": 297.96, "end": 299.72, "text": "learning engineers build systems."}, {"index": 78, "start": 299.72, "end": 304.04, "text": "And I hope you finish this class as one of those very rare people"}, {"index": 79, "start": 304.04, "end": 307.8, "text": "in today's world that know how to design and build serious"}, {"index": 80, "start": 307.8, "end": 309.68, "text": "machine learning systems."}, {"index": 81, "start": 309.68, "end": 311.88, "text": "So last machine learning."}, {"index": 82, "start": 311.88, "end": 315.16, "text": "In the next video, let's look more deeply at what"}, {"index": 83, "start": 315.16, "end": 319.92, "text": "is supervised learning and also what is unsupervised learning."}, {"index": 84, "start": 319.92, "end": 323.56, "text": "In addition, you learn when you might want to use each of them,"}, {"index": 85, "start": 323.56, "end": 326.08, "text": "supervised and unsupervised learning."}, {"index": 86, "start": 326.08, "end": 328.68, "text": "I'll see you in the next video."}], "vi": [{"index": 0, "start": 0.0, "end": 2.94, "text": "V\\u1eady, h\\u1ecdc m\\u00e1y l\\u00e0 g\\u00ec?"}, {"index": 1, "start": 2.94, "end": 7.84, "text": "Trong video n\\u00e0y, b\\u1ea1n s\\u1ebd h\\u1ecdc \\u0111\\u1ecbnh ngh\\u0129a v\\u1ec1 n\\u00f3 v\\u00e0 c\\u0169ng c\\u00f3 th\\u1ec3 c\\u1ea3m nh\\u1eadn khi n\\u00e0o b\\u1ea1n"}, {"index": 2, "start": 7.84, "end": 9.36, "text": "c\\u00f3 th\\u1ec3 mu\\u1ed1n \\u00e1p d\\u1ee5ng n\\u00f3."}, {"index": 3, "start": 9.36, "end": 10.84, "text": "H\\u00e3y c\\u00f9ng xem x\\u00e9t nh\\u00e9."}, {"index": 4, "start": 10.84, "end": 17.36, "text": "D\\u01b0\\u1edbi \\u0111\\u00e2y l\\u00e0 m\\u1ed9t \\u0111\\u1ecbnh ngh\\u0129a v\\u1ec1 h\\u1ecdc m\\u00e1y \\u0111\\u01b0\\u1ee3c g\\u00e1n cho Arthur Samuel."}, {"index": 5, "start": 17.36, "end": 22.2, "text": "\\u00d4ng \\u0111\\u1ecbnh ngh\\u0129a h\\u1ecdc m\\u00e1y l\\u00e0 nh\\u1eefng nghi\\u00ean c\\u1ee9u cho ph\\u00e9p m\\u00e1y t\\u00ednh h\\u1ecdc"}, {"index": 6, "start": 22.2, "end": 25.04, "text": "m\\u00e0 kh\\u00f4ng c\\u1ea7n \\u0111\\u01b0\\u1ee3c l\\u1eadp tr\\u00ecnh r\\u00f5 r\\u00e0ng."}, {"index": 7, "start": 25.04, "end": 30.84, "text": "Danh ti\\u1ebfng c\\u1ee7a Arthur \\u0111\\u1ebfn t\\u1eeb vi\\u1ec7c v\\u00e0o nh\\u1eefng n\\u0103m 1950, \\u00f4ng \\u0111\\u00e3 vi\\u1ebft m\\u1ed9t ch\\u01b0\\u01a1ng tr\\u00ecnh ch\\u01a1i c\\u1edd."}, {"index": 8, "start": 30.84, "end": 35.96, "text": "V\\u00e0 \\u0111i\\u1ec1u tuy\\u1ec7t v\\u1eddi v\\u1ec1 ch\\u01b0\\u01a1ng tr\\u00ecnh n\\u00e0y l\\u00e0 Arthur Samuel t\\u1ef1 \\u00f4ng kh\\u00f4ng ph\\u1ea3i l\\u00e0 m\\u1ed9t"}, {"index": 9, "start": 35.96, "end": 38.12, "text": "ng\\u01b0\\u1eddi ch\\u01a1i c\\u1edd gi\\u1ecfi."}, {"index": 10, "start": 38.12, "end": 42.88, "text": "Nh\\u1eefng g\\u00ec \\u00f4ng l\\u00e0m l\\u00e0 l\\u1eadp tr\\u00ecnh m\\u00e1y t\\u00ednh ch\\u01a1i c\\u00f3 th\\u1ec3 h\\u00e0ng ch\\u1ee5c ngh\\u00ecn v\\u00e1n c\\u1edd"}, {"index": 11, "start": 42.88, "end": 44.32, "text": "ch\\u1ed1ng l\\u1ea1i ch\\u00ednh m\\u00ecnh."}, {"index": 12, "start": 44.32, "end": 48.76, "text": "V\\u00e0 b\\u1eb1ng c\\u00e1ch theo d\\u00f5i c\\u00e1c v\\u1ecb tr\\u00ed b\\u00e0n c\\u1edd n\\u00e0o th\\u01b0\\u1eddng d\\u1eabn \\u0111\\u1ebfn chi\\u1ebfn th\\u1eafng, v\\u00e0 v\\u1ecb tr\\u00ed n\\u00e0o"}, {"index": 13, "start": 48.76, "end": 54.04, "text": "th\\u01b0\\u1eddng d\\u1eabn \\u0111\\u1ebfn th\\u1ea5t b\\u1ea1i, ch\\u01b0\\u01a1ng tr\\u00ecnh ch\\u01a1i c\\u1edd \\u0111\\u00e3 h\\u1ecdc theo th\\u1eddi gian nh\\u1eefng v\\u1ecb tr\\u00ed n\\u00e0o l\\u00e0 t\\u1ed1t"}, {"index": 14, "start": 54.04, "end": 56.08, "text": "hay x\\u1ea5u."}, {"index": 15, "start": 56.08, "end": 61.96, "text": "B\\u1eb1ng c\\u00e1ch c\\u1ed1 g\\u1eafng \\u0111\\u1ea1t \\u0111\\u01b0\\u1ee3c nh\\u1eefng v\\u1ecb tr\\u00ed t\\u1ed1t v\\u00e0 tr\\u00e1nh nh\\u1eefng v\\u1ecb tr\\u00ed x\\u1ea5u, ch\\u01b0\\u01a1ng tr\\u00ecnh c\\u1ee7a \\u00f4ng \\u0111\\u00e3 h\\u1ecdc \\u0111\\u1ec3 tr\\u1edf n\\u00ean ng\\u00e0y c\\u00e0ng"}, {"index": 16, "start": 61.96, "end": 64.02, "text": "gi\\u1ecfi h\\u01a1n trong vi\\u1ec7c ch\\u01a1i c\\u1edd."}, {"index": 17, "start": 64.02, "end": 68.0, "text": "V\\u00ec m\\u00e1y t\\u00ednh c\\u00f3 s\\u1ef1 ki\\u00ean nh\\u1eabn \\u0111\\u1ec3 ch\\u01a1i h\\u00e0ng ch\\u1ee5c ngh\\u00ecn v\\u00e1n c\\u1edd ch\\u1ed1ng l\\u1ea1i ch\\u00ednh n\\u00f3,"}, {"index": 18, "start": 68.0, "end": 73.8, "text": "n\\u00f3 \\u0111\\u00e3 t\\u00edch l\\u0169y \\u0111\\u01b0\\u1ee3c r\\u1ea5t nhi\\u1ec1u kinh nghi\\u1ec7m ch\\u01a1i c\\u1edd \\u0111\\u1ebfn m\\u1ee9c cu\\u1ed1i c\\u00f9ng n\\u00f3 tr\\u1edf th\\u00e0nh m\\u1ed9t ng\\u01b0\\u1eddi ch\\u01a1i c\\u1edd gi\\u1ecfi h\\u01a1n"}, {"index": 19, "start": 73.8, "end": 77.16, "text": "h\\u01a1n c\\u1ea3 Arthur Samuel."}, {"index": 20, "start": 77.16, "end": 82.28, "text": "B\\u00e2y gi\\u1edd, trong su\\u1ed1t nh\\u1eefng video n\\u00e0y, b\\u00ean c\\u1ea1nh vi\\u1ec7c t\\u00f4i c\\u1ed1 g\\u1eafng n\\u00f3i v\\u1ec1 nh\\u1eefng \\u0111i\\u1ec1u, th\\u1ec9nh tho\\u1ea3ng t\\u00f4i s\\u1ebd"}, {"index": 21, "start": 82.32, "end": 86.6, "text": "h\\u1ecfi b\\u1ea1n m\\u1ed9t c\\u00e2u \\u0111\\u1ec3 gi\\u00fap \\u0111\\u1ea3m b\\u1ea3o r\\u1eb1ng b\\u1ea1n hi\\u1ec3u n\\u1ed9i dung."}, {"index": 22, "start": 86.6, "end": 91.44, "text": "\\u0110\\u00e2y l\\u00e0 c\\u00e2u h\\u1ecfi v\\u1ec1 vi\\u1ec7c \\u0111i\\u1ec1u g\\u00ec s\\u1ebd x\\u1ea3y ra n\\u1ebfu m\\u00e1y t\\u00ednh ch\\u01a1i \\u00edt tr\\u00f2 ch\\u01a1i h\\u01a1n r\\u1ea5t nhi\\u1ec1u."}, {"index": 23, "start": 91.44, "end": 94.84, "text": "Xin h\\u00e3y xem qua v\\u00e0 ch\\u1ecdn c\\u00e2u tr\\u1ea3 l\\u1eddi n\\u00e0o m\\u00e0 b\\u1ea1n ngh\\u0129 l\\u00e0 t\\u1ed1t h\\u01a1n."}, {"index": 24, "start": 98.72, "end": 100.68, "text": "C\\u1ea3m \\u01a1n b\\u1ea1n \\u0111\\u00e3 xem qua b\\u00e0i ki\\u1ec3m tra."}, {"index": 25, "start": 100.68, "end": 108.88, "text": "V\\u00e0 n\\u1ebfu b\\u1ea1n \\u0111\\u00e3 ch\\u1ecdn c\\u00e2u tr\\u1ea3 l\\u1eddi n\\u00e0y, cho d\\u00f9 n\\u00f3 c\\u00f3 l\\u00e0m m\\u1ecdi th\\u1ee9 t\\u1ec7 h\\u01a1n hay kh\\u00f4ng, th\\u00ec b\\u1ea1n \\u0111\\u00e3 \\u0111\\u00fang."}, {"index": 26, "start": 108.88, "end": 112.96, "text": "N\\u00f3i chung, c\\u00e0ng c\\u00f3 nhi\\u1ec1u c\\u01a1 h\\u1ed9i \\u0111\\u1ec3 m\\u1ed9t thu\\u1eadt to\\u00e1n h\\u1ecdc t\\u1eadp h\\u1ecdc h\\u1ecfi,"}, {"index": 27, "start": 112.96, "end": 114.92, "text": "n\\u00f3 s\\u1ebd ho\\u1ea1t \\u0111\\u1ed9ng t\\u1ed1t h\\u01a1n."}, {"index": 28, "start": 114.92, "end": 119.48, "text": "N\\u1ebfu b\\u1ea1n kh\\u00f4ng ch\\u1ecdn c\\u00e2u tr\\u1ea3 l\\u1eddi \\u0111\\u00fang l\\u1ea7n \\u0111\\u1ea7u ti\\u00ean, c\\u0169ng kh\\u00f4ng sao c\\u1ea3."}, {"index": 29, "start": 119.48, "end": 123.08, "text": "M\\u1ee5c ti\\u00eau c\\u1ee7a nh\\u1eefng c\\u00e2u h\\u1ecfi ki\\u1ec3m tra n\\u00e0y kh\\u00f4ng ph\\u1ea3i l\\u00e0 xem li\\u1ec7u b\\u1ea1n c\\u00f3 th\\u1ec3 l\\u00e0m \\u0111\\u00fang t\\u1ea5t c\\u1ea3 hay kh\\u00f4ng"}, {"index": 30, "start": 123.08, "end": 124.76, "text": "\\u0111\\u00fang ngay t\\u1eeb l\\u1ea7n \\u0111\\u1ea7u ti\\u00ean."}, {"index": 31, "start": 124.76, "end": 129.32, "text": "Nh\\u1eefng c\\u00e2u h\\u1ecfi n\\u00e0y ch\\u1ec9 \\u0111\\u1ec3 gi\\u00fap b\\u1ea1n th\\u1ef1c h\\u00e0nh c\\u00e1c kh\\u00e1i ni\\u1ec7m m\\u00e0 b\\u1ea1n \\u0111ang h\\u1ecdc."}, {"index": 32, "start": 129.32, "end": 133.56, "text": "\\u0110\\u1ecbnh ngh\\u0129a c\\u1ee7a Arthur Samuel l\\u00e0 kh\\u00e1 kh\\u00f4ng ch\\u00ednh th\\u1ee9c, nh\\u01b0ng trong hai"}, {"index": 33, "start": 133.56, "end": 138.0, "text": "video ti\\u1ebfp theo, ch\\u00fang ta s\\u1ebd kh\\u00e1m ph\\u00e1 s\\u00e2u h\\u01a1n v\\u1ec1 c\\u00e1c lo\\u1ea1i m\\u00e1y"}, {"index": 34, "start": 138.04, "end": 141.04, "text": "h\\u1ecdc thu\\u1eadt."}, {"index": 35, "start": 141.04, "end": 145.04, "text": "Trong l\\u1edbp h\\u1ecdc n\\u00e0y, b\\u1ea1n s\\u1ebd t\\u00ecm hi\\u1ec3u v\\u1ec1 nhi\\u1ec1u thu\\u1eadt to\\u00e1n h\\u1ecdc kh\\u00e1c nhau."}, {"index": 36, "start": 145.04, "end": 150.6, "text": "Hai lo\\u1ea1i ch\\u00ednh c\\u1ee7a h\\u1ecdc m\\u00e1y l\\u00e0 h\\u1ecdc c\\u00f3 gi\\u00e1m s\\u00e1t v\\u00e0 kh\\u00f4ng c\\u00f3 gi\\u00e1m s\\u00e1t."}, {"index": 37, "start": 150.6, "end": 151.64, "text": "h\\u1ecdc."}, {"index": 38, "start": 151.64, "end": 156.64, "text": "Ch\\u00fang ta s\\u1ebd \\u0111\\u1ecbnh ngh\\u0129a nh\\u1eefng thu\\u1eadt ng\\u1eef n\\u00e0y c\\u00f3 ngh\\u0129a l\\u00e0 g\\u00ec trong v\\u00e0i video ti\\u1ebfp theo."}, {"index": 39, "start": 156.64, "end": 161.48, "text": "Trong hai lo\\u1ea1i n\\u00e0y, h\\u1ecdc c\\u00f3 gi\\u00e1m s\\u00e1t l\\u00e0 lo\\u1ea1i h\\u1ecdc m\\u00e1y \\u0111\\u01b0\\u1ee3c s\\u1eed d\\u1ee5ng"}, {"index": 40, "start": 161.48, "end": 166.88, "text": "h\\u1ea7u h\\u1ebft trong nhi\\u1ec1u \\u1ee9ng d\\u1ee5ng th\\u1ef1c t\\u1ebf v\\u00e0 \\u0111\\u00e3 ch\\u1ee9ng ki\\u1ebfn s\\u1ef1 ph\\u00e1t tri\\u1ec3n nhanh nh\\u1ea5t"}, {"index": 41, "start": 166.88, "end": 169.12, "text": "v\\u00e0 \\u0111\\u1ed5i m\\u1edbi."}, {"index": 42, "start": 169.12, "end": 174.32, "text": "Trong chuy\\u00ean ng\\u00e0nh n\\u00e0y, c\\u00f3 t\\u1ed5ng c\\u1ed9ng ba nguy\\u00ean nh\\u00e2n, nguy\\u00ean nh\\u00e2n th\\u1ee9 nh\\u1ea5t v\\u00e0 th\\u1ee9 hai"}, {"index": 43, "start": 174.32, "end": 179.24, "text": "s\\u1ebd t\\u1eadp trung v\\u00e0o h\\u1ecdc c\\u00f3 gi\\u00e1m s\\u00e1t v\\u00e0 nguy\\u00ean nh\\u00e2n th\\u1ee9 ba s\\u1ebd t\\u1eadp trung v\\u00e0o h\\u1ecdc kh\\u00f4ng gi\\u00e1m s\\u00e1t"}, {"index": 44, "start": 179.24, "end": 183.44, "text": "h\\u1ecdc, h\\u1ec7 th\\u1ed1ng g\\u1ee3i \\u00fd v\\u00e0 h\\u1ecdc t\\u0103ng c\\u01b0\\u1eddng."}, {"index": 45, "start": 183.44, "end": 188.04, "text": "Cho \\u0111\\u1ebfn nay, c\\u00e1c lo\\u1ea1i thu\\u1eadt to\\u00e1n h\\u1ecdc \\u0111\\u01b0\\u1ee3c s\\u1eed d\\u1ee5ng nhi\\u1ec1u nh\\u1ea5t hi\\u1ec7n nay l\\u00e0 h\\u1ecdc c\\u00f3 gi\\u00e1m s\\u00e1t"}, {"index": 46, "start": 188.04, "end": 192.36, "text": "h\\u1ecdc kh\\u00f4ng gi\\u00e1m s\\u00e1t v\\u00e0 h\\u1ec7 th\\u1ed1ng g\\u1ee3i \\u00fd."}, {"index": 47, "start": 192.36, "end": 195.92, "text": "\\u0110i\\u1ec1u kh\\u00e1c m\\u00e0 ch\\u00fang ta s\\u1ebd d\\u00e0nh nhi\\u1ec1u th\\u1eddi gian trong chuy\\u00ean ng\\u00e0nh n\\u00e0y"}, {"index": 48, "start": 195.92, "end": 200.44, "text": "l\\u00e0 nh\\u1eefng l\\u1eddi khuy\\u00ean th\\u1ef1c ti\\u1ec5n v\\u1ec1 vi\\u1ec7c \\u00e1p d\\u1ee5ng c\\u00e1c thu\\u1eadt to\\u00e1n h\\u1ecdc."}, {"index": 49, "start": 200.44, "end": 202.88, "text": "\\u0110\\u00e2y l\\u00e0 \\u0111i\\u1ec1u m\\u00e0 t\\u00f4i c\\u1ea3m th\\u1ea5y r\\u1ea5t m\\u1ea1nh m\\u1ebd."}, {"index": 50, "start": 202.88, "end": 207.64, "text": "D\\u1ea1y v\\u1ec1 c\\u00e1c thu\\u1eadt to\\u00e1n h\\u1ecdc gi\\u1ed1ng nh\\u01b0 vi\\u1ec7c \\u0111\\u01b0a cho ai \\u0111\\u00f3 m\\u1ed9t b\\u1ed9 c\\u00f4ng c\\u1ee5"}, {"index": 51, "start": 207.64, "end": 212.12, "text": "v\\u00e0 \\u0111i\\u1ec1u n\\u00e0y quan tr\\u1ecdng kh\\u00f4ng k\\u00e9m ho\\u1eb7c th\\u1eadm ch\\u00ed c\\u00f2n quan tr\\u1ecdng h\\u01a1n l\\u00e0 \\u0111\\u1ea3m b\\u1ea3o b\\u1ea1n c\\u00f3"}, {"index": 52, "start": 212.12, "end": 216.24, "text": "nh\\u1eefng c\\u00f4ng c\\u1ee5 tuy\\u1ec7t v\\u1eddi nh\\u01b0ng c\\u00f2n quan tr\\u1ecdng h\\u01a1n l\\u00e0 b\\u1ea1n bi\\u1ebft c\\u00e1ch \\u00e1p d\\u1ee5ng ch\\u00fang."}, {"index": 53, "start": 216.24, "end": 219.84, "text": "B\\u1edfi v\\u00ec, b\\u1ea1n bi\\u1ebft \\u0111\\u1ea5y, c\\u00e1i g\\u00ec s\\u1ebd t\\u1ed1t n\\u1ebfu ai \\u0111\\u00f3 trao cho b\\u1ea1n m\\u1ed9t"}, {"index": 54, "start": 219.84, "end": 223.56, "text": "chi\\u1ebfc b\\u00faa t\\u1ed1i t\\u00e2n ho\\u1eb7c m\\u1ed9t c\\u00e1i khoan c\\u1ea7m tay t\\u1ed1i t\\u00e2n v\\u00e0 n\\u00f3i,"}, {"index": 55, "start": 223.56, "end": 227.4, "text": "ch\\u00fac may m\\u1eafn, gi\\u1edd th\\u00ec b\\u1ea1n \\u0111\\u00e3 c\\u00f3 t\\u1ea5t c\\u1ea3 c\\u00f4ng c\\u1ee5 c\\u1ea7n thi\\u1ebft \\u0111\\u1ec3 x\\u00e2y d\\u1ef1ng m\\u1ed9t ng\\u00f4i nh\\u00e0 ba t\\u1ea7ng."}, {"index": 56, "start": 227.4, "end": 229.36, "text": "Th\\u1ef1c s\\u1ef1 kh\\u00f4ng ho\\u1ea1t \\u0111\\u1ed9ng nh\\u01b0 v\\u1eady."}, {"index": 57, "start": 229.36, "end": 235.0, "text": "V\\u00e0 c\\u0169ng nh\\u01b0 v\\u1eady trong h\\u1ecdc m\\u00e1y, vi\\u1ec7c \\u0111\\u1ea3m b\\u1ea3o b\\u1ea1n c\\u00f3 c\\u00f4ng c\\u1ee5 l\\u00e0 r\\u1ea5t quan tr\\u1ecdng"}, {"index": 58, "start": 235.0, "end": 239.2, "text": "v\\u00e0 c\\u0169ng quan tr\\u1ecdng kh\\u00f4ng k\\u00e9m l\\u00e0 \\u0111\\u1ea3m b\\u1ea3o r\\u1eb1ng b\\u1ea1n bi\\u1ebft c\\u00e1ch \\u00e1p d\\u1ee5ng c\\u00e1c c\\u00f4ng c\\u1ee5 c\\u1ee7a m\\u00e1y"}, {"index": 59, "start": 239.2, "end": 240.84, "text": "h\\u1ecdc m\\u1ed9t c\\u00e1ch hi\\u1ec7u qu\\u1ea3."}, {"index": 60, "start": 240.84, "end": 244.48, "text": "V\\u1eady n\\u00ean, nh\\u1eefng g\\u00ec b\\u1ea1n nh\\u1eadn \\u0111\\u01b0\\u1ee3c trong l\\u1edbp h\\u1ecdc n\\u00e0y l\\u00e0 c\\u1ea3 c\\u00f4ng c\\u1ee5 l\\u1eabn k\\u1ef9 n\\u0103ng"}, {"index": 61, "start": 244.48, "end": 247.04, "text": "\\u0111\\u1ec3 \\u00e1p d\\u1ee5ng ch\\u00fang m\\u1ed9t c\\u00e1ch hi\\u1ec7u qu\\u1ea3."}, {"index": 62, "start": 247.04, "end": 250.48, "text": "T\\u00f4i th\\u01b0\\u1eddng xuy\\u00ean g\\u1eb7p g\\u1ee1 b\\u1ea1n b\\u00e8 v\\u00e0 c\\u00e1c nh\\u00f3m t\\u1ea1i m\\u1ed9t s\\u1ed1"}, {"index": 63, "start": 250.52, "end": 251.76, "text": "c\\u00f4ng ty c\\u00f4ng ngh\\u1ec7 h\\u00e0ng \\u0111\\u1ea7u."}, {"index": 64, "start": 251.76, "end": 256.44, "text": "V\\u00e0 ngay c\\u1ea3 h\\u00f4m nay, t\\u00f4i th\\u1ea5y c\\u00e1c \\u0111\\u1ed9i ng\\u0169 m\\u00e1y h\\u1ecdc d\\u00e0y d\\u1ea1n kinh nghi\\u1ec7m \\u0111ang \\u00e1p d\\u1ee5ng"}, {"index": 65, "start": 256.44, "end": 258.92, "text": "c\\u00e1c thu\\u1eadt to\\u00e1n m\\u00e1y h\\u1ecdc cho m\\u1ed9t s\\u1ed1 v\\u1ea5n \\u0111\\u1ec1."}, {"index": 66, "start": 258.92, "end": 263.64, "text": "\\u0110\\u00f4i khi h\\u1ecd \\u0111\\u00e3 l\\u00e0m vi\\u1ec7c trong s\\u00e1u th\\u00e1ng m\\u00e0 kh\\u00f4ng \\u0111\\u1ea1t \\u0111\\u01b0\\u1ee3c nhi\\u1ec1u th\\u00e0nh c\\u00f4ng."}, {"index": 67, "start": 263.64, "end": 267.16, "text": "V\\u00e0 khi t\\u00f4i nh\\u00ecn v\\u00e0o nh\\u1eefng g\\u00ec h\\u1ecd \\u0111ang l\\u00e0m, t\\u00f4i \\u0111\\u00f4i khi c\\u1ea3m th\\u1ea5y m\\u00ecnh \\u0111\\u00e3 c\\u00f3 th\\u1ec3"}, {"index": 68, "start": 267.16, "end": 270.36, "text": "n\\u00f3i v\\u1edbi h\\u1ecd t\\u1eeb s\\u00e1u th\\u00e1ng tr\\u01b0\\u1edbc r\\u1eb1ng ph\\u01b0\\u01a1ng ph\\u00e1p hi\\u1ec7n t\\u1ea1i s\\u1ebd kh\\u00f4ng hi\\u1ec7u qu\\u1ea3."}, {"index": 69, "start": 270.36, "end": 273.52, "text": "V\\u00e0 c\\u00f3 m\\u1ed9t c\\u00e1ch kh\\u00e1c \\u0111\\u1ec3 s\\u1eed d\\u1ee5ng nh\\u1eefng c\\u00f4ng c\\u1ee5 n\\u00e0y s\\u1ebd mang l\\u1ea1i"}, {"index": 70, "start": 273.52, "end": 275.84, "text": "cho h\\u1ecd c\\u01a1 h\\u1ed9i th\\u00e0nh c\\u00f4ng t\\u1ed1t h\\u01a1n r\\u1ea5t nhi\\u1ec1u."}, {"index": 71, "start": 275.84, "end": 279.4, "text": "V\\u00ec v\\u1eady, trong l\\u1edbp h\\u1ecdc n\\u00e0y, m\\u1ed9t trong nh\\u1eefng \\u0111i\\u1ec1u t\\u01b0\\u01a1ng \\u0111\\u1ed1i \\u0111\\u1ed9c \\u0111\\u00e1o m\\u00e0 b\\u1ea1n s\\u1ebd h\\u1ecdc"}, {"index": 72, "start": 279.4, "end": 282.92, "text": "l\\u00e0 b\\u1ea1n s\\u1ebd bi\\u1ebft nhi\\u1ec1u v\\u1ec1 nh\\u1eefng th\\u1ef1c h\\u00e0nh t\\u1ed1t nh\\u1ea5t \\u0111\\u1ec3 th\\u1ef1c s\\u1ef1"}, {"index": 73, "start": 282.92, "end": 287.36, "text": "ph\\u00e1t tri\\u1ec3n m\\u1ed9t h\\u1ec7 th\\u1ed1ng m\\u00e1y h\\u1ecdc th\\u1ef1c ti\\u1ec5n v\\u00e0 c\\u00f3 gi\\u00e1 tr\\u1ecb."}, {"index": 74, "start": 287.36, "end": 290.2, "text": "B\\u1eb1ng c\\u00e1ch n\\u00e0y, b\\u1ea1n s\\u1ebd \\u00edt c\\u00f3 kh\\u1ea3 n\\u0103ng r\\u01a1i v\\u00e0o m\\u1ed9t trong nh\\u1eefng \\u0111\\u1ed9i"}, {"index": 75, "start": 290.2, "end": 294.48, "text": "c\\u00f3 kh\\u1ea3 n\\u0103ng d\\u1eabn \\u0111\\u1ebfn vi\\u1ec7c t\\u1ed1n s\\u00e1u th\\u00e1ng \\u0111i sai h\\u01b0\\u1edbng."}, {"index": 76, "start": 294.48, "end": 297.96, "text": "Trong l\\u1edbp h\\u1ecdc n\\u00e0y, b\\u1ea1n s\\u1ebd hi\\u1ec3u c\\u00e1ch m\\u00e0 nh\\u1eefng k\\u1ef9 s\\u01b0 m\\u00e1y h\\u1ecdc t\\u00e0i n\\u0103ng nh\\u1ea5t"}, {"index": 77, "start": 297.96, "end": 299.72, "text": "x\\u00e2y d\\u1ef1ng h\\u1ec7 th\\u1ed1ng."}, {"index": 78, "start": 299.72, "end": 304.04, "text": "V\\u00e0 t\\u00f4i hy v\\u1ecdng b\\u1ea1n s\\u1ebd k\\u1ebft th\\u00fac l\\u1edbp h\\u1ecdc n\\u00e0y nh\\u01b0 m\\u1ed9t trong nh\\u1eefng ng\\u01b0\\u1eddi r\\u1ea5t hi\\u1ebfm hoi"}, {"index": 79, "start": 304.04, "end": 307.8, "text": "trong th\\u1ebf gi\\u1edbi ng\\u00e0y nay bi\\u1ebft c\\u00e1ch thi\\u1ebft k\\u1ebf v\\u00e0 x\\u00e2y d\\u1ef1ng nh\\u1eefng h\\u1ec7 th\\u1ed1ng nghi\\u00eam t\\u00fac"}, {"index": 80, "start": 307.8, "end": 309.68, "text": "c\\u00e1c h\\u1ec7 th\\u1ed1ng h\\u1ecdc m\\u00e1y."}, {"index": 81, "start": 309.68, "end": 311.88, "text": "V\\u1eady l\\u00e0, h\\u1ecdc m\\u00e1y g\\u1ea7n \\u0111\\u00e2y."}, {"index": 82, "start": 311.88, "end": 315.16, "text": "Trong video ti\\u1ebfp theo, h\\u00e3y c\\u00f9ng t\\u00ecm hi\\u1ec3u s\\u00e2u h\\u01a1n v\\u1ec1 vi\\u1ec7c"}, {"index": 83, "start": 315.16, "end": 319.92, "text": "h\\u1ecdc c\\u00f3 gi\\u00e1m s\\u00e1t v\\u00e0 c\\u1ea3 h\\u1ecdc kh\\u00f4ng c\\u00f3 gi\\u00e1m s\\u00e1t."}, {"index": 84, "start": 319.92, "end": 323.56, "text": "Ngo\\u00e0i ra, b\\u1ea1n s\\u1ebd bi\\u1ebft khi n\\u00e0o b\\u1ea1n c\\u00f3 th\\u1ec3 mu\\u1ed1n s\\u1eed d\\u1ee5ng t\\u1eebng lo\\u1ea1i,"}, {"index": 85, "start": 323.56, "end": 326.08, "text": "h\\u1ecdc c\\u00f3 gi\\u00e1m s\\u00e1t v\\u00e0 h\\u1ecdc kh\\u00f4ng c\\u00f3 gi\\u00e1m s\\u00e1t."}, {"index": 86, "start": 326.08, "end": 328.68, "text": "H\\u1eb9n g\\u1eb7p b\\u1ea1n trong video ti\\u1ebfp theo."}]}}, "summary": ["- H\\u1ecdc m\\u00e1y l\\u00e0 nghi\\u00ean c\\u1ee9u cho ph\\u00e9p m\\u00e1y t\\u00ednh h\\u1ecdc m\\u00e0 kh\\u00f4ng c\\u1ea7n l\\u1eadp tr\\u00ecnh r\\u00f5 r\\u00e0ng.", "- Arthur Samuel, m\\u1ed9t ng\\u01b0\\u1eddi ti\\u00ean phong trong l\\u0129nh v\\u1ef1c n\\u00e0y, \\u0111\\u00e3 ph\\u00e1t tri\\u1ec3n ch\\u01b0\\u01a1ng tr\\u00ecnh ch\\u01a1i c\\u1edd t\\u1ef1 \\u0111\\u1ed9ng.", "- Ch\\u01b0\\u01a1ng tr\\u00ecnh c\\u1ee7a \\u00f4ng h\\u1ecdc t\\u1eeb h\\u00e0ng ch\\u1ee5c ngh\\u00ecn v\\u00e1n c\\u1edd v\\u00e0 d\\u1ea7n tr\\u1edf n\\u00ean gi\\u1ecfi h\\u01a1n trong vi\\u1ec7c ch\\u01a1i c\\u1edd.", "- S\\u1ed1 l\\u01b0\\u1ee3ng tr\\u1ea3i nghi\\u1ec7m h\\u1ecdc t\\u1eadp \\u1ea3nh h\\u01b0\\u1edfng \\u0111\\u1ebfn hi\\u1ec7u qu\\u1ea3 c\\u1ee7a thu\\u1eadt to\\u00e1n h\\u1ecdc m\\u00e1y.", "- H\\u1ecdc m\\u00e1y chia th\\u00e0nh hai lo\\u1ea1i ch\\u00ednh: h\\u1ecdc c\\u00f3 gi\\u00e1m s\\u00e1t v\\u00e0 kh\\u00f4ng c\\u00f3 gi\\u00e1m s\\u00e1t.", "- H\\u1ecdc c\\u00f3 gi\\u00e1m s\\u00e1t l\\u00e0 lo\\u1ea1i ph\\u1ed5 bi\\u1ebfn nh\\u1ea5t trong \\u1ee9ng d\\u1ee5ng th\\u1ef1c t\\u1ebf.", "- C\\u1ea7n n\\u1eafm r\\u00f5 c\\u00e1ch \\u00e1p d\\u1ee5ng c\\u00e1c thu\\u1eadt to\\u00e1n h\\u1ecdc m\\u00e1y c\\u0169ng nh\\u01b0 c\\u00f3 c\\u00f4ng c\\u1ee5 ph\\u00f9 h\\u1ee3p.", "- Kh\\u1ea3 n\\u0103ng \\u00e1p d\\u1ee5ng hi\\u1ec7u qu\\u1ea3 c\\u00e1c c\\u00f4ng c\\u1ee5 h\\u1ecdc m\\u00e1y l\\u00e0 \\u0111i\\u1ec1u quan tr\\u1ecdng trong qu\\u00e1 tr\\u00ecnh h\\u1ecdc."], "timeline": [{"time": "00:00", "title": "Gi\\u1edbi thi\\u1ec7u v\\u1ec1 h\\u1ecdc m\\u00e1y"}, {"time": "01:04", "title": "V\\u00ed d\\u1ee5 v\\u1ec1 ch\\u01b0\\u01a1ng tr\\u00ecnh c\\u1edd vua c\\u1ee7a Arthur Samuel"}, {"time": "02:04", "title": "Kh\\u00e1i ni\\u1ec7m v\\u00e0 m\\u1ee5c ti\\u00eau c\\u1ee7a c\\u00e1c c\\u00e2u h\\u1ecfi ki\\u1ec3m tra"}, {"time": "02:36", "title": "C\\u00e1c lo\\u1ea1i h\\u1ecdc m\\u00e1y: H\\u1ecdc c\\u00f3 gi\\u00e1m s\\u00e1t v\\u00e0 kh\\u00f4ng c\\u00f3 gi\\u00e1m s\\u00e1t"}, {"time": "04:00", "title": "T\\u1ea7m quan tr\\u1ecdng c\\u1ee7a vi\\u1ec7c \\u00e1p d\\u1ee5ng c\\u00f4ng c\\u1ee5 h\\u1ecdc m\\u00e1y"}, {"time": "05:09", "title": "K\\u1ebft th\\u00fac v\\u00e0 tri\\u1ec3n v\\u1ecdng b\\u00e0i h\\u1ecdc ti\\u1ebfp theo"}], "highlights": [{"time": "01:48", "reason": "Cung c\\u1ea5p hi\\u1ec3u bi\\u1ebft v\\u1ec1 t\\u1ea7m quan tr\\u1ecdng c\\u1ee7a vi\\u1ec7c c\\u00f3 nhi\\u1ec1u d\\u1eef li\\u1ec7u h\\u1ecdc.", "context": "C\\u00e0ng c\\u00f3 nhi\\u1ec1u c\\u01a1 h\\u1ed9i \\u0111\\u1ec3 m\\u1ed9t thu\\u1eadt to\\u00e1n h\\u1ecdc t\\u1eadp h\\u1ecdc h\\u1ecfi, n\\u00f3 s\\u1ebd ho\\u1ea1t \\u0111\\u1ed9ng t\\u1ed1t h\\u01a1n."}, {"time": "04:32", "reason": "Nh\\u1ea5n m\\u1ea1nh v\\u00e0o vi\\u1ec7c kh\\u00f4ng ch\\u1ec9 c\\u00f3 c\\u00f4ng c\\u1ee5 m\\u00e0 c\\u00f2n l\\u00e0 c\\u00e1ch \\u00e1p d\\u1ee5ng ch\\u00fang.", "context": "Vi\\u1ec7c \\u0111\\u1ea3m b\\u1ea3o b\\u1ea1n c\\u00f3 c\\u00f4ng c\\u1ee5 l\\u00e0 r\\u1ea5t quan tr\\u1ecdng v\\u00e0 c\\u0169ng quan tr\\u1ecdng kh\\u00f4ng k\\u00e9m l\\u00e0 \\u0111\\u1ea3m b\\u1ea3o r\\u1eb1ng b\\u1ea1n bi\\u1ebft c\\u00e1ch \\u00e1p d\\u1ee5ng c\\u00e1c c\\u00f4ng c\\u1ee5."}, {"time": "05:07", "reason": "\\u0110\\u1ecbnh h\\u01b0\\u1edbng cho sinh vi\\u00ean v\\u1ec1 kh\\u1ea3 n\\u0103ng thi\\u1ebft k\\u1ebf v\\u00e0 x\\u00e2y d\\u1ef1ng h\\u1ec7 th\\u1ed1ng h\\u1ecdc m\\u00e1y.", "context": "T\\u00f4i hy v\\u1ecdng b\\u1ea1n s\\u1ebd k\\u1ebft th\\u00fac l\\u1edbp h\\u1ecdc n\\u00e0y nh\\u01b0 m\\u1ed9t trong nh\\u1eefng ng\\u01b0\\u1eddi r\\u1ea5t hi\\u1ebfm hoi trong th\\u1ebf gi\\u1edbi ng\\u00e0y nay bi\\u1ebft c\\u00e1ch thi\\u1ebft k\\u1ebf v\\u00e0 x\\u00e2y d\\u1ef1ng nh\\u1eefng h\\u1ec7 th\\u1ed1ng nghi\\u00eam t\\u00fac."}], "questions": [{"time": "01:17", "original": "\\u0110i\\u1ec1u g\\u00ec s\\u1ebd x\\u1ea3y ra n\\u1ebfu m\\u00e1y t\\u00ednh ch\\u01a1i \\u00edt tr\\u00f2 ch\\u01a1i h\\u01a1n r\\u1ea5t nhi\\u1ec1u?", "rephrased": "N\\u1ebfu m\\u00e1y t\\u00ednh ch\\u1ec9 ch\\u01a1i m\\u1ed9t s\\u1ed1 l\\u01b0\\u1ee3ng tr\\u00f2 ch\\u01a1i r\\u1ea5t \\u00edt, \\u0111i\\u1ec1u g\\u00ec s\\u1ebd x\\u1ea3y ra v\\u1edbi kh\\u1ea3 n\\u0103ng h\\u1ecdc c\\u1ee7a n\\u00f3?"}], "briefing": {"objective": "M\\u1ee5c ti\\u00eau ch\\u00ednh c\\u1ee7a b\\u00e0i h\\u1ecdc n\\u00e0y l\\u00e0 hi\\u1ec3u \\u0111\\u1ecbnh ngh\\u0129a v\\u1ec1 h\\u1ecdc m\\u00e1y v\\u00e0 c\\u00e1c lo\\u1ea1i thu\\u1eadt to\\u00e1n li\\u00ean quan \\u0111\\u1ebfn n\\u00f3.", "summary": "Trong video n\\u00e0y, sinh vi\\u00ean s\\u1ebd t\\u00ecm hi\\u1ec3u v\\u1ec1 h\\u1ecdc m\\u00e1y, kh\\u00e1i ni\\u1ec7m do Arthur Samuel \\u0111\\u1ecbnh ngh\\u0129a v\\u00e0 c\\u00e1ch m\\u00e0 m\\u00e1y t\\u00ednh c\\u00f3 th\\u1ec3 h\\u1ecdc t\\u1ef1 \\u0111\\u1ed9ng m\\u00e0 kh\\u00f4ng c\\u1ea7n l\\u1eadp tr\\u00ecnh r\\u00f5 r\\u00e0ng. B\\u00e0i h\\u1ecdc c\\u0169ng s\\u1ebd tr\\u00ecnh b\\u00e0y hai lo\\u1ea1i h\\u1ecdc m\\u00e1y ch\\u00ednh l\\u00e0 h\\u1ecdc c\\u00f3 gi\\u00e1m s\\u00e1t v\\u00e0 kh\\u00f4ng c\\u00f3 gi\\u00e1m s\\u00e1t, c\\u0169ng nh\\u01b0 c\\u00e1c \\u1ee9ng d\\u1ee5ng th\\u1ef1c ti\\u1ec5n c\\u1ee7a ch\\u00fang. Sinh vi\\u00ean s\\u1ebd \\u0111\\u01b0\\u1ee3c khuy\\u1ebfn kh\\u00edch th\\u1ef1c h\\u00e0nh qua c\\u00e1c c\\u00e2u h\\u1ecfi \\u