\u1ea5y c\\u00f3 r\\u1ea5t nhi\\u1ec1u \\u0111i\\u1ec1u x\\u1ea3y ra trong ph\\u01b0\\u01a1ng tr\\u00ecnh n\\u00e0y, kh\\u00f4ng sao c\\u1ea3, \\u0111\\u1eebng lo l\\u1eafng"}, {"index": 9, "start": 54.6, "end": 58.0, "text": "v\\u1ec1 n\\u00f3, ch\\u00fang ta s\\u1ebd gi\\u1ea3i th\\u00edch c\\u00f9ng nhau."}, {"index": 10, "start": 58.0, "end": 61.8, "text": "\\u0110\\u1ea7u ti\\u00ean, ch\\u00fa \\u00fd \\u0111\\u1ebfn k\\u00fd hi\\u1ec7u b\\u1eb1ng \\u1edf \\u0111\\u00e2y."}, {"index": 11, "start": 61.8, "end": 66.6, "text": "Ch\\u00fa \\u00fd r\\u1eb1ng t\\u00f4i \\u0111\\u00e3 n\\u00f3i ch\\u00fang ta \\u0111ang g\\u00e1n cho w m\\u1ed9t gi\\u00e1 tr\\u1ecb b\\u1eb1ng c\\u00e1ch s\\u1eed d\\u1ee5ng d\\u1ea5u '='."}, {"index": 12, "start": 66.6, "end": 72.16, "text": "V\\u00ec v\\u1eady, trong ng\\u1eef c\\u1ea3nh n\\u00e0y, d\\u1ea5u '=' l\\u00e0 to\\u00e1n t\\u1eed g\\u00e1n."}, {"index": 13, "start": 72.16, "end": 78.84, "text": "C\\u1ee5 th\\u1ec3 trong ng\\u1eef c\\u1ea3nh n\\u00e0y, n\\u1ebfu b\\u1ea1n vi\\u1ebft m\\u00e3 n\\u00f3i r\\u1eb1ng a b\\u1eb1ng c, c\\u00f3 ngh\\u0129a l\\u00e0 l\\u1ea5y"}, {"index": 14, "start": 78.84, "end": 84.0, "text": "gi\\u00e1 tr\\u1ecb c\\u1ee7a c v\\u00e0 l\\u01b0u tr\\u1eef n\\u00f3 trong m\\u00e1y t\\u00ednh c\\u1ee7a b\\u1ea1n trong bi\\u1ebfn a."}, {"index": 15, "start": 84.04, "end": 88.6, "text": "Ho\\u1eb7c n\\u1ebfu b\\u1ea1n vi\\u1ebft a b\\u1eb1ng a c\\u1ed9ng m\\u1ed9t, c\\u00f3 ngh\\u0129a l\\u00e0 \\u0111\\u1eb7t gi\\u00e1 tr\\u1ecb c\\u1ee7a a b\\u1eb1ng"}, {"index": 16, "start": 88.6, "end": 93.6, "text": "a c\\u1ed9ng m\\u1ed9t, ho\\u1eb7c t\\u0103ng gi\\u00e1 tr\\u1ecb c\\u1ee7a a l\\u00ean m\\u1ed9t."}, {"index": 17, "start": 93.6, "end": 100.08, "text": "V\\u00ec v\\u1eady, to\\u00e1n t\\u1eed g\\u00e1n trong l\\u1eadp tr\\u00ecnh kh\\u00e1c v\\u1edbi c\\u00e1c kh\\u1eb3ng \\u0111\\u1ecbnh v\\u1ec1 s\\u1ef1 th\\u1eadt trong"}, {"index": 18, "start": 100.08, "end": 106.44, "text": "to\\u00e1n h\\u1ecdc, n\\u01a1i n\\u1ebfu t\\u00f4i vi\\u1ebft a b\\u1eb1ng c, t\\u00f4i \\u0111ang kh\\u1eb3ng \\u0111\\u1ecbnh r\\u1eb1ng t\\u00f4i \\u0111ang tuy\\u00ean b\\u1ed1"}, {"index": 19, "start": 106.44, "end": 110.32, "text": "r\\u1eb1ng gi\\u00e1 tr\\u1ecb c\\u1ee7a a v\\u00e0 c l\\u00e0 b\\u1eb1ng nhau."}, {"index": 20, "start": 110.32, "end": 114.4, "text": "V\\u00e0 hy v\\u1ecdng t\\u00f4i s\\u1ebd kh\\u00f4ng bao gi\\u1edd vi\\u1ebft m\\u1ed9t gi\\u1ea3 thi\\u1ebft \\u0111\\u00fang r\\u1eb1ng a b\\u1eb1ng a c\\u1ed9ng m\\u1ed9t,"}, {"index": 21, "start": 114.4, "end": 116.84, "text": "b\\u1edfi v\\u00ec \\u0111i\\u1ec1u \\u0111\\u00f3 ho\\u00e0n to\\u00e0n kh\\u00f4ng th\\u1ec3 \\u0111\\u00fang."}, {"index": 22, "start": 118.16, "end": 121.4, "text": "V\\u00ec v\\u1eady, trong Python v\\u00e0 c\\u00e1c ng\\u00f4n ng\\u1eef l\\u1eadp tr\\u00ecnh kh\\u00e1c,"}, {"index": 23, "start": 121.4, "end": 125.84, "text": "c\\u00e1c gi\\u1ea3 thi\\u1ebft \\u0111\\u00fang \\u0111\\u00f4i khi \\u0111\\u01b0\\u1ee3c vi\\u1ebft d\\u01b0\\u1edbi d\\u1ea1ng b\\u1eb1ng b\\u1eb1ng."}, {"index": 24, "start": 125.84, "end": 130.64, "text": "V\\u00ec v\\u1eady, b\\u1ea1n c\\u00f3 th\\u1ec3 th\\u1ea5y m\\u00e3 l\\u1ec7nh n\\u00f3i r\\u1eb1ng a b\\u1eb1ng b\\u1eb1ng c n\\u1ebfu b\\u1ea1n \\u0111ang ki\\u1ec3m tra"}, {"index": 25, "start": 130.64, "end": 132.84, "text": "xem a c\\u00f3 b\\u1eb1ng c kh\\u00f4ng."}, {"index": 26, "start": 132.84, "end": 136.12, "text": "Nh\\u01b0ng trong k\\u00fd hi\\u1ec7u to\\u00e1n h\\u1ecdc nh\\u01b0 ch\\u00fang ta th\\u01b0\\u1eddng s\\u1eed d\\u1ee5ng,"}, {"index": 27, "start": 136.12, "end": 140.96, "text": "nh\\u01b0 trong nh\\u1eefng video n\\u00e0y, d\\u1ea5u b\\u1eb1ng c\\u00f3 th\\u1ec3 \\u0111\\u01b0\\u1ee3c s\\u1eed d\\u1ee5ng cho c\\u1ea3 g\\u00e1n gi\\u00e1 tr\\u1ecb"}, {"index": 28, "start": 140.96, "end": 143.28, "text": "ho\\u1eb7c cho gi\\u1ea3 thi\\u1ebft \\u0111\\u00fang."}, {"index": 29, "start": 143.28, "end": 147.0, "text": "V\\u00e0 v\\u00ec v\\u1eady t\\u00f4i s\\u1ebd c\\u1ed1 g\\u1eafng l\\u00e0m cho n\\u00f3 r\\u00f5 r\\u00e0ng khi t\\u00f4i vi\\u1ebft d\\u1ea5u b\\u1eb1ng,"}, {"index": 30, "start": 147.0, "end": 150.16, "text": "xem c\\u00f3 ph\\u1ea3i ch\\u00fang ta \\u0111ang g\\u00e1n m\\u1ed9t gi\\u00e1 tr\\u1ecb cho bi\\u1ebfn hay kh\\u00f4ng, ho\\u1eb7c li\\u1ec7u ch\\u00fang ta \\u0111ang"}, {"index": 31, "start": 150.16, "end": 154.12, "text": "kh\\u1eb3ng \\u0111\\u1ecbnh s\\u1ef1 \\u0111\\u00fang \\u0111\\u1eafn c\\u1ee7a s\\u1ef1 b\\u00ecnh \\u0111\\u1eb3ng gi\\u1eefa hai gi\\u00e1 tr\\u1ecb."}, {"index": 32, "start": 155.44, "end": 160.48, "text": "B\\u00e2y gi\\u1edd, h\\u00e3y \\u0111i s\\u00e2u h\\u01a1n v\\u00e0o nh\\u1eefng g\\u00ec c\\u00e1c k\\u00fd hi\\u1ec7u trong ph\\u01b0\\u01a1ng tr\\u00ecnh n\\u00e0y c\\u00f3 ngh\\u0129a."}, {"index": 33, "start": 160.48, "end": 165.32, "text": "K\\u00fd hi\\u1ec7u \\u1edf \\u0111\\u00e2y l\\u00e0 ch\\u1eef c\\u00e1i Hy L\\u1ea1p alpha."}, {"index": 34, "start": 165.32, "end": 171.12, "text": "V\\u00e0 trong ph\\u01b0\\u01a1ng tr\\u00ecnh n\\u00e0y, alpha c\\u00f2n \\u0111\\u01b0\\u1ee3c g\\u1ecdi l\\u00e0 t\\u1ed1c \\u0111\\u1ed9 h\\u1ecdc."}, {"index": 35, "start": 171.12, "end": 175.64, "text": "T\\u1ed1c \\u0111\\u1ed9 h\\u1ecdc th\\u01b0\\u1eddng l\\u00e0 m\\u1ed9t s\\u1ed1 d\\u01b0\\u01a1ng nh\\u1ecf trong kho\\u1ea3ng t\\u1eeb kh\\u00f4ng \\u0111\\u1ebfn m\\u1ed9t."}, {"index": 36, "start": 175.64, "end": 178.28, "text": "V\\u00e0 n\\u00f3 c\\u00f3 th\\u1ec3 l\\u00e0 kho\\u1ea3ng 0.01."}, {"index": 37, "start": 179.72, "end": 184.76, "text": "\\u0110i\\u1ec1u alpha l\\u00e0m l\\u00e0 n\\u00f3 ki\\u1ec3m so\\u00e1t k\\u00edch th\\u01b0\\u1edbc c\\u1ee7a b\\u01b0\\u1edbc \\u0111i xu\\u1ed1ng \\u0111\\u1ed3i."}, {"index": 38, "start": 185.88, "end": 191.04, "text": "V\\u00ec v\\u1eady, n\\u1ebfu alpha r\\u1ea5t l\\u1edbn, th\\u00ec \\u0111i\\u1ec1u \\u0111\\u00f3 t\\u01b0\\u01a1ng \\u1ee9ng v\\u1edbi m\\u1ed9t quy tr\\u00ecnh"}, {"index": 39, "start": 191.04, "end": 195.8, "text": "gi\\u1ea3m d\\u1ea7n gradient r\\u1ea5t m\\u1ea1nh, n\\u01a1i b\\u1ea1n \\u0111ang c\\u1ed1 g\\u1eafng th\\u1ef1c hi\\u1ec7n nh\\u1eefng b\\u01b0\\u1edbc \\u0111i l\\u1edbn xu\\u1ed1ng d\\u1ed1c."}, {"index": 40, "start": 195.8, "end": 201.12, "text": "N\\u1ebfu alpha r\\u1ea5t nh\\u1ecf, b\\u1ea1n s\\u1ebd ch\\u1ec9 ti\\u1ebfn b\\u1ed9 t\\u1eebng b\\u01b0\\u1edbc nh\\u1ecf xu\\u1ed1ng d\\u1ed1c."}, {"index": 41, "start": 201.12, "end": 206.92, "text": "Ch\\u00fang ta s\\u1ebd tr\\u1edf l\\u1ea1i sau \\u0111\\u1ec3 \\u0111i s\\u00e2u h\\u01a1n v\\u00e0o c\\u00e1ch ch\\u1ecdn m\\u1ed9t t\\u1ef7 l\\u1ec7 h\\u1ecdc alpha ph\\u00f9 h\\u1ee3p."}, {"index": 42, "start": 206.92, "end": 213.6, "text": "Cu\\u1ed1i c\\u00f9ng, thu\\u1eadt ng\\u1eef n\\u00e0y ch\\u00ednh l\\u00e0 \\u0111\\u1ea1o h\\u00e0m c\\u1ee7a h\\u00e0m chi ph\\u00ed J."}, {"index": 43, "start": 213.6, "end": 217.04, "text": "Ch\\u00fang ta kh\\u00f4ng c\\u1ea7n lo l\\u1eafng v\\u1ec1 chi ti\\u1ebft c\\u1ee7a \\u0111\\u1ea1o h\\u00e0m n\\u00e0y ngay b\\u00e2y gi\\u1edd,"}, {"index": 44, "start": 217.04, "end": 221.08, "text": "nh\\u01b0ng sau n\\u00e0y, b\\u1ea1n s\\u1ebd \\u0111\\u01b0\\u1ee3c t\\u00ecm hi\\u1ec3u nhi\\u1ec1u h\\u01a1n v\\u1ec1 thu\\u1eadt ng\\u1eef \\u0111\\u1ea1o h\\u00e0m."}, {"index": 45, "start": 221.08, "end": 225.88, "text": "Nh\\u01b0ng hi\\u1ec7n t\\u1ea1i, b\\u1ea1n c\\u00f3 th\\u1ec3 ngh\\u0129 v\\u1ec1 c\\u1ee5m t\\u1eeb \\u0111\\u1ea1o h\\u00e0m n\\u00e0y m\\u00e0 t\\u00f4i \\u0111\\u00e3 v\\u1ebd m\\u1ed9t \\u00f4 m\\u00e0u t\\u00edm xung quanh."}, {"index": 46, "start": 225.88, "end": 229.8, "text": "nh\\u01b0 l\\u00e0 ch\\u1ec9 d\\u1eabn cho b\\u1ea1n bi\\u1ebft h\\u01b0\\u1edbng n\\u00e0o b\\u1ea1n mu\\u1ed1n ti\\u1ebfn m\\u1ed9t b\\u01b0\\u1edbc nh\\u1ecf."}, {"index": 47, "start": 229.8, "end": 233.4, "text": "V\\u00e0 k\\u1ebft h\\u1ee3p v\\u1edbi h\\u1ec7 s\\u1ed1 h\\u1ecdc alpha,"}, {"index": 48, "start": 233.4, "end": 236.76, "text": "n\\u00f3 c\\u0169ng x\\u00e1c \\u0111\\u1ecbnh k\\u00edch th\\u01b0\\u1edbc c\\u1ee7a c\\u00e1c b\\u01b0\\u1edbc b\\u1ea1n mu\\u1ed1n \\u0111i xu\\u1ed1ng."}, {"index": 49, "start": 238.44, "end": 242.92, "text": "B\\u00e2y gi\\u1edd, t\\u00f4i mu\\u1ed1n \\u0111\\u1ec1 c\\u1eadp r\\u1eb1ng \\u0111\\u1ea1o h\\u00e0m xu\\u1ea5t ph\\u00e1t t\\u1eeb gi\\u1ea3i t\\u00edch."}, {"index": 50, "start": 242.92, "end": 246.44, "text": "V\\u00e0 ngay c\\u1ea3 khi b\\u1ea1n kh\\u00f4ng quen thu\\u1ed9c v\\u1edbi gi\\u1ea3i t\\u00edch, \\u0111\\u1eebng lo l\\u1eafng v\\u1ec1 \\u0111i\\u1ec1u \\u0111\\u00f3."}, {"index": 51, "start": 247.16, "end": 251.12, "text": "Ngay c\\u1ea3 khi kh\\u00f4ng bi\\u1ebft g\\u00ec v\\u1ec1 gi\\u1ea3i t\\u00edch, b\\u1ea1n v\\u1eabn c\\u00f3 th\\u1ec3 t\\u00ecm ra m\\u1ecdi \\u0111i\\u1ec1u b\\u1ea1n c\\u1ea7n bi\\u1ebft."}, {"index": 52, "start": 251.12, "end": 254.32, "text": "v\\u1ec1 thu\\u1eadt ng\\u1eef \\u0111\\u1ea1o h\\u00e0m n\\u00e0y trong video n\\u00e0y v\\u00e0 s\\u1ef1 k\\u1ebft h\\u1ee3p."}, {"index": 53, "start": 255.48, "end": 262.04, "text": "M\\u1ed9t \\u0111i\\u1ec1u n\\u1eefa, h\\u00e3y nh\\u1edb r\\u1eb1ng m\\u00f4 h\\u00ecnh c\\u1ee7a b\\u1ea1n c\\u00f3 hai tham s\\u1ed1, kh\\u00f4ng ch\\u1ec9 l\\u00e0 W, m\\u00e0 c\\u00f2n l\\u00e0 B."}, {"index": 54, "start": 262.04, "end": 268.92, "text": "V\\u00ec v\\u1eady, b\\u1ea1n c\\u0169ng c\\u00f3 m\\u1ed9t ph\\u00e9p g\\u00e1n \\u0111\\u1ec3 c\\u1eadp nh\\u1eadt tham s\\u1ed1 B tr\\u00f4ng r\\u1ea5t gi\\u1ed1ng."}, {"index": 55, "start": 268.92, "end": 275.64, "text": "B \\u0111\\u01b0\\u1ee3c g\\u00e1n gi\\u00e1 tr\\u1ecb c\\u0169 c\\u1ee7a B tr\\u1eeb \\u0111i t\\u1ef7 l\\u1ec7 h\\u1ecdc alpha"}, {"index": 56, "start": 275.64, "end": 283.0, "text": "nh\\u00e2n v\\u1edbi \\u0111\\u1ea1o h\\u00e0m h\\u01a1i kh\\u00e1c D theo dB c\\u1ee7a J c\\u1ee7a WB."}, {"index": 57, "start": 283.0, "end": 286.68, "text": "V\\u00ec v\\u1eady, h\\u00e3y nh\\u1edb trong \\u0111\\u1ed3 th\\u1ecb c\\u1ee7a bi\\u1ec3u \\u0111\\u1ed3 m\\u1eb7t ph\\u1eb3ng,"}, {"index": 58, "start": 286.68, "end": 290.72, "text": "n\\u01a1i b\\u1ea1n \\u0111ang t\\u1eebng b\\u01b0\\u1edbc ti\\u1ebfn nh\\u1ecf cho \\u0111\\u1ebfn khi \\u0111\\u1ebfn \\u0111\\u00e1y thung l\\u0169ng?"}, {"index": 59, "start": 290.72, "end": 293.36, "text": "Th\\u00ec, \\u0111\\u1ed1i v\\u1edbi thu\\u1eadt to\\u00e1n t\\u1ed1i \\u01b0u h\\u00f3a \\u0111\\u1ed9 d\\u1ed1c,"}, {"index": 60, "start": 293.36, "end": 298.2, "text": "b\\u1ea1n s\\u1ebd l\\u1eb7p l\\u1ea1i hai b\\u01b0\\u1edbc c\\u1eadp nh\\u1eadt n\\u00e0y cho \\u0111\\u1ebfn khi thu\\u1eadt to\\u00e1n h\\u1ed9i t\\u1ee5."}, {"index": 61, "start": 298.2, "end": 303.32, "text": "V\\u00e0 khi t\\u00f4i n\\u00f3i h\\u1ed9i t\\u1ee5, t\\u00f4i c\\u00f3 \\u00fd l\\u00e0 b\\u1ea1n \\u0111\\u1ea1t \\u0111\\u1ebfn \\u0111i\\u1ec3m t\\u1ea1i c\\u1ef1c ti\\u1ec3u \\u0111\\u1ecba ph\\u01b0\\u01a1ng"}, {"index": 62, "start": 303.32, "end": 309.24, "text": "n\\u01a1i m\\u00e0 c\\u00e1c tham s\\u1ed1 W v\\u00e0 B kh\\u00f4ng c\\u00f2n thay \\u0111\\u1ed5i nhi\\u1ec1u v\\u1edbi m\\u1ed7i b\\u01b0\\u1edbc b\\u1ed5 sung m\\u00e0 b\\u1ea1n th\\u1ef1c hi\\u1ec7n."}, {"index": 63, "start": 310.4, "end": 316.64, "text": "B\\u00e2y gi\\u1edd, c\\u00f3 m\\u1ed9t chi ti\\u1ebft tinh t\\u1ebf n\\u1eefa v\\u1ec1 c\\u00e1ch th\\u1ef1c hi\\u1ec7n \\u0111\\u00fang thu\\u1eadt to\\u00e1n gi\\u1ea3m d\\u1ea7n \\u0111\\u1ed9 d\\u1ed1c."}, {"index": 64, "start": 316.64, "end": 320.8, "text": "B\\u1ea1n s\\u1ebd c\\u1eadp nh\\u1eadt hai tham s\\u1ed1 W v\\u00e0 B, ph\\u1ea3i kh\\u00f4ng?"}, {"index": 65, "start": 320.8, "end": 325.0, "text": "V\\u1eady th\\u00ec vi\\u1ec7c c\\u1eadp nh\\u1eadt n\\u00e0y di\\u1ec5n ra \\u0111\\u1ed1i v\\u1edbi c\\u1ea3 hai tham s\\u1ed1 W v\\u00e0 B."}, {"index": 66, "start": 326.28, "end": 331.04, "text": "M\\u1ed9t chi ti\\u1ebft quan tr\\u1ecdng l\\u00e0 \\u0111\\u1ed1i v\\u1edbi thu\\u1eadt to\\u00e1n gi\\u1ea3m d\\u1ea7n \\u0111\\u1ed9 d\\u1ed1c,"}, {"index": 67, "start": 331.04, "end": 335.8, "text": "b\\u1ea1n mu\\u1ed1n \\u0111\\u1ed3ng th\\u1eddi c\\u1eadp nh\\u1eadt W v\\u00e0 B,"}, {"index": 68, "start": 335.8, "end": 340.0, "text": "c\\u00f3 ngh\\u0129a l\\u00e0 b\\u1ea1n mu\\u1ed1n c\\u1eadp nh\\u1eadt c\\u1ea3 hai tham s\\u1ed1 c\\u00f9ng m\\u1ed9t l\\u00fac."}, {"index": 69, "start": 340.0, "end": 343.52, "text": "\\u00dd t\\u00f4i l\\u00e0 trong bi\\u1ec3u th\\u1ee9c n\\u00e0y,"}, {"index": 70, "start": 343.52, "end": 348.64, "text": "b\\u1ea1n s\\u1ebd c\\u1eadp nh\\u1eadt W t\\u1eeb W c\\u0169 sang W m\\u1edbi."}, {"index": 71, "start": 348.64, "end": 355.2, "text": "V\\u00e0 b\\u1ea1n c\\u0169ng c\\u1eadp nh\\u1eadt B t\\u1eeb gi\\u00e1 tr\\u1ecb c\\u0169 c\\u1ee7a n\\u00f3 sang gi\\u00e1 tr\\u1ecb m\\u1edbi c\\u1ee7a B."}, {"index": 72, "start": 355.2, "end": 359.32, "text": "V\\u00e0 c\\u00e1ch th\\u1ef1c hi\\u1ec7n \\u0111i\\u1ec1u n\\u00e0y l\\u00e0 t\\u00ednh to\\u00e1n ph\\u00eda b\\u00ean ph\\u1ea3i,"}, {"index": 73, "start": 359.32, "end": 362.84, "text": "t\\u00ednh to\\u00e1n \\u0111i\\u1ec1u n\\u00e0y cho W v\\u00e0 B,"}, {"index": 74, "start": 362.84, "end": 365.92, "text": "v\\u00e0 \\u0111\\u1ed3ng th\\u1eddi c\\u00f9ng m\\u1ed9t l\\u00fac,"}, {"index": 75, "start": 365.92, "end": 370.52, "text": "c\\u1eadp nh\\u1eadt W v\\u00e0 B \\u0111\\u1ebfn c\\u00e1c gi\\u00e1 tr\\u1ecb m\\u1edbi."}, {"index": 76, "start": 370.52, "end": 374.16, "text": "V\\u1eady h\\u00e3y c\\u00f9ng xem \\u0111i\\u1ec1u n\\u00e0y c\\u00f3 ngh\\u0129a l\\u00e0 g\\u00ec."}, {"index": 77, "start": 374.16, "end": 377.32, "text": "\\u0110\\u00e2y l\\u00e0 c\\u00e1ch \\u0111\\u00fang \\u0111\\u1ec3 th\\u1ef1c hi\\u1ec7n thu\\u1eadt to\\u00e1n gi\\u1ea3m d\\u1ea7n \\u0111\\u1ed9 d\\u1ed1c,"}, {"index": 78, "start": 377.32, "end": 380.12, "text": "m\\u00e0 th\\u1ef1c hi\\u1ec7n m\\u1ed9t c\\u1eadp nh\\u1eadt \\u0111\\u1ed3ng th\\u1eddi."}, {"index": 79, "start": 380.12, "end": 384.64, "text": "\\u0110i\\u1ec1u n\\u00e0y g\\u00e1n m\\u1ed9t bi\\u1ebfn tempW b\\u1eb1ng v\\u1edbi bi\\u1ec3u th\\u1ee9c \\u0111\\u00f3,"}, {"index": 80, "start": 384.64, "end": 388.0, "text": "c\\u00e1i n\\u00e0y l\\u00e0 W tr\\u1eeb \\u0111i h\\u1ea1ng m\\u1ee5c \\u0111\\u00f3 \\u1edf \\u0111\\u00e2y."}, {"index": 81, "start": 388.04, "end": 391.52, "text": "Ch\\u00fang ta c\\u0169ng \\u0111\\u1eb7t m\\u1ed9t bi\\u1ebfn kh\\u00e1c, tempB b\\u1eb1ng c\\u00e1i \\u0111\\u00f3,"}, {"index": 82, "start": 391.52, "end": 393.92, "text": "c\\u00e1i n\\u00e0y l\\u00e0 B tr\\u1eeb \\u0111i h\\u1ea1ng m\\u1ee5c \\u0111\\u00f3."}, {"index": 83, "start": 393.92, "end": 396.88, "text": "V\\u1eady b\\u1ea1n t\\u00ednh c\\u1ea3 hai b\\u00ean ph\\u1ea3i, c\\u1ea3 hai c\\u1eadp nh\\u1eadt,"}, {"index": 84, "start": 396.88, "end": 401.56, "text": "v\\u00e0 l\\u01b0u ch\\u00fang v\\u00e0o c\\u00e1c bi\\u1ebfn tempW v\\u00e0 tempB."}, {"index": 85, "start": 401.56, "end": 406.96, "text": "Sau \\u0111\\u00f3, b\\u1ea1n sao ch\\u00e9p gi\\u00e1 tr\\u1ecb c\\u1ee7a tempW v\\u00e0o W,"}, {"index": 86, "start": 406.96, "end": 411.92, "text": "v\\u00e0 b\\u1ea1n c\\u0169ng sao ch\\u00e9p gi\\u00e1 tr\\u1ecb c\\u1ee7a tempB v\\u00e0o B."}, {"index": 87, "start": 411.92, "end": 413.72, "text": "B\\u00e2y gi\\u1edd, m\\u1ed9t \\u0111i\\u1ec1u b\\u1ea1n c\\u00f3 th\\u1ec3 nh\\u1eadn th\\u1ea5y"}, {"index": 88, "start": 413.72, "end": 420.64, "text": "l\\u00e0 gi\\u00e1 tr\\u1ecb c\\u1ee7a W n\\u00e0y l\\u00e0 t\\u1eeb tr\\u01b0\\u1edbc khi W \\u0111\\u01b0\\u1ee3c c\\u1eadp nh\\u1eadt."}, {"index": 89, "start": 420.64, "end": 423.68, "text": "\\u1ede \\u0111\\u00e2y, h\\u00e3y nh\\u1eadn x\\u00e9t r\\u1eb1ng W tr\\u01b0\\u1edbc khi c\\u1eadp nh\\u1eadt"}, {"index": 90, "start": 423.68, "end": 428.48, "text": "l\\u00e0 c\\u00e1i \\u0111\\u01b0\\u1ee3c \\u0111\\u01b0a v\\u00e0o h\\u1ea1ng m\\u1ee5c \\u0111\\u1ea1o h\\u00e0m \\u1edf \\u0111\\u00e2y, hi\\u1ec3u ch\\u1ee9?"}, {"index": 91, "start": 428.48, "end": 431.88, "text": "Ng\\u01b0\\u1ee3c l\\u1ea1i, \\u0111\\u00e2y l\\u00e0 m\\u1ed9t tri\\u1ec3n khai sai"}, {"index": 92, "start": 431.88, "end": 436.16, "text": "c\\u1ee7a ph\\u01b0\\u01a1ng ph\\u00e1p gi\\u1ea3m d\\u1ea7n m\\u00e0 kh\\u00f4ng th\\u1ef1c hi\\u1ec7n c\\u1eadp nh\\u1eadt \\u0111\\u1ed3ng th\\u1eddi."}, {"index": 93, "start": 436.16, "end": 438.52, "text": "Trong tri\\u1ec3n khai sai n\\u00e0y,"}, {"index": 94, "start": 438.56, "end": 443.84, "text": "ch\\u00fang ta t\\u00ednh to\\u00e1n tempW gi\\u1ed1ng nh\\u01b0 tr\\u01b0\\u1edbc, cho \\u0111\\u1ebfn b\\u00e2y gi\\u1edd th\\u00ec OK."}, {"index": 95, "start": 443.84, "end": 447.08, "text": "V\\u00e0 b\\u00e2y gi\\u1edd, \\u0111\\u00e2y l\\u00e0 n\\u01a1i m\\u1ecdi th\\u1ee9 b\\u1eaft \\u0111\\u1ea7u kh\\u00e1c bi\\u1ec7t."}, {"index": 96, "start": 447.08, "end": 451.12, "text": "Sau \\u0111\\u00f3, ch\\u00fang ta c\\u1eadp nh\\u1eadt W v\\u1edbi gi\\u00e1 tr\\u1ecb trong tempW"}, {"index": 97, "start": 451.12, "end": 456.08, "text": "tr\\u01b0\\u1edbc khi t\\u00ednh to\\u00e1n gi\\u00e1 tr\\u1ecb m\\u1edbi cho tham s\\u1ed1 kh\\u00e1c B."}, {"index": 98, "start": 456.08, "end": 460.68, "text": "Ti\\u1ebfp theo, ch\\u00fang ta t\\u00ednh to\\u00e1n tempB b\\u1eb1ng B tr\\u1eeb \\u0111i h\\u1ea1ng m\\u1ee5c \\u0111\\u00f3 \\u1edf \\u0111\\u00e2y."}, {"index": 99, "start": 460.68, "end": 465.72, "text": "V\\u00e0 cu\\u1ed1i c\\u00f9ng, ch\\u00fang ta c\\u1eadp nh\\u1eadt B v\\u1edbi gi\\u00e1 tr\\u1ecb trong tempB."}, {"index": 100, "start": 465.72, "end": 467.32, "text": "S\\u1ef1 kh\\u00e1c bi\\u1ec7t gi\\u1eefa b\\u00ean ph\\u1ea3i"}, {"index": 101, "start": 467.32, "end": 469.28, "text": "v\\u00e0 b\\u00ean tr\\u00e1i trong c\\u00e1c tri\\u1ec3n khai"}, {"index": 102, "start": 469.28, "end": 471.56, "text": "l\\u00e0 n\\u1ebfu b\\u1ea1n nh\\u00ecn \\u1edf \\u0111\\u00e2y,"}, {"index": 103, "start": 471.56, "end": 476.12, "text": "th\\u00ec W n\\u00e0y \\u0111\\u00e3 \\u0111\\u01b0\\u1ee3c c\\u1eadp nh\\u1eadt v\\u1edbi gi\\u00e1 tr\\u1ecb m\\u1edbi n\\u00e0y,"}, {"index": 104, "start": 476.12, "end": 479.36, "text": "v\\u00e0 ch\\u00ednh W \\u0111\\u00e3 \\u0111\\u01b0\\u1ee3c c\\u1eadp nh\\u1eadt n\\u00e0y s\\u1ebd"}, {"index": 105, "start": 479.36, "end": 483.36, "text": "\\u0111\\u01b0\\u1ee3c \\u0111\\u01b0a v\\u00e0o h\\u00e0m const j c\\u1ee7a WB."}, {"index": 106, "start": 483.36, "end": 485.36, "text": "\\u0110i\\u1ec1u \\u0111\\u00f3 c\\u00f3 ngh\\u0129a l\\u00e0 thu\\u1eadt ng\\u1eef n\\u00e0y \\u1edf b\\u00ean ph\\u1ea3i"}, {"index": 107, "start": 485.36, "end": 488.6, "text": "kh\\u00f4ng gi\\u1ed1ng nh\\u01b0 thu\\u1eadt ng\\u1eef n\\u00e0y \\u1edf b\\u00ean tr\\u00e1i"}, {"index": 108, "start": 488.6, "end": 491.04, "text": "m\\u00e0 b\\u1ea1n th\\u1ea5y b\\u00ean tr\\u00e1i."}, {"index": 109, "start": 491.04, "end": 496.04, "text": "V\\u00e0 \\u0111i\\u1ec1u \\u0111\\u00f3 c\\u0169ng c\\u00f3 ngh\\u0129a l\\u00e0 thu\\u1eadt ng\\u1eef tempB n\\u00e0y b\\u00ean ph\\u1ea3i"}, {"index": 110, "start": 496.04, "end": 500.24, "text": "kh\\u00f4ng ho\\u00e0n to\\u00e0n gi\\u1ed1ng v\\u1edbi thu\\u1eadt ng\\u1eef tempB b\\u00ean tr\\u00e1i,"}, {"index": 111, "start": 500.24, "end": 503.16, "text": "v\\u00e0 do \\u0111\\u00f3, gi\\u00e1 tr\\u1ecb \\u0111\\u00e3 c\\u1eadp nh\\u1eadt cho B b\\u00ean ph\\u1ea3i"}, {"index": 112, "start": 503.16, "end": 506.24, "text": "kh\\u00f4ng gi\\u1ed1ng v\\u1edbi gi\\u00e1 tr\\u1ecb \\u0111\\u00e3 c\\u1eadp nh\\u1eadt n\\u00e0y"}, {"index": 113, "start": 506.24, "end": 509.6, "text": "cho bi\\u1ebfn B b\\u00ean tr\\u00e1i."}, {"index": 114, "start": 509.6, "end": 512.24, "text": "C\\u00e1ch m\\u00e0 thu\\u1eadt to\\u00e1n gradient descent \\u0111\\u01b0\\u1ee3c tri\\u1ec3n khai trong m\\u00e3,"}, {"index": 115, "start": 512.24, "end": 514.68, "text": "h\\u00f3a ra l\\u00e0 t\\u1ef1 nhi\\u00ean h\\u01a1n"}, {"index": 116, "start": 514.68, "end": 520.16, "text": "khi tri\\u1ec3n khai \\u0111\\u00fang c\\u00e1ch v\\u1edbi c\\u00e1c c\\u1eadp nh\\u1eadt \\u0111\\u1ed3ng th\\u1eddi."}, {"index": 117, "start": 520.16, "end": 522.72, "text": "Khi b\\u1ea1n nghe ai \\u0111\\u00f3 n\\u00f3i v\\u1ec1 gradient descent,"}, {"index": 118, "start": 522.72, "end": 524.72, "text": "h\\u1ecd lu\\u00f4n c\\u00f3 \\u00fd ngh\\u0129a \\u0111\\u1ebfn gradient descent"}, {"index": 119, "start": 524.72, "end": 528.76, "text": "n\\u01a1i b\\u1ea1n th\\u1ef1c hi\\u1ec7n c\\u1eadp nh\\u1eadt \\u0111\\u1ed3ng th\\u1eddi c\\u00e1c tham s\\u1ed1."}, {"index": 120, "start": 528.76, "end": 531.56, "text": "Tuy nhi\\u00ean, n\\u1ebfu b\\u1ea1n th\\u1ef1c hi\\u1ec7n"}, {"index": 121, "start": 531.56, "end": 533.56, "text": "c\\u1eadp nh\\u1eadt kh\\u00f4ng \\u0111\\u1ed3ng th\\u1eddi,"}, {"index": 122, "start": 533.56, "end": 537.48, "text": "th\\u00ec c\\u00f3 th\\u1ec3 n\\u00f3 s\\u1ebd ho\\u1ea1t \\u0111\\u1ed9ng h\\u01a1n ho\\u1eb7c k\\u00e9m, b\\u1ea5t k\\u1ec3 th\\u1ebf n\\u00e0o,"}, {"index": 123, "start": 537.48, "end": 538.68, "text": "nh\\u01b0ng l\\u00e0m theo c\\u00e1ch n\\u00e0y"}, {"index": 124, "start": 538.68, "end": 541.12, "text": "th\\u1ef1c s\\u1ef1 kh\\u00f4ng ph\\u1ea3i l\\u00e0 c\\u00e1ch \\u0111\\u00fang \\u0111\\u1ec3 th\\u1ef1c hi\\u1ec7n,"}, {"index": 125, "start": 541.12, "end": 544.44, "text": "n\\u00f3 th\\u1ef1c s\\u1ef1 l\\u00e0 m\\u1ed9t thu\\u1eadt to\\u00e1n kh\\u00e1c v\\u1edbi c\\u00e1c thu\\u1ed9c t\\u00ednh kh\\u00e1c."}, {"index": 126, "start": 544.44, "end": 546.4, "text": "V\\u00ec v\\u1eady, t\\u00f4i khuy\\u00ean b\\u1ea1n ch\\u1ec9 n\\u00ean duy tr\\u00ec"}, {"index": 127, "start": 546.4, "end": 548.8, "text": "c\\u1eadp nh\\u1eadt \\u0111\\u1ed3ng th\\u1eddi \\u0111\\u00fang c\\u00e1ch"}, {"index": 128, "start": 548.8, "end": 552.88, "text": "v\\u00e0 kh\\u00f4ng s\\u1eed d\\u1ee5ng phi\\u00ean b\\u1ea3n sai n\\u00e0y b\\u00ean ph\\u1ea3i."}, {"index": 129, "start": 552.88, "end": 555.04, "text": "\\u0110\\u1ea5y l\\u00e0 ph\\u01b0\\u01a1ng ph\\u00e1p gi\\u1ea3m d\\u1ea7n."}, {"index": 130, "start": 555.04, "end": 558.76, "text": "Trong video ti\\u1ebfp theo, ch\\u00fang ta s\\u1ebd \\u0111i s\\u00e2u v\\u00e0o chi ti\\u1ebft v\\u1ec1 h\\u1ea1ng t\\u1eed \\u0111\\u1ea1o h\\u00e0m,"}, {"index": 131, "start": 558.76, "end": 560.36, "text": "m\\u00e0 b\\u1ea1n \\u0111\\u00e3 th\\u1ea5y trong video n\\u00e0y,"}, {"index": 132, "start": 560.36, "end": 563.36, "text": "nh\\u01b0ng m\\u00e0 ch\\u00fang ta ch\\u01b0a th\\u1ef1c s\\u1ef1 n\\u00f3i v\\u1ec1 chi ti\\u1ebft."}, {"index": 133, "start": 563.36, "end": 565.6, "text": "\\u0110\\u1ea1o h\\u00e0m l\\u00e0 m\\u1ed9t ph\\u1ea7n c\\u1ee7a gi\\u1ea3i t\\u00edch,"}, {"index": 134, "start": 565.6, "end": 568.0, "text": "v\\u00e0 n\\u1ebfu b\\u1ea1n kh\\u00f4ng quen thu\\u1ed9c v\\u1edbi gi\\u1ea3i t\\u00edch,"}, {"index": 135, "start": 568.0, "end": 569.36, "text": "\\u0111\\u1eebng lo l\\u1eafng v\\u1ec1 \\u0111i\\u1ec1u \\u0111\\u00f3."}, {"index": 136, "start": 569.36, "end": 571.24, "text": "B\\u1ea1n s\\u1ebd kh\\u00f4ng c\\u1ea7n ph\\u1ea3i bi\\u1ebft gi\\u1ea3i t\\u00edch"}, {"index": 137, "start": 571.24, "end": 574.76, "text": "\\u0111\\u1ec3 ho\\u00e0n th\\u00e0nh kh\\u00f3a h\\u1ecdc ho\\u1eb7c chuy\\u00ean ng\\u00e0nh n\\u00e0y,"}, {"index": 138, "start": 574.76, "end": 576.92, "text": "v\\u00e0 b\\u1ea1n s\\u1ebd c\\u00f3 t\\u1ea5t c\\u1ea3 th\\u00f4ng tin c\\u1ea7n thi\\u1ebft"}, {"index": 139, "start": 576.92, "end": 580.08, "text": "\\u0111\\u1ec3 th\\u1ef1c hi\\u1ec7n ph\\u01b0\\u01a1ng ph\\u00e1p gi\\u1ea3m d\\u1ea7n."}, {"index": 140, "start": 580.08, "end": 581.52, "text": "Trong video ti\\u1ebfp theo,"}, {"index": 141, "start": 581.52, "end": 584.08, "text": "ch\\u00fang ta s\\u1ebd c\\u00f9ng nhau t\\u00ecm hi\\u1ec3u v\\u1ec1 \\u0111\\u1ea1o h\\u00e0m,"}, {"index": 142, "start": 584.08, "end": 587.6, "text": "v\\u00e0 b\\u1ea1n s\\u1ebd c\\u00f3 \\u0111\\u01b0\\u1ee3c tr\\u1ef1c gi\\u00e1c v\\u00e0 ki\\u1ebfn th\\u1ee9c c\\u1ea7n thi\\u1ebft"}, {"index": 143, "start": 587.6, "end": 592.28, "text": "\\u0111\\u1ec3 c\\u00f3 th\\u1ec3 t\\u1ef1 implement v\\u00e0 \\u00e1p d\\u1ee5ng ph\\u01b0\\u01a1ng ph\\u00e1p gi\\u1ea3m \\u0111\\u1ed9 d\\u1ed1c."}, {"index": 144, "start": 592.28, "end": 593.96, "text": "T\\u00f4i ngh\\u0129 \\u0111\\u00f3 s\\u1ebd l\\u00e0 \\u0111i\\u1ec1u th\\u00fa v\\u1ecb"}, {"index": 145, "start": 593.96, "end": 595.72, "text": "\\u0111\\u1ec3 b\\u1ea1n bi\\u1ebft c\\u00e1ch implement."}, {"index": 146, "start": 595.72, "end": 598.92, "text": "V\\u1eady h\\u00e3y c\\u00f9ng chuy\\u1ec3n sang video ti\\u1ebfp theo \\u0111\\u1ec3 xem c\\u00e1ch th\\u1ef1c hi\\u1ec7n."}], "segments_by_language": {"en": [{"index": 0, "start": 0.0, "end": 9.96, "text": "Let's take a look at how you can actually implement the gradient descent algorithm."}, {"index": 1, "start": 9.96, "end": 14.2, "text": "Let me write down the gradient descent algorithm."}, {"index": 2, "start": 14.2, "end": 15.32, "text": "Here it is."}, {"index": 3, "start": 15.32, "end": 25.16, "text": "On each step, w, the parameter, is updated to the old value of w minus alpha times this"}, {"index": 4, "start": 25.16, "end": 30.72, "text": "term d over dw of the cos function j of wb."}, {"index": 5, "start": 30.72, "end": 36.68, "text": "So what this expression is saying is, update your parameter w by taking the current value"}, {"index": 6, "start": 36.68, "end": 44.36, "text": "of w and adjusting it a small amount, which is this expression on the right, minus alpha"}, {"index": 7, "start": 44.36, "end": 49.24, "text": "times this term over here, okay?"}, {"index": 8, "start": 49.24, "end": 54.6, "text": "So if you feel like there's a lot going on in this equation, it's okay, don't worry"}, {"index": 9, "start": 54.6, "end": 58.0, "text": "about it, we'll unpack it together."}, {"index": 10, "start": 58.0, "end": 61.8, "text": "First, this equal notation here."}, {"index": 11, "start": 61.8, "end": 66.6, "text": "Notice I said we're assigning w a value using this equal sign."}, {"index": 12, "start": 66.6, "end": 72.16, "text": "So in this context, this equal sign is the assignment operator."}, {"index": 13, "start": 72.16, "end": 78.84, "text": "Specifically in this context, if you write code that says a equals c, it means take"}, {"index": 14, "start": 78.84, "end": 84.0, "text": "the value of c and store it in your computer in the variable a."}, {"index": 15, "start": 84.04, "end": 88.6, "text": "Or if you write a equals a plus one, it means set the value of a to be equal"}, {"index": 16, "start": 88.6, "end": 93.6, "text": "to a plus one, or increment the value of a by one."}, {"index": 17, "start": 93.6, "end": 100.08, "text": "So the assignment operator in coding is different than truth assertions in"}, {"index": 18, "start": 100.08, "end": 106.44, "text": "mathematics, where if I write a equals c, I'm asserting that is I am claiming"}, {"index": 19, "start": 106.44, "end": 110.32, "text": "that the values of a and c are equal to each other."}, {"index": 20, "start": 110.32, "end": 114.4, "text": "And hopefully I will never write a truth assertion a equals a plus one,"}, {"index": 21, "start": 114.4, "end": 116.84, "text": "because that just can't possibly be true."}, {"index": 22, "start": 118.16, "end": 121.4, "text": "So in Python and in other programming languages,"}, {"index": 23, "start": 121.4, "end": 125.84, "text": "truth assertions are sometimes written as equals equals."}, {"index": 24, "start": 125.84, "end": 130.64, "text": "So you may see code that says a equals equals c if you're testing"}, {"index": 25, "start": 130.64, "end": 132.84, "text": "whether a is equal to c."}, {"index": 26, "start": 132.84, "end": 136.12, "text": "But in math notation as we conventionally use it,"}, {"index": 27, "start": 136.12, "end": 140.96, "text": "like in these videos, the equals sign can be used for either assignment"}, {"index": 28, "start": 140.96, "end": 143.28, "text": "or for truth assertion."}, {"index": 29, "start": 143.28, "end": 147.0, "text": "And so I'll try to make sure it's clear when I write an equals sign,"}, {"index": 30, "start": 147.0, "end": 150.16, "text": "whether we're assigning a value to a variable, or whether we're"}, {"index": 31, "start": 150.16, "end": 154.12, "text": "asserting the truth of the equality of two values."}, {"index": 32, "start": 155.44, "end": 160.48, "text": "Now, let's dive more deeply into what the symbols in this equation means."}, {"index": 33, "start": 160.48, "end": 165.32, "text": "The symbol here is the Greek alphabet alpha."}, {"index": 34, "start": 165.32, "end": 171.12, "text": "And in this equation, alpha is also called the learning rate."}, {"index": 35, "start": 171.12, "end": 175.64, "text": "The learning rate is usually a small positive number between zero and one."}, {"index": 36, "start": 175.64, "end": 178.28, "text": "And it might be say 0.01."}, {"index": 37, "start": 179.72, "end": 184.76, "text": "What alpha does is it basically controls how big of a step you take downhill."}, {"index": 38, "start": 185.88, "end": 191.04, "text": "So if alpha is very large, then that corresponds to a very aggressive"}, {"index": 39, "start": 191.04, "end": 195.8, "text": "gradient descent procedure where you're trying to take huge steps downhill."}, {"index": 40, "start": 195.8, "end": 201.12, "text": "And if alpha is very small, then you'll be taking small baby steps downhill."}, {"index": 41, "start": 201.12, "end": 206.92, "text": "We'll come back later to delve more deeply into how to choose a good learning rate alpha."}, {"index": 42, "start": 206.92, "end": 213.6, "text": "And finally, this term here, that's the derivative term of the cost function J."}, {"index": 43, "start": 213.6, "end": 217.04, "text": "Let's not worry about the details of this derivative right now,"}, {"index": 44, "start": 217.04, "end": 221.08, "text": "but later on, you get to see more about the derivative term."}, {"index": 45, "start": 221.08, "end": 225.88, "text": "But for now, you can think of this derivative term that I drew a magenta box around"}, {"index": 46, "start": 225.88, "end": 229.8, "text": "as telling you in which direction you want to take your baby step."}, {"index": 47, "start": 229.8, "end": 233.4, "text": "And in combination with the learning rate alpha,"}, {"index": 48, "start": 233.4, "end": 236.76, "text": "it also determines the size of the steps you want to take downhill."}, {"index": 49, "start": 238.44, "end": 242.92, "text": "Now, I do want to mention that derivatives come from calculus."}, {"index": 50, "start": 242.92, "end": 246.44, "text": "And even if you aren't familiar with calculus, don't worry about it."}, {"index": 51, "start": 247.16, "end": 251.12, "text": "Even without knowing any calculus, you'll be able to figure out all you need to know"}, {"index": 52, "start": 251.12, "end": 254.32, "text": "about this derivative term in this video and the mix."}, {"index": 53, "start": 255.48, "end": 262.04, "text": "One more thing, remember your model has two parameters, not just W, but also B."}, {"index": 54, "start": 262.04, "end": 268.92, "text": "So you also have an assignment operation to update the parameter B that looks very similar."}, {"index": 55, "start": 268.92, "end": 275.64, "text": "B is assigned the old value of B minus the learning rate alpha"}, {"index": 56, "start": 275.64, "end": 283.0, "text": "times this slightly different derivative term D over dB of J of WB."}, {"index": 57, "start": 283.0, "end": 286.68, "text": "So remember in the graph of the surface plot,"}, {"index": 58, "start": 286.68, "end": 290.72, "text": "where you're taking baby steps until you get to the bottom of the valley?"}, {"index": 59, "start": 290.72, "end": 293.36, "text": "Well, for the gradient descent algorithm,"}, {"index": 60, "start": 293.36, "end": 298.2, "text": "you're going to repeat these two update steps until the algorithm converges."}, {"index": 61, "start": 298.2, "end": 303.32, "text": "And by converges, I mean that you reach the point at the local minimum"}, {"index": 62, "start": 303.32, "end": 309.24, "text": "where the parameters W and B no longer change much with each additional step that you take."}, {"index": 63, "start": 310.4, "end": 316.64, "text": "Now, there's one more subtle detail about how to correctly implement gradient descent."}, {"index": 64, "start": 316.64, "end": 320.8, "text": "You're going to update two parameters W and B, right?"}, {"index": 65, "start": 320.8, "end": 325.0, "text": "So this update takes place for both parameters W and B."}, {"index": 66, "start": 326.28, "end": 331.04, "text": "One important detail is that for gradient descent,"}, {"index": 67, "start": 331.04, "end": 335.8, "text": "you want to simultaneously update W and B,"}, {"index": 68, "start": 335.8, "end": 340.0, "text": "meaning you want to update both parameters at the same time."}, {"index": 69, "start": 340.0, "end": 343.52, "text": "What I mean by that is that in this expression,"}, {"index": 70, "start": 343.52, "end": 348.64, "text": "you're going to update W from the old W to a new W."}, {"index": 71, "start": 348.64, "end": 355.2, "text": "And you're also updating B from its old value to a new value of B."}, {"index": 72, "start": 355.2, "end": 359.32, "text": "And the way to implement this is to compute the right side,"}, {"index": 73, "start": 359.32, "end": 362.84, "text": "computing this thing for W and B,"}, {"index": 74, "start": 362.84, "end": 365.92, "text": "and simultaneously at the same time,"}, {"index": 75, "start": 365.92, "end": 370.52, "text": "update W and B to the new values."}, {"index": 76, "start": 370.52, "end": 374.16, "text": "So let's take a look at what this means."}, {"index": 77, "start": 374.16, "end": 377.32, "text": "Here's the correct way to implement gradient descent,"}, {"index": 78, "start": 377.32, "end": 380.12, "text": "which does a simultaneous update."}, {"index": 79, "start": 380.12, "end": 384.64, "text": "This sets a variable tempW equal to that expression,"}, {"index": 80, "start": 384.64, "end": 388.0, "text": "which is W minus that term here."}, {"index": 81, "start": 388.04, "end": 391.52, "text": "Let's also set another variable, tempB to that,"}, {"index": 82, "start": 391.52, "end": 393.92, "text": "which is B minus that term."}, {"index": 83, "start": 393.92, "end": 396.88, "text": "So you compute both right-hand sides, both updates,"}, {"index": 84, "start": 396.88, "end": 401.56, "text": "and store them into variables tempW and tempB."}, {"index": 85, "start": 401.56, "end": 406.96, "text": "Then you copy the value of tempW into W,"}, {"index": 86, "start": 406.96, "end": 411.92, "text": "and you also copy the value of tempB into B."}, {"index": 87, "start": 411.92, "end": 413.72, "text": "Now, one thing you may notice"}, {"index": 88, "start": 413.72, "end": 420.64, "text": "is that this value of W is from before W gets updated."}, {"index": 89, "start": 420.64, "end": 423.68, "text": "Here, notice that the pre-update W"}, {"index": 90, "start": 423.68, "end": 428.48, "text": "is what goes into the derivative term over here, OK?"}, {"index": 91, "start": 428.48, "end": 431.88, "text": "In contrast, here's an incorrect implementation"}, {"index": 92, "start": 431.88, "end": 436.16, "text": "of gradient descent that does not do a simultaneous update."}, {"index": 93, "start": 436.16, "end": 438.52, "text": "In this incorrect implementation,"}, {"index": 94, "start": 438.56, "end": 443.84, "text": "we compute tempW same as before, so far that's OK."}, {"index": 95, "start": 443.84, "end": 447.08, "text": "And now, here's where things start to differ."}, {"index": 96, "start": 447.08, "end": 451.12, "text": "We then update W with the value in tempW"}, {"index": 97, "start": 451.12, "end": 456.08, "text": "before calculating the new value for the other parameter B."}, {"index": 98, "start": 456.08, "end": 460.68, "text": "Next, we calculate tempB as B minus that term here."}, {"index": 99, "start": 460.68, "end": 465.72, "text": "And finally, we update B with the value in tempB."}, {"index": 100, "start": 465.72, "end": 467.32, "text": "The difference between the right-hand side"}, {"index": 101, "start": 467.32, "end": 469.28, "text": "and the left-hand side implementations"}, {"index": 102, "start": 469.28, "end": 471.56, "text": "is that if you look over here,"}, {"index": 103, "start": 471.56, "end": 476.12, "text": "this W has already been updated to this new value,"}, {"index": 104, "start": 476.12, "end": 479.36, "text": "and it's this updated W that actually goes"}, {"index": 105, "start": 479.36, "end": 483.36, "text": "into the const function j of WB."}, {"index": 106, "start": 483.36, "end": 485.36, "text": "It means that this term here on the right"}, {"index": 107, "start": 485.36, "end": 488.6, "text": "is not the same as this term over here"}, {"index": 108, "start": 488.6, "end": 491.04, "text": "that you see on the left."}, {"index": 109, "start": 491.04, "end": 496.04, "text": "And that also means this tempB term on the right"}, {"index": 110, "start": 496.04, "end": 500.24, "text": "is not quite the same as the tempB term on the left,"}, {"index": 111, "start": 500.24, "end": 503.16, "text": "and thus this updated value for B on the right"}, {"index": 112, "start": 503.16, "end": 506.24, "text": "is not the same as this updated value"}, {"index": 113, "start": 506.24, "end": 509.6, "text": "for variable B on the left."}, {"index": 114, "start": 509.6, "end": 512.24, "text": "The way that gradient descent is implemented in code,"}, {"index": 115, "start": 512.24, "end": 514.68, "text": "it actually turns out to be more natural"}, {"index": 116, "start": 514.68, "end": 520.16, "text": "to implement it the correct way with simultaneous updates."}, {"index": 117, "start": 520.16, "end": 522.72, "text": "When you hear someone talk about gradient descent,"}, {"index": 118, "start": 522.72, "end": 524.72, "text": "they always mean the gradient descent"}, {"index": 119, "start": 524.72, "end": 528.76, "text": "where you perform a simultaneous update of the parameters."}, {"index": 120, "start": 528.76, "end": 531.56, "text": "If, however, you were to implement"}, {"index": 121, "start": 531.56, "end": 533.56, "text": "non-simultaneous update,"}, {"index": 122, "start": 533.56, "end": 537.48, "text": "it turns out it will probably work more or less anyway,"}, {"index": 123, "start": 537.48, "end": 538.68, "text": "but doing it this way"}, {"index": 124, "start": 538.68, "end": 541.12, "text": "isn't really the correct way to implement it,"}, {"index": 125, "start": 541.12, "end": 544.44, "text": "it's actually some other algorithm with different properties."}, {"index": 126, "start": 544.44, "end": 546.4, "text": "So I would advise you to just stick"}, {"index": 127, "start": 546.4, "end": 548.8, "text": "to the correct simultaneous update"}, {"index": 128, "start": 548.8, "end": 552.88, "text": "and not use this incorrect version on the right."}, {"index": 129, "start": 552.88, "end": 555.04, "text": "So that's gradient descent."}, {"index": 130, "start": 555.04, "end": 558.76, "text": "In the next video, we'll go into details of the derivative term,"}, {"index": 131, "start": 558.76, "end": 560.36, "text": "which you saw in this video,"}, {"index": 132, "start": 560.36, "end": 563.36, "text": "but that we didn't really talk about in detail."}, {"index": 133, "start": 563.36, "end": 565.6, "text": "Derivatives are a part of calculus,"}, {"index": 134, "start": 565.6, "end": 568.0, "text": "and again, if you're not familiar with calculus,"}, {"index": 135, "start": 568.0, "end": 569.36, "text": "don't worry about it."}, {"index": 136, "start": 569.36, "end": 571.24, "text": "You won't need to know calculus at all"}, {"index": 137, "start": 571.24, "end": 574.76, "text": "in order to complete this course or this specialization,"}, {"index": 138, "start": 574.76, "end": 576.92, "text": "and you'll have all the information you need"}, {"index": 139, "start": 576.92, "end": 580.08, "text": "in order to implement gradient descent."}, {"index": 140, "start": 580.08, "end": 581.52, "text": "Coming up in the next video,"}, {"index": 141, "start": 581.52, "end": 584.08, "text": "we'll go over derivatives together,"}, {"index": 142, "start": 584.08, "end": 587.6, "text": "and you come away with the intuition and knowledge you need"}, {"index": 143, "start": 587.6, "end": 592.28, "text": "to be able to implement and apply gradient descent yourself."}, {"index": 144, "start": 592.28, "end": 593.96, "text": "I think that'll be an exciting thing"}, {"index": 145, "start": 593.96, "end": 595.72, "text": "for you to know how to implement."}, {"index": 146, "start": 595.72, "end": 598.92, "text": "So let's go on to the next video to see how to do that."}], "vi": [{"index": 0, "start": 0.0, "end": 9.96, "text": "H\\u00e3y c\\u00f9ng xem c\\u00e1ch b\\u1ea1n c\\u00f3 th\\u1ec3 th\\u1ef1c s\\u1ef1 tri\\u1ec3n khai thu\\u1eadt to\\u00e1n gradient descent."}, {"index": 1, "start": 9.96, "end": 14.2, "text": "H\\u00e3y \\u0111\\u1ec3 t\\u00f4i ghi l\\u1ea1i thu\\u1eadt to\\u00e1n gradient descent."}, {"index": 2, "start": 14.2, "end": 15.32, "text": "\\u0110\\u00e2y r\\u1ed3i."}, {"index": 3, "start": 15.32, "end": 25.16, "text": "\\u1ede m\\u1ed7i b\\u01b0\\u1edbc, w, tham s\\u1ed1, \\u0111\\u01b0\\u1ee3c c\\u1eadp nh\\u1eadt th\\u00e0nh gi\\u00e1 tr\\u1ecb c\\u0169 c\\u1ee7a w tr\\u1eeb \\u0111i alpha nh\\u00e2n v\\u1edbi c\\u00e1i n\\u00e0y"}, {"index": 4, "start": 25.16, "end": 30.72, "text": "thu\\u1eadt ng\\u1eef d tr\\u00ean dw c\\u1ee7a h\\u00e0m cos j c\\u1ee7a wb."}, {"index": 5, "start": 30.72, "end": 36.68, "text": "V\\u1eady bi\\u1ec3u th\\u1ee9c n\\u00e0y \\u0111ang n\\u00f3i r\\u1eb1ng, h\\u00e3y c\\u1eadp nh\\u1eadt tham s\\u1ed1 w c\\u1ee7a b\\u1ea1n b\\u1eb1ng c\\u00e1ch l\\u1ea5y gi\\u00e1 tr\\u1ecb hi\\u1ec7n t\\u1ea1i"}, {"index": 6, "start": 36.68, "end": 44.36, "text": "c\\u1ee7a w v\\u00e0 \\u0111i\\u1ec1u ch\\u1ec9nh n\\u00f3 m\\u1ed9t ch\\u00fat, \\u0111i\\u1ec1u n\\u00e0y l\\u00e0 bi\\u1ec3u th\\u1ee9c \\u1edf b\\u00ean ph\\u1ea3i, tr\\u1eeb \\u0111i alpha"}, {"index": 7, "start": 44.36, "end": 49.24, "text": "nh\\u00e2n v\\u1edbi thu\\u1eadt ng\\u1eef n\\u00e0y \\u1edf \\u0111\\u00e2y, \\u0111\\u01b0\\u1ee3c ch\\u1ee9?"}, {"index": 8, "start": 49.24, "end": 54.6, "text": "N\\u1ebfu b\\u1ea1n c\\u1ea3m th\\u1ea5y c\\u00f3 r\\u1ea5t nhi\\u1ec1u \\u0111i\\u1ec1u x\\u1ea3y ra trong ph\\u01b0\\u01a1ng tr\\u00ecnh n\\u00e0y, kh\\u00f4ng sao c\\u1ea3, \\u0111\\u1eebng lo l\\u1eafng"}, {"index": 9, "start": 54.6, "end": 58.0, "text": "v\\u1ec1 n\\u00f3, ch\\u00fang ta s\\u1ebd gi\\u1ea3i th\\u00edch c\\u00f9ng nhau."}, {"index": 10, "start": 58.0, "end": 61.8, "text": "\\u0110\\u1ea7u ti\\u00ean, ch\\u00fa \\u00fd \\u0111\\u1ebfn k\\u00fd hi\\u1ec7u b\\u1eb1ng \\u1edf \\u0111\\u00e2y."}, {"index": 11, "start": 61.8, "end": 66.6, "text": "Ch\\u00fa \\u00fd r\\u1eb1ng t\\u00f4i \\u0111\\u00e3 n\\u00f3i ch\\u00fang ta \\u0111ang g\\u00e1n cho w m\\u1ed9t gi\\u00e1 tr\\u1ecb b\\u1eb1ng c\\u00e1ch s\\u1eed d\\u1ee5ng d\\u1ea5u '='."}, {"index": 12, "start": 66.6, "end": 72.16, "text": "V\\u00ec v\\u1eady, trong ng\\u1eef c\\u1ea3nh n\\u00e0y, d\\u1ea5u '=' l\\u00e0 to\\u00e1n t\\u1eed g\\u00e1n."}, {"index": 13, "start": 72.16, "end": 78.84, "text": "C\\u1ee5 th\\u1ec3 trong ng\\u1eef c\\u1ea3nh n\\u00e0y, n\\u1ebfu b\\u1ea1n vi\\u1ebft m\\u00e3 n\\u00f3i r\\u1eb1ng a b\\u1eb1ng c, c\\u00f3 ngh\\u0129a l\\u00e0 l\\u1ea5y"}, {"index": 14, "start": 78.84, "end": 84.0, "text": "gi\\u00e1 tr\\u1ecb c\\u1ee7a c v\\u00e0 l\\u01b0u tr\\u1eef n\\u00f3 trong m\\u00e1y t\\u00ednh c\\u1ee7a b\\u1ea1n trong bi\\u1ebfn a."}, {"index": 15, "start": 84.04, "end": 88.6, "text": "Ho\\u1eb7c n\\u1ebfu b\\u1ea1n vi\\u1ebft a b\\u1eb1ng a c\\u1ed9ng m\\u1ed9t, c\\u00f3 ngh\\u0129a l\\u00e0 \\u0111\\u1eb7t gi\\u00e1 tr\\u1ecb c\\u1ee7a a b\\u1eb1ng"}, {"index": 16, "start": 88.6, "end": 93.6, "text": "a c\\u1ed9ng m\\u1ed9t, ho\\u1eb7c t\\u0103ng gi\\u00e1 tr\\u1ecb c\\u1ee7a a l\\u00ean m\\u1ed9t."}, {"index": 17, "start": 93.6, "end": 100.08, "text": "V\\u00ec v\\u1eady, to\\u00e1n t\\u1eed g\\u00e1n trong l\\u1eadp tr\\u00ecnh kh\\u00e1c v\\u1edbi c\\u00e1c kh\\u1eb3ng \\u0111\\u1ecbnh v\\u1ec1 s\\u1ef1 th\\u1eadt trong"}, {"index": 18, "start": 100.08, "end": 106.44, "text": "to\\u00e1n h\\u1ecdc, n\\u01a1i n\\u1ebfu t\\u00f4i vi\\u1ebft a b\\u1eb1ng c, t\\u00f4i \\u0111ang kh\\u1eb3ng \\u0111\\u1ecbnh r\\u1eb1ng t\\u00f4i \\u0111ang tuy\\u00ean b\\u1ed1"}, {"index": 19, "start": 106.44, "end": 110.32, "text": "r\\u1eb1ng gi\\u00e1 tr\\u1ecb c\\u1ee7a a v\\u00e0 c l\\u00e0 b\\u1eb1ng nhau."}, {"index": 20, "start": 110.32, "end": 114.4, "text": "V\\u00e0 hy v\\u1ecdng t\\u00f4i s\\u1ebd kh\\u00f4ng bao gi\\u1edd vi\\u1ebft m\\u1ed9t gi\\u1ea3 thi\\u1ebft \\u0111\\u00fang r\\u1eb1ng a b\\u1eb1ng a c\\u1ed9ng m\\u1ed9t,"}, {"index": 21, "start": 114.4, "end": 116.84, "text": "b\\u1edfi v\\u00ec \\u0111i\\u1ec1u \\u0111\\u00f3 ho\\u00e0n to\\u00e0n kh\\u00f4ng th\\u1ec3 \\u0111\\u00fang."}, {"index": 22, "start": 118.16, "end": 121.4, "text": "V\\u00ec v\\u1eady, trong Python v\\u00e0 c\\u00e1c ng\\u00f4n ng\\u1eef l\\u1eadp tr\\u00ecnh kh\\u00e1c,"}, {"index": 23, "start": 121.4, "end": 125.84, "text": "c\\u00e1c gi\\u1ea3 thi\\u1ebft \\u0111\\u00fang \\u0111\\u00f4i khi \\u0111\\u01b0\\u1ee3c vi\\u1ebft d\\u01b0\\u1edbi d\\u1ea1ng b\\u1eb1ng b\\u1eb1ng."}, {"index": 24, "start": 125.84, "end": 130.64, "text": "V\\u00ec v\\u1eady, b\\u1ea1n c\\u00f3 th\\u1ec3 th\\u1ea5y m\\u00e3 l\\u1ec7nh n\\u00f3i r\\u1eb1ng a b\\u1eb1ng b\\u1eb1ng c n\\u1ebfu b\\u1ea1n \\u0111ang ki\\u1ec3m tra"}, {"index": 25, "start": 130.64, "end": 132.84, "text": "xem a c\\u00f3 b\\u1eb1ng c kh\\u00f4ng."}, {"index": 26, "start": 132.84, "end": 136.12, "text": "Nh\\u01b0ng trong k\\u00fd hi\\u1ec7u to\\u00e1n h\\u1ecdc nh\\u01b0 ch\\u00fang ta th\\u01b0\\u1eddng s\\u1eed d\\u1ee5ng,"}, {"index": 27, "start": 136.12, "end": 140.96, "text": "nh\\u01b0 trong nh\\u1eefng video n\\u00e0y, d\\u1ea5u b\\u1eb1ng c\\u00f3 th\\u1ec3 \\u0111\\u01b0\\u1ee3c s\\u1eed d\\u1ee5ng cho c\\u1ea3 g\\u00e1n gi\\u00e1 tr\\u1ecb"}, {"index": 28, "start": 140.96, "end": 143.28, "text": "ho\\u1eb7c cho gi\\u1ea3 thi\\u1ebft \\u0111\\u00fang."}, {"index": 29, "start": 143.28, "end": 147.0, "text": "V\\u00e0 v\\u00ec v\\u1eady t\\u00f4i s\\u1ebd c\\u1ed1 g\\u1eafng l\\u00e0m cho n\\u00f3 r\\u00f5 r\\u00e0ng khi t\\u00f4i vi\\u1ebft d\\u1ea5u b\\u1eb1ng,"}, {"index": 30, "start": 147.0, "end": 150.16, "text": "xem c\\u00f3 ph\\u1ea3i ch\\u00fang ta \\u0111ang g\\u00e1n m\\u1ed9t gi\\u00e1 tr\\u1ecb cho bi\\u1ebfn hay kh\\u00f4ng, ho\\u1eb7c li\\u1ec7u ch\\u00fang ta \\u0111ang"}, {"index": 31, "start": 150.16, "end": 154.12, "text": "kh\\u1eb3ng \\u0111\\u1ecbnh s\\u1ef1 \\u0111\\u00fang \\u0111\\u1eafn c\\u1ee7a s\\u1ef1 b\\u00ecnh \\u0111\\u1eb3ng gi\\u1eefa hai gi\\u00e1 tr\\u1ecb."}, {"index": 32, "start": 155.44, "end": 160.48, "text": "B\\u00e2y gi\\u1edd, h\\u00e3y \\u0111i s\\u00e2u h\\u01a1n v\\u00e0o nh\\u1eefng g\\u00ec c\\u00e1c k\\u00fd hi\\u1ec7u trong ph\\u01b0\\u01a1ng tr\\u00ecnh n\\u00e0y c\\u00f3 ngh\\u0129a."}, {"index": 33, "start": 160.48, "end": 165.32, "text": "K\\u00fd hi\\u1ec7u \\u1edf \\u0111\\u00e2y l\\u00e0 ch\\u1eef c\\u00e1i Hy L\\u1ea1p alpha."}, {"index": 34, "start": 165.32, "end": 171.12, "text": "V\\u00e0 trong ph\\u01b0\\u01a1ng tr\\u00ecnh n\\u00e0y, alpha c\\u00f2n \\u0111\\u01b0\\u1ee3c g\\u1ecdi l\\u00e0 t\\u1ed1c \\u0111\\u1ed9 h\\u1ecdc."}, {"index": 35, "start": 171.12, "end": 175.64, "text": "T\\u1ed1c \\u0111\\u1ed9 h\\u1ecdc th\\u01b0\\u1eddng l\\u00e0 m\\u1ed9t s\\u1ed1 d\\u01b0\\u01a1ng nh\\u1ecf trong kho\\u1ea3ng t\\u1eeb kh\\u00f4ng \\u0111\\u1ebfn m\\u1ed9t."}, {"index": 36, "start": 175.64, "end": 178.28, "text": "V\\u00e0 n\\u00f3 c\\u00f3 th\\u1ec3 l\\u00e0 kho\\u1ea3ng 0.01."}, {"index": 37, "start": 179.72, "end": 184.76, "text": "\\u0110i\\u1ec1u alpha l\\u00e0m l\\u00e0 n\\u00f3 ki\\u1ec3m so\\u00e1t k\\u00edch th\\u01b0\\u1edbc c\\u1ee7a b\\u01b0\\u1edbc \\u0111i xu\\u1ed1ng \\u0111\\u1ed3i."}, {"index": 38, "start": 185.88, "end": 191.04, "text": "V\\u00ec v\\u1eady, n\\u1ebfu alpha r\\u1ea5t l\\u1edbn, th\\u00ec \\u0111i\\u1ec1u \\u0111\\u00f3 t\\u01b0\\u01a1ng \\u1ee9ng v\\u1edbi m\\u1ed9t quy tr\\u00ecnh"}, {"index": 39, "start": 191.04, "end": 195.8, "text": "gi\\u1ea3m d\\u1ea7n gradient r\\u1ea5t m\\u1ea1nh, n\\u01a1i b\\u1ea1n \\u0111ang c\\u1ed1 g\\u1eafng th\\u1ef1c hi\\u1ec7n nh\\u1eefng b\\u01b0\\u1edbc \\u0111i l\\u1edbn xu\\u1ed1ng d\\u1ed1c."}, {"index": 40, "start": 195.8, "end": 201.12, "text": "N\\u1ebfu alpha r\\u1ea5t nh\\u1ecf, b\\u1ea1n s\\u1ebd ch\\u1ec9 ti\\u1ebfn b\\u1ed9 t\\u1eebng b\\u01b0\\u1edbc nh\\u1ecf xu\\u1ed1ng d\\u1ed1c."}, {"index": 41, "start": 201.12, "end": 206.92, "text": "Ch\\u00fang ta s\\u1ebd tr\\u1edf l\\u1ea1i sau \\u0111\\u1ec3 \\u0111i s\\u00e2u h\\u01a1n v\\u00e0o c\\u00e1ch ch\\u1ecdn m\\u1ed9t t\\u1ef7 l\\u1ec7 h\\u1ecdc alpha ph\\u00f9 h\\u1ee3p."}, {"index": 42, "start": 206.92, "end": 213.6, "text": "Cu\\u1ed1i c\\u00f9ng, thu\\u1eadt ng\\u1eef n\\u00e0y ch\\u00ednh l\\u00e0 \\u0111\\u1ea1o h\\u00e0m c\\u1ee7a h\\u00e0m chi ph\\u00ed J."}, {"index": 43, "start": 213.6, "end": 217.04, "text": "Ch\\u00fang ta kh\\u00f4ng c\\u1ea7n lo l\\u1eafng v\\u1ec1 chi ti\\u1ebft c\\u1ee7a \\u0111\\u1ea1o h\\u00e0m n\\u00e0y ngay b\\u00e2y gi\\u1edd,"}, {"index": 44, "start": 217.04, "end": 221.08, "text": "nh\\u01b0ng sau n\\u00e0y, b\\u1ea1n s\\u1ebd \\u0111\\u01b0\\u1ee3c t\\u00ecm hi\\u1ec3u nhi\\u1ec1u h\\u01a1n v\\u1ec1 thu\\u1eadt ng\\u1eef \\u0111\\u1ea1o h\\u00e0m."}, {"index": 45, "start": 221.08, "end": 225.88, "text": "Nh\\u01b0ng hi\\u1ec7n t\\u1ea1i, b\\u1ea1n c\\u00f3 th\\u1ec3 ngh\\u0129 v\\u1ec1 c\\u1ee5m t\\u1eeb \\u0111\\u1ea1o h\\u00e0m n\\u00e0y m\\u00e0 t\\u00f4i \\u0111\\u00e3 v\\u1ebd m\\u1ed9t \\u00f4 m\\u00e0u t\\u00edm xung quanh."}, {"index": 46, "start": 225.88, "end": 229.8, "text": "nh\\u01b0 l\\u00e0 ch\\u1ec9 d\\u1eabn cho b\\u1ea1n bi\\u1ebft h\\u01b0\\u1edbng n\\u00e0o b\\u1ea1n mu\\u1ed1n ti\\u1ebfn m\\u1ed9t b\\u01b0\\u1edbc nh\\u1ecf."}, {"index": 47, "start": 229.8, "end": 233.4, "text": "V\\u00e0 k\\u1ebft h\\u1ee3p v\\u1edbi h\\u1ec7 s\\u1ed1 h\\u1ecdc alpha,"}, {"index": 48, "start": 233.4, "end": 236.76, "text": "n\\u00f3 c\\u0169ng x\\u00e1c \\u0111\\u1ecbnh k\\u00edch th\\u01b0\\u1edbc c\\u1ee7a c\\u00e1c b\\u01b0\\u1edbc b\\u1ea1n mu\\u1ed1n \\u0111i xu\\u1ed1ng."}, {"index": 49, "start": 238.44, "end": 242.92, "text": "B\\u00e2y gi\\u1edd, t\\u00f4i mu\\u1ed1n \\u0111\\u1ec1 c\\u1eadp r\\u1eb1ng \\u0111\\u1ea1o h\\u00e0m xu\\u1ea5t ph\\u00e1t t\\u1eeb gi\\u1ea3i t\\u00edch."}, {"index": 50, "start": 242.92, "end": 246.44, "text": "V\\u00e0 ngay c\\u1ea3 khi b\\u1ea1n kh\\u00f4ng quen thu\\u1ed9c v\\u1edbi gi\\u1ea3i t\\u00edch, \\u0111\\u1eebng lo l\\u1eafng v\\u1ec1 \\u0111i\\u1ec1u \\u0111\\u00f3."}, {"index": 51, "start": 247.16, "end": 251.12, "text": "Ngay c\\u1ea3 khi kh\\u00f4ng bi\\u1ebft g\\u00ec v\\u1ec1 gi\\u1ea3i t\\u00edch, b\\u1ea1n v\\u1eabn c\\u00f3 th\\u1ec3 t\\u00ecm ra m\\u1ecdi \\u0111i\\u1ec1u b\\u1ea1n c\\u1ea7n bi\\u1ebft."}, {"index": 52, "start": 251.12, "end": 254.32, "text": "v\\u1ec1 thu\\u1eadt ng\\u1eef \\u0111\\u1ea1o h\\u00e0m n\\u00e0y trong video n\\u00e0y v\\u00e0 s\\u1ef1 k\\u1ebft h\\u1ee3p."}, {"index": 53, "start": 255.48, "end": 262.04, "text": "M\\u1ed9t \\u0111i\\u1ec1u n\\u1eefa, h\\u00e3y nh\\u1edb r\\u1eb1ng m\\u00f4 h\\u00ecnh c\\u1ee7a b\\u1ea1n c\\u00f3 hai tham s\\u1ed1, kh\\u00f4ng ch\\u1ec9 l\\u00e0 W, m\\u00e0 c\\u00f2n l\\u00e0 B."}, {"index": 54, "start": 262.04, "end": 268.92, "text": "V\\u00ec v\\u1eady, b\\u1ea1n c\\u0169ng c\\u00f3 m\\u1ed9t ph\\u00e9p g\\u00e1n \\u0111\\u1ec3 c\\u1eadp nh\\u1eadt tham s\\u1ed1 B tr\\u00f4ng r\\u1ea5t gi\\u1ed1ng."}, {"index": 55, "start": 268.92, "end": 275.64, "text": "B \\u0111\\u01b0\\u1ee3c g\\u00e1n gi\\u00e1 tr\\u1ecb c\\u0169 c\\u1ee7a B tr\\u1eeb \\u0111i t\\u1ef7 l\\u1ec7 h\\u1ecdc alpha"}, {"index": 56, "start": 275.64, "end": 283.0, "text": "nh\\u00e2n v\\u1edbi \\u0111\\u1ea1o h\\u00e0m h\\u01a1i kh\\u00e1c D theo dB c\\u1ee7a J c\\u1ee7a WB."}, {"index": 57, "start": 283.0, "end": 286.68, "text": "V\\u00ec v\\u1eady, h\\u00e3y nh\\u1edb trong \\u0111\\u1ed3 th\\u1ecb c\\u1ee7a bi\\u1ec3u \\u0111\\u1ed3 m\\u1eb7t ph\\u1eb3ng,"}, {"index": 58, "start": 286.68, "end": 290.72, "text": "n\\u01a1i b\\u1ea1n \\u0111ang t\\u1eebng b\\u01b0\\u1edbc ti\\u1ebfn nh\\u1ecf cho \\u0111\\u1ebfn khi \\u0111\\u1ebfn \\u0111\\u00e1y thung l\\u0169ng?"}, {"index": 59, "start": 290.72, "end": 293.36, "text": "Th\\u00ec, \\u0111\\u1ed1i v\\u1edbi thu\\u1eadt to\\u00e1n t\\u1ed1i \\u01b0u h\\u00f3a \\u0111\\u1ed9 d\\u1ed1c,"}, {"index": 60, "start": 293.36, "end": 298.2, "text": "b\\u1ea1n s\\u1ebd l\\u1eb7p l\\u1ea1i hai b\\u01b0\\u1edbc c\\u1eadp nh\\u1eadt n\\u00e0y cho \\u0111\\u1ebfn khi thu\\u1eadt to\\u00e1n h\\u1ed9i t\\u1ee5."}, {"index": 61, "start": 298.2, "end": 303.32, "text": "V\\u00e0 khi t\\u00f4i n\\u00f3i h\\u1ed9i t\\u1ee5, t\\u00f4i c\\u00f3 \\u00fd l\\u00e0 b\\u1ea1n \\u0111\\u1ea1t \\u0111\\u1ebfn \\u0111i\\u1ec3m t\\u1ea1i c\\u1ef1c ti\\u1ec3u \\u0111\\u1ecba ph\\u01b0\\u01a1ng"}, {"index": 62, "start": 303.32, "end": 309.24, "text": "n\\u01a1i m\\u00e0 c\\u00e1c tham s\\u1ed1 W v\\u00e0 B kh\\u00f4ng c\\u00f2n thay \\u0111\\u1ed5i nhi\\u1ec1u v\\u1edbi m\\u1ed7i b\\u01b0\\u1edbc b\\u1ed5 sung m\\u00e0 b\\u1ea1n th\\u1ef1c hi\\u1ec7n."}, {"index": 63, "start": 310.4, "end": 316.64, "text": "B\\u00e2y gi\\u1edd, c\\u00f3 m\\u1ed9t chi ti\\u1ebft tinh t\\u1ebf n\\u1eefa v\\u1ec1 c\\u00e1ch th\\u1ef1c hi\\u1ec7n \\u0111\\u00fang thu\\u1eadt to\\u00e1n gi\\u1ea3m d\\u1ea7n \\u0111\\u1ed9 d\\u1ed1c."}, {"index": 64, "start": 316.64, "end": 320.8, "text": "B\\u1ea1n s\\u1ebd c\\u1eadp nh\\u1eadt hai tham s\\u1ed1 W v\\u00e0 B, ph\\u1ea3i kh\\u00f4ng?"}, {"index": 65, "start": 320.8, "end": 325.0, "text": "V\\u1eady th\\u00ec vi\\u1ec7c c\\u1eadp nh\\u1eadt n\\u00e0y di\\u1ec5n ra \\u0111\\u1ed1i v\\u1edbi c\\u1ea3 hai tham s\\u1ed1 W v\\u00e0 B."}, {"index": 66, "start": 326.28, "end": 331.04, "text": "M\\u1ed9t chi ti\\u1ebft quan tr\\u1ecdng l\\u00e0 \\u0111\\u1ed1i v\\u1edbi thu\\u1eadt to\\u00e1n gi\\u1ea3m d\\u1ea7n \\u0111\\u1ed9 d\\u1ed1c,"}, {"index": 67, "start": 331.04, "end": 335.8, "text": "b\\u1ea1n mu\\u1ed1n \\u0111\\u1ed3ng th\\u1eddi c\\u1eadp nh\\u1eadt W v\\u00e0 B,"}, {"index": 68, "start": 335.8, "end": 340.0, "text": "c\\u00f3 ngh\\u0129a l\\u00e0 b\\u1ea1n mu\\u1ed1n c\\u1eadp nh\\u1eadt c\\u1ea3 hai tham s\\u1ed1 c\\u00f9ng m\\u1ed9t l\\u00fac."}, {"index": 69, "start": 340.0, "end": 343.52, "text": "\\u00dd t\\u00f4i l\\u00e0 trong bi\\u1ec3u th\\u1ee9c n\\u00e0y,"}, {"index": 70, "start": 343.52, "end": 348.64, "text": "b\\u1ea1n s\\u1ebd c\\u1eadp nh\\u1eadt W t\\u1eeb W c\\u0169 sang W m\\u1edbi."}, {"index": 71, "start": 348.64, "end": 355.2, "text": "V\\u00e0 b\\u1ea1n c\\u0169ng c\\u1eadp nh\\u1eadt B t\\u1eeb gi\\u00e1 tr\\u1ecb c\\u0169 c\\u1ee7a n\\u00f3 sang gi\\u00e1 tr\\u1ecb m\\u1edbi c\\u1ee7a B."}, {"index": 72, "start": 355.2, "end": 359.32, "text": "V\\u00e0 c\\u00e1ch th\\u1ef1c hi\\u1ec7n \\u0111i\\u1ec1u n\\u00e0y l\\u00e0 t\\u00ednh to\\u00e1n ph\\u00eda b\\u00ean ph\\u1ea3i,"}, {"index": 73, "start": 359.32, "end": 362.84, "text": "t\\u00ednh to\\u00e1n \\u0111i\\u1ec1u n\\u00e0y cho W v\\u00e0 B,"}, {"index": 74, "start": 362.84, "end": 365.92, "text": "v\\u00e0 \\u0111\\u1ed3ng th\\u1eddi c\\u00f9ng m\\u1ed9t l\\u00fac,"}, {"index": 75, "start": 365.92, "end": 370.52, "text": "c\\u1eadp nh\\u1eadt W v\\u00e0 B \\u0111\\u1ebfn c\\u00e1c gi\\u00e1 tr\\u1ecb m\\u1edbi."}, {"index": 76, "start": 370.52, "end": 374.16, "text": "V\\u1eady h\\u00e3y c\\u00f9ng xem \\u0111i\\u1ec1u n\\u00e0y c\\u00f3 ngh\\u0129a l\\u00e0 g\\u00ec."}, {"index": 77, "start": 374.16, "end": 377.32, "text": "\\u0110\\u00e2y l\\u00e0 c\\u00e1ch \\u0111\\u00fang \\u0111\\u1ec3 th\\u1ef1c hi\\u1ec7n thu\\u1eadt to\\u00e1n gi\\u1ea3m d\\u1ea7n \\u0111\\u1ed9 d\\u1ed1c,"}, {"index": 78, "start": 377.32, "end": 380.12, "text": "m\\u00e0 th\\u1ef1c hi\\u1ec7n m\\u1ed9t c\\u1eadp nh\\u1eadt \\u0111\\u1ed3ng th\\u1eddi."}, {"index": 79, "start": 380.12, "end": 384.64, "text": "\\u0110i\\u1ec1u n\\u00e0y g\\u00e1n m\\u1ed9t bi\\u1ebfn tempW b\\u1eb1ng v\\u1edbi bi\\u1ec3u th\\u1ee9c \\u0111\\u00f3,"}, {"index": 80, "start": 384.64, "end": 388.0, "text": "c\\u00e1i n\\u00e0y l\\u00e0 W tr\\u1eeb \\u0111i h\\u1ea1ng m\\u1ee5c \\u0111\\u00f3 \\u1edf \\u0111\\u00e2y."}, {"index": 81, "start": 388.04, "end": 391.52, "text": "Ch\\u00fang ta c\\u0169ng \\u0111\\u1eb7t m\\u1ed9t bi\\u1ebfn kh\\u00e1c, tempB b\\u1eb1ng c\\u00e1i \\u0111\\u00f3,"}, {"index": 82, "start": 391.52, "end": 393.92, "text": "c\\u00e1i n\\u00e0y l\\u00e0 B tr\\u1eeb \\u0111i h\\u1ea1ng m\\u1ee5c \\u0111\\u00f3."}, {"index": 83, "start": 393.92, "end": 396.88, "text": "V\\u1eady b\\u1ea1n t\\u00ednh c\\u1ea3 hai b\\u00ean ph\\u1ea3i, c\\u1ea3 hai c\\u1eadp nh\\u1eadt,"}, {"index": 84, "start": 396.88, "end": 401.56, "text": "v\\u00e0 l\\u01b0u ch\\u00fang v\\u00e0o c\\u00e1c bi\\u1ebfn tempW v\\u00e0 tempB."}, {"index": 85, "start": 401.56, "end": 406.96, "text": "Sau \\u0111\\u00f3, b\\u1ea1n sao ch\\u00e9p gi\\u00e1 tr\\u1ecb c\\u1ee7a tempW v\\u00e0o W,"}, {"index": 86, "start": 406.96, "end": 411.92, "text": "v\\u00e0 b\\u1ea1n c\\u0169ng sao ch\\u00e9p gi\\u00e1 tr\\u1ecb c\\u1ee7a tempB v\\u00e0o B."}, {"index": 87, "start": 411.92, "end": 413.72, "text": "B\\u00e2y gi\\u1edd, m\\u1ed9t \\u0111i\\u1ec1u b\\u1ea1n c\\u00f3 th\\u1ec3 nh\\u1eadn th\\u1ea5y"}, {"index": 88, "start": 413.72, "end": 420.64, "text": "l\\u00e0 gi\\u00e1 tr\\u1ecb c\\u1ee7a W n\\u00e0y l\\u00e0 t\\u1eeb tr\\u01b0\\u1edbc khi W \\u0111\\u01b0\\u1ee3c c\\u1eadp nh\\u1eadt."}, {"index": 89, "start": 420.64, "end": 423.68, "text": "\\u1ede \\u0111\\u00e2y, h\\u00e3y nh\\u1eadn x\\u00e9t r\\u1eb1ng W tr\\u01b0\\u1edbc khi c\\u1eadp nh\\u1eadt"}, {"index": 90, "start": 423.68, "end": 428.48, "text": "l\\u00e0 c\\u00e1i \\u0111\\u01b0\\u1ee3c \\u0111\\u01b0a v\\u00e0o h\\u1ea1ng m\\u1ee5c \\u0111\\u1ea1o h\\u00e0m \\u1edf \\u0111\\u00e2y, hi\\u1ec3u ch\\u1ee9?"}, {"index": 91, "start": 428.48, "end": 431.88, "text": "Ng\\u01b0\\u1ee3c l\\u1ea1i, \\u0111\\u00e2y l\\u00e0 m\\u1ed9t tri\\u1ec3n khai sai"}, {"index": 92, "start": 431.88, "end": 436.16, "text": "c\\u1ee7a ph\\u01b0\\u01a1ng ph\\u00e1p gi\\u1ea3m d\\u1ea7n m\\u00e0 kh\\u00f4ng th\\u1ef1c hi\\u1ec7n c\\u1eadp nh\\u1eadt \\u0111\\u1ed3ng th\\u1eddi."}, {"index": 93, "start": 436.16, "end": 438.52, "text": "Trong tri\\u1ec3n khai sai n\\u00e0y,"}, {"index": 94, "start": 438.56, "end": 443.84, "text": "ch\\u00fang ta t\\u00ednh to\\u00e1n tempW gi\\u1ed1ng nh\\u01b0 tr\\u01b0\\u1edbc, cho \\u0111\\u1ebfn b\\u00e2y gi\\u1edd th\\u00ec OK."}, {"index": 95, "start": 443.84, "end": 447.08, "text": "V\\u00e0 b\\u00e2y gi\\u1edd, \\u0111\\u00e2y l\\u00e0 n\\u01a1i m\\u1ecdi th\\u1ee9 b\\u1eaft \\u0111\\u1ea7u kh\\u00e1c bi\\u1ec7t."}, {"index": 96, "start": 447.08, "end": 451.12, "text": "Sau \\u0111\\u00f3, ch\\u00fang ta c\\u1eadp nh\\u1eadt W v\\u1edbi gi\\u00e1 tr\\u1ecb trong tempW"}, {"index": 97, "start": 451.12, "end": 456.08, "text": "tr\\u01b0\\u1edbc khi t\\u00ednh to\\u00e1n gi\\u00e1 tr\\u1ecb m\\u1edbi cho tham s\\u1ed1 kh\\u00e1c B."}, {"index": 98, "start": 456.08, "end": 460.68, "text": "Ti\\u1ebfp theo, ch\\u00fang ta t\\u00ednh to\\u00e1n tempB b\\u1eb1ng B tr\\u1eeb \\u0111i h\\u1ea1ng m\\u1ee5c \\u0111\\u00f3 \\u1edf \\u0111\\u00e2y."}, {"index": 99, "start": 460.68, "end": 465.72, "text": "V\\u00e0 cu\\u1ed1i c\\u00f9ng, ch\\u00fang ta c\\u1eadp nh\\u1eadt B v\\u1edbi gi\\u00e1 tr\\u1ecb trong tempB."}, {"index": 100, "start": 465.72, "end": 467.32, "text": "S\\u1ef1 kh\\u00e1c bi\\u1ec7t gi\\u1eefa b\\u00ean ph\\u1ea3i"}, {"index": 101, "start": 467.32, "end": 469.28, "text": "v\\u00e0 b\\u00ean tr\\u00e1i trong c\\u00e1c tri\\u1ec3n khai"}, {"index": 102, "start": 469.28, "end": 471.56, "text": "l\\u00e0 n\\u1ebfu b\\u1ea1n nh\\u00ecn \\u1edf \\u0111\\u00e2y,"}, {"index": 103, "start": 471.56, "end": 476.12, "text": "th\\u00ec W n\\u00e0y \\u0111\\u00e3 \\u0111\\u01b0\\u1ee3c c\\u1eadp nh\\u1eadt v\\u1edbi gi\\u00e1 tr\\u1ecb m\\u1edbi n\\u00e0y,"}, {"index": 104, "start": 476.12, "end": 479.36, "text": "v\\u00e0 ch\\u00ednh W \\u0111\\u00e3 \\u0111\\u01b0\\u1ee3c c\\u1eadp nh\\u1eadt n\\u00e0y s\\u1ebd"}, {"index": 105, "start": 479.36, "end": 483.36, "text": "\\u0111\\u01b0\\u1ee3c \\u0111\\u01b0a v\\u00e0o h\\u00e0m const j c\\u1ee7a WB."}, {"index": 106, "start": 483.36, "end": 485.36, "text": "\\u0110i\\u1ec1u \\u0111\\u00f3 c\\u00f3 ngh\\u0129a l\\u00e0 thu\\u1eadt ng\\u1eef n\\u00e0y \\u1edf b\\u00ean ph\\u1ea3i"}, {"index": 107, "start": 485.36, "end": 488.6, "text": "kh\\u00f4ng gi\\u1ed1ng nh\\u01b0 thu\\u1eadt ng\\u1eef n\\u00e0y \\u1edf b\\u00ean tr\\u00e1i"}, {"index": 108, "start": 488.6, "end": 491.04, "text": "m\\u00e0 b\\u1ea1n th\\u1ea5y b\\u00ean tr\\u00e1i."}, {"index": 109, "start": 491.04, "end": 496.04, "text": "V\\u00e0 \\u0111i\\u1ec1u \\u0111\\u00f3 c\\u0169ng c\\u00f3 ngh\\u0129a l\\u00e0 thu\\u1eadt ng\\u1eef tempB n\\u00e0y b\\u00ean ph\\u1ea3i"}, {"index": 110, "start": 496.04, "end": 500.24, "text": "kh\\u00f4ng ho\\u00e0n to\\u00e0n gi\\u1ed1ng v\\u1edbi thu\\u1eadt ng\\u1eef tempB b\\u00ean tr\\u00e1i,"}, {"index": 111, "start": 500.24, "end": 503.16, "text": "v\\u00e0 do \\u0111\\u00f3, gi\\u00e1 tr\\u1ecb \\u0111\\u00e3 c\\u1eadp nh\\u1eadt cho B b\\u00ean ph\\u1ea3i"}, {"index": 112, "start": 503.16, "end": 506.24, "text": "kh\\u00f4ng gi\\u1ed1ng v\\u1edbi gi\\u00e1 tr\\u1ecb \\u0111\\u00e3 c\\u1eadp nh\\u1eadt n\\u00e0y"}, {"index": 113, "start": 506.24, "end": 509.6, "text": "cho bi\\u1ebfn B b\\u00ean tr\\u00e1i."}, {"index": 114, "start": 509.6, "end": 512.24, "text": "C\\u00e1ch m\\u00e0 thu\\u1eadt to\\u00e1n gradient descent \\u0111\\u01b0\\u1ee3c tri\\u1ec3n khai trong m\\u00e3,"}, {"index": 115, "start": 512.24, "end": 514.68, "text": "h\\u00f3a ra l\\u00e0 t\\u1ef1 nhi\\u00ean h\\u01a1n"}, {"index": 116, "start": 514.68, "end": 520.16, "text": "khi tri\\u1ec3n khai \\u0111\\u00fang c\\u00e1ch v\\u1edbi c\\u00e1c c\\u1eadp nh\\u1eadt \\u0111\\u1ed3ng th\\u1eddi."}, {"index": 117, "start": 520.16, "end": 522.72, "text": "Khi b\\u1ea1n nghe ai \\u0111\\u00f3 n\\u00f3i v\\u1ec1 gradient descent,"}, {"index": 118, "start": 522.72, "end": 524.72, "text": "h\\u1ecd lu\\u00f4n c\\u00f3 \\u00fd ngh\\u0129a \\u0111\\u1ebfn gradient descent"}, {"index": 119, "start": 524.72, "end": 528.76, "text": "n\\u01a1i b\\u1ea1n th\\u1ef1c hi\\u1ec7n c\\u1eadp nh\\u1eadt \\u0111\\u1ed3ng th\\u1eddi c\\u00e1c tham s\\u1ed1."}, {"index": 120, "start": 528.76, "end": 531.56, "text": "Tuy nhi\\u00ean, n\\u1ebfu b\\u1ea1n th\\u1ef1c hi\\u1ec7n"}, {"index": 121, "start": 531.56, "end": 533.56, "text": "c\\u1eadp nh\\u1eadt kh\\u00f4ng \\u0111\\u1ed3ng th\\u1eddi,"}, {"index": 122, "start": 533.56, "end": 537.48, "text": "th\\u00ec c\\u00f3 th\\u1ec3 n\\u00f3 s\\u1ebd ho\\u1ea1t \\u0111\\u1ed9ng h\\u01a1n ho\\u1eb7c k\\u00e9m, b\\u1ea5t k\\u1ec3 th\\u1ebf n\\u00e0o,"}, {"index": 123, "start": 537.48, "end": 538.68, "text": "nh\\u01b0ng l\\u00e0m theo c\\u00e1ch n\\u00e0y"}, {"index": 124, "start": 538.68, "end": 541.12, "text": "th\\u1ef1c s\\u1ef1 kh\\u00f4ng ph\\u1ea3i l\\u00e0 c\\u00e1ch \\u0111\\u00fang \\u0111\\u1ec3 th\\u1ef1c hi\\u1ec7n,"}, {"index": 125, "start": 541.12, "end": 544.44, "text": "n\\u00f3 th\\u1ef1c s\\u1ef1 l\\u00e0 m\\u1ed9t thu\\u1eadt to\\u00e1n kh\\u00e1c v\\u1edbi c\\u00e1c thu\\u1ed9c t\\u00ednh kh\\u00e1c."}, {"index": 126, "start": 544.44, "end": 546.4, "text": "V\\u00ec v\\u1eady, t\\u00f4i khuy\\u00ean b\\u1ea1n ch\\u1ec9 n\\u00ean duy tr\\u00ec"}, {"index": 127, "start": 546.4, "end": 548.8, "text": "c\\u1eadp nh\\u1eadt \\u0111\\u1ed3ng th\\u1eddi \\u0111\\u00fang c\\u00e1ch"}, {"index": 128, "start": 548.8, "end": 552.88, "text": "v\\u00e0 kh\\u00f4ng s\\u1eed d\\u1ee5ng phi\\u00ean b\\u1ea3n sai n\\u00e0y b\\u00ean ph\\u1ea3i."}, {"index": 129, "start": 552.88, "end": 555.04, "text": "\\u0110\\u1ea5y l\\u00e0 ph\\u01b0\\u01a1ng ph\\u00e1p gi\\u1ea3m d\\u1ea7n."}, {"index": 130, "start": 555.04, "end": 558.76, "text": "Trong video ti\\u1ebfp theo, ch\\u00fang ta s\\u1ebd \\u0111i s\\u00e2u v\\u00e0o chi ti\\u1ebft v\\u1ec1 h\\u1ea1ng t\\u1eed \\u0111\\u1ea1o h\\u00e0m,"}, {"index": 131, "start": 558.76, "end": 560.36, "text": "m\\u00e0 b\\u1ea1n \\u0111\\u00e3 th\\u1ea5y trong video n\\u00e0y,"}, {"index": 132, "start": 560.36, "end": 563.36, "text": "nh\\u01b0ng m\\u00e0 ch\\u00fang ta ch\\u01b0a th\\u1ef1c s\\u1ef1 n\\u00f3i v\\u1ec1 chi ti\\u1ebft."}, {"index": 133, "start": 563.36, "end": 565.6, "text": "\\u0110\\u1ea1o h\\u00e0m l\\u00e0 m\\u1ed9t ph\\u1ea7n c\\u1ee7a gi\\u1ea3i t\\u00edch,"}, {"index": 134, "start": 565.6, "end": 568.0, "text": "v\\u00e0 n\\u1ebfu b\\u1ea1n kh\\u00f4ng quen thu\\u1ed9c v\\u1edbi gi\\u1ea3i t\\u00edch,"}, {"index": 135, "start": 568.0, "end": 569.36, "text": "\\u0111\\u1eebng lo l\\u1eafng v\\u1ec1 \\u0111i\\u1ec1u \\u0111\\u00f3."}, {"index": 136, "start": 569.36, "end": 571.24, "text": "B\\u1ea1n s\\u1ebd kh\\u00f4ng c\\u1ea7n ph\\u1ea3i bi\\u1ebft gi\\u1ea3i t\\u00edch"}, {"index": 137, "start": 571.24, "end": 574.76, "text": "\\u0111\\u1ec3 ho\\u00e0n th\\u00e0nh kh\\u00f3a h\\u1ecdc ho\\u1eb7c chuy\\u00ean ng\\u00e0nh n\\u00e0y,"}, {"index": 138, "start": 574.76, "end": 576.92, "text": "v\\u00e0 b\\u1ea1n s\\u1ebd c\\u00f3 t\\u1ea5t c\\u1ea3 th\\u00f4ng tin c\\u1ea7n thi\\u1ebft"}, {"index": 139, "start": 576.92, "end": 580.08, "text": "\\u0111\\u1ec3 th\\u1ef1c hi\\u1ec7n ph\\u01b0\\u01a1ng ph\\u00e1p gi\\u1ea3m d\\u1ea7n."}, {"index": 140, "start": 580.08, "end": 581.52, "text": "Trong video ti\\u1ebfp theo,"}, {"index": 141, "start": 581.52, "end": 584.08, "text": "ch\\u00fang ta s\\u1ebd c\\u00f9ng nhau t\\u00ecm hi\\u1ec3u v\\u1ec1 \\u0111\\u1ea1o h\\u00e0m,"}, {"index": 142, "start": 584.08, "end": 587.6, "text": "v\\u00e0 b\\u1ea1n s\\u1ebd c\\u00f3 \\u0111\\u01b0\\u1ee3c tr\\u1ef1c gi\\u00e1c v\\u00e0 ki\\u1ebfn th\\u1ee9c c\\u1ea7n thi\\u1ebft"}, {"index": 143, "start": 587.6, "end": 592.28, "text": "\\u0111\\u1ec3 c\\u00f3 th\\u1ec3 t\\u1ef1 implement v\\u00e0 \\u00e1p d\\u1ee5ng ph\\u01b0\\u01a1ng ph\\u00e1p gi\\u1ea3m \\u0111\\u1ed9 d\\u1ed1c."}, {"index": 144, "start": 592.28, "end": 593.96, "text": "T\\u00f4i ngh\\u0129 \\u0111\\u00f3 s\\u1ebd l\\u00e0 \\u0111i\\u1ec1u th\\u00fa v\\u1ecb"}, {"index": 145, "start": 593.96, "end": 595.72, "text": "\\u0111\\u1ec3 b\\u1ea1n bi\\u1ebft c\\u00e1ch implement."}, {"index": 146, "start": 595.72, "end": 598.92, "text": "V\\u1eady h\\u00e3y c\\u00f9ng chuy\\u1ec3n sang video ti\\u1ebfp theo \\u0111\\u1ec3 xem c\\u00e1ch th\\u1ef1c hi\\u1ec7n."}]}}, "summary": ["- Gi\\u1edbi thi\\u1ec7u c\\u00e1ch tri\\u1ec3n khai thu\\u1eadt to\\u00e1n gradient descent.", "- C\\u1eadp nh\\u1eadt tham s\\u1ed1 w b\\u1eb1ng c\\u00e1ch l\\u1ea5y gi\\u00e1 tr\\u1ecb c\\u0169 tr\\u1eeb \\u0111i alpha nh\\u00e2n v\\u1edbi \\u0111\\u1ea1o h\\u00e0m c\\u1ee7a h\\u00e0m chi ph\\u00ed.", "- D\\u1ea5u '=' trong ng\\u1eef c\\u1ea3nh l\\u1eadp tr\\u00ecnh l\\u00e0 to\\u00e1n t\\u1eed g\\u00e1n, kh\\u00e1c v\\u1edbi kh\\u1eb3ng \\u0111\\u1ecbnh v\\u1ec1 s\\u1ef1 b\\u1eb1ng nhau trong to\\u00e1n h\\u1ecdc.", "- Alpha \\u0111\\u01b0\\u1ee3c g\\u1ecdi l\\u00e0 t\\u1ed1c \\u0111\\u1ed9 h\\u1ecdc, quy\\u1ebft \\u0111\\u1ecbnh k\\u00edch th\\u01b0\\u1edbc b\\u01b0\\u1edbc \\u0111i trong qu\\u00e1 tr\\u00ecnh gi\\u1ea3m gradient.", "- T\\u1ed1c \\u0111\\u1ed9 h\\u1ecdc th\\u01b0\\u1eddng l\\u00e0 s\\u1ed1 d\\u01b0\\u01a1ng nh\\u1ecf trong kho\\u1ea3ng t\\u1eeb 0 \\u0111\\u1ebfn 1, v\\u00ed d\\u1ee5 0.01.", "- \\u0110\\u1ea1o h\\u00e0m c\\u1ee7a h\\u00e0m chi ph\\u00ed cho bi\\u1ebft h\\u01b0\\u1edbng \\u0111i v\\u00e0 k\\u00edch th\\u01b0\\u1edbc b\\u01b0\\u1edbc \\u0111i ti\\u1ebfp theo.", "- Kh\\u00e1i ni\\u1ec7m \\u0111\\u1ea1o h\\u00e0m xu\\u1ea5t ph\\u00e1t t\\u1eeb gi\\u1ea3i t\\u00edch nh\\u01b0ng kh\\u00f4ng c\\u1ea7n hi\\u1ec3u bi\\u1ebft s\\u00e2u \\u0111\\u1ec3 \\u00e1p d\\u1ee5ng.", "- C\\u1ea7n nh\\u1edb m\\u00f4 h\\u00ecnh c\\u00f3 hai tham s\\u1ed1 W v\\u00e0 B, c\\u1ea3 hai \\u0111\\u1ec1u \\u0111\\u01b0\\u1ee3c c\\u1eadp nh\\u1eadt t\\u01b0\\u01a1ng t\\u1ef1.", "- L\\u1eb7p l\\u1ea1i c\\u00e1c b\\u01b0\\u1edbc c\\u1eadp nh\\u1eadt cho \\u0111\\u1ebfn khi thu\\u1eadt to\\u00e1n h\\u1ed9i t\\u1ee5 \\u1edf \\u0111i\\u1ec3m c\\u1ef1c ti\\u1ec3u \\u0111\\u1ecba ph\\u01b0\\u01a1ng."], "timeline": [{"time": "00:00", "title": "Gi\\u1edbi thi\\u1ec7u v\\u1ec1 thu\\u1eadt to\\u00e1n gradient descent"}, {"time": "01:00", "title": "To\\u00e1n t\\u1eed g\\u00e1n trong l\\u1eadp tr\\u00ecnh v\\u00e0 to\\u00e1n h\\u1ecdc"}, {"time": "02:35", "title": "K\\u00fd hi\\u1ec7u alpha v\\u00e0 t\\u1ed1c \\u0111\\u1ed9 h\\u1ecdc"}, {"time": "04:00", "title": "C\\u1eadp nh\\u1eadt tham s\\u1ed1 W v\\u00e0 B"}, {"time": "06:10", "title": "Th\\u1ef1c hi\\u1ec7n \\u0111\\u00fang thu\\u1eadt to\\u00e1n gradient descent"}, {"time": "08:40", "title": "L\\u1eddi khuy\\u00ean v\\u1ec1 c\\u1eadp nh\\u1eadt \\u0111\\u1ed3ng th\\u1eddi"}], "highlights": [{"time": "03:05", "reason": "Gi\\u00fap hi\\u1ec3u c\\u00e1ch th\\u1ee9c ho\\u1ea1t \\u0111\\u1ed9ng c\\u1ee7a t\\u1ed1c \\u0111\\u1ed9 h\\u1ecdc", "context": "T\\u1ed1c \\u0111\\u1ed9 h\\u1ecdc th\\u01b0\\u1eddng l\\u00e0 m\\u1ed9t s\\u1ed1 d\\u01b0\\u01a1ng nh\\u1ecf trong kho\\u1ea3ng t\\u1eeb kh\\u00f4ng \\u0111\\u1ebfn m\\u1ed9t."}, {"time": "05:10", "reason": "Nh\\u1ea5n m\\u1ea1n