c37e2242-a8f8-4028-950e-cd22a68d741a	9df16d2a-a767-4686-b534-7f9e686ed230	data\\uploads\\videos\\9df16d2a-a767-4686-b534-7f9e686ed230.mp4	\N	\N	\N	\N	{"transcript": {"video_id": "9df16d2a-a767-4686-b534-7f9e686ed230", "language": "vi", "source_language": "en", "target_language": "vi", "available_languages": ["vi", "en"], "translation_status": {"vi": {"status": "completed", "error": null}}, "segments": [{"index": 0, "start": 0.0, "end": 5.0, "text": "Hi\\u1ec7n nay, ch\\u00fang ta \\u0111\\u00e3 c\\u00f3 m\\u1ed9t m\\u00f4 h\\u00ecnh h\\u00ecnh \\u1ea3nh kh\\u00e1 m\\u1ea1nh m\\u1ebd v\\u1ec1 m\\u1ed1i quan h\\u1ec7 gi\\u1eefa"}, {"index": 1, "start": 5.0, "end": 9.0, "text": "c\\u00e1c s\\u1ef1 v\\u1eadt trong th\\u1ebf gi\\u1edbi v\\u00e0 h\\u00ecnh \\u1ea3nh c\\u1ee7a ch\\u00fang, nh\\u01b0ng ch\\u00fang ta v\\u1eabn ch\\u01b0a ho\\u00e0n to\\u00e0n \\u0111\\u1ea1t \\u0111\\u01b0\\u1ee3c."}, {"index": 2, "start": 9.0, "end": 13.0, "text": "C\\u00f3 m\\u1ed9t v\\u00e0i \\u0111i\\u1ec1u m\\u00e0 camera obscura ho\\u1eb7c m\\u00f4 h\\u00ecnh l\\u1ed7 kim,"}, {"index": 3, "start": 13.0, "end": 18.0, "text": "d\\u00f9 c\\u00f3 t\\u1ea5t c\\u1ea3 nh\\u1eefng s\\u1ef1 t\\u1ed5ng qu\\u00e1t \\u0111\\u00f3, nh\\u01b0ng v\\u1eabn kh\\u00f4ng th\\u1ec3 m\\u00f4 t\\u1ea3."}, {"index": 4, "start": 18.0, "end": 20.0, "text": "D\\u01b0\\u1edbi \\u0111\\u00e2y l\\u00e0 m\\u1ed9t trong s\\u1ed1 \\u0111\\u00f3, ch\\u1eb3ng h\\u1ea1n."}, {"index": 5, "start": 20.0, "end": 23.0, "text": "V\\u1eady n\\u00ean, t\\u00f4i xin nh\\u1eafc b\\u1ea1n r\\u1eb1ng \\u0111\\u00e2y l\\u00e0 m\\u1ed9t h\\u00ecnh \\u1ea3nh m\\u00e0 ch\\u00fang ta \\u0111\\u00e3 th\\u1ea5y trong m\\u1ed9t trong nh\\u1eefng slide \\u0111\\u1ea7u ti\\u00ean."}, {"index": 6, "start": 23.0, "end": 28.0, "text": "V\\u00e0 c\\u0169ng h\\u00e3y nh\\u1edb r\\u1eb1ng n\\u1ec1n \\u1edf \\u0111\\u00e2y b\\u1ea1n c\\u00f3 th\\u1ec3 th\\u1ea5y l\\u00e0 h\\u01a1i m\\u1edd m\\u1ed9t ch\\u00fat."}, {"index": 7, "start": 28.0, "end": 31.0, "text": "So v\\u1edbi ph\\u1ea7n foreground."}, {"index": 8, "start": 31.0, "end": 34.0, "text": "V\\u00e0 \\u0111i\\u1ec1u \\u0111\\u00f3 kh\\u00f4ng ph\\u1ea3i l\\u00e0 \\u0111i\\u1ec1u c\\u00f3 th\\u1ec3 x\\u1ea3y ra v\\u1edbi m\\u00e1y \\u1ea3nh pinhole."}, {"index": 9, "start": 34.0, "end": 36.0, "text": "T\\u1ea1i sao kh\\u00f4ng?"}, {"index": 10, "start": 36.0, "end": 40.0, "text": "H\\u00e3y nh\\u1edb r\\u1eb1ng c\\u00e1ch ho\\u1ea1t \\u0111\\u1ed9ng c\\u1ee7a m\\u00e1y \\u1ea3nh pinhole l\\u00e0 cho m\\u1ed7i \\u0111i\\u1ec3m trong th\\u1ebf gi\\u1edbi."}, {"index": 11, "start": 40.0, "end": 44.0, "text": "C\\u00f3 m\\u1ed9t tia s\\u00e1ng \\u0111\\u01a1n l\\u1ebb \\u0111i qua l\\u1ed7 nh\\u1ecf \\u0111\\u00f3"}, {"index": 12, "start": 44.0, "end": 50.0, "text": "v\\u00e0 chi\\u1ebfu v\\u00e0o m\\u1eb7t sau c\\u1ee7a m\\u00e1y \\u1ea3nh ho\\u1eb7c v\\u1eadt li\\u1ec7u nh\\u1ea1y s\\u00e1ng."}, {"index": 13, "start": 50.0, "end": 53.0, "text": "V\\u00e0 v\\u00ec v\\u1eady kh\\u00f4ng c\\u00f3 c\\u01a1 ch\\u1ebf n\\u00e0o \\u0111\\u1ec3 c\\u00e1i g\\u00ec \\u0111\\u00f3 b\\u1ecb m\\u1edd."}, {"index": 14, "start": 53.0, "end": 57.0, "text": "T\\u1ea5t c\\u1ea3 m\\u1ecdi th\\u1ee9 n\\u00ean \\u0111\\u01b0\\u1ee3c h\\u00ecnh \\u1ea3nh h\\u00f3a v\\u1edbi \\u0111\\u1ed9 n\\u00e9t ho\\u00e0n h\\u1ea3o."}, {"index": 15, "start": 57.0, "end": 63.0, "text": "V\\u00e0 l\\u00fd do m\\u00e0 m\\u00f4 h\\u00ecnh hi\\u1ec7n t\\u1ea1i c\\u1ee7a ch\\u00fang ta kh\\u00f4ng th\\u1ec3 gi\\u1ea3i th\\u00edch \\u0111\\u01b0\\u1ee3c lo\\u1ea1i hi\\u1ec7n t\\u01b0\\u1ee3ng n\\u00e0y"}, {"index": 16, "start": 63.0, "end": 65.0, "text": "l\\u00e0 v\\u00ec n\\u00f3 kh\\u00f4ng ho\\u00e0n ch\\u1ec9nh."}, {"index": 17, "start": 65.0, "end": 67.0, "text": "N\\u00f3 g\\u1ea7n nh\\u01b0ng ch\\u01b0a ho\\u00e0n to\\u00e0n \\u0111\\u00fang."}, {"index": 18, "start": 67.0, "end": 70.0, "text": "V\\u00ec v\\u1eady, h\\u00e3y \\u0111\\u1ec3 t\\u00f4i nh\\u1eafc l\\u1ea1i m\\u00f4 h\\u00ecnh \\u0111\\u00f3 m\\u1ed9t l\\u1ea7n n\\u1eefa ch\\u1ec9 v\\u1ec1 m\\u1eb7t h\\u00ecnh \\u1ea3nh."}, {"index": 19, "start": 70.0, "end": 72.0, "text": "Ch\\u00fang ta c\\u00f3 m\\u00e1y \\u1ea3nh c\\u1ee7a m\\u00ecnh."}, {"index": 20, "start": 72.0, "end": 74.0, "text": "Th\\u1ef1c ra t\\u00f4i s\\u1ebd quay l\\u1ea1i v\\u1edbi kh\\u00eda c\\u1ea1nh ti\\u00eau c\\u1ef1c m\\u1ed9t l\\u1ea7n n\\u1eefa"}, {"index": 21, "start": 74.0, "end": 77.0, "text": "b\\u1edfi v\\u00ec \\u0111i\\u1ec1u \\u0111\\u00f3 s\\u1ebd gi\\u00fap t\\u00f4i d\\u1ec5 d\\u00e0ng m\\u00f4 t\\u1ea3 nh\\u1eefng g\\u00ec ti\\u1ebfp theo."}, {"index": 22, "start": 77.0, "end": 79.0, "text": "V\\u00ec v\\u1eady, t\\u00f4i c\\u00f3 kh\\u1ea9u \\u0111\\u1ed9 ph\\u00eda tr\\u01b0\\u1edbc."}, {"index": 23, "start": 79.0, "end": 81.0, "text": "T\\u00f4i c\\u00f3 v\\u1eadt li\\u1ec7u nh\\u1ea1y s\\u00e1ng \\u1edf ph\\u00eda sau."}, {"index": 24, "start": 81.0, "end": 83.0, "text": "V\\u00e0 m\\u1ed9t l\\u1ea7n n\\u1eefa, tr\\u1ee5c quang h\\u1ecdc c\\u1ee7a t\\u00f4i n\\u1eb1m \\u1edf \\u0111\\u00e2y."}, {"index": 25, "start": 83.0, "end": 86.0, "text": "V\\u00e0 ch\\u00fang ta s\\u1ebd l\\u00e0m \\u0111i\\u1ec1u n\\u00e0y trong kh\\u00f4ng gian 2D m\\u1ed9t l\\u1ea7n n\\u1eefa v\\u00ec 3D l\\u00e0 r\\u1ea5t d\\u1ec5."}, {"index": 26, "start": 86.0, "end": 90.0, "text": "V\\u00e0 v\\u1ea5n \\u0111\\u1ec1, t\\u1ea5t nhi\\u00ean, ch\\u00ednh l\\u00e0 kh\\u1ea9u \\u0111\\u1ed9 nh\\u1ecf n\\u00e0y."}, {"index": 27, "start": 90.0, "end": 92.0, "text": "C\\u00f3 hai v\\u1ea5n \\u0111\\u1ec1 v\\u1edbi n\\u00f3."}, {"index": 28, "start": 92.0, "end": 95.0, "text": "\\u0110\\u00e2y kh\\u00f4ng ph\\u1ea3i l\\u00e0 h\\u00ecnh d\\u1ea1ng c\\u1ee7a m\\u1ed9t chi\\u1ebfc m\\u00e1y \\u1ea3nh hi\\u1ec7n \\u0111\\u1ea1i."}, {"index": 29, "start": 95.0, "end": 97.0, "text": "N\\u00f3 kh\\u00f4ng c\\u00f3 kh\\u1ea9u \\u0111\\u1ed9 b\\u00e9 x\\u00edu n\\u00e0y."}, {"index": 30, "start": 97.0, "end": 100.0, "text": "qua \\u0111\\u00f3 m\\u1ed9t tia s\\u00e1ng duy nh\\u1ea5t \\u0111i v\\u00e0o."}, {"index": 31, "start": 100.0, "end": 102.0, "text": "C\\u00f3 m\\u1ed9t v\\u00e0i l\\u00fd do cho \\u0111i\\u1ec1u \\u0111\\u00f3."}, {"index": 32, "start": 102.0, "end": 104.0, "text": "L\\u00fd do quan tr\\u1ecdng nh\\u1ea5t l\\u00e0 hi\\u1ec7u su\\u1ea5t."}, {"index": 33, "start": 104.0, "end": 107.0, "text": "Khi b\\u1ea1n ch\\u1ec9 cho ph\\u00e9p m\\u1ed9t l\\u01b0\\u1ee3ng \\u00e1nh s\\u00e1ng r\\u1ea5t nh\\u1ecf v\\u00e0o,"}, {"index": 34, "start": 107.0, "end": 111.0, "text": "b\\u1ea1n c\\u1ea7n c\\u00f3 m\\u1ed9t c\\u1ea3nh r\\u1ea5t, r\\u1ea5t s\\u00e1ng"}, {"index": 35, "start": 111.0, "end": 114.0, "text": "\\u0111\\u1ec3 c\\u00f3 th\\u1ec3 ch\\u1ee5p h\\u00ecnh m\\u1ed9t c\\u00e1ch ch\\u00ednh x\\u00e1c,"}, {"index": 36, "start": 114.0, "end": 117.0, "text": "ho\\u1eb7c b\\u1ea1n ph\\u1ea3i c\\u00f3 th\\u1eddi gian ph\\u01a1i s\\u00e1ng r\\u1ea5t d\\u00e0i"}, {"index": 37, "start": 117.0, "end": 121.0, "text": "\\u0111\\u1ec3 cho ph\\u00e9p \\u0111\\u1ee7 \\u00e1nh s\\u00e1ng v\\u00e0o nh\\u1eb1m ph\\u01a1i s\\u00e1ng \\u0111\\u00fang c\\u00e1ch."}, {"index": 38, "start": 121.0, "end": 125.0, "text": "V\\u00ec v\\u1eady, c\\u00e1c m\\u00e1y \\u1ea3nh hi\\u1ec7n \\u0111\\u1ea1i \\u0111\\u00e3 thay th\\u1ebf kh\\u1ea9u \\u0111\\u1ed9 b\\u00e9 nh\\u1ecf \\u0111\\u00f3"}, {"index": 39, "start": 125.0, "end": 127.0, "text": "b\\u1eb1ng c\\u00e1ch ch\\u1ec9 m\\u1edf m\\u1ed9t l\\u1ed7 v\\u00e0 \\u0111\\u00f3ng l\\u1ea1i."}, {"index": 40, "start": 127.0, "end": 131.0, "text": "v\\u1edbi ph\\u00e9p m\\u00e0u c\\u1ee7a quang h\\u1ecdc, \\u0111\\u00f3 l\\u00e0 th\\u1ea5u k\\u00ednh."}, {"index": 41, "start": 131.0, "end": 134.0, "text": "V\\u00e0 nh\\u1eefng g\\u00ec th\\u1ea5u k\\u00ednh l\\u00e0m, th\\u1ea5u k\\u00ednh \\u1edf \\u0111\\u00e2y trong m\\u1eaft b\\u1ea1n,"}, {"index": 42, "start": 134.0, "end": 137.0, "text": "th\\u1ea5u k\\u00ednh trong m\\u00e1y \\u1ea3nh, th\\u1ea5u k\\u00ednh trong k\\u00ednh vi\\u1ec5n v\\u1ecdng,"}, {"index": 43, "start": 137.0, "end": 141.0, "text": "thu th\\u1eadp \\u00e1nh s\\u00e1ng t\\u1eeb nhi\\u1ec1u h\\u01b0\\u1edbng kh\\u00e1c nhau"}, {"index": 44, "start": 141.0, "end": 143.0, "text": "v\\u00e0 t\\u1eadp trung \\u00e1nh s\\u00e1ng \\u0111\\u00f3."}, {"index": 45, "start": 143.0, "end": 146.0, "text": "V\\u00e0 b\\u1ea1n c\\u00f3 th\\u1ec3 minh h\\u1ecda \\u0111i\\u1ec1u \\u0111\\u00f3 m\\u1ed9t c\\u00e1ch kh\\u00e1 \\u0111\\u01a1n gi\\u1ea3n"}, {"index": 46, "start": 146.0, "end": 149.0, "text": "n\\u1ebfu b\\u1ea1n gi\\u1ea3 \\u0111\\u1ecbnh m\\u1ed9t m\\u00f4 h\\u00ecnh th\\u1ea5u k\\u00ednh m\\u1ecfng r\\u1ea5t \\u0111\\u01a1n gi\\u1ea3n,"}, {"index": 47, "start": 149.0, "end": 153.0, "text": "m\\u00f4 h\\u00ecnh n\\u00e0y kh\\u00f4ng th\\u1eadt s\\u1ef1 l\\u00e0 m\\u00f4 h\\u00ecnh t\\u1ed5ng qu\\u00e1t nh\\u1ea5t c\\u00f3 th\\u1ec3 cho c\\u00e1c th\\u1ea5u k\\u00ednh,"}, {"index": 48, "start": 153.0, "end": 156.0, "text": "nh\\u01b0ng n\\u00f3 s\\u1ebd \\u0111\\u1ee7 t\\u1ed1t cho nh\\u1eefng g\\u00ec ch\\u00fang ta c\\u1ea7n l\\u00e0m."}, {"index": 49, "start": 156.0, "end": 157.0, "text": "V\\u00e0 \\u0111\\u00e2y l\\u00e0 \\u00fd t\\u01b0\\u1edfng."}, {"index": 50, "start": 157.0, "end": 159.0, "text": "T\\u00f4i c\\u00f3 m\\u1ed9t \\u0111i\\u1ec3m \\u1edf \\u0111\\u00e2y trong th\\u1ebf gi\\u1edbi c\\u1ee7a m\\u00ecnh."}, {"index": 51, "start": 159.0, "end": 162.0, "text": "v\\u00e0 \\u0111\\u00f3 l\\u00e0 tia s\\u00e1ng m\\u00e0 t\\u00f4i \\u0111ang ch\\u1ec9 cho b\\u1ea1n, \\u0111i ngay qua gi\\u1eefa."}, {"index": 52, "start": 162.0, "end": 163.0, "text": "tr\\u00f4ng c\\u00f3 v\\u1ebb r\\u1ea5t quen thu\\u1ed9c."}, {"index": 53, "start": 163.0, "end": 164.0, "text": "\\u0110\\u00e2y l\\u00e0 c\\u1ea3m bi\\u1ebfn m\\u1ed9t l\\u1ea7n n\\u1eefa."}, {"index": 54, "start": 164.0, "end": 167.0, "text": "\\u0110\\u00f3 tr\\u00f4ng gi\\u1ed1ng nh\\u01b0 tia s\\u00e1ng chi\\u1ebfu ph\\u1ed1i c\\u1ea3nh,"}, {"index": 55, "start": 167.0, "end": 169.0, "text": "tia s\\u00e1ng \\u0111\\u01a1n l\\u1ebb n\\u1ebfu b\\u1ea1n t\\u01b0\\u1edfng t\\u01b0\\u1ee3ng l\\u1ea5y \\u1ed1ng k\\u00ednh \\u0111\\u00f3,"}, {"index": 56, "start": 169.0, "end": 172.0, "text": "v\\u00e0 ch\\u1ec9 c\\u1ea7n \\u0111\\u00f3ng l\\u1ea1i cho \\u0111\\u1ebfn khi ch\\u1ec9 m\\u1ed9t tia s\\u00e1ng \\u0111i qua."}, {"index": 57, "start": 172.0, "end": 175.0, "text": "Nh\\u01b0ng t\\u1ea5t nhi\\u00ean, \\u0111i\\u1ec3m \\u0111\\u00f3 trong th\\u1ebf gi\\u1edbi,"}, {"index": 58, "start": 175.0, "end": 177.0, "text": "ph\\u00e1t ra \\u00e1nh s\\u00e1ng theo m\\u1ecdi h\\u01b0\\u1edbng."}, {"index": 59, "start": 177.0, "end": 179.0, "text": "Nh\\u1edb r\\u1eb1ng ch\\u00fang ta c\\u00f3 ngu\\u1ed3n \\u00e1nh s\\u00e1ng,"}, {"index": 60, "start": 179.0, "end": 182.0, "text": "n\\u00f3 va \\u0111\\u1ebfn \\u0111\\u00e2y v\\u00e0 sau \\u0111\\u00f3 \\u00e1nh s\\u00e1ng d\\u1ed9i l\\u1ea1i theo m\\u1ecdi h\\u01b0\\u1edbng"}, {"index": 61, "start": 182.0, "end": 188.0, "text": "v\\u00e0 sau \\u0111\\u00f3 \\u1ed1ng k\\u00ednh n\\u00e0y thu nh\\u1eadn m\\u1ed9t s\\u1ed1 tia s\\u00e1ng \\u0111\\u00f3,"}, {"index": 62, "start": 188.0, "end": 189.0, "text": "m\\u1ed9t s\\u1ed1 l\\u01b0\\u1ee3ng l\\u1edbn ch\\u00fang,"}, {"index": 63, "start": 189.0, "end": 192.0, "text": "nh\\u01b0ng sau \\u0111\\u00f3 \\u0111i\\u1ec1u k\\u1ef3 di\\u1ec7u x\\u1ea3y ra \\u0111\\u00f3 l\\u00e0 n\\u00f3 t\\u1eadp trung nh\\u1eefng tia s\\u00e1ng \\u0111\\u00f3"}, {"index": 64, "start": 192.0, "end": 195.0, "text": "v\\u00e0o m\\u1ed9t \\u0111i\\u1ec3m duy nh\\u1ea5t."}, {"index": 65, "start": 195.0, "end": 198.0, "text": "V\\u00e0 n\\u1ebfu \\u0111i\\u1ec3m \\u0111\\u00f3 \\u1edf \\u0111\\u00e2y ch\\u1eb3ng h\\u1ea1n"}, {"index": 66, "start": 198.0, "end": 200.0, "text": "thay v\\u00ec \\u1edf \\u0111\\u00e2y,"}, {"index": 67, "start": 200.0, "end": 203.0, "text": "th\\u00ec tia s\\u00e1ng trung t\\u00e2m c\\u0169ng l\\u00e0m \\u0111i\\u1ec1u t\\u01b0\\u01a1ng t\\u1ef1"}, {"index": 68, "start": 203.0, "end": 205.0, "text": "v\\u00e0 sau \\u0111\\u00f3 nh\\u1eefng tia s\\u00e1ng n\\u00e0y u\\u1ed1n cong"}, {"index": 69, "start": 205.0, "end": 208.0, "text": "v\\u00e0 ch\\u00fang u\\u1ed1n cong \\u0111\\u1ec3 t\\u1eadp trung \\u00e1nh s\\u00e1ng m\\u1ed9t c\\u00e1ch ho\\u00e0n h\\u1ea3o."}, {"index": 70, "start": 208.0, "end": 210.0, "text": "V\\u00ec v\\u1eady gi\\u1edd \\u0111\\u00e2y ch\\u00fang ta c\\u00f3 th\\u1ec3,"}, {"index": 71, "start": 210.0, "end": 213.0, "text": "ch\\u00fang ta c\\u00f3 m\\u1ed9t v\\u00e0i \\u0111i\\u1ec1u \\u0111ang ho\\u1ea1t \\u0111\\u1ed9ng c\\u00f3 l\\u1ee3i cho ch\\u00fang ta."}, {"index": 72, "start": 213.0, "end": 215.0, "text": "M\\u1ed9t l\\u00e0 ch\\u00fang ta c\\u00f3 th\\u1ec3 thu th\\u1eadp nhi\\u1ec1u \\u00e1nh s\\u00e1ng h\\u01a1n"}, {"index": 73, "start": 215.0, "end": 216.0, "text": "v\\u00ec v\\u1eady ch\\u00fang ta c\\u00f3 hi\\u1ec7u su\\u1ea5t cao h\\u01a1n,"}, {"index": 74, "start": 216.0, "end": 218.0, "text": "nh\\u01b0ng m\\u1ed9t \\u0111i\\u1ec1u g\\u00ec \\u0111\\u00f3 s\\u1ebd th\\u00fa v\\u1ecb"}, {"index": 75, "start": 218.0, "end": 219.0, "text": "s\\u1ebd x\\u1ea3y ra."}, {"index": 76, "start": 219.0, "end": 221.0, "text": "H\\u00e3y ch\\u00fa \\u00fd r\\u1eb1ng hai \\u0111i\\u1ec3m m\\u00e0 t\\u00f4i \\u0111\\u00e3 v\\u1ebd"}, {"index": 77, "start": 221.0, "end": 226.0, "text": "c\\u00e1ch nhau c\\u00f9ng m\\u1ed9t kho\\u1ea3ng c\\u00e1ch t\\u01b0\\u01a1ng \\u0111\\u1ed1i v\\u1edbi \\u1ed1ng k\\u00ednh"}, {"index": 78, "start": 226.0, "end": 227.0, "text": "ho\\u1eb7c camera."}, {"index": 79, "start": 227.0, "end": 230.0, "text": "Chuy\\u1ec7n g\\u00ec s\\u1ebd x\\u1ea3y ra khi \\u0111i\\u1ec3m n\\u00e0y g\\u1ea7n l\\u1ea1i?"}, {"index": 80, "start": 230.0, "end": 233.0, "text": "\\u00c0, tia ch\\u00ednh \\u0111\\u00f3 th\\u00ec th\\u1ef1c s\\u1ef1 kh\\u00f4ng c\\u00f3 g\\u00ec x\\u1ea3y ra,"}, {"index": 81, "start": 233.0, "end": 234.0, "text": "c\\u0169ng gi\\u1ed1ng nh\\u01b0 v\\u1eady,"}, {"index": 82, "start": 234.0, "end": 236.0, "text": "n\\u00f3 ch\\u1ec9 \\u0111i th\\u1eb3ng qua v\\u00e0 t\\u1ea1o h\\u00ecnh \\u1ea3nh,"}, {"index": 83, "start": 236.0, "end": 239.0, "text": "nh\\u01b0ng nh\\u1eefng tia kh\\u00e1c \\u0111i qua th\\u00ec"}, {"index": 84, "start": 239.0, "end": 241.0, "text": "c\\u00e1c b\\u1ea1n ch\\u00fa \\u00fd l\\u00e0 khi ch\\u00fang u\\u1ed1n cong"}, {"index": 85, "start": 241.0, "end": 243.0, "text": "th\\u00ec ch\\u00fang kh\\u00f4ng ho\\u00e0n to\\u00e0n h\\u1ed9i t\\u1ee5,"}, {"index": 86, "start": 243.0, "end": 245.0, "text": "ch\\u00fang h\\u01a1i b\\u1ecb m\\u1edd,"}, {"index": 87, "start": 245.0, "end": 247.0, "text": "v\\u00e0 s\\u1ebd tr\\u1edf n\\u00ean m\\u1edd."}, {"index": 88, "start": 247.0, "end": 248.0, "text": "T\\u1ea1i sao l\\u1ea1i m\\u1edd?"}, {"index": 89, "start": 248.0, "end": 250.0, "text": "\\u00c0, c\\u00e1i \\u0111i\\u1ec3m nh\\u1ecf \\u0111\\u00f3,"}, {"index": 90, "start": 250.0, "end": 253.0, "text": "c\\u00e1i \\u0111i\\u1ec3m nh\\u1ecf duy nh\\u1ea5t \\u0111ang ph\\u1ea3n x\\u1ea1 \\u00e1nh s\\u00e1ng"}, {"index": 91, "start": 253.0, "end": 254.0, "text": "theo nhi\\u1ec1u h\\u01b0\\u1edbng kh\\u00e1c nhau"}, {"index": 92, "start": 254.0, "end": 256.0, "text": "s\\u1ebd b\\u1ecb lan ra"}, {"index": 93, "start": 256.0, "end": 258.0, "text": "tr\\u00ean khu v\\u1ef1c nh\\u1ecf n\\u00e0y."}, {"index": 94, "start": 258.0, "end": 260.0, "text": "V\\u00e0 n\\u1ebfu \\u0111i\\u1ec3m \\u0111\\u00f3 \\u1edf xa h\\u01a1n"}, {"index": 95, "start": 260.0, "end": 261.0, "text": "so v\\u1edbi v\\u1ecb tr\\u00ed ch\\u00fang ta \\u0111\\u00e3 n\\u00f3i tr\\u01b0\\u1edbc \\u0111\\u00f3,"}, {"index": 96, "start": 261.0, "end": 262.0, "text": "t\\u1ee9c l\\u00e0 ngay \\u0111\\u00f3,"}, {"index": 97, "start": 262.0, "end": 265.0, "text": "th\\u00ec n\\u00f3 s\\u1ebd h\\u1ed9i t\\u1ee5 qu\\u00e1 s\\u1edbm"}, {"index": 98, "start": 265.0, "end": 267.0, "text": "v\\u00e0 v\\u1eabn b\\u1ecb lan ra"}, {"index": 99, "start": 267.0, "end": 269.0, "text": "m\\u1ed9t ch\\u00fat."}, {"index": 100, "start": 269.0, "end": 271.0, "text": "V\\u00e0 \\u0111\\u00e2y l\\u00e0 nh\\u1eefng g\\u00ec \\u0111ang g\\u00e2y ra"}, {"index": 101, "start": 271.0, "end": 273.0, "text": "s\\u1ef1 kh\\u00e1c bi\\u1ec7t \\u0111\\u00f3 trong s\\u1ef1 t\\u1eadp trung"}, {"index": 102, "start": 273.0, "end": 275.0, "text": "\\u0111\\u1ed1i v\\u1edbi t\\u00f4i trong b\\u1ee9c tranh \\u0111\\u00f3"}, {"index": 103, "start": 275.0, "end": 277.0, "text": "v\\u00e0 \\u0111\\u1ed1i v\\u1edbi n\\u1ec1n,"}, {"index": 104, "start": 277.0, "end": 278.0, "text": "n\\u00f3 x\\u1ea3y ra v\\u00ec \\u0111i\\u1ec1u n\\u00e0y."}, {"index": 105, "start": 278.0, "end": 280.0, "text": "V\\u00e0 gi\\u1edd \\u0111\\u00e2y, r\\u00f5 r\\u00e0ng l\\u00e0 \\u0111i\\u1ec1u ch\\u00fang ta mu\\u1ed1n l\\u00e0m"}, {"index": 106, "start": 280.0, "end": 281.0, "text": "l\\u00e0 \\u0111\\u1ecbnh l\\u01b0\\u1ee3ng \\u0111i\\u1ec1u n\\u00e0y m\\u1ed9t ch\\u00fat"}, {"index": 107, "start": 281.0, "end": 283.0, "text": "v\\u00e0 \\u0111\\u01b0a ra m\\u1ed9t s\\u1ed1 ph\\u01b0\\u01a1ng tr\\u00ecnh"}, {"index": 108, "start": 283.0, "end": 285.0, "text": "\\u0111\\u1ec3 gi\\u1ea3i th\\u00edch nh\\u1eefng g\\u00ec \\u0111ang di\\u1ec5n ra."}, {"index": 109, "start": 285.0, "end": 287.0, "text": "V\\u1eady h\\u00e3y l\\u00e0m \\u0111i\\u1ec1u \\u0111\\u00f3 ti\\u1ebfp theo."}, {"index": 110, "start": 287.0, "end": 289.0, "text": "\\u0110\\u1ea7u ti\\u00ean v\\u00e0 quan tr\\u1ecdng nh\\u1ea5t,"}, {"index": 111, "start": 289.0, "end": 291.0, "text": "h\\u00e3y l\\u01b0u \\u00fd r\\u1eb1ng ch\\u00fang ta ch\\u01b0a b\\u1ecf \\u0111i"}, {"index": 112, "start": 291.0, "end": 292.0, "text": "m\\u00e1y \\u1ea3nh ch\\u00f3p."}, {"index": 113, "start": 292.0, "end": 294.0, "text": "\\u0110i\\u1ec1u n\\u00e0y th\\u1ef1c s\\u1ef1 l\\u00e0 m\\u1ed9t s\\u1ef1 t\\u1ed5ng qu\\u00e1t"}, {"index": 114, "start": 294.0, "end": 295.0, "text": "theo c\\u00e1ch r\\u1ea5t \\u0111\\u1eb9p."}, {"index": 115, "start": 295.0, "end": 297.0, "text": "V\\u00ec v\\u1eady, n\\u1ebfu t\\u00f4i l\\u1ea5y m\\u1ed9t \\u0111i\\u1ec3m trong th\\u1ebf gi\\u1edbi"}, {"index": 116, "start": 297.0, "end": 299.0, "text": "v\\u00e0 gi\\u1edd t\\u00f4i s\\u1ebd tr\\u1edf v\\u1ec1 m\\u00f4 h\\u00ecnh c\\u0169"}, {"index": 117, "start": 299.0, "end": 300.0, "text": "b\\u1edfi v\\u00ec t\\u00f4i kh\\u00f4ng c\\u1ea7n ph\\u1ea3i lo l\\u1eafng"}, {"index": 118, "start": 300.0, "end": 302.0, "text": "v\\u1ec1 t\\u1ea5t c\\u1ea3 c\\u00e1c bi\\u1ebfn \\u0111\\u1ed5i t\\u1ecda \\u0111\\u1ed9,"}, {"index": 119, "start": 302.0, "end": 303.0, "text": "t\\u00f4i ch\\u1ec9 mu\\u1ed1n l\\u00e0m \\u0111i\\u1ec1u g\\u00ec \\u0111\\u00f3 \\u0111\\u01a1n gi\\u1ea3n."}, {"index": 120, "start": 303.0, "end": 305.0, "text": "T\\u00f4i c\\u00f3 m\\u1ed9t \\u0111i\\u1ec3m \\u1edf trong th\\u1ebf gi\\u1edbi,"}, {"index": 121, "start": 305.0, "end": 307.0, "text": "n\\u00f3 \\u0111\\u01b0\\u1ee3c bi\\u1ec3u th\\u1ecb b\\u1eb1ng ch\\u1eef X vi\\u1ebft hoa, Z vi\\u1ebft hoa"}, {"index": 122, "start": 307.0, "end": 309.0, "text": "v\\u00e0 tia trung t\\u00e2m \\u0111\\u00f3"}, {"index": 123, "start": 309.0, "end": 311.0, "text": "\\u0111i qua \\u0111\\u00e2y"}, {"index": 124, "start": 311.0, "end": 313.0, "text": "s\\u1ebd chi\\u1ebfu ra"}, {"index": 125, "start": 313.0, "end": 315.0, "text": "\\u00e2m fx"}, {"index": 126, "start": 315.0, "end": 316.0, "text": "tr\\u00ean Z."}, {"index": 127, "start": 316.0, "end": 318.0, "text": "C\\u00f9ng c\\u00e1c ph\\u01b0\\u01a1ng tr\\u00ecnh chi\\u1ebfu quan \\u0111i\\u1ec3m nh\\u01b0 c\\u0169."}, {"index": 128, "start": 318.0, "end": 320.0, "text": "V\\u00ec v\\u1eady, \\u0111i\\u1ec1u \\u0111\\u00f3 v\\u1eabn gi\\u1eef nguy\\u00ean."}, {"index": 129, "start": 320.0, "end": 322.0, "text": "Ch\\u1ec9 l\\u00e0 b\\u00e2y gi\\u1edd ch\\u00fang ta ph\\u1ea3i x\\u1eed l\\u00fd"}, {"index": 130, "start": 322.0, "end": 324.0, "text": "tr\\u01b0\\u1eddng h\\u1ee3p khi \\u0111i\\u1ec3m"}, {"index": 131, "start": 324.0, "end": 326.0, "text": "g\\u1ea7n h\\u01a1n v\\u00e0 xa h\\u01a1n"}, {"index": 132, "start": 326.0, "end": 328.0, "text": "n\\u00f3 s\\u1ebd b\\u1ecb m\\u1edd bao nhi\\u00eau"}, {"index": 133, "start": 328.0, "end": 331.0, "text": "v\\u00e0 li\\u1ec7u ch\\u00fang ta c\\u00f3 th\\u1ec3 \\u0111\\u1ecbnh l\\u01b0\\u1ee3ng \\u0111i\\u1ec1u \\u0111\\u00f3 kh\\u00f4ng."}, {"index": 134, "start": 331.0, "end": 333.0, "text": "V\\u1eady th\\u00ec h\\u00e3y \\u0111\\u1ec3 t\\u00f4i \\u0111\\u1ecbnh ngh\\u0129a m\\u1ed9t v\\u00e0i \\u0111i\\u1ec1u"}, {"index": 135, "start": 333.0, "end": 334.0, "text": "v\\u00e0 kh\\u00f4ng may \\u1edf \\u0111\\u00e2y"}, {"index": 136, "start": 334.0, "end": 336.0, "text": "ch\\u00fang ta ph\\u1ea3i chuy\\u1ec3n \\u0111\\u1ed5i k\\u00fd hi\\u1ec7u"}, {"index": 137, "start": 336.0, "end": 337.0, "text": "\\u0111i\\u1ec1u n\\u00e0y l\\u00e0 m\\u1ed9t th\\u1ef1c t\\u1ebf kh\\u00f4ng may"}, {"index": 138, "start": 337.0, "end": 339.0, "text": "nh\\u01b0ng b\\u1ea1n c\\u0169ng s\\u1ebd th\\u1ea5y \\u0111i\\u1ec1u n\\u00e0y trong t\\u00e0i li\\u1ec7u"}, {"index": 139, "start": 339.0, "end": 341.0, "text": "v\\u00ec v\\u1eady t\\u00f4i ch\\u1ec9 quy\\u1ebft \\u0111\\u1ecbnh th\\u1ef1c hi\\u1ec7n \\u1edf \\u0111\\u00e2y."}, {"index": 140, "start": 341.0, "end": 343.0, "text": "V\\u00ec v\\u1eady, t\\u00f4i s\\u1ebd \\u0111\\u1ecbnh ngh\\u0129a"}, {"index": 141, "start": 343.0, "end": 346.0, "text": "kho\\u1ea3ng c\\u00e1ch gi\\u1eefa \\u0111i\\u1ec3m"}, {"index": 142, "start": 346.0, "end": 349.0, "text": "v\\u00e0 m\\u1eb7t tr\\u01b0\\u1edbc c\\u1ee7a m\\u00e1y \\u1ea3nh l\\u00e0 Z"}, {"index": 143, "start": 349.0, "end": 350.0, "text": "gi\\u1ed1ng nh\\u01b0 tr\\u01b0\\u1edbc \\u0111\\u00e2y"}, {"index": 144, "start": 350.0, "end": 352.0, "text": "tr\\u00ean tr\\u1ee5c quang h\\u1ecdc"}, {"index": 145, "start": 352.0, "end": 354.0, "text": "v\\u00e0 b\\u00e2y gi\\u1edd t\\u00f4i s\\u1ebd \\u0111\\u1ecbnh ngh\\u0129a l\\u1ea1i"}, {"index": 146, "start": 354.0, "end": 356.0, "text": "kho\\u1ea3ng c\\u00e1ch n\\u00e0y gi\\u1eefa \\u1ed1ng k\\u00ednh"}, {"index": 147, "start": 356.0, "end": 359.0, "text": "v\\u00e0 m\\u1eb7t sau c\\u1ee7a c\\u1ea3m bi\\u1ebfn"}, {"index": 148, "start": 359.0, "end": 361.0, "text": "l\\u00e0 D thay v\\u00ec f"}, {"index": 149, "start": 361.0, "end": 362.0, "text": "v\\u00e0 b\\u1ea1n s\\u1ebd th\\u1ea5y trong m\\u1ed9t ch\\u00fat"}, {"index": 150, "start": 362.0, "end": 364.0, "text": "t\\u1ea1i sao l\\u1ea1i nh\\u01b0 v\\u1eady"}, {"index": 151, "start": 364.0, "end": 366.0, "text": "v\\u00e0 b\\u00e2y gi\\u1edd l\\u00fd do t\\u00f4i l\\u00e0m \\u0111i\\u1ec1u \\u0111\\u00f3"}, {"index": 152, "start": 366.0, "end": 368.0, "text": "l\\u00e0 v\\u00ec ch\\u00fang ta s\\u1ebd"}, {"index": 153, "start": 368.0, "end": 370.0, "text": "\\u0111\\u1ecbnh ngh\\u0129a chi\\u1ec1u d\\u00e0i ti\\u00eau c\\u1ef1"}, {"index": 154, "start": 370.0, "end": 372.0, "text": "c\\u1ee7a \\u1ed1ng k\\u00ednh l\\u00e0 f nh\\u1ecf"}, {"index": 155, "start": 372.0, "end": 374.0, "text": "v\\u00ec v\\u1eady n\\u00f3 kh\\u00f4ng c\\u00f2n l\\u00e0 kho\\u1ea3ng c\\u00e1ch"}, {"index": 156, "start": 374.0, "end": 375.0, "text": "t\\u1eeb \\u1ed1ng k\\u00ednh \\u0111\\u1ebfn c\\u1ea3m bi\\u1ebfn"}, {"index": 157, "start": 375.0, "end": 377.0, "text": "m\\u00e0 n\\u00f3 l\\u00e0 chi\\u1ec1u d\\u00e0i ti\\u00eau c\\u1ef1"}, {"index": 158, "start": 377.0, "end": 379.0, "text": "li\\u00ean quan \\u0111\\u1ebfn t\\u00ednh ch\\u1ea5t b\\u1ebb cong n\\u00e0y"}, {"index": 159, "start": 379.0, "end": 381.0, "text": "m\\u00e0 b\\u1ea1n \\u0111ang th\\u1ea5y c\\u1ee7a \\u00e1nh s\\u00e1ng \\u1edf \\u0111\\u00e2y"}, {"index": 160, "start": 381.0, "end": 384.0, "text": "v\\u00e0 \\u0111i\\u1ec1u \\u0111\\u00f3 \\u0111\\u01b0\\u1ee3c \\u0111\\u1ecbnh ngh\\u0129a nh\\u01b0 sau"}, {"index": 161, "start": 384.0, "end": 386.0, "text": "1 chia cho f, l\\u00e0 chi\\u1ec1u d\\u00e0i ti\\u00eau c\\u1ef1"}, {"index": 162, "start": 386.0, "end": 387.0, "text": "c\\u1ee7a th\\u1ea5u k\\u00ednh"}, {"index": 163, "start": 387.0, "end": 388.0, "text": "\\u0111i\\u1ec1u n\\u00e0y \\u0111\\u1ecbnh ngh\\u0129a s\\u1ef1 kh\\u00fac x\\u1ea1 c\\u1ee7a \\u00e1nh s\\u00e1ng"}, {"index": 164, "start": 388.0, "end": 390.0, "text": "b\\u1eb1ng 1 chia cho Z"}, {"index": 165, "start": 390.0, "end": 392.0, "text": "c\\u1ed9ng v\\u1edbi 1 chia cho D"}, {"index": 166, "start": 392.0, "end": 394.0, "text": "n\\u01a1i D l\\u00e0 kho\\u1ea3ng c\\u00e1ch t\\u1eeb th\\u1ea5u k\\u00ednh \\u0111\\u1ebfn"}, {"index": 167, "start": 394.0, "end": 396.0, "text": "c\\u1ea3m bi\\u1ebfn."}, {"index": 168, "start": 396.0, "end": 398.0, "text": "\\u0110\\u01b0\\u1ee3c r\\u1ed3i, b\\u00e2y gi\\u1edd"}, {"index": 169, "start": 398.0, "end": 400.0, "text": "\\u0111i\\u1ec1u \\u0111\\u00f3 c\\u00f3 ngh\\u0129a l\\u00e0 g\\u00ec v\\u1ec1 chi\\u1ec1u d\\u00e0i ti\\u00eau c\\u1ef1"}, {"index": 170, "start": 400.0, "end": 402.0, "text": "th\\u1ef1c ra c\\u00f3 m\\u1ed9t c\\u00e1ch di\\u1ec5n gi\\u1ea3i h\\u00ecnh h\\u1ecdc r\\u1ea5t \\u0111\\u1eb9p v\\u1ec1 n\\u00f3"}, {"index": 171, "start": 402.0, "end": 404.0, "text": "l\\u1ea5y m\\u1ed9t \\u0111i\\u1ec3m"}, {"index": 172, "start": 404.0, "end": 406.0, "text": "ra \\u0111\\u00e2y trong th\\u1ebf gi\\u1edbi"}, {"index": 173, "start": 406.0, "end": 408.0, "text": "c\\u00f3 kho\\u1ea3ng c\\u00e1ch b\\u1eb1ng"}, {"index": 174, "start": 408.0, "end": 410.0, "text": "chi\\u1ec1u cao c\\u1ee7a"}, {"index": 175, "start": 410.0, "end": 412.0, "text": "th\\u1ea5u k\\u00ednh"}, {"index": 176, "start": 412.0, "end": 414.0, "text": "v\\u00e0 v\\u1ebd r\\u1eb1ng tia s\\u1ebd di chuy\\u1ec3n"}, {"index": 177, "start": 414.0, "end": 416.0, "text": "th\\u1eb3ng v\\u00e0 n\\u00f3 s\\u1ebd b\\u1ecb kh\\u00fac x\\u1ea1"}, {"index": 178, "start": 416.0, "end": 418.0, "text": "v\\u00e0 n\\u01a1i n\\u00f3 c\\u1eaft tr\\u1ee5c quang"}, {"index": 179, "start": 418.0, "end": 420.0, "text": "\\u0111\\u01b0\\u1ee3c \\u0111\\u1ecbnh ngh\\u0129a l\\u00e0 chi\\u1ec1u d\\u00e0i ti\\u00eau c\\u1ef1"}, {"index": 180, "start": 420.0, "end": 422.0, "text": "c\\u1ee7a th\\u1ea5u k\\u00ednh"}, {"index": 181, "start": 422.0, "end": 424.0, "text": "b\\u1ea1n c\\u00f3 th\\u1ec3 l\\u00e0m \\u0111i\\u1ec1u n\\u00e0y theo h\\u01b0\\u1edbng ng\\u01b0\\u1ee3c l\\u1ea1i"}, {"index": 182, "start": 424.0, "end": 426.0, "text": "nh\\u00e2n ti\\u1ec7n, b\\u1ea1n c\\u00f3 th\\u1ec3 b\\u1eaft \\u0111\\u1ea7u t\\u1eeb \\u0111\\u00e2y"}, {"index": 183, "start": 426.0, "end": 428.0, "text": "\\u0111i th\\u1eb3ng ra ngo\\u00e0i"}, {"index": 184, "start": 428.0, "end": 430.0, "text": "b\\u1ebb cong \\u00e1nh s\\u00e1ng ra th\\u1ebf gi\\u1edbi"}, {"index": 185, "start": 430.0, "end": 432.0, "text": "v\\u00e0 ch\\u1ed7 m\\u00e0 n\\u00f3 c\\u1eaft qua tr\\u1ee5c quang h\\u1ecdc"}, {"index": 186, "start": 432.0, "end": 434.0, "text": "\\u0111\\u01b0\\u1ee3c x\\u00e1c \\u0111\\u1ecbnh l\\u00e0 chi\\u1ec1u d\\u00e0i ti\\u00eau c\\u1ef1"}, {"index": 187, "start": 434.0, "end": 436.0, "text": "n\\u00f3 li\\u00ean quan nh\\u01b0 b\\u1ea1n c\\u00f3 th\\u1ec3 th\\u1ea5y \\u1edf \\u0111\\u00e2y"}, {"index": 188, "start": 436.0, "end": 438.0, "text": "\\u0111\\u1ebfn c\\u00e1c thu\\u1ed9c t\\u00ednh b\\u1ebb cong c\\u1ee7a th\\u1ea5u k\\u00ednh"}, {"index": 189, "start": 438.0, "end": 440.0, "text": "v\\u00e0 b\\u00e2y gi\\u1edd ch\\u00fang ta c\\u1ea7n hai \\u0111i\\u1ec1u"}, {"index": 190, "start": 440.0, "end": 442.0, "text": "\\u0111\\u1ec3 x\\u00e1c \\u0111\\u1ecbnh camera c\\u1ee7a ch\\u00fang ta"}, {"index": 191, "start": 442.0, "end": 444.0, "text": "kho\\u1ea3ng c\\u00e1ch t\\u1eeb th\\u1ea5u k\\u00ednh \\u0111\\u1ebfn c\\u1ea3m bi\\u1ebfn"}, {"index": 192, "start": 444.0, "end": 446.0, "text": "D, D cho kho\\u1ea3ng c\\u00e1ch, t\\u1ea5t nhi\\u00ean"}, {"index": 193, "start": 446.0, "end": 448.0, "text": "v\\u00e0 chi\\u1ec1u d\\u00e0i ti\\u00eau c\\u1ef1 c\\u1ee7a th\\u1ea5u k\\u00ednh"}, {"index": 194, "start": 448.0, "end": 450.0, "text": "l\\u00e0 f nh\\u1ecf"}, {"index": 195, "start": 450.0, "end": 452.0, "text": "v\\u00e0 n\\u00f3 \\u0111\\u01b0\\u1ee3c th\\u1ecfa m\\u00e3n b\\u1edfi ph\\u01b0\\u01a1ng tr\\u00ecnh th\\u1ea5u k\\u00ednh m\\u1ecfng \\u0111\\u00f3"}, {"index": 196, "start": 452.0, "end": 454.0, "text": "m\\u00e0 b\\u1ea1n th\\u1ea5y ngay \\u1edf \\u0111\\u00f3"}, {"index": 197, "start": 454.0, "end": 456.0, "text": "b\\u00e2y gi\\u1edd t\\u1ea5t c\\u1ea3 nh\\u1eefng \\u0111i\\u1ec1u \\u0111\\u00f3"}, {"index": 198, "start": 456.0, "end": 458.0, "text": "l\\u00e0 \\u0111\\u1ec3 \\u0111\\u01b0a ch\\u00fang ta \\u0111\\u1ebfn \\u0111i\\u1ec3m n\\u00e0y ngay t\\u1ea1i \\u0111\\u00e2y"}, {"index": 199, "start": 458.0, "end": 460.0, "text": "\\u0111i\\u1ec1u n\\u00e0y l\\u00e0 \\u0111\\u1ed9 m\\u1edd"}, {"index": 200, "start": 460.0, "end": 462.0, "text": "c\\u00e1c v\\u1eadt s\\u1ebd nh\\u01b0 th\\u1ebf n\\u00e0o"}, {"index": 201, "start": 462.0, "end": 464.0, "text": "khi ch\\u00fang di chuy\\u1ec3n v\\u00e0o v\\u00e0 ra kh\\u1ecfi"}, {"index": 202, "start": 464.0, "end": 466.0, "text": "\\u0111i\\u1ec3m m\\u00e0 ch\\u00fang n\\u1eb1m trong ti\\u00eau \\u0111i\\u1ec3m ho\\u00e0n h\\u1ea3o"}, {"index": 203, "start": 466.0, "end": 468.0, "text": "m\\u00e0 ch\\u00fang ta v\\u1eeba th\\u1ea5y"}, {"index": 204, "start": 468.0, "end": 470.0, "text": "v\\u00e0 v\\u00ec v\\u1eady ch\\u00fang ta c\\u00f3 ph\\u01b0\\u01a1ng tr\\u00ecnh th\\u1ea5u k\\u00ednh m\\u1ecfng \\u1edf \\u0111\\u00e2y"}, {"index": 205, "start": 470.0, "end": 472.0, "text": "v\\u00e0 \\u0111\\u00e2y l\\u00e0 ph\\u01b0\\u01a1ng tr\\u00ecnh c\\u1ee7a ch\\u00fang ta"}, {"index": 206, "start": 472.0, "end": 474.0, "text": "cho b\\u00e1n k\\u00ednh m\\u1edd r"}, {"index": 207, "start": 474.0, "end": 476.0, "text": "m\\u00e0 b\\u1ea1n c\\u00f3 th\\u1ec3 th\\u1ea5y"}, {"index": 208, "start": 476.0, "end": 478.0, "text": "\\u1edf \\u0111\\u00e2y"}, {"index": 209, "start": 478.0, "end": 480.0, "text": "th\\u00ec b\\u00e2y gi\\u1edd \\u0111i\\u1ec3m \\u0111\\u00f3 \\u0111ang b\\u1ecb l\\u00e0m m\\u1edd"}, {"index": 210, "start": 480.0, "end": 482.0, "text": "tr\\u00ean c\\u1ea3m bi\\u1ebfn"}, {"index": 211, "start": 482.0, "end": 484.0, "text": "v\\u1edbi m\\u1ed9t b\\u00e1n k\\u00ednh nh\\u1ecf r"}, {"index": 212, "start": 484.0, "end": 486.0, "text": "v\\u00e0 \\u0111i\\u1ec1u \\u0111\\u00f3"}, {"index": 213, "start": 486.0, "end": 488.0, "text": "\\u0111\\u01b0\\u1ee3c \\u0111\\u1ecbnh ngh\\u0129a nh\\u01b0 sau"}, {"index": 214, "start": 488.0, "end": 490.0, "text": "R l\\u1edbn, m\\u00e0 l\\u00e0 b\\u00e1n k\\u00ednh c\\u1ee7a th\\u1ea5u k\\u00ednh"}, {"index": 215, "start": 490.0, "end": 492.0, "text": "k\\u00edch th\\u01b0\\u1edbc c\\u1ee7a th\\u1ea5u k\\u00ednh l\\u00e0 bao nhi\\u00eau"}, {"index": 216, "start": 492.0, "end": 494.0, "text": "chia cho 1 tr\\u00ean f tr\\u1eeb 1 tr\\u00ean"}, {"index": 217, "start": 494.0, "end": 496.0, "text": "z naught, z naught t\\u1ea5t nhi\\u00ean"}, {"index": 218, "start": 496.0, "end": 498.0, "text": "ch\\u1ec9 l\\u00e0 kho\\u1ea3ng c\\u00e1ch t\\u1eeb \\u0111i\\u1ec3m \\u0111\\u00f3"}, {"index": 219, "start": 498.0, "end": 500.0, "text": "nh\\u00e2n v\\u1edbi gi\\u00e1 tr\\u1ecb tuy\\u1ec7t \\u0111\\u1ed1i"}, {"index": 220, "start": 500.0, "end": 502.0, "text": "c\\u1ee7a 1 tr\\u00ean f tr\\u1eeb"}, {"index": 221, "start": 502.0, "end": 504.0, "text": "1 tr\\u00ean z kh\\u00f4ng"}, {"index": 222, "start": 504.0, "end": 506.0, "text": "\\u0111\\u00f3 l\\u00e0 c\\u00e1i \\u0111i\\u1ec1u m\\u00e0 b\\u1ea1n \\u0111\\u00e3 th\\u1ea5y \\u1edf m\\u1eabu s\\u1ed1 \\u1edf \\u0111\\u00e2y"}, {"index": 223, "start": 506.0, "end": 508.0, "text": "tr\\u1eeb 1 tr\\u00ean d"}, {"index": 224, "start": 508.0, "end": 510.0, "text": "n\\u00ean c\\u00f3 r\\u1ea5t nhi\\u1ec1u \\u0111i\\u1ec1u"}, {"index": 225, "start": 510.0, "end": 512.0, "text": "\\u0111ang di\\u1ec5n ra trong ph\\u01b0\\u01a1ng tr\\u00ecnh n\\u00e0y"}, {"index": 226, "start": 512.0, "end": 514.0, "text": "ch\\u00fang ta h\\u00e3y th\\u1ef1c hi\\u1ec7n m\\u1ed9t ki\\u1ec3m tra nhanh \\u1edf \\u0111\\u00e2y"}, {"index": 227, "start": 514.0, "end": 516.0, "text": "\\u0111i\\u1ec1u g\\u00ec x\\u1ea3y ra n\\u1ebfu t\\u00f4i l\\u1ea5y"}, {"index": 228, "start": 516.0, "end": 518.0, "text": "b\\u00e1n k\\u00ednh c\\u1ee7a th\\u1ea5u k\\u00ednh c\\u1ee7a t\\u00f4i"}, {"index": 229, "start": 518.0, "end": 520.0, "text": "v\\u00e0 t\\u00f4i \\u0111i\\u1ec1u ch\\u1ec9nh b\\u00e1n k\\u00ednh \\u0111\\u00f3"}, {"index": 230, "start": 520.0, "end": 522.0, "text": "v\\u1ec1 0"}, {"index": 231, "start": 522.0, "end": 524.0, "text": "gi\\u1edbi h\\u1ea1n khi n\\u00f3 ti\\u1ebfn g\\u1ea7n 0"}, {"index": 232, "start": 524.0, "end": 526.0, "text": "\\u0111\\u1ec3 t\\u00f4i c\\u00f3 m\\u1ed9t l\\u1ed7 nh\\u1ecf x\\u00edu"}, {"index": 233, "start": 526.0, "end": 528.0, "text": "v\\u00e0 ch\\u1ec9 c\\u00f3 m\\u1ed9t tia s\\u00e1ng \\u0111i qua"}, {"index": 234, "start": 528.0, "end": 530.0, "text": "th\\u00ec ch\\u00fang ta h\\u00e3y xem ph\\u01b0\\u01a1ng tr\\u00ecnh"}, {"index": 235, "start": 530.0, "end": 532.0, "text": "ph\\u01b0\\u01a1ng tr\\u00ecnh n\\u00f3i r\\u1eb1ng"}, {"index": 236, "start": 532.0, "end": 534.0, "text": "b\\u00e1n k\\u00ednh l\\u1edbn"}, {"index": 237, "start": 534.0, "end": 536.0, "text": "khi n\\u00f3 ti\\u1ebfn g\\u1ea7n 0"}, {"index": 238, "start": 536.0, "end": 538.0, "text": "b\\u00e1n k\\u00ednh m\\u1edd c\\u0169ng ti\\u1ebfn g\\u1ea7n 0"}, {"index": 239, "start": 538.0, "end": 540.0, "text": "v\\u00ec v\\u1eady m\\u1ecdi th\\u1ee9 \\u0111\\u1ec1u \\u0111\\u01b0\\u1ee3c h\\u00ecnh \\u1ea3nh h\\u00f3a trong s\\u1ef1 l\\u1ea5y n\\u00e9t ho\\u00e0n h\\u1ea3o"}, {"index": 240, "start": 540.0, "end": 542.0, "text": "\\u0111i\\u1ec1u \\u0111\\u00f3 th\\u1eadt h\\u1ee3p l\\u00fd"}, {"index": 241, "start": 542.0, "end": 544.0, "text": "m\\u1ee9c \\u0111\\u1ed9 nh\\u00f2e s\\u1ebd t\\u1ef7 l\\u1ec7 thu\\u1eadn"}, {"index": 242, "start": 544.0, "end": 546.0, "text": "v\\u1edbi k\\u00edch th\\u01b0\\u1edbc c\\u1ee7a \\u1ed1ng k\\u00ednh ho\\u1eb7c kh\\u1ea9u \\u0111\\u1ed9 c\\u1ee7a b\\u1ea1n"}, {"index": 243, "start": 546.0, "end": 548.0, "text": "t\\u1ea1i ph\\u00eda tr\\u01b0\\u1edbc c\\u1ee7a \\u1ed1ng k\\u00ednh"}, {"index": 244, "start": 548.0, "end": 550.0, "text": "t\\u1ed1t, \\u0111i\\u1ec1u \\u0111\\u00f3 th\\u1eadt h\\u1ee3p l\\u00fd"}, {"index": 245, "start": 550.0, "end": 552.0, "text": "c\\u00f2n \\u0111i\\u1ec1u g\\u00ec kh\\u00e1c m\\u00e0 ch\\u00fang ta bi\\u1ebft"}, {"index": 246, "start": 552.0, "end": 554.0, "text": "ch\\u00fang ta bi\\u1ebft r\\u1eb1ng khi z b\\u1eb1ng"}, {"index": 247, "start": 554.0, "end": 556.0, "text": "khi z naught b\\u1eb1ng z"}, {"index": 248, "start": 556.0, "end": 558.0, "text": "\\u0111i\\u1ec1u \\u0111\\u00f3 th\\u1ecfa m\\u00e3n ph\\u01b0\\u01a1ng tr\\u00ecnh \\u1ed1ng k\\u00ednh m\\u1ecfng"}, {"index": 249, "start": 558.0, "end": 560.0, "text": "m\\u1ecdi th\\u1ee9 n\\u00ean \\u0111\\u01b0\\u1ee3c l\\u1ea5y n\\u00e9t ho\\u00e0n h\\u1ea3o"}, {"index": 250, "start": 560.0, "end": 562.0, "text": "v\\u1eady h\\u00e3y xem chuy\\u1ec7n g\\u00ec x\\u1ea3y ra b\\u00e2y gi\\u1edd"}, {"index": 251, "start": 562.0, "end": 564.0, "text": "v\\u00ec v\\u1eady \\u1edf \\u0111\\u00e2y h\\u00e3y nh\\u00ecn v\\u00e0o gi\\u00e1 tr\\u1ecb tuy\\u1ec7t \\u0111\\u1ed1i"}, {"index": 252, "start": 564.0, "end": 566.0, "text": "gi\\u00e1 tr\\u1ecb b\\u00ean trong gi\\u00e1 tr\\u1ecb tuy\\u1ec7t \\u0111\\u1ed1i l\\u00e0"}, {"index": 253, "start": 566.0, "end": 568.0, "text": "1 tr\\u00ean f tr\\u1eeb 1 tr\\u00ean z naught"}, {"index": 254, "start": 568.0, "end": 570.0, "text": "nh\\u01b0ng n\\u1ebfu z naught b\\u1eb1ng z"}, {"index": 255, "start": 570.0, "end": 572.0, "text": "th\\u1ecfa m\\u00e3n ph\\u01b0\\u01a1ng tr\\u00ecnh \\u1ed1ng k\\u00ednh m\\u1ecfng"}, {"index": 256, "start": 572.0, "end": 574.0, "text": "m\\u00e0 ch\\u00fang ta th\\u1ea5y \\u1edf \\u0111\\u00e2y"}, {"index": 257, "start": 574.0, "end": 576.0, "text": "th\\u00ec gi\\u00e1 tr\\u1ecb \\u0111\\u00f3 b\\u1eb1ng 1 tr\\u00ean d"}, {"index": 258, "start": 576.0, "end": 578.0, "text": "1 tr\\u00ean d tr\\u1eeb 1 tr\\u00ean d"}, {"index": 259, "start": 578.0, "end": 580.0, "text": "t\\u1ea5t nhi\\u00ean b\\u1eb1ng 0 v\\u00e0 b\\u00e1n k\\u00ednh nh\\u00f2e"}, {"index": 260, "start": 580.0, "end": 582.0, "text": "l\\u00e0 0, v\\u1eady b\\u00e2y gi\\u1edd ch\\u00fang ta th\\u1ea5y"}, {"index": 261, "start": 582.0, "end": 584.0, "text": "l\\u00e0 l\\u01b0\\u1ee3ng m\\u1edd"}, {"index": 262, "start": 584.0, "end": 586.0, "text": "trong h\\u00ecnh \\u1ea3nh t\\u1ec9 l\\u1ec7 v\\u1edbi hai y\\u1ebfu t\\u1ed1"}, {"index": 263, "start": 586.0, "end": 588.0, "text": "k\\u00edch th\\u01b0\\u1edbc c\\u1ee7a kh\\u1ea9u \\u0111\\u1ed9 ho\\u1eb7c \\u1ed1ng k\\u00ednh"}, {"index": 264, "start": 588.0, "end": 590.0, "text": "v\\u00e0 kho\\u1ea3ng c\\u00e1ch ch\\u00fang ta di chuy\\u1ec3n"}, {"index": 265, "start": 590.0, "end": 592.0, "text": "v\\u00e0o v\\u00e0 ra kh\\u1ecfi"}, {"index": 266, "start": 592.0, "end": 594.0, "text": "m\\u1eb7t ph\\u1eb3ng l\\u1ea5y n\\u00e9t ho\\u00e0n h\\u1ea3o"}, {"index": 267, "start": 594.0, "end": 596.0, "text": "\\u0111\\u01b0\\u1ee3c r\\u1ed3i"}, {"index": 268, "start": 596.0, "end": 598.0, "text": "b\\u00e2y gi\\u1edd ch\\u00fang ta \\u0111\\u00e3 c\\u00f3"}, {"index": 269, "start": 598.0, "end": 600.0, "text": "g\\u1ea7n nh\\u01b0 n\\u01a1i ch\\u00fang ta c\\u1ea7n \\u0111\\u1ebfn"}, {"index": 270, "start": 600.0, "end": 602.0, "text": "\\u0111\\u1ec3 gi\\u1ea3i th\\u00edch m\\u1ed9t chi\\u1ebfc m\\u00e1y \\u1ea3nh k\\u1ef9 thu\\u1eadt s\\u1ed1 hi\\u1ec7n \\u0111\\u1ea1i"}, {"index": 271, "start": 602.0, "end": 604.0, "text": "m\\u00e0 ch\\u00fang ta s\\u1ebd s\\u1eed d\\u1ee5ng trong h\\u1ec7 th\\u1ed1ng th\\u1ecb gi\\u00e1c m\\u00e1y t\\u00ednh c\\u1ee7a m\\u00ecnh"}, {"index": 272, "start": 604.0, "end": 606.0, "text": "v\\u00e0 h\\u00e3y ch\\u00fa \\u00fd \\u0111\\u1ebfn \\u0111i\\u1ec1u g\\u00ec \\u0111\\u00f3 th\\u1eadt s\\u1ef1"}, {"index": 273, "start": 606.0, "end": 608.0, "text": "\\u0111\\u1eb9p \\u1edf \\u0111\\u00e2y nh\\u1edd v\\u00e0o s\\u1ef1 k\\u1ebft h\\u1ee3p c\\u1ee7a \\u1ed1ng k\\u00ednh"}, {"index": 274, "start": 608.0, "end": 610.0, "text": "ch\\u00fang ta kh\\u00f4ng ph\\u1ea3i v\\u1ee9t b\\u1ecf m\\u00f4 h\\u00ecnh m\\u00e1y \\u1ea3nh ph\\u1ed1i c\\u1ea3nh"}, {"index": 275, "start": 610.0, "end": 612.0, "text": "ch\\u00fang ta kh\\u00f4ng ph\\u1ea3i v\\u1ee9t b\\u1ecf m\\u1ecdi th\\u1ee9 ch\\u00fang ta \\u0111\\u00e3"}, {"index": 276, "start": 612.0, "end": 614.0, "text": "th\\u1ef1c hi\\u1ec7n v\\u1edbi m\\u00e1y \\u1ea3nh t\\u1ed1i v\\u00e0 l\\u1ed7 kim"}, {"index": 277, "start": 614.0, "end": 616.0, "text": "t\\u1ea5t c\\u1ea3 nh\\u1eefng g\\u00ec ch\\u00fang ta c\\u1ea7n l\\u00e0m l\\u00e0 th\\u00eam m\\u1ed9t thu\\u1eadt ng\\u1eef n\\u1eefa"}, {"index": 278, "start": 616.0, "end": 618.0, "text": "\\u0111\\u00f3 l\\u00e0 m\\u1ee9c \\u0111\\u1ed9"}, {"index": 279, "start": 618.0, "end": 620.0, "text": "m\\u1edd, r\\u1ea5t b\\u1ecb nh\\u00f2e"}, {"index": 280, "start": 620.0, "end": 622.0, "text": "n\\u1ed9i dung s\\u1ebd l\\u00e0"}, {"index": 281, "start": 622.0, "end": 624.0, "text": "nh\\u01b0 m\\u1ed9t h\\u00e0m c\\u1ee7a m\\u1ed9t kho\\u1ea3ng c\\u00e1ch nh\\u1ea5t \\u0111\\u1ecbnh"}, {"index": 282, "start": 624.0, "end": 626.0, "text": "t\\u1eeb m\\u00e1y \\u1ea3nh v\\u00e0 v\\u1edbi \\u0111i\\u1ec1u \\u0111\\u00f3"}, {"index": 283, "start": 626.0, "end": 628.0, "text": "ch\\u00fang ta gi\\u1edd \\u0111\\u00e2y \\u0111\\u00e3 s\\u1eb5n s\\u00e0ng \\u0111\\u1ec3 xem"}, {"index": 284, "start": 628.0, "end": 630.0, "text": "m\\u1ed9t s\\u1ed1 kh\\u00eda c\\u1ea1nh kh\\u00e1c c\\u1ee7a m\\u1ed9t"}, {"index": 285, "start": 630.0, "end": 632.0, "text": "m\\u00e1y \\u1ea3nh k\\u1ef9 thu\\u1eadt s\\u1ed1 hi\\u1ec7n \\u0111\\u1ea1i"}], "segments_by_language": {"en": [{"index": 0, "start": 0.0, "end": 5.0, "text": "We now have a pretty powerful imaging model of the relationship between"}, {"index": 1, "start": 5.0, "end": 9.0, "text": "things in the world and their image, but we're not quite there."}, {"index": 2, "start": 9.0, "end": 13.0, "text": "There's a few things that the camera obscura or the pinhole model,"}, {"index": 3, "start": 13.0, "end": 18.0, "text": "even with all that generalization, can't describe."}, {"index": 4, "start": 18.0, "end": 20.0, "text": "Here's one of them, for example."}, {"index": 5, "start": 20.0, "end": 23.0, "text": "So let me remind you this is an image we saw in one of the first slides."}, {"index": 6, "start": 23.0, "end": 28.0, "text": "And remember also that the background here you can see is slightly blurry"}, {"index": 7, "start": 28.0, "end": 31.0, "text": "relative to the foreground."}, {"index": 8, "start": 31.0, "end": 34.0, "text": "And that is not something that can happen with the pinhole camera."}, {"index": 9, "start": 34.0, "end": 36.0, "text": "Why not?"}, {"index": 10, "start": 36.0, "end": 40.0, "text": "Remember that the way the pinhole camera works is for every point in the world."}, {"index": 11, "start": 40.0, "end": 44.0, "text": "There is a single ray that projects through that small aperture"}, {"index": 12, "start": 44.0, "end": 50.0, "text": "and strikes the back of the camera or the photosensitive material."}, {"index": 13, "start": 50.0, "end": 53.0, "text": "And so there's no mechanism for something to get smeared."}, {"index": 14, "start": 53.0, "end": 57.0, "text": "Everything should be imaged into perfect focus."}, {"index": 15, "start": 57.0, "end": 63.0, "text": "And the reason why our current model can't explain this type of phenomenon"}, {"index": 16, "start": 63.0, "end": 65.0, "text": "is that it's not complete."}, {"index": 17, "start": 65.0, "end": 67.0, "text": "It's close but not quite there."}, {"index": 18, "start": 67.0, "end": 70.0, "text": "So let me remind you what the model was again just in terms of the picture."}, {"index": 19, "start": 70.0, "end": 72.0, "text": "We have our camera."}, {"index": 20, "start": 72.0, "end": 74.0, "text": "I'm actually going to revert back to the negative again"}, {"index": 21, "start": 74.0, "end": 77.0, "text": "because it's going to make it a little bit easier to describe what's next."}, {"index": 22, "start": 77.0, "end": 79.0, "text": "So I have the aperture front."}, {"index": 23, "start": 79.0, "end": 81.0, "text": "I have the photosensitive material in the back."}, {"index": 24, "start": 81.0, "end": 83.0, "text": "And again my optical axis going here."}, {"index": 25, "start": 83.0, "end": 86.0, "text": "And we're going to do this in 2D again because the 3D is very easy."}, {"index": 26, "start": 86.0, "end": 90.0, "text": "And the problem of course is right here is this little aperture."}, {"index": 27, "start": 90.0, "end": 92.0, "text": "There's two problems with it."}, {"index": 28, "start": 92.0, "end": 95.0, "text": "This is not what a modern camera looks like."}, {"index": 29, "start": 95.0, "end": 97.0, "text": "It doesn't have this tiny, tiny little aperture"}, {"index": 30, "start": 97.0, "end": 100.0, "text": "through which one single ray of light goes through."}, {"index": 31, "start": 100.0, "end": 102.0, "text": "There's a couple of reasons for that."}, {"index": 32, "start": 102.0, "end": 104.0, "text": "The most important one is efficiency."}, {"index": 33, "start": 104.0, "end": 107.0, "text": "When you only allow a tiny amount of light in,"}, {"index": 34, "start": 107.0, "end": 111.0, "text": "you need to have an extremely, extremely bright scene"}, {"index": 35, "start": 111.0, "end": 114.0, "text": "in order to image properly"}, {"index": 36, "start": 114.0, "end": 117.0, "text": "or you have to have very long exposure"}, {"index": 37, "start": 117.0, "end": 121.0, "text": "in order to allow enough light to come in to properly expose."}, {"index": 38, "start": 121.0, "end": 125.0, "text": "So modern cameras have replaced that tiny little aperture"}, {"index": 39, "start": 125.0, "end": 127.0, "text": "of just opening a hole and closing it"}, {"index": 40, "start": 127.0, "end": 131.0, "text": "with the miracle of optics which is the lens."}, {"index": 41, "start": 131.0, "end": 134.0, "text": "And what the lens does, the lens here in your eye,"}, {"index": 42, "start": 134.0, "end": 137.0, "text": "the lens in a camera, the lens in a telescope,"}, {"index": 43, "start": 137.0, "end": 141.0, "text": "collects light from a multitude of directions"}, {"index": 44, "start": 141.0, "end": 143.0, "text": "and focuses that light."}, {"index": 45, "start": 143.0, "end": 146.0, "text": "And you can draw that in a pretty simple way"}, {"index": 46, "start": 146.0, "end": 149.0, "text": "if you assume a very simple, what's called thin lens model,"}, {"index": 47, "start": 149.0, "end": 153.0, "text": "which is not really the most general possible model for lenses,"}, {"index": 48, "start": 153.0, "end": 156.0, "text": "but it's going to be good enough for what we need to do."}, {"index": 49, "start": 156.0, "end": 157.0, "text": "And so here's the idea."}, {"index": 50, "start": 157.0, "end": 159.0, "text": "I have a point out here again in my world"}, {"index": 51, "start": 159.0, "end": 162.0, "text": "and that's ray that I'm showing you going right through the middle"}, {"index": 52, "start": 162.0, "end": 163.0, "text": "looks awfully familiar."}, {"index": 53, "start": 163.0, "end": 164.0, "text": "Here's the sensor again."}, {"index": 54, "start": 164.0, "end": 167.0, "text": "That looks like the perspective projection ray,"}, {"index": 55, "start": 167.0, "end": 169.0, "text": "that single ray if you imagine taking that lens"}, {"index": 56, "start": 169.0, "end": 172.0, "text": "and just stopping it down until only one ray goes by."}, {"index": 57, "start": 172.0, "end": 175.0, "text": "But of course that point out in the world"}, {"index": 58, "start": 175.0, "end": 177.0, "text": "reflects light in all directions."}, {"index": 59, "start": 177.0, "end": 179.0, "text": "Remember we have the light source,"}, {"index": 60, "start": 179.0, "end": 182.0, "text": "it hits here and then light bounces in all directions"}, {"index": 61, "start": 182.0, "end": 188.0, "text": "and then this lens is capturing a number of those rays,"}, {"index": 62, "start": 188.0, "end": 189.0, "text": "a multitude of them,"}, {"index": 63, "start": 189.0, "end": 192.0, "text": "but then magic happens which is that it focuses those rays"}, {"index": 64, "start": 192.0, "end": 195.0, "text": "into a single point."}, {"index": 65, "start": 195.0, "end": 198.0, "text": "And so if that point is up here for example"}, {"index": 66, "start": 198.0, "end": 200.0, "text": "instead of down here,"}, {"index": 67, "start": 200.0, "end": 203.0, "text": "well then that central ray does the same thing"}, {"index": 68, "start": 203.0, "end": 205.0, "text": "and then these rays bend"}, {"index": 69, "start": 205.0, "end": 208.0, "text": "and they bend so that they focus light perfectly."}, {"index": 70, "start": 208.0, "end": 210.0, "text": "So now we can,"}, {"index": 71, "start": 210.0, "end": 213.0, "text": "we have a couple of things that are working to our advantage."}, {"index": 72, "start": 213.0, "end": 215.0, "text": "One is we can collect more light"}, {"index": 73, "start": 215.0, "end": 216.0, "text": "so we have more efficiency,"}, {"index": 74, "start": 216.0, "end": 218.0, "text": "but something is going to be interesting"}, {"index": 75, "start": 218.0, "end": 219.0, "text": "is going to happen."}, {"index": 76, "start": 219.0, "end": 221.0, "text": "Notice that these two points I've drawn"}, {"index": 77, "start": 221.0, "end": 226.0, "text": "are at the same distance relative to the lens"}, {"index": 78, "start": 226.0, "end": 227.0, "text": "or the camera."}, {"index": 79, "start": 227.0, "end": 230.0, "text": "What happens when the point gets say closer?"}, {"index": 80, "start": 230.0, "end": 233.0, "text": "Well that central ray nothing really happens,"}, {"index": 81, "start": 233.0, "end": 234.0, "text": "the same thing,"}, {"index": 82, "start": 234.0, "end": 236.0, "text": "it just goes straight through and it images,"}, {"index": 83, "start": 236.0, "end": 239.0, "text": "but these other rays that come through"}, {"index": 84, "start": 239.0, "end": 241.0, "text": "notice that when they're bending"}, {"index": 85, "start": 241.0, "end": 243.0, "text": "they're not quite focusing,"}, {"index": 86, "start": 243.0, "end": 245.0, "text": "they're a little bit out of focus,"}, {"index": 87, "start": 245.0, "end": 247.0, "text": "they're going to be blurry."}, {"index": 88, "start": 247.0, "end": 248.0, "text": "Why blurry?"}, {"index": 89, "start": 248.0, "end": 250.0, "text": "Well that point right there,"}, {"index": 90, "start": 250.0, "end": 253.0, "text": "that single tiny point that is reflecting light"}, {"index": 91, "start": 253.0, "end": 254.0, "text": "in all these directions"}, {"index": 92, "start": 254.0, "end": 256.0, "text": "is going to get smeared out"}, {"index": 93, "start": 256.0, "end": 258.0, "text": "over this little area right here."}, {"index": 94, "start": 258.0, "end": 260.0, "text": "And if the point is further"}, {"index": 95, "start": 260.0, "end": 261.0, "text": "from where we were before,"}, {"index": 96, "start": 261.0, "end": 262.0, "text": "which is right there,"}, {"index": 97, "start": 262.0, "end": 265.0, "text": "well then it's going to focus too early"}, {"index": 98, "start": 265.0, "end": 267.0, "text": "and then still get smeared out"}, {"index": 99, "start": 267.0, "end": 269.0, "text": "ever so slightly."}, {"index": 100, "start": 269.0, "end": 271.0, "text": "And this is what is causing"}, {"index": 101, "start": 271.0, "end": 273.0, "text": "that difference in focus"}, {"index": 102, "start": 273.0, "end": 275.0, "text": "for me in that picture"}, {"index": 103, "start": 275.0, "end": 277.0, "text": "and for the background,"}, {"index": 104, "start": 277.0, "end": 278.0, "text": "it's caused by this."}, {"index": 105, "start": 278.0, "end": 280.0, "text": "And now of course what we want to be able to do"}, {"index": 106, "start": 280.0, "end": 281.0, "text": "is quantify this a little bit"}, {"index": 107, "start": 281.0, "end": 283.0, "text": "and come up with some equations"}, {"index": 108, "start": 283.0, "end": 285.0, "text": "to explain what is happening."}, {"index": 109, "start": 285.0, "end": 287.0, "text": "So let's do that next."}, {"index": 110, "start": 287.0, "end": 289.0, "text": "So first and foremost,"}, {"index": 111, "start": 289.0, "end": 291.0, "text": "notice that we haven't thrown away"}, {"index": 112, "start": 291.0, "end": 292.0, "text": "the pinhole camera."}, {"index": 113, "start": 292.0, "end": 294.0, "text": "This really is a generalization"}, {"index": 114, "start": 294.0, "end": 295.0, "text": "in a very nice way."}, {"index": 115, "start": 295.0, "end": 297.0, "text": "So if I take a point out in the world"}, {"index": 116, "start": 297.0, "end": 299.0, "text": "and now I'm going to revert back to the old model"}, {"index": 117, "start": 299.0, "end": 300.0, "text": "because I don't have to worry"}, {"index": 118, "start": 300.0, "end": 302.0, "text": "about all the coordinate transformations,"}, {"index": 119, "start": 302.0, "end": 303.0, "text": "I just want to do something simple."}, {"index": 120, "start": 303.0, "end": 305.0, "text": "I have a point out in the world,"}, {"index": 121, "start": 305.0, "end": 307.0, "text": "it is denoted by capital X, capital Z"}, {"index": 122, "start": 307.0, "end": 309.0, "text": "and that center ray"}, {"index": 123, "start": 309.0, "end": 311.0, "text": "that is going through here"}, {"index": 124, "start": 311.0, "end": 313.0, "text": "is going to project to"}, {"index": 125, "start": 313.0, "end": 315.0, "text": "minus fx"}, {"index": 126, "start": 315.0, "end": 316.0, "text": "over Z."}, {"index": 127, "start": 316.0, "end": 318.0, "text": "Same old perspective projection equations."}, {"index": 128, "start": 318.0, "end": 320.0, "text": "So that stays exactly the same."}, {"index": 129, "start": 320.0, "end": 322.0, "text": "It's just that we have to deal now"}, {"index": 130, "start": 322.0, "end": 324.0, "text": "with the case when the point"}, {"index": 131, "start": 324.0, "end": 326.0, "text": "is closer and further"}, {"index": 132, "start": 326.0, "end": 328.0, "text": "how much is it going to get blurred"}, {"index": 133, "start": 328.0, "end": 331.0, "text": "and can we quantify that."}, {"index": 134, "start": 331.0, "end": 333.0, "text": "So let me define a few things"}, {"index": 135, "start": 333.0, "end": 334.0, "text": "and unfortunately here"}, {"index": 136, "start": 334.0, "end": 336.0, "text": "we have to now switch notation"}, {"index": 137, "start": 336.0, "end": 337.0, "text": "which is an unfortunate fact"}, {"index": 138, "start": 337.0, "end": 339.0, "text": "but you'll see this in the literature as well"}, {"index": 139, "start": 339.0, "end": 341.0, "text": "so I just decided to do it here."}, {"index": 140, "start": 341.0, "end": 343.0, "text": "So I'm going to define"}, {"index": 141, "start": 343.0, "end": 346.0, "text": "the distance between the point"}, {"index": 142, "start": 346.0, "end": 349.0, "text": "and the front of the camera as Z"}, {"index": 143, "start": 349.0, "end": 350.0, "text": "same as before"}, {"index": 144, "start": 350.0, "end": 352.0, "text": "along the optical axis"}, {"index": 145, "start": 352.0, "end": 354.0, "text": "and now I'm going to redefine"}, {"index": 146, "start": 354.0, "end": 356.0, "text": "this distance between the lens"}, {"index": 147, "start": 356.0, "end": 359.0, "text": "and the back of the sensor"}, {"index": 148, "start": 359.0, "end": 361.0, "text": "as D instead of f"}, {"index": 149, "start": 361.0, "end": 362.0, "text": "and you're going to see in a little bit"}, {"index": 150, "start": 362.0, "end": 364.0, "text": "why that is"}, {"index": 151, "start": 364.0, "end": 366.0, "text": "and now the reason I'm doing that"}, {"index": 152, "start": 366.0, "end": 368.0, "text": "is because we are going to now"}, {"index": 153, "start": 368.0, "end": 370.0, "text": "define the focal length"}, {"index": 154, "start": 370.0, "end": 372.0, "text": "of the lens to be little f"}, {"index": 155, "start": 372.0, "end": 374.0, "text": "so it's no longer the lens"}, {"index": 156, "start": 374.0, "end": 375.0, "text": "to sensor distance"}, {"index": 157, "start": 375.0, "end": 377.0, "text": "it's the focal length"}, {"index": 158, "start": 377.0, "end": 379.0, "text": "which has to do with this bending property"}, {"index": 159, "start": 379.0, "end": 381.0, "text": "that you're seeing of the light here"}, {"index": 160, "start": 381.0, "end": 384.0, "text": "and that is defined as follows"}, {"index": 161, "start": 384.0, "end": 386.0, "text": "1 over f the focal length"}, {"index": 162, "start": 386.0, "end": 387.0, "text": "of the lens"}, {"index": 163, "start": 387.0, "end": 388.0, "text": "which defines the bending of the light"}, {"index": 164, "start": 388.0, "end": 390.0, "text": "is equal to 1 over Z"}, {"index": 165, "start": 390.0, "end": 392.0, "text": "plus 1 over D"}, {"index": 166, "start": 392.0, "end": 394.0, "text": "where D is the lens to"}, {"index": 167, "start": 394.0, "end": 396.0, "text": "sensor distance."}, {"index": 168, "start": 396.0, "end": 398.0, "text": "Alright now"}, {"index": 169, "start": 398.0, "end": 400.0, "text": "what is that focal length by the way"}, {"index": 170, "start": 400.0, "end": 402.0, "text": "there's actually a really nice geometric interpretation of it"}, {"index": 171, "start": 402.0, "end": 404.0, "text": "take a point"}, {"index": 172, "start": 404.0, "end": 406.0, "text": "out here in the world"}, {"index": 173, "start": 406.0, "end": 408.0, "text": "that is the same distance"}, {"index": 174, "start": 408.0, "end": 410.0, "text": "up as the"}, {"index": 175, "start": 410.0, "end": 412.0, "text": "height of the lens"}, {"index": 176, "start": 412.0, "end": 414.0, "text": "and draw that that ray is going to move"}, {"index": 177, "start": 414.0, "end": 416.0, "text": "straight and it's going to bend"}, {"index": 178, "start": 416.0, "end": 418.0, "text": "and where it crosses the optical axis"}, {"index": 179, "start": 418.0, "end": 420.0, "text": "is defined as the focal length"}, {"index": 180, "start": 420.0, "end": 422.0, "text": "of the lens"}, {"index": 181, "start": 422.0, "end": 424.0, "text": "you can do this in the opposite direction"}, {"index": 182, "start": 424.0, "end": 426.0, "text": "by the way you can start from here"}, {"index": 183, "start": 426.0, "end": 428.0, "text": "go straight out"}, {"index": 184, "start": 428.0, "end": 430.0, "text": "bend the light out to the world"}, {"index": 185, "start": 430.0, "end": 432.0, "text": "and where it crosses the optical axis"}, {"index": 186, "start": 432.0, "end": 434.0, "text": "is defined as the focal length"}, {"index": 187, "start": 434.0, "end": 436.0, "text": "it has to do as you can see here"}, {"index": 188, "start": 436.0, "end": 438.0, "text": "with the bending properties of the lens"}, {"index": 189, "start": 438.0, "end": 440.0, "text": "and so now we need two things"}, {"index": 190, "start": 440.0, "end": 442.0, "text": "to define our camera"}, {"index": 191, "start": 442.0, "end": 444.0, "text": "the lens to sensor distance"}, {"index": 192, "start": 444.0, "end": 446.0, "text": "D, D for distance of course"}, {"index": 193, "start": 446.0, "end": 448.0, "text": "and the focal length of the lens"}, {"index": 194, "start": 448.0, "end": 450.0, "text": "which is little f"}, {"index": 195, "start": 450.0, "end": 452.0, "text": "and it is satisfied by that thin lens equation"}, {"index": 196, "start": 452.0, "end": 454.0, "text": "that you see right there"}, {"index": 197, "start": 454.0, "end": 456.0, "text": "now all of that"}, {"index": 198, "start": 456.0, "end": 458.0, "text": "is to get us to this point right here"}, {"index": 199, "start": 458.0, "end": 460.0, "text": "which is how blurry"}, {"index": 200, "start": 460.0, "end": 462.0, "text": "will things be"}, {"index": 201, "start": 462.0, "end": 464.0, "text": "when they move in and out of"}, {"index": 202, "start": 464.0, "end": 466.0, "text": "that point where they are in perfect focus"}, {"index": 203, "start": 466.0, "end": 468.0, "text": "that we just saw"}, {"index": 204, "start": 468.0, "end": 470.0, "text": "and so we've got our thin lens equation here"}, {"index": 205, "start": 470.0, "end": 472.0, "text": "and here is our equation"}, {"index": 206, "start": 472.0, "end": 474.0, "text": "for the blur radius r"}, {"index": 207, "start": 474.0, "end": 476.0, "text": "which you can see"}, {"index": 208, "start": 476.0, "end": 478.0, "text": "over here"}, {"index": 209, "start": 478.0, "end": 480.0, "text": "so that point now is being smeared"}, {"index": 210, "start": 480.0, "end": 482.0, "text": "across the sensor"}, {"index": 211, "start": 482.0, "end": 484.0, "text": "with some radius little r"}, {"index": 212, "start": 484.0, "end": 486.0, "text": "and that"}, {"index": 213, "start": 486.0, "end": 488.0, "text": "is defined as the following"}, {"index": 214, "start": 488.0, "end": 490.0, "text": "big r which is the radius of the lens"}, {"index": 215, "start": 490.0, "end": 492.0, "text": "how big is the lens"}, {"index": 216, "start": 492.0, "end": 494.0, "text": "divided by 1 over f minus 1 over"}, {"index": 217, "start": 494.0, "end": 496.0, "text": "z naught, z naught of course"}, {"index": 218, "start": 496.0, "end": 498.0, "text": "is just how far the point is"}, {"index": 219, "start": 498.0, "end": 500.0, "text": "times the absolute value"}, {"index": 220, "start": 500.0, "end": 502.0, "text": "of 1 over f minus"}, {"index": 221, "start": 502.0, "end": 504.0, "text": "1 over z naught"}, {"index": 222, "start": 504.0, "end": 506.0, "text": "that's that same thing that you saw in the denominator here"}, {"index": 223, "start": 506.0, "end": 508.0, "text": "minus 1 over d"}, {"index": 224, "start": 508.0, "end": 510.0, "text": "so there's a lot of things"}, {"index": 225, "start": 510.0, "end": 512.0, "text": "going on in this equation"}, {"index": 226, "start": 512.0, "end": 514.0, "text": "let's just do a quick sanity check here"}, {"index": 227, "start": 514.0, "end": 516.0, "text": "what happens if I take"}, {"index": 228, "start": 516.0, "end": 518.0, "text": "my radius of my lens"}, {"index": 229, "start": 518.0, "end": 520.0, "text": "and I drive that radius"}, {"index": 230, "start": 520.0, "end": 522.0, "text": "to 0"}, {"index": 231, "start": 522.0, "end": 524.0, "text": "the limit as it approaches 0"}, {"index": 232, "start": 524.0, "end": 526.0, "text": "so that I have a tiny tiny little pinhole"}, {"index": 233, "start": 526.0, "end": 528.0, "text": "and only a single ray of light goes through"}, {"index": 234, "start": 528.0, "end": 530.0, "text": "well let's look at the equation"}, {"index": 235, "start": 530.0, "end": 532.0, "text": "the equation says that"}, {"index": 236, "start": 532.0, "end": 534.0, "text": "big r"}, {"index": 237, "start": 534.0, "end": 536.0, "text": "as that approaches 0"}, {"index": 238, "start": 536.0, "end": 538.0, "text": "blur radius also approaches 0"}, {"index": 239, "start": 538.0, "end": 540.0, "text": "so everything is imaged into perfect focus"}, {"index": 240, "start": 540.0, "end": 542.0, "text": "so that makes sense"}, {"index": 241, "start": 542.0, "end": 544.0, "text": "the amount of blur will be proportional"}, {"index": 242, "start": 544.0, "end": 546.0, "text": "to how big your lens or your aperture is"}, {"index": 243, "start": 546.0, "end": 548.0, "text": "at the front of the lens"}, {"index": 244, "start": 548.0, "end": 550.0, "text": "good that makes sense"}, {"index": 245, "start": 550.0, "end": 552.0, "text": "what's the other thing that we know"}, {"index": 246, "start": 552.0, "end": 554.0, "text": "we know that when z is equal to"}, {"index": 247, "start": 554.0, "end": 556.0, "text": "when z naught is equal to z"}, {"index": 248, "start": 556.0, "end": 558.0, "text": "that satisfies that thin lens equation"}, {"index": 249, "start": 558.0, "end": 560.0, "text": "everything should be in perfect focus"}, {"index": 250, "start": 560.0, "end": 562.0, "text": "so let's see what happens now"}, {"index": 251, "start": 562.0, "end": 564.0, "text": "so here let's look inside the absolute"}, {"index": 252, "start": 564.0, "end": 566.0, "text": "value inside the absolute value is"}, {"index": 253, "start": 566.0, "end": 568.0, "text": "1 over f minus 1 over z naught"}, {"index": 254, "start": 568.0, "end": 570.0, "text": "but if z naught is z"}, {"index": 255, "start": 570.0, "end": 572.0, "text": "satisfying the thin lens equation"}, {"index": 256, "start": 572.0, "end": 574.0, "text": "that we see here"}, {"index": 257, "start": 574.0, "end": 576.0, "text": "well then that term is equal to 1 over d"}, {"index": 258, "start": 576.0, "end": 578.0, "text": "1 over d minus 1 over d"}, {"index": 259, "start": 578.0, "end": 580.0, "text": "of course is 0 and the blur radius"}, {"index": 260, "start": 580.0, "end": 582.0, "text": "is 0 so now what we see"}, {"index": 261, "start": 582.0, "end": 584.0, "text": "is that the amount of blur"}, {"index": 262, "start": 584.0, "end": 586.0, "text": "in the image is proportional to two things"}, {"index": 263, "start": 586.0, "end": 588.0, "text": "how big the aperture or lenses"}, {"index": 264, "start": 588.0, "end": 590.0, "text": "and then how far we move"}, {"index": 265, "start": 590.0, "end": 592.0, "text": "in and out of this"}, {"index": 266, "start": 592.0, "end": 594.0, "text": "perfect plane of focus"}, {"index": 267, "start": 594.0, "end": 596.0, "text": "okay"}, {"index": 268, "start": 596.0, "end": 598.0, "text": "now we've got"}, {"index": 269, "start": 598.0, "end": 600.0, "text": "almost where we need to be"}, {"index": 270, "start": 600.0, "end": 602.0, "text": "to explain a modern digital camera"}, {"index": 271, "start": 602.0, "end": 604.0, "text": "that we're going to be using in our computer vision systems"}, {"index": 272, "start": 604.0, "end": 606.0, "text": "and notice something really"}, {"index": 273, "start": 606.0, "end": 608.0, "text": "beautiful here by the introduction of the lens"}, {"index": 274, "start": 608.0, "end": 610.0, "text": "we didn't have to throw away the perspective camera model"}, {"index": 275, "start": 610.0, "end": 612.0, "text": "we didn't have to throw away everything we have"}, {"index": 276, "start": 612.0, "end": 614.0, "text": "done with camera obscures and pinholes"}, {"index": 277, "start": 614.0, "end": 616.0, "text": "all we had to do was add one extra"}, {"index": 278, "start": 616.0, "end": 618.0, "text": "term which is how"}, {"index": 279, "start": 618.0, "end": 620.0, "text": "blurry, much smeared"}, {"index": 280, "start": 620.0, "end": 622.0, "text": "will content be"}, {"index": 281, "start": 622.0, "end": 624.0, "text": "as a function of a certain distance"}, {"index": 282, "start": 624.0, "end": 626.0, "text": "from the camera and with that"}, {"index": 283, "start": 626.0, "end": 628.0, "text": "we're now ready to go on to look at"}, {"index": 284, "start": 628.0, "end": 630.0, "text": "some of the other aspects of a modern"}, {"index": 285, "start": 630.0, "end": 632.0, "text": "digital camera"}], "vi": [{"index": 0, "start": 0.0, "end": 5.0, "text": "Hi\\u1ec7n nay, ch\\u00fang ta \\u0111\\u00e3 c\\u00f3 m\\u1ed9t m\\u00f4 h\\u00ecnh h\\u00ecnh \\u1ea3nh kh\\u00e1 m\\u1ea1nh m\\u1ebd v\\u1ec1 m\\u1ed1i quan h\\u1ec7 gi\\u1eefa"}, {"index": 1, "start": 5.0, "end": 9.0, "text": "c\\u00e1c s\\u1ef1 v\\u1eadt trong th\\u1ebf gi\\u1edbi v\\u00e0 h\\u00ecnh \\u1ea3nh c\\u1ee7a ch\\u00fang, nh\\u01b0ng ch\\u00fang ta v\\u1eabn ch\\u01b0a ho\\u00e0n to\\u00e0n \\u0111\\u1ea1t \\u0111\\u01b0\\u1ee3c."}, {"index": 2, "start": 9.0, "end": 13.0, "text": "C\\u00f3 m\\u1ed9t v\\u00e0i \\u0111i\\u1ec1u m\\u00e0 camera obscura ho\\u1eb7c m\\u00f4 h\\u00ecnh l\\u1ed7 kim,"}, {"index": 3, "start": 13.0, "end": 18.0, "text": "d\\u00f9 c\\u00f3 t\\u1ea5t c\\u1ea3 nh\\u1eefng s\\u1ef1 t\\u1ed5ng qu\\u00e1t \\u0111\\u00f3, nh\\u01b0ng v\\u1eabn kh\\u00f4ng th\\u1ec3 m\\u00f4 t\\u1ea3."}, {"index": 4, "start": 18.0, "end": 20.0, "text": "D\\u01b0\\u1edbi \\u0111\\u00e2y l\\u00e0 m\\u1ed9t trong s\\u1ed1 \\u0111\\u00f3, ch\\u1eb3ng h\\u1ea1n."}, {"index": 5, "start": 20.0, "end": 23.0, "text": "V\\u1eady n\\u00ean, t\\u00f4i xin nh\\u1eafc b\\u1ea1n r\\u1eb1ng \\u0111\\u00e2y l\\u00e0 m\\u1ed9t h\\u00ecnh \\u1ea3nh m\\u00e0 ch\\u00fang ta \\u0111\\u00e3 th\\u1ea5y trong m\\u1ed9t trong nh\\u1eefng slide \\u0111\\u1ea7u ti\\u00ean."}, {"index": 6, "start": 23.0, "end": 28.0, "text": "V\\u00e0 c\\u0169ng h\\u00e3y nh\\u1edb r\\u1eb1ng n\\u1ec1n \\u1edf \\u0111\\u00e2y b\\u1ea1n c\\u00f3 th\\u1ec3 th\\u1ea5y l\\u00e0 h\\u01a1i m\\u1edd m\\u1ed9t ch\\u00fat."}, {"index": 7, "start": 28.0, "end": 31.0, "text": "So v\\u1edbi ph\\u1ea7n foreground."}, {"index": 8, "start": 31.0, "end": 34.0, "text": "V\\u00e0 \\u0111i\\u1ec1u \\u0111\\u00f3 kh\\u00f4ng ph\\u1ea3i l\\u00e0 \\u0111i\\u1ec1u c\\u00f3 th\\u1ec3 x\\u1ea3y ra v\\u1edbi m\\u00e1y \\u1ea3nh pinhole."}, {"index": 9, "start": 34.0, "end": 36.0, "text": "T\\u1ea1i sao kh\\u00f4ng?"}, {"index": 10, "start": 36.0, "end": 40.0, "text": "H\\u00e3y nh\\u1edb r\\u1eb1ng c\\u00e1ch ho\\u1ea1t \\u0111\\u1ed9ng c\\u1ee7a m\\u00e1y \\u1ea3nh pinhole l\\u00e0 cho m\\u1ed7i \\u0111i\\u1ec3m trong th\\u1ebf gi\\u1edbi."}, {"index": 11, "start": 40.0, "end": 44.0, "text": "C\\u00f3 m\\u1ed9t tia s\\u00e1ng \\u0111\\u01a1n l\\u1ebb \\u0111i qua l\\u1ed7 nh\\u1ecf \\u0111\\u00f3"}, {"index": 12, "start": 44.0, "end": 50.0, "text": "v\\u00e0 chi\\u1ebfu v\\u00e0o m\\u1eb7t sau c\\u1ee7a m\\u00e1y \\u1ea3nh ho\\u1eb7c v\\u1eadt li\\u1ec7u nh\\u1ea1y s\\u00e1ng."}, {"index": 13, "start": 50.0, "end": 53.0, "text": "V\\u00e0 v\\u00ec v\\u1eady kh\\u00f4ng c\\u00f3 c\\u01a1 ch\\u1ebf n\\u00e0o \\u0111\\u1ec3 c\\u00e1i g\\u00ec \\u0111\\u00f3 b\\u1ecb m\\u1edd."}, {"index": 14, "start": 53.0, "end": 57.0, "text": "T\\u1ea5t c\\u1ea3 m\\u1ecdi th\\u1ee9 n\\u00ean \\u0111\\u01b0\\u1ee3c h\\u00ecnh \\u1ea3nh h\\u00f3a v\\u1edbi \\u0111\\u1ed9 n\\u00e9t ho\\u00e0n h\\u1ea3o."}, {"index": 15, "start": 57.0, "end": 63.0, "text": "V\\u00e0 l\\u00fd do m\\u00e0 m\\u00f4 h\\u00ecnh hi\\u1ec7n t\\u1ea1i c\\u1ee7a ch\\u00fang ta kh\\u00f4ng th\\u1ec3 gi\\u1ea3i th\\u00edch \\u0111\\u01b0\\u1ee3c lo\\u1ea1i hi\\u1ec7n t\\u01b0\\u1ee3ng n\\u00e0y"}, {"index": 16, "start": 63.0, "end": 65.0, "text": "l\\u00e0 v\\u00ec n\\u00f3 kh\\u00f4ng ho\\u00e0n ch\\u1ec9nh."}, {"index": 17, "start": 65.0, "end": 67.0, "text": "N\\u00f3 g\\u1ea7n nh\\u01b0ng ch\\u01b0a ho\\u00e0n to\\u00e0n \\u0111\\u00fang."}, {"index": 18, "start": 67.0, "end": 70.0, "text": "V\\u00ec v\\u1eady, h\\u00e3y \\u0111\\u1ec3 t\\u00f4i nh\\u1eafc l\\u1ea1i m\\u00f4 h\\u00ecnh \\u0111\\u00f3 m\\u1ed9t l\\u1ea7n n\\u1eefa ch\\u1ec9 v\\u1ec1 m\\u1eb7t h\\u00ecnh \\u1ea3nh."}, {"index": 19, "start": 70.0, "end": 72.0, "text": "Ch\\u00fang ta c\\u00f3 m\\u00e1y \\u1ea3nh c\\u1ee7a m\\u00ecnh."}, {"index": 20, "start": 72.0, "end": 74.0, "text": "Th\\u1ef1c ra t\\u00f4i s\\u1ebd quay l\\u1ea1i v\\u1edbi kh\\u00eda c\\u1ea1nh ti\\u00eau c\\u1ef1c m\\u1ed9t l\\u1ea7n n\\u1eefa"}, {"index": 21, "start": 74.0, "end": 77.0, "text": "b\\u1edfi v\\u00ec \\u0111i\\u1ec1u \\u0111\\u00f3 s\\u1ebd gi\\u00fap t\\u00f4i d\\u1ec5 d\\u00e0ng m\\u00f4 t\\u1ea3 nh\\u1eefng g\\u00ec ti\\u1ebfp theo."}, {"index": 22, "start": 77.0, "end": 79.0, "text": "V\\u00ec v\\u1eady, t\\u00f4i c\\u00f3 kh\\u1ea9u \\u0111\\u1ed9 ph\\u00eda tr\\u01b0\\u1edbc."}, {"index": 23, "start": 79.0, "end": 81.0, "text": "T\\u00f4i c\\u00f3 v\\u1eadt li\\u1ec7u nh\\u1ea1y s\\u00e1ng \\u1edf ph\\u00eda sau."}, {"index": 24, "start": 81.0, "end": 83.0, "text": "V\\u00e0 m\\u1ed9t l\\u1ea7n n\\u1eefa, tr\\u1ee5c quang h\\u1ecdc c\\u1ee7a t\\u00f4i n\\u1eb1m \\u1edf \\u0111\\u00e2y."}, {"index": 25, "start": 83.0, "end": 86.0, "text": "V\\u00e0 ch\\u00fang ta s\\u1ebd l\\u00e0m \\u0111i\\u1ec1u n\\u00e0y trong kh\\u00f4ng gian 2D m\\u1ed9t l\\u1ea7n n\\u1eefa v\\u00ec 3D l\\u00e0 r\\u1ea5t d\\u1ec5."}, {"index": 26, "start": 86.0, "end": 90.0, "text": "V\\u00e0 v\\u1ea5n \\u0111\\u1ec1, t\\u1ea5t nhi\\u00ean, ch\\u00ednh l\\u00e0 kh\\u1ea9u \\u0111\\u1ed9 nh\\u1ecf n\\u00e0y."}, {"index": 27, "start": 90.0, "end": 92.0, "text": "C\\u00f3 hai v\\u1ea5n \\u0111\\u1ec1 v\\u1edbi n\\u00f3."}, {"index": 28, "start": 92.0, "end": 95.0, "text": "\\u0110\\u00e2y kh\\u00f4ng ph\\u1ea3i l\\u00e0 h\\u00ecnh d\\u1ea1ng c\\u1ee7a m\\u1ed9t chi\\u1ebfc m\\u00e1y \\u1ea3nh hi\\u1ec7n \\u0111\\u1ea1i."}, {"index": 29, "start": 95.0, "end": 97.0, "text": "N\\u00f3 kh\\u00f4ng c\\u00f3 kh\\u1ea9u \\u0111\\u1ed9 b\\u00e9 x\\u00edu n\\u00e0y."}, {"index": 30, "start": 97.0, "end": 100.0, "text": "qua \\u0111\\u00f3 m\\u1ed9t tia s\\u00e1ng duy nh\\u1ea5t \\u0111i v\\u00e0o."}, {"index": 31, "start": 100.0, "end": 102.0, "text": "C\\u00f3 m\\u1ed9t v\\u00e0i l\\u00fd do cho \\u0111i\\u1ec1u \\u0111\\u00f3."}, {"index": 32, "start": 102.0, "end": 104.0, "text": "L\\u00fd do quan tr\\u1ecdng nh\\u1ea5t l\\u00e0 hi\\u1ec7u su\\u1ea5t."}, {"index": 33, "start": 104.0, "end": 107.0, "text": "Khi b\\u1ea1n ch\\u1ec9 cho ph\\u00e9p m\\u1ed9t l\\u01b0\\u1ee3ng \\u00e1nh s\\u00e1ng r\\u1ea5t nh\\u1ecf v\\u00e0o,"}, {"index": 34, "start": 107.0, "end": 111.0, "text": "b\\u1ea1n c\\u1ea7n c\\u00f3 m\\u1ed9t c\\u1ea3nh r\\u1ea5t, r\\u1ea5t s\\u00e1ng"}, {"index": 35, "start": 111.0, "end": 114.0, "text": "\\u0111\\u1ec3 c\\u00f3 th\\u1ec3 ch\\u1ee5p h\\u00ecnh m\\u1ed9t c\\u00e1ch ch\\u00ednh x\\u00e1c,"}, {"index": 36, "start": 114.0, "end": 117.0, "text": "ho\\u1eb7c b\\u1ea1n ph\\u1ea3i c\\u00f3 th\\u1eddi gian ph\\u01a1i s\\u00e1ng r\\u1ea5t d\\u00e0i"}, {"index": 37, "start": 117.0, "end": 121.0, "text": "\\u0111\\u1ec3 cho ph\\u00e9p \\u0111\\u1ee7 \\u00e1nh s\\u00e1ng v\\u00e0o nh\\u1eb1m ph\\u01a1i s\\u00e1ng \\u0111\\u00fang c\\u00e1ch."}, {"index": 38, "start": 121.0, "end": 125.0, "text": "V\\u00ec v\\u1eady, c\\u00e1c m\\u00e1y \\u1ea3nh hi\\u1ec7n \\u0111\\u1ea1i \\u0111\\u00e3 thay th\\u1ebf kh\\u1ea9u \\u0111\\u1ed9 b\\u00e9 nh\\u1ecf \\u0111\\u00f3"}, {"index": 39, "start": 125.0, "end": 127.0, "text": "b\\u1eb1ng c\\u00e1ch ch\\u1ec9 m\\u1edf m\\u1ed9t l\\u1ed7 v\\u00e0 \\u0111\\u00f3ng l\\u1ea1i."}, {"index": 40, "start": 127.0, "end": 131.0, "text": "v\\u1edbi ph\\u00e9p m\\u00e0u c\\u1ee7a quang h\\u1ecdc, \\u0111\\u00f3 l\\u00e0 th\\u1ea5u k\\u00ednh."}, {"index": 41, "start": 131.0, "end": 134.0, "text": "V\\u00e0 nh\\u1eefng g\\u00ec th\\u1ea5u k\\u00ednh l\\u00e0m, th\\u1ea5u k\\u00ednh \\u1edf \\u0111\\u00e2y trong m\\u1eaft b\\u1ea1n,"}, {"index": 42, "start": 134.0, "end": 137.0, "text": "th\\u1ea5u k\\u00ednh trong m\\u00e1y \\u1ea3nh, th\\u1ea5u k\\u00ednh trong k\\u00ednh vi\\u1ec5n v\\u1ecdng,"}, {"index": 43, "start": 137.0, "end": 141.0, "text": "thu th\\u1eadp \\u00e1nh s\\u00e1ng t\\u1eeb nhi\\u1ec1u h\\u01b0\\u1edbng kh\\u00e1c nhau"}, {"index": 44, "start": 141.0, "end": 143.0, "text": "v\\u00e0 t\\u1eadp trung \\u00e1nh s\\u00e1ng \\u0111\\u00f3."}, {"index": 45, "start": 143.0, "end": 146.0, "text": "V\\u00e0 b\\u1ea1n c\\u00f3 th\\u1ec3 minh h\\u1ecda \\u0111i\\u1ec1u \\u0111\\u00f3 m\\u1ed9t c\\u00e1ch kh\\u00e1 \\u0111\\u01a1n gi\\u1ea3n"}, {"index": 46, "start": 146.0, "end": 149.0, "text": "n\\u1ebfu b\\u1ea1n gi\\u1ea3 \\u0111\\u1ecbnh m\\u1ed9t m\\u00f4 h\\u00ecnh th\\u1ea5u k\\u00ednh m\\u1ecfng r\\u1ea5t \\u0111\\u01a1n gi\\u1ea3n,"}, {"index": 47, "start": 149.0, "end": 153.0, "text": "m\\u00f4 h\\u00ecnh n\\u00e0y kh\\u00f4ng th\\u1eadt s\\u1ef1 l\\u00e0 m\\u00f4 h\\u00ecnh t\\u1ed5ng qu\\u00e1t nh\\u1ea5t c\\u00f3 th\\u1ec3 cho c\\u00e1c th\\u1ea5u k\\u00ednh,"}, {"index": 48, "start": 153.0, "end": 156.0, "text": "nh\\u01b0ng n\\u00f3 s\\u1ebd \\u0111\\u1ee7 t\\u1ed1t cho nh\\u1eefng g\\u00ec ch\\u00fang ta c\\u1ea7n l\\u00e0m."}, {"index": 49, "start": 156.0, "end": 157.0, "text": "V\\u00e0 \\u0111\\u00e2y l\\u00e0 \\u00fd t\\u01b0\\u1edfng."}, {"index": 50, "start": 157.0, "end": 159.0, "text": "T\\u00f4i c\\u00f3 m\\u1ed9t \\u0111i\\u1ec3m \\u1edf \\u0111\\u00e2y trong th\\u1ebf gi\\u1edbi c\\u1ee7a m\\u00ecnh."}, {"index": 51, "start": 159.0, "end": 162.0, "text": "v\\u00e0 \\u0111\\u00f3 l\\u00e0 tia s\\u00e1ng m\\u00e0 t\\u00f4i \\u0111ang ch\\u1ec9 cho b\\u1ea1n, \\u0111i ngay qua gi\\u1eefa."}, {"index": 52, "start": 162.0, "end": 163.0, "text": "tr\\u00f4ng c\\u00f3 v\\u1ebb r\\u1ea5t quen thu\\u1ed9c."}, {"index": 53, "start": 163.0, "end": 164.0, "text": "\\u0110\\u00e2y l\\u00e0 c\\u1ea3m bi\\u1ebfn m\\u1ed9t l\\u1ea7n n\\u1eefa."}, {"index": 54, "start": 164.0, "end": 167.0, "text": "\\u0110\\u00f3 tr\\u00f4ng gi\\u1ed1ng nh\\u01b0 tia s\\u00e1ng chi\\u1ebfu ph\\u1ed1i c\\u1ea3nh,"}, {"index": 55, "start": 167.0, "end": 169.0, "text": "tia s\\u00e1ng \\u0111\\u01a1n l\\u1ebb n\\u1ebfu b\\u1ea1n t\\u01b0\\u1edfng t\\u01b0\\u1ee3ng l\\u1ea5y \\u1ed1ng k\\u00ednh \\u0111\\u00f3,"}, {"index": 56, "start": 169.0, "end": 172.0, "text": "v\\u00e0 ch\\u1ec9 c\\u1ea7n \\u0111\\u00f3ng l\\u1ea1i cho \\u0111\\u1ebfn khi ch\\u1ec9 m\\u1ed9t tia s\\u00e1ng \\u0111i qua."}, {"index": 57, "start": 172.0, "end": 175.0, "text": "Nh\\u01b0ng t\\u1ea5t nhi\\u00ean, \\u0111i\\u1ec3m \\u0111\\u00f3 trong th\\u1ebf gi\\u1edbi,"}, {"index": 58, "start": 175.0, "end": 177.0, "text": "ph\\u00e1t ra \\u00e1nh s\\u00e1ng theo m\\u1ecdi h\\u01b0\\u1edbng."}, {"index": 59, "start": 177.0, "end": 179.0, "text": "Nh\\u1edb r\\u1eb1ng ch\\u00fang ta c\\u00f3 ngu\\u1ed3n \\u00e1nh s\\u00e1ng,"}, {"index": 60, "start": 179.0, "end": 182.0, "text": "n\\u00f3 va \\u0111\\u1ebfn \\u0111\\u00e2y v\\u00e0 sau \\u0111\\u00f3 \\u00e1nh s\\u00e1ng d\\u1ed9i l\\u1ea1i theo m\\u1ecdi h\\u01b0\\u1edbng"}, {"index": 61, "start": 182.0, "end": 188.0, "text": "v\\u00e0 sau \\u0111\\u00f3 \\u1ed1ng k\\u00ednh n\\u00e0y thu nh\\u1eadn m\\u1ed9t s\\u1ed1 tia s\\u00e1ng \\u0111\\u00f3,"}, {"index": 62, "start": 188.0, "end": 189.0, "text": "m\\u1ed9t s\\u1ed1 l\\u01b0\\u1ee3ng l\\u1edbn ch\\u00fang,"}, {"index": 63, "start": 189.0, "end": 192.0, "text": "nh\\u01b0ng sau \\u0111\\u00f3 \\u0111i\\u1ec1u k\\u1ef3 di\\u1ec7u x\\u1ea3y ra \\u0111\\u00f3 l\\u00e0 n\\u00f3 t\\u1eadp trung nh\\u1eefng tia s\\u00e1ng \\u0111\\u00f3"}, {"index": 64, "start": 192.0, "end": 195.0, "text": "v\\u00e0o m\\u1ed9t \\u0111i\\u1ec3m duy nh\\u1ea5t."}, {"index": 65, "start": 195.0, "end": 198.0, "text": "V\\u00e0 n\\u1ebfu \\u0111i\\u1ec3m \\u0111\\u00f3 \\u1edf \\u0111\\u00e2y ch\\u1eb3ng h\\u1ea1n"}, {"index": 66, "start": 198.0, "end": 200.0, "text": "thay v\\u00ec \\u1edf \\u0111\\u00e2y,"}, {"index": 67, "start": 200.0, "end": 203.0, "text": "th\\u00ec tia s\\u00e1ng trung t\\u00e2m c\\u0169ng l\\u00e0m \\u0111i\\u1ec1u t\\u01b0\\u01a1ng t\\u1ef1"}, {"index": 68, "start": 203.0, "end": 205.0, "text": "v\\u00e0 sau \\u0111\\u00f3 nh\\u1eefng tia s\\u00e1ng n\\u00e0y u\\u1ed1n cong"}, {"index": 69, "start": 205.0, "end": 208.0, "text": "v\\u00e0 ch\\u00fang u\\u1ed1n cong \\u0111\\u1ec3 t\\u1eadp trung \\u00e1nh s\\u00e1ng m\\u1ed9t c\\u00e1ch ho\\u00e0n h\\u1ea3o."}, {"index": 70, "start": 208.0, "end": 210.0, "text": "V\\u00ec v\\u1eady gi\\u1edd \\u0111\\u00e2y ch\\u00fang ta c\\u00f3 th\\u1ec3,"}, {"index": 71, "start": 210.0, "end": 213.0, "text": "ch\\u00fang ta c\\u00f3 m\\u1ed9t v\\u00e0i \\u0111i\\u1ec1u \\u0111ang ho\\u1ea1t \\u0111\\u1ed9ng c\\u00f3 l\\u1ee3i cho ch\\u00fang ta."}, {"index": 72, "start": 213.0, "end": 215.0, "text": "M\\u1ed9t l\\u00e0 ch\\u00fang ta c\\u00f3 th\\u1ec3 thu th\\u1eadp nhi\\u1ec1u \\u00e1nh s\\u00e1ng h\\u01a1n"}, {"index": 73, "start": 215.0, "end": 216.0, "text": "v\\u00ec v\\u1eady ch\\u00fang ta c\\u00f3 hi\\u1ec7u su\\u1ea5t cao h\\u01a1n,"}, {"index": 74, "start": 216.0, "end": 218.0, "text": "nh\\u01b0ng m\\u1ed9t \\u0111i\\u1ec1u g\\u00ec \\u0111\\u00f3 s\\u1ebd th\\u00fa v\\u1ecb"}, {"index": 75, "start": 218.0, "end": 219.0, "text": "s\\u1ebd x\\u1ea3y ra."}, {"index": 76, "start": 219.0, "end": 221.0, "text": "H\\u00e3y ch\\u00fa \\u00fd r\\u1eb1ng hai \\u0111i\\u1ec3m m\\u00e0 t\\u00f4i \\u0111\\u00e3 v\\u1ebd"}, {"index": 77, "start": 221.0, "end": 226.0, "text": "c\\u00e1ch nhau c\\u00f9ng m\\u1ed9t kho\\u1ea3ng c\\u00e1ch t\\u01b0\\u01a1ng \\u0111\\u1ed1i v\\u1edbi \\u1ed1ng k\\u00ednh"}, {"index": 78, "start": 226.0, "end": 227.0, "text": "ho\\u1eb7c camera."}, {"index": 79, "start": 227.0, "end": 230.0, "text": "Chuy\\u1ec7n g\\u00ec s\\u1ebd x\\u1ea3y ra khi \\u0111i\\u1ec3m n\\u00e0y g\\u1ea7n l\\u1ea1i?"}, {"index": 80, "start": 230.0, "end": 233.0, "text": "\\u00c0, tia ch\\u00ednh \\u0111\\u00f3 th\\u00ec th\\u1ef1c s\\u1ef1 kh\\u00f4ng c\\u00f3 g\\u00ec x\\u1ea3y ra,"}, {"index": 81, "start": 233.0, "end": 234.0, "text": "c\\u0169ng gi\\u1ed1ng nh\\u01b0 v\\u1eady,"}, {"index": 82, "start": 234.0, "end": 236.0, "text": "n\\u00f3 ch\\u1ec9 \\u0111i th\\u1eb3ng qua v\\u00e0 t\\u1ea1o h\\u00ecnh \\u1ea3nh,"}, {"index": 83, "start": 236.0, "end": 239.0, "text": "nh\\u01b0ng nh\\u1eefng tia kh\\u00e1c \\u0111i qua th\\u00ec"}, {"index": 84, "start": 239.0, "end": 241.0, "text": "c\\u00e1c b\\u1ea1n ch\\u00fa \\u00fd l\\u00e0 khi ch\\u00fang u\\u1ed1n cong"}, {"index": 85, "start": 241.0, "end": 243.0, "text": "th\\u00ec ch\\u00fang kh\\u00f4ng ho\\u00e0n to\\u00e0n h\\u1ed9i t\\u1ee5,"}, {"index": 86, "start": 243.0, "end": 245.0, "text": "ch\\u00fang h\\u01a1i b\\u1ecb m\\u1edd,"}, {"index": 87, "start": 245.0, "end": 247.0, "text": "v\\u00e0 s\\u1ebd tr\\u1edf n\\u00ean m\\u1edd."}, {"index": 88, "start": 247.0, "end": 248.0, "text": "T\\u1ea1i sao l\\u1ea1i m\\u1edd?"}, {"index": 89, "start": 248.0, "end": 250.0, "text": "\\u00c0, c\\u00e1i \\u0111i\\u1ec3m nh\\u1ecf \\u0111\\u00f3,"}, {"index": 90, "start": 250.0, "end": 253.0, "text": "c\\u00e1i \\u0111i\\u1ec3m nh\\u1ecf duy nh\\u1ea5t \\u0111ang ph\\u1ea3n x\\u1ea1 \\u00e1nh s\\u00e1ng"}, {"index": 91, "start": 253.0, "end": 254.0, "text": "theo nhi\\u1ec1u h\\u01b0\\u1edbng kh\\u00e1c nhau"}, {"index": 92, "start": 254.0, "end": 256.0, "text": "s\\u1ebd b\\u1ecb lan ra"}, {"index": 93, "start": 256.0, "end": 258.0, "text": "tr\\u00ean khu v\\u1ef1c nh\\u1ecf n\\u00e0y."}, {"index": 94, "start": 258.0, "end": 260.0, "text": "V\\u00e0 n\\u1ebfu \\u0111i\\u1ec3m \\u0111\\u00f3 \\u1edf xa h\\u01a1n"}, {"index": 95, "start": 260.0, "end": 261.0, "text": "so v\\u1edbi v\\u1ecb tr\\u00ed ch\\u00fang ta \\u0111\\u00e3 n\\u00f3i tr\\u01b0\\u1edbc \\u0111\\u00f3,"}, {"index": 96, "start": 261.0, "end": 262.0, "text": "t\\u1ee9c l\\u00e0 ngay \\u0111\\u00f3,"}, {"index": 97, "start": 262.0, "end": 265.0, "text": "th\\u00ec n\\u00f3 s\\u1ebd h\\u1ed9i t\\u1ee5 qu\\u00e1 s\\u1edbm"}, {"index": 98, "start": 265.0, "end": 267.0, "text": "v\\u00e0 v\\u1eabn b\\u1ecb lan ra"}, {"index": 99, "start": 267.0, "end": 269.0, "text": "m\\u1ed9t ch\\u00fat."}, {"index": 100, "start": 269.0, "end": 271.0, "text": "V\\u00e0 \\u0111\\u00e2y l\\u00e0 nh\\u1eefng g\\u00ec \\u0111ang g\\u00e2y ra"}, {"index": 101, "start": 271.0, "end": 273.0, "text": "s\\u1ef1 kh\\u00e1c bi\\u1ec7t \\u0111\\u00f3 trong s\\u1ef1 t\\u1eadp trung"}, {"index": 102, "start": 273.0, "end": 275.0, "text": "\\u0111\\u1ed1i v\\u1edbi t\\u00f4i trong b\\u1ee9c tranh \\u0111\\u00f3"}, {"index": 103, "start": 275.0, "end": 277.0, "text": "v\\u00e0 \\u0111\\u1ed1i v\\u1edbi n\\u1ec1n,"}, {"index": 104, "start": 277.0, "end": 278.0, "text": "n\\u00f3 x\\u1ea3y ra v\\u00ec \\u0111i\\u1ec1u n\\u00e0y."}, {"index": 105, "start": 278.0, "end": 280.0, "text": "V\\u00e0 gi\\u1edd \\u0111\\u00e2y, r\\u00f5 r\\u00e0ng l\\u00e0 \\u0111i\\u1ec1u ch\\u00fang ta mu\\u1ed1n l\\u00e0m"}, {"index": 106, "start": 280.0, "end": 281.0, "text": "l\\u00e0 \\u0111\\u1ecbnh l\\u01b0\\u1ee3ng \\u0111i\\u1ec1u n\\u00e0y m\\u1ed9t ch\\u00fat"}, {"index": 107, "start": 281.0, "end": 283.0, "text": "v\\u00e0 \\u0111\\u01b0a ra m\\u1ed9t s\\u1ed1 ph\\u01b0\\u01a1ng tr\\u00ecnh"}, {"index": 108, "start": 283.0, "end": 285.0, "text": "\\u0111\\u1ec3 gi\\u1ea3i th\\u00edch nh\\u1eefng g\\u00ec \\u0111ang di\\u1ec5n ra."}, {"index": 109, "start": 285.0, "end": 287.0, "text": "V\\u1eady h\\u00e3y l\\u00e0m \\u0111i\\u1ec1u \\u0111\\u00f3 ti\\u1ebfp theo."}, {"index": 110, "start": 287.0, "end": 289.0, "text": "\\u0110\\u1ea7u ti\\u00ean v\\u00e0 quan tr\\u1ecdng nh\\u1ea5t,"}, {"index": 111, "start": 289.0, "end": 291.0, "text": "h\\u00e3y l\\u01b0u \\u00fd r\\u1eb1ng ch\\u00fang ta ch\\u01b0a b\\u1ecf \\u0111i"}, {"index": 112, "start": 291.0, "end": 292.0, "text": "m\\u00e1y \\u1ea3nh ch\\u00f3p."}, {"index": 113, "start": 292.0, "end": 294.0, "text": "\\u0110i\\u1ec1u n\\u00e0y th\\u1ef1c s\\u1ef1 l\\u00e0 m\\u1ed9t s\\u1ef1 t\\u1ed5ng qu\\u00e1t"}, {"index": 114, "start": 294.0, "end": 295.0, "text": "theo c\\u00e1ch r\\u1ea5t \\u0111\\u1eb9p."}, {"index": 115, "start": 295.0, "end": 297.0, "text": "V\\u00ec v\\u1eady, n\\u1ebfu t\\u00f4i l\\u1ea5y m\\u1ed9t \\u0111i\\u1ec3m trong th\\u1ebf gi\\u1edbi"}, {"index": 116, "start": 297.0, "end": 299.0, "text": "v\\u00e0 gi\\u1edd t\\u00f4i s\\u1ebd tr\\u1edf v\\u1ec1 m\\u00f4 h\\u00ecnh c\\u0169"}, {"index": 117, "start": 299.0, "end": 300.0, "text": "b\\u1edfi v\\u00ec t\\u00f4i kh\\u00f4ng c\\u1ea7n ph\\u1ea3i lo l\\u1eafng"}, {"index": 118, "start": 300.0, "end": 302.0, "text": "v\\u1ec1 t\\u1ea5t c\\u1ea3 c\\u00e1c bi\\u1ebfn \\u0111\\u1ed5i t\\u1ecda \\u0111\\u1ed9,"}, {"index": 119, "start": 302.0, "end": 303.0, "text": "t\\u00f4i ch\\u1ec9 mu\\u1ed1n l\\u00e0m \\u0111i\\u1ec1u g\\u00ec \\u0111\\u00f3 \\u0111\\u01a1n gi\\u1ea3n."}, {"index": 120, "start": 303.0, "end": 305.0, "text": "T\\u00f4i c\\u00f3 m\\u1ed9t \\u0111i\\u1ec3m \\u1edf trong th\\u1ebf gi\\u1edbi,"}, {"index": 121, "start": 305.0, "end": 307.0, "text": "n\\u00f3 \\u0111\\u01b0\\u1ee3c bi\\u1ec3u th\\u1ecb b\\u1eb1ng ch\\u1eef X vi\\u1ebft hoa, Z vi\\u1ebft hoa"}, {"index": 122, "start": 307.0, "end": 309.0, "text": "v\\u00e0 tia trung t\\u00e2m \\u0111\\u00f3"}, {"index": 123, "start": 309.0, "end": 311.0, "text": "\\u0111i qua \\u0111\\u00e2y"}, {"index": 124, "start": 311.0, "end": 313.0, "text": "s\\u1ebd chi\\u1ebfu ra"}, {"index": 125, "start": 313.0, "end": 315.0, "text": "\\u00e2m fx"}, {"index": 126, "start": 315.0, "end": 316.0, "text": "tr\\u00ean Z."}, {"index": 127, "start": 316.0, "end": 318.0, "text": "C\\u00f9ng c\\u00e1c ph\\u01b0\\u01a1ng tr\\u00ecnh chi\\u1ebfu quan \\u0111i\\u1ec3m nh\\u01b0 c\\u0169."}, {"index": 128, "start": 318.0, "end": 320.0, "text": "V\\u00ec v\\u1eady, \\u0111i\\u1ec1u \\u0111\\u00f3 v\\u1eabn gi\\u1eef nguy\\u00ean."}, {"index": 129, "start": 320.0, "end": 322.0, "text": "Ch\\u1ec9 l\\u00e0 b\\u00e2y gi\\u1edd ch\\u00fang ta ph\\u1ea3i x\\u1eed l\\u00fd"}, {"index": 130, "start": 322.0, "end": 324.0, "text": "tr\\u01b0\\u1eddng h\\u1ee3p khi \\u0111i\\u1ec3m"}, {"index": 131, "start": 324.0, "end": 326.0, "text": "g\\u1ea7n h\\u01a1n v\\u00e0 xa h\\u01a1n"}, {"index": 132, "start": 326.0, "end": 328.0, "text": "n\\u00f3 s\\u1ebd b\\u1ecb m\\u1edd bao nhi\\u00eau"}, {"index": 133, "start": 328.0, "end": 331.0, "text": "v\\u00e0 li\\u1ec7u ch\\u00fang ta c\\u00f3 th\\u1ec3 \\u0111\\u1ecbnh l\\u01b0\\u1ee3ng \\u0111i\\u1ec1u \\u0111\\u00f3 kh\\u00f4ng."}, {"index": 134, "start": 331.0, "end": 333.0, "text": "V\\u1eady th\\u00ec h\\u00e3y \\u0111\\u1ec3 t\\u00f4i \\u0111\\u1ecbnh ngh\\u0129a m\\u1ed9t v\\u00e0i \\u0111i\\u1ec1u"}, {"index": 135, "start": 333.0, "end": 334.0, "text": "v\\u00e0 kh\\u00f4ng may \\u1edf \\u0111\\u00e2y"}, {"index": 136, "start": 334.0, "end": 336.0, "text": "ch\\u00fang ta ph\\u1ea3i chuy\\u1ec3n \\u0111\\u1ed5i k\\u00fd hi\\u1ec7u"}, {"index": 137, "start": 336.0, "end": 337.0, "text": "\\u0111i\\u1ec1u n\\u00e0y l\\u00e0 m\\u1ed9t th\\u1ef1c t\\u1ebf kh\\u00f4ng may"}, {"index": 138, "start": 337.0, "end": 339.0, "text": "nh\\u01b0ng b\\u1ea1n c\\u0169ng s\\u1ebd th\\u1ea5y \\u0111i\\u1ec1u n\\u00e0y trong t\\u00e0i li\\u1ec7u"}, {"index": 139, "start": 339.0, "end": 341.0, "text": "v\\u00ec v\\u1eady t\\u00f4i ch\\u1ec9 quy\\u1ebft \\u0111\\u1ecbnh th\\u1ef1c hi\\u1ec7n \\u1edf \\u0111\\u00e2y."}, {"index": 140, "start": 341.0, "end": 343.0, "text": "V\\u00ec v\\u1eady, t\\u00f4i s\\u1ebd \\u0111\\u1ecbnh ngh\\u0129a"}, {"index": 141, "start": 343.0, "end": 346.0, "text": "kho\\u1ea3ng c\\u00e1ch gi\\u1eefa \\u0111i\\u1ec3m"}, {"index": 142, "start": 346.0, "end": 349.0, "text": "v\\u00e0 m\\u1eb7t tr\\u01b0\\u1edbc c\\u1ee7a m\\u00e1y \\u1ea3nh l\\u00e0 Z"}, {"index": 143, "start": 349.0, "end": 350.0, "text": "gi\\u1ed1ng nh\\u01b0 tr\\u01b0\\u1edbc \\u0111\\u00e2y"}, {"index": 144, "start": 350.0, "end": 352.0, "text": "tr\\u00ean tr\\u1ee5c quang h\\u1ecdc"}, {"index": 145, "start": 352.0, "end": 354.0, "text": "v\\u00e0 b\\u00e2y gi\\u1edd t\\u00f4i s\\u1ebd \\u0111\\u1ecbnh ngh\\u0129a l\\u1ea1i"}, {"index": 146, "start": 354.0, "end": 356.0, "text": "kho\\u1ea3ng c\\u00e1ch n\\u00e0y gi\\u1eefa \\u1ed1ng k\\u00ednh"}, {"index": 147, "start": 356.0, "end": 359.0, "text": "v\\u00e0 m\\u1eb7t sau c\\u1ee7a c\\u1ea3m bi\\u1ebfn"}, {"index": 148, "start": 359.0, "end": 361.0, "text": "l\\u00e0 D thay v\\u00ec f"}, {"index": 149, "start": 361.0, "end": 362.0, "text": "v\\u00e0 b\\u1ea1n s\\u1ebd th\\u1ea5y trong m\\u1ed9t ch\\u00fat"}, {"index": 150, "start": 362.0, "end": 364.0, "text": "t\\u1ea1i sao l\\u1ea1i nh\\u01b0 v\\u1eady"}, {"index": 151, "start": 364.0, "end": 366.0, "text": "v\\u00e0 b\\u00e2y gi\\u1edd l\\u00fd do t\\u00f4i l\\u00e0m \\u0111i\\u1ec1u \\u0111\\u00f3"}, {"index": 152, "start": 366.0, "end": 368.0, "text": "l\\u00e0 v\\u00ec ch\\u00fang ta s\\u1ebd"}, {"index": 153, "start": 368.0, "end": 370.0, "text": "\\u0111\\u1ecbnh ngh\\u0129a chi\\u1ec1u d\\u00e0i ti\\u00eau c\\u1ef1"}, {"index": 154, "start": 370.0, "end": 372.0, "text": "c\\u1ee7a \\u1ed1ng k\\u00ednh l\\u00e0 f nh\\u1ecf"}, {"index": 155, "start": 372.0, "end": 374.0, "text": "v\\u00ec v\\u1eady n\\u00f3 kh\\u00f4ng c\\u00f2n l\\u00e0 kho\\u1ea3ng c\\u00e1ch"}, {"index": 156, "start": 374.0, "end": 375.0, "text": "t\\u1eeb \\u1ed1ng k\\u00ednh \\u0111\\u1ebfn c\\u1ea3m bi\\u1ebfn"}, {"index": 157, "start": 375.0, "end": 377.0, "text": "m\\u00e0 n\\u00f3 l\\u00e0 chi\\u1ec1u d\\u00e0i ti\\u00eau c\\u1ef1"}, {"index": 158, "start": 377.0, "end": 379.0, "text": "li\\u00ean quan \\u0111\\u1ebfn t\\u00ednh ch\\u1ea5t b\\u1ebb cong n\\u00e0y"}, {"index": 159, "start": 379.0, "end": 381.0, "text": "m\\u00e0 b\\u1ea1n \\u0111ang th\\u1ea5y c\\u1ee7a \\u00e1nh s\\u00e1ng \\u1edf \\u0111\\u00e2y"}, {"index": 160, "start": 381.0, "end": 384.0, "text": "v\\u00e0 \\u0111i\\u1ec1u \\u0111\\u00f3 \\u0111\\u01b0\\u1ee3c \\u0111\\u1ecbnh ngh\\u0129a nh\\u01b0 sau"}, {"index": 161, "start": 384.0, "end": 386.0, "text": "1 chia cho f, l\\u00e0 chi\\u1ec1u d\\u00e0i ti\\u00eau c\\u1ef1"}, {"index": 162, "start": 386.0, "end": 387.0, "text": "c\\u1ee7a th\\u1ea5u k\\u00ednh"}, {"index": 163, "start": 387.0, "end": 388.0, "text": "\\u0111i\\u1ec1u n\\u00e0y \\u0111\\u1ecbnh ngh\\u0129a s\\u1ef1 kh\\u00fac x\\u1ea1 c\\u1ee7a \\u00e1nh s\\u00e1ng"}, {"index": 164, "start": 388.0, "end": 390.0, "text": "b\\u1eb1ng 1 chia cho Z"}, {"index": 165, "start": 390.0, "end": 392.0, "text": "c\\u1ed9ng v\\u1edbi 1 chia cho D"}, {"index": 166, "start": 392.0, "end": 394.0, "text": "n\\u01a1i D l\\u00e0 kho\\u1ea3ng c\\u00e1ch t\\u1eeb th\\u1ea5u k\\u00ednh \\u0111\\u1ebfn"}, {"index": 167, "start": 394.0, "end": 396.0, "text": "c\\u1ea3m bi\\u1ebfn."}, {"index": 168, "start": 396.0, "end": 398.0, "text": "\\u0110\\u01b0\\u1ee3c r\\u1ed3i, b\\u00e2y gi\\u1edd"}, {"index": 169, "start": 398.0, "end": 400.0, "text": "\\u0111i\\u1ec1u \\u0111\\u00f3 c\\u00f3 ngh\\u0129a l\\u00e0 g\\u00ec v\\u1ec1 chi\\u1ec1u d\\u00e0i ti\\u00eau c\\u1ef1"}, {"index": 170, "start": 400.0, "end": 402.0, "text": "th\\u1ef1c ra c\\u00f3 m\\u1ed9t c\\u00e1ch di\\u1ec5n gi\\u1ea3i h\\u00ecnh h\\u1ecdc r\\u1ea5t \\u0111\\u1eb9p v\\u1ec1 n\\u00f3"}, {"index": 171, "start": 402.0, "end": 404.0, "text": "l\\u1ea5y m\\u1ed9t \\u0111i\\u1ec3m"}, {"index": 172, "start": 404.0, "end": 406.0, "text": "ra \\u0111\\u00e2y trong th\\u1ebf gi\\u1edbi"}, {"index": 173, "start": 406.0, "end": 408.0, "text": "c\\u00f3 kho\\u1ea3ng c\\u00e1ch b\\u1eb1ng"}, {"index": 174, "start": 408.0, "end": 410.0, "text": "chi\\u1ec1u cao c\\u1ee7a"}, {"index": 175, "start": 410.0, "end": 412.0, "text": "th\\u1ea5u k\\u00ednh"}, {"index": 176, "start": 412.0, "end": 414.0, "text": "v\\u00e0 v\\u1ebd r\\u1eb1ng tia s\\u1ebd di chuy\\u1ec3n"}, {"index": 177, "start": 414.0, "end": 416.0, "text": "th\\u1eb3ng v\\u00e0 n\\u00f3 s\\u1ebd b\\u1ecb kh\\u00fac x\\u1ea1"}, {"index": 178, "start": 416.0, "end": 418.0, "text": "v\\u00e0 n\\u01a1i n\\u00f3 c\\u1eaft tr\\u1ee5c quang"}, {"index": 179, "start": 418.0, "end": 420.0, "text": "\\u0111\\u01b0\\u1ee3c \\u0111\\u1ecbnh ngh\\u0129a l\\u00e0 chi\\u1ec1u d\\u00e0i ti\\u00eau c\\u1ef1"}, {"index": 180, "start": 420.0, "end": 422.0, "text": "c\\u1ee7a th\\u1ea5u k\\u00ednh"}, {"index": 181, "start": 422.0, "end": 424.0, "text": "b\\u1ea1n c\\u00f3 th\\u1ec3 l\\u00e0m \\u0111i\\u1ec1u n\\u00e0y theo h\\u01b0\\u1edbng ng\\u01b0\\u1ee3c l\\u1ea1i"}, {"index": 182, "start": 424.0, "end": 426.0, "text": "nh\\u00e2n ti\\u1ec7n, b\\u1ea1n c\\u00f3 th\\u1ec3 b\\u1eaft \\u0111\\u1ea7u t\\u1eeb \\u0111\\u00e2y"}, {"index": 183, "start": 426.0, "end": 428.0, "text": "\\u0111i th\\u1eb3ng ra ngo\\u00e0i"}, {"index": 184, "start": 428.0, "end": 430.0, "text": "b\\u1ebb cong \\u00e1nh s\\u00e1ng ra th\\u1ebf gi\\u1edbi"}, {"index": 185, "start": 430.0, "end": 432.0, "text": "v\\u00e0 ch\\u1ed7 m\\u00e0 n\\u00f3 c\\u1eaft qua tr\\u1ee5c quang h\\u1ecdc"}, {"index": 186, "start": 432.0, "end": 434.0, "text": "\\u0111\\u01b0\\u1ee3c x\\u00e1c \\u0111\\u1ecbnh l\\u00e0 chi\\u1ec1u d\\u00e0i ti\\u00eau c\\u1ef1"}, {"index": 187, "start": 434.0, "end": 436.0, "text": "n\\u00f3 li\\u00ean quan nh\\u01b0 b\\u1ea1n c\\u00f3 th\\u1ec3 th\\u1ea5y \\u1edf \\u0111\\u00e2y"}, {"index": 188, "start": 436.0, "end": 438.0, "text": "\\u0111\\u1ebfn c\\u00e1c thu\\u1ed9c t\\u00ednh b\\u1ebb cong c\\u1ee7a th\\u1ea5u k\\u00ednh"}, {"index": 189, "start": 438.0, "end": 440.0, "text": "v\\u00e0 b\\u00e2y gi\\u1edd ch\\u00fang ta c\\u1ea7n hai \\u0111i\\u1ec1u"}, {"index": 190, "start": 440.0, "end": 442.0, "text": "\\u0111\\u1ec3 x\\u00e1c \\u0111\\u1ecbnh camera c\\u1ee7a ch\\u00fang ta"}, {"index": 191, "start": 442.0, "end": 444.0, "text": "kho\\u1ea3ng c\\u00e1ch t\\u1eeb th\\u1ea5u k\\u00ednh \\u0111\\u1ebfn c\\u1ea3m bi\\u1ebfn"}, {"index": 192, "start": 444.0, "end": 446.0, "text": "D, D cho kho\\u1ea3ng c\\u00e1ch, t\\u1ea5t nhi\\u00ean"}, {"index": 193, "start": 446.0, "end": 448.0, "text": "v\\u00e0 chi\\u1ec1u d\\u00e0i ti\\u00eau c\\u1ef1 c\\u1ee7a th\\u1ea5u k\\u00ednh"}, {"index": 194, "start": 448.0, "end": 450.0, "text": "l\\u00e0 f nh\\u1ecf"}, {"index": 195, "start": 450.0, "end": 452.0, "text": "v\\u00e0 n\\u00f3 \\u0111\\u01b0\\u1ee3c th\\u1ecfa m\\u00e3n b\\u1edfi ph\\u01b0\\u01a1ng tr\\u00ecnh th\\u1ea5u k\\u00ednh m\\u1ecfng \\u0111\\u00f3"}, {"index": 196, "start": 452.0, "end": 454.0, "text": "m\\u00e0 b\\u1ea1n th\\u1ea5y ngay \\u1edf \\u0111\\u00f3"}, {"index": 197, "start": 454.0, "end": 456.0, "text": "b\\u00e2y gi\\u1edd t\\u1ea5t c\\u1ea3 nh\\u1eefng \\u0111i\\u1ec1u \\u0111\\u00f3"}, {"index": 198, "start": 456.0, "end": 458.0, "text": "l\\u00e0 \\u0111\\u1ec3 \\u0111\\u01b0a ch\\u00fang ta \\u0111\\u1ebfn \\u0111i\\u1ec3m n\\u00e0y ngay t\\u1ea1i \\u0111\\u00e2y"}, {"index": 199, "start": 458.0, "end": 460.0, "text": "\\u0111i\\u1ec1u n\\u00e0y l\\u00e0 \\u0111\\u1ed9 m\\u1edd"}, {"index": 200, "start": 460.0, "end": 462.0, "text": "c\\u00e1c v\\u1eadt s\\u1ebd nh\\u01b0 th\\u1ebf n\\u00e0o"}, {"index": 201, "start": 462.0, "end": 464.0, "text": "khi ch\\u00fang di chuy\\u1ec3n v\\u00e0o v\\u00e0 ra kh\\u1ecfi"}, {"index": 202, "start": 464.0, "end": 466.0, "text": "\\u0111i\\u1ec3m m\\u00e0 ch\\u00fang n\\u1eb1m trong ti\\u00eau \\u0111i\\u1ec3m ho\\u00e0n h\\u1ea3o"}, {"index": 203, "start": 466.0, "end": 468.0, "text": "m\\u00e0 ch\\u00fang ta v\\u1eeba th\\u1ea5y"}, {"index": 204, "start": 468.0, "end": 470.0, "text": "v\\u00e0 v\\u00ec v\\u1eady ch\\u00fang ta c\\u00f3 ph\\u01b0\\u01a1ng tr\\u00ecnh th\\u1ea5u k\\u00ednh m\\u1ecfng \\u1edf \\u0111\\u00e2y"}, {"index": 205, "start": 470.0, "end": 472.0, "text": "v\\u00e0 \\u0111\\u00e2y l\\u00e0 ph\\u01b0\\u01a1ng tr\\u00ecnh c\\u1ee7a ch\\u00fang ta"}, {"index": 206, "start": 472.0, "end": 474.0, "text": "cho b\\u00e1n k\\u00ednh m\\u1edd r"}, {"index": 207, "start": 474.0, "end": 476.0, "text": "m\\u00e0 b\\u1ea1n c\\u00f3 th\\u1ec3 th\\u1ea5y"}, {"index": 208, "start": 476.0, "end": 478.0, "text": "\\u1edf \\u0111\\u00e2y"}, {"index": 209, "start": 478.0, "end": 480.0, "text": "th\\u00ec b\\u00e2y gi\\u1edd \\u0111i\\u1ec3m \\u0111\\u00f3 \\u0111ang b\\u1ecb l\\u00e0m m\\u1edd"}, {"index": 210, "start": 480.0, "end": 482.0, "text": "tr\\u00ean c\\u1ea3m bi\\u1ebfn"}, {"index": 211, "start": 482.0, "end": 484.0, "text": "v\\u1edbi m\\u1ed9t b\\u00e1n k\\u00ednh nh\\u1ecf r"}, {"index": 212, "start": 484.0, "end": 486.0, "text": "v\\u00e0 \\u0111i\\u