e1ch th\\u1ef1c hi\\u1ec7n \\u0111i\\u1ec1u tr\\u1ecb b\\u1ec7nh kh\\u00f4ng \\u0111\\u01b0\\u1ee3c \\u0111\\u1ec1 c\\u1eadp \\u0111\\u1ebfn trong n\\u1ed9i dung v\\u1ec1 tu\\u1ea7n ti\\u1ebfp theo.", "difficulty": "Kh\\u00f3"}], "artifact_status": {"transcript": {"status": "ready", "error": null}, "summary": {"status": "ready", "error": null}, "timeline": {"status": "ready", "error": null}, "highlights": {"status": "ready", "error": null}, "questions": {"status": "ready", "error": null}, "briefing": {"status": "ready", "error": null}, "visual_data": {"status": "ready", "error": null}, "flashcards": {"status": "ready", "error": null}, "handsign_data": {"status": "ready", "error": null}, "quizzes": {"status": "ready", "error": null}}}	2026-05-16 11:06:40.314539
8d70e4ff-510f-4eea-afa1-8d26ef6fe48b	7118d961-efa1-4c92-92c2-5ecf42d788a4	data\\uploads\\videos\\7118d961-efa1-4c92-92c2-5ecf42d788a4.mp4	\N	\N	\N	\N	{"transcript": {"video_id": "7118d961-efa1-4c92-92c2-5ecf42d788a4", "language": "vi", "source_language": "en", "target_language": "vi", "available_languages": ["vi", "en"], "translation_status": {"vi": {"status": "completed", "error": null}}, "segments": [{"index": 0, "start": 0.0, "end": 4.24, "text": "Trong video n\\u00e0y, b\\u1ea1n s\\u1ebd t\\u00ecm hi\\u1ec3u v\\u1ec1 m\\u1ed9t s\\u1ed1 ki\\u1ebfn tr\\u00fac m\\u1ea1ng n\\u01a1-ron c\\u1ed5 \\u0111i\\u1ec3n"}, {"index": 1, "start": 4.24, "end": 8.88, "text": "b\\u1eaft \\u0111\\u1ea7u v\\u1edbi net5 v\\u00e0 sau \\u0111\\u00f3 l\\u00e0 AlexNet v\\u00e0 VGNet."}, {"index": 2, "start": 8.88, "end": 13.76, "text": "H\\u00e3y c\\u00f9ng xem x\\u00e9t. \\u0110\\u00e2y l\\u00e0 ki\\u1ebfn tr\\u00fac c\\u1ee7a net5. B\\u1ea1n b\\u1eaft \\u0111\\u1ea7u v\\u1edbi m\\u1ed9t"}, {"index": 3, "start": 13.76, "end": 20.24, "text": "h\\u00ecnh \\u1ea3nh, c\\u00f3 k\\u00edch th\\u01b0\\u1edbc 32 x 32 x 1. V\\u00e0 m\\u1ee5c ti\\u00eau c\\u1ee7a net5 l\\u00e0 nh\\u1eadn di\\u1ec7n"}, {"index": 4, "start": 20.24, "end": 26.8, "text": "c\\u00e1c ch\\u1eef s\\u1ed1 vi\\u1ebft tay, c\\u00f3 th\\u1ec3 l\\u00e0 m\\u1ed9t h\\u00ecnh \\u1ea3nh c\\u1ee7a m\\u1ed9t ch\\u1eef s\\u1ed1 nh\\u01b0 v\\u1eady. V\\u00e0 net5 \\u0111\\u01b0\\u1ee3c"}, {"index": 5, "start": 26.8, "end": 32.0, "text": "hu\\u1ea5n luy\\u1ec7n tr\\u00ean c\\u00e1c h\\u00ecnh \\u1ea3nh \\u0111en tr\\u1eafng, \\u0111\\u00f3 l\\u00e0 l\\u00fd do t\\u1ea1i sao k\\u00edch th\\u01b0\\u1edbc l\\u00e0 32 x 32 x 1."}, {"index": 6, "start": 32.0, "end": 35.28, "text": "Ki\\u1ebfn tr\\u00fac m\\u1ea1ng n\\u01a1-ron n\\u00e0y th\\u1ef1c t\\u1ebf kh\\u00e1 gi\\u1ed1ng v\\u1edbi"}, {"index": 7, "start": 35.28, "end": 41.28, "text": "v\\u00ed d\\u1ee5 cu\\u1ed1i c\\u00f9ng m\\u00e0 b\\u1ea1n \\u0111\\u00e3 th\\u1ea5y tu\\u1ea7n tr\\u01b0\\u1edbc. \\u1ede b\\u01b0\\u1edbc \\u0111\\u1ea7u ti\\u00ean, b\\u1ea1n s\\u1eed d\\u1ee5ng m\\u1ed9t t\\u1eadp h\\u1ee3p"}, {"index": 8, "start": 41.28, "end": 46.88, "text": "6 b\\u1ed9 l\\u1ecdc 5 x 5 v\\u1edbi b\\u01b0\\u1edbc nh\\u1ea3y l\\u00e0 1. V\\u00ec b\\u1ea1n s\\u1eed d\\u1ee5ng 6 b\\u1ed9 l\\u1ecdc, b\\u1ea1n s\\u1ebd c\\u00f3"}, {"index": 9, "start": 46.88, "end": 52.72, "text": "k\\u00edch th\\u01b0\\u1edbc 28 x 28 x 6 \\u1edf \\u0111\\u00f3. V\\u00e0 v\\u1edbi b\\u01b0\\u1edbc nh\\u1ea3y l\\u00e0 1 v\\u00e0 kh\\u00f4ng c\\u00f3 padding,"}, {"index": 10, "start": 52.72, "end": 57.04, "text": "k\\u00edch th\\u01b0\\u1edbc h\\u00ecnh \\u1ea3nh gi\\u1ea3m t\\u1eeb 32 x 32 xu\\u1ed1ng"}, {"index": 11, "start": 57.04, "end": 62.56, "text": "28 x 28. Sau \\u0111\\u00f3, m\\u1ea1ng n\\u01a1-ron th\\u1ef1c hi\\u1ec7n vi\\u1ec7c l\\u1ea5y m\\u1eabu."}, {"index": 12, "start": 62.56, "end": 65.6, "text": "V\\u00e0 l\\u00fac \\u0111\\u00f3, khi b\\u00e0i b\\u00e1o n\\u00e0y \\u0111\\u01b0\\u1ee3c vi\\u1ebft, m\\u1ecdi ng\\u01b0\\u1eddi th\\u01b0\\u1eddng s\\u1eed d\\u1ee5ng"}, {"index": 13, "start": 65.6, "end": 69.44, "text": "l\\u1ea5y m\\u1eabu trung b\\u00ecnh nhi\\u1ec1u h\\u01a1n. N\\u1ebfu b\\u1ea1n x\\u00e2y d\\u1ef1ng m\\u1ed9t bi\\u1ebfn th\\u1ec3 hi\\u1ec7n \\u0111\\u1ea1i, b\\u1ea1n"}, {"index": 14, "start": 69.44, "end": 74.64, "text": "c\\u00f3 l\\u1ebd s\\u1ebd s\\u1eed d\\u1ee5ng l\\u1ea5y m\\u1eabu t\\u1ed1i \\u0111a thay th\\u1ebf. Nh\\u01b0ng trong v\\u00ed d\\u1ee5 n\\u00e0y, l\\u1ea5y m\\u1eabu trung b\\u00ecnh c\\u1ee7a b\\u1ea1n"}, {"index": 15, "start": 74.64, "end": 78.64, "text": "v\\u1edbi chi\\u1ec1u r\\u1ed9ng b\\u1ed9 l\\u1ecdc l\\u00e0 2 v\\u00e0 b\\u01b0\\u1edbc nh\\u1ea3y l\\u00e0 2, b\\u1ea1n s\\u1ebd c\\u00f3"}, {"index": 16, "start": 78.64, "end": 82.64, "text": "k\\u00edch th\\u01b0\\u1edbc gi\\u1ea3m, chi\\u1ec1u cao v\\u00e0 chi\\u1ec1u r\\u1ed9ng gi\\u1ea3m xu\\u1ed1ng c\\u00f2n m\\u1ed9t n\\u1eeda."}, {"index": 17, "start": 82.64, "end": 90.08, "text": "V\\u00ec v\\u1eady, b\\u00e2y gi\\u1edd b\\u1ea1n s\\u1ebd c\\u00f3 m\\u1ed9t kh\\u1ed1i 14 x 14 x 6. T\\u00f4i \\u0111o\\u00e1n r\\u1eb1ng chi\\u1ec1u cao v\\u00e0 chi\\u1ec1u r\\u1ed9ng c\\u1ee7a"}, {"index": 18, "start": 90.08, "end": 93.44, "text": "c\\u00e1c kh\\u1ed1i n\\u00e0y kh\\u00f4ng ho\\u00e0n to\\u00e0n \\u0111\\u01b0\\u1ee3c v\\u1ebd theo t\\u1ef7 l\\u1ec7. V\\u1ec1 l\\u00fd thuy\\u1ebft,"}, {"index": 19, "start": 93.44, "end": 96.64, "text": "n\\u1ebfu t\\u00f4i v\\u1ebd nh\\u1eefng kh\\u1ed1i n\\u00e0y theo t\\u1ef7 l\\u1ec7, chi\\u1ec1u cao v\\u00e0 chi\\u1ec1u r\\u1ed9ng s\\u1ebd b\\u1ecb thu nh\\u1ecf"}, {"index": 20, "start": 96.64, "end": 101.2, "text": "b\\u1eb1ng m\\u1ed9t h\\u1ec7 s\\u1ed1 2. Ti\\u1ebfp theo, b\\u1ea1n \\u00e1p d\\u1ee5ng m\\u1ed9t l\\u1edbp convolutional kh\\u00e1c."}, {"index": 21, "start": 101.2, "end": 104.96, "text": "L\\u1ea7n n\\u00e0y, b\\u1ea1n s\\u1eed d\\u1ee5ng m\\u1ed9t t\\u1eadp h\\u1ee3p 16 b\\u1ed9 l\\u1ecdc, k\\u00edch th\\u01b0\\u1edbc 5 x 5."}, {"index": 22, "start": 104.96, "end": 108.88, "text": "V\\u00ec v\\u1eady, b\\u1ea1n s\\u1ebd c\\u00f3 16 k\\u00eanh cho kh\\u1ed1i l\\u01b0\\u1ee3ng ti\\u1ebfp theo."}, {"index": 23, "start": 108.88, "end": 114.8, "text": "V\\u00e0 khi b\\u00e0i b\\u00e1o n\\u00e0y \\u0111\\u01b0\\u1ee3c vi\\u1ebft v\\u00e0o n\\u0103m 1998, m\\u1ecdi ng\\u01b0\\u1eddi th\\u1ef1c s\\u1ef1 kh\\u00f4ng s\\u1eed d\\u1ee5ng padding ho\\u1eb7c"}, {"index": 24, "start": 114.8, "end": 118.64, "text": "b\\u1ea1n lu\\u00f4n s\\u1eed d\\u1ee5ng c\\u00e1c convolution h\\u1ee3p l\\u1ec7, \\u0111\\u00f3 l\\u00e0 l\\u00fd do t\\u1ea1i sao m\\u1ed7i l\\u1ea7n b\\u1ea1n \\u00e1p d\\u1ee5ng m\\u1ed9t"}, {"index": 25, "start": 118.64, "end": 121.92, "text": "l\\u1edbp convolutional, chi\\u1ec1u cao v\\u00e0 chi\\u1ec1u r\\u1ed9ng s\\u1ebd thu nh\\u1ecf l\\u1ea1i."}, {"index": 26, "start": 121.92, "end": 126.64, "text": "V\\u00ec v\\u1eady, \\u0111\\u00f3 l\\u00e0 l\\u00fd do t\\u1ea1i sao \\u1edf \\u0111\\u00e2y b\\u1ea1n \\u0111i t\\u1eeb 14 x 14 xu\\u1ed1ng 10 x 10."}, {"index": 27, "start": 126.64, "end": 130.08, "text": "Sau \\u0111\\u00f3 l\\u00e0 m\\u1ed9t l\\u1edbp pooling kh\\u00e1c, v\\u00ec v\\u1eady n\\u00f3 gi\\u1ea3m chi\\u1ec1u cao v\\u00e0 chi\\u1ec1u r\\u1ed9ng theo"}, {"index": 28, "start": 130.08, "end": 133.84, "text": "h\\u1ec7 s\\u1ed1 2 v\\u00e0 b\\u1ea1n s\\u1ebd c\\u00f3 5 x 5 \\u1edf \\u0111\\u00e2y."}, {"index": 29, "start": 133.84, "end": 137.76, "text": "V\\u00e0 n\\u1ebfu b\\u1ea1n nh\\u00e2n c\\u00e1c s\\u1ed1 n\\u00e0y l\\u1ea1i, 5 x 5 x 16, th\\u00ec"}, {"index": 30, "start": 137.76, "end": 144.0, "text": "k\\u1ebft qu\\u1ea3 s\\u1ebd l\\u00e0 400. 25 nh\\u00e2n 16 l\\u00e0 400."}, {"index": 31, "start": 144.0, "end": 147.92, "text": "V\\u00e0 l\\u1edbp ti\\u1ebfp theo l\\u00e0 m\\u1ed9t l\\u1edbp k\\u1ebft n\\u1ed1i ho\\u00e0n to\\u00e0n"}, {"index": 32, "start": 147.92, "end": 154.16, "text": "k\\u1ebft n\\u1ed1i ho\\u00e0n to\\u00e0n t\\u1eebngnode n\\u00e0y v\\u1edbi"}, {"index": 33, "start": 154.16, "end": 158.56, "text": "m\\u1ed7i m\\u1ed9t trong 120 n\\u01a1-ron. V\\u1eady n\\u00ean c\\u00f3 m\\u1ed9t l\\u1edbp k\\u1ebft n\\u1ed1i ho\\u00e0n to\\u00e0n."}, {"index": 34, "start": 158.56, "end": 162.08, "text": "V\\u00e0 \\u0111\\u00f4i khi \\u0111i\\u1ec1u \\u0111\\u00f3 s\\u1ebd \\u0111\\u01b0\\u1ee3c v\\u1ebd ra m\\u1ed9t c\\u00e1ch r\\u00f5 r\\u00e0ng"}, {"index": 35, "start": 162.08, "end": 165.92, "text": "m\\u1ed9t l\\u1edbp v\\u1edbi 400 node, nh\\u01b0ng b\\u1ecf qua \\u0111i\\u1ec1u \\u0111\\u00f3 \\u1edf \\u0111\\u00e2y."}, {"index": 36, "start": 165.92, "end": 169.6, "text": "V\\u00ec v\\u1eady, c\\u00f3 m\\u1ed9t l\\u1edbp k\\u1ebft n\\u1ed1i ho\\u00e0n to\\u00e0n v\\u00e0 sau \\u0111\\u00f3 l\\u00e0 m\\u1ed9t l\\u1edbp k\\u1ebft n\\u1ed1i ho\\u00e0n to\\u00e0n n\\u1eefa."}, {"index": 37, "start": 169.6, "end": 174.0, "text": "V\\u00e0 b\\u01b0\\u1edbc cu\\u1ed1i c\\u00f9ng l\\u00e0 n\\u00f3 s\\u1eed d\\u1ee5ng nh\\u1eefng \\u0111\\u1eb7c tr\\u01b0ng c\\u01a1 b\\u1ea3n n\\u00e0y, 84"}, {"index": 38, "start": 174.0, "end": 179.2, "text": "v\\u00e0 s\\u1eed d\\u1ee5ng n\\u00f3 v\\u1edbi m\\u1ed9t \\u0111\\u1ea7u ra cu\\u1ed1i c\\u00f9ng. T\\u00f4i \\u0111o\\u00e1n b\\u1ea1n c\\u00f3 th\\u1ec3 v\\u1ebd th\\u00eam m\\u1ed9t node \\u1edf \\u0111\\u00e2y"}, {"index": 39, "start": 179.2, "end": 182.96, "text": "\\u0111\\u1ec3 t\\u1ea1o ra m\\u1ed9t d\\u1ef1 \\u0111o\\u00e1n cho y hat. V\\u00e0 y hat nh\\u1eadn gi\\u00e1 tr\\u1ecb"}, {"index": 40, "start": 182.96, "end": 187.28, "text": "10 gi\\u00e1 tr\\u1ecb kh\\u1ea3 d\\u0129 t\\u01b0\\u01a1ng \\u1ee9ng v\\u1edbi vi\\u1ec7c nh\\u1eadn di\\u1ec7n t\\u1eebng ch\\u1eef s\\u1ed1"}, {"index": 41, "start": 187.28, "end": 191.52, "text": "t\\u1eeb 0 \\u0111\\u1ebfn 9. M\\u1ed9t phi\\u00ean b\\u1ea3n hi\\u1ec7n \\u0111\\u1ea1i c\\u1ee7a m\\u1ea1ng n\\u01a1-ron n\\u00e0y"}, {"index": 42, "start": 191.52, "end": 197.28, "text": "s\\u1ebd s\\u1eed d\\u1ee5ng m\\u1ed9t l\\u1edbp softmax v\\u1edbi \\u0111\\u1ea7u ra ph\\u00e2n lo\\u1ea1i 10 chi\\u1ec1u."}, {"index": 43, "start": 197.28, "end": 201.44, "text": "M\\u1eb7c d\\u00f9 l\\u00fac \\u0111\\u00f3, Net5 th\\u1ef1c s\\u1ef1 s\\u1eed d\\u1ee5ng m\\u1ed9t lo\\u1ea1i ph\\u00e2n lo\\u1ea1i kh\\u00e1c"}, {"index": 44, "start": 201.44, "end": 205.44, "text": "t\\u1ea1i l\\u1edbp \\u0111\\u1ea7u ra, m\\u1ed9t lo\\u1ea1i kh\\u00f4ng c\\u00f2n h\\u1eefu \\u00edch ng\\u00e0y nay."}, {"index": 45, "start": 205.44, "end": 209.12, "text": "V\\u00ec v\\u1eady, m\\u1ea1ng n\\u01a1-ron n\\u00e0y nh\\u1ecf theo ti\\u00eau chu\\u1ea9n hi\\u1ec7n \\u0111\\u1ea1i."}, {"index": 46, "start": 209.12, "end": 214.0, "text": "N\\u00f3 c\\u00f3 kho\\u1ea3ng 60.000 tham s\\u1ed1. V\\u00e0 ng\\u00e0y nay b\\u1ea1n"}, {"index": 47, "start": 214.08, "end": 218.8, "text": "th\\u01b0\\u1eddng th\\u1ea5y c\\u00e1c m\\u1ea1ng n\\u01a1-ron v\\u1edbi s\\u1ed1 tham s\\u1ed1 t\\u1eeb 10 tri\\u1ec7u \\u0111\\u1ebfn 100 tri\\u1ec7u"}, {"index": 48, "start": 218.8, "end": 221.76, "text": "tham s\\u1ed1. V\\u00e0 kh\\u00f4ng c\\u00f3 g\\u00ec l\\u1ea1 khi th\\u1ea5y c\\u00e1c m\\u1ea1ng nh\\u01b0 v\\u1eady."}, {"index": 49, "start": 221.76, "end": 225.28, "text": "Ch\\u00fang th\\u1ef1c s\\u1ef1 l\\u1edbn h\\u01a1n m\\u1ea1ng n\\u00e0y kho\\u1ea3ng m\\u1ed9t ng\\u00e0n l\\u1ea7n."}, {"index": 50, "start": 225.28, "end": 230.08, "text": "Nh\\u01b0ng m\\u1ed9t \\u0111i\\u1ec1u b\\u1ea1n th\\u1ea5y l\\u00e0 khi b\\u1ea1n \\u0111i s\\u00e2u h\\u01a1n v\\u00e0o m\\u1ea1ng, t\\u1eeb tr\\u00e1i sang ph\\u1ea3i"}, {"index": 51, "start": 230.08, "end": 234.32, "text": "chi\\u1ec1u cao v\\u00e0 chi\\u1ec1u r\\u1ed9ng"}, {"index": 52, "start": 234.32, "end": 237.6, "text": "c\\u00f3 xu h\\u01b0\\u1edbng gi\\u1ea3m. B\\u1ea1n \\u0111\\u00e3 \\u0111i t\\u1eeb 30 x 32 xu\\u1ed1ng 28 \\u0111\\u1ebfn"}, {"index": 53, "start": 237.6, "end": 242.08, "text": "14, 10, \\u0111\\u1ebfn 5. Trong khi s\\u1ed1 k\\u00eanh"}, {"index": 54, "start": 242.08, "end": 249.12, "text": "c\\u00f3 xu h\\u01b0\\u1edbng t\\u0103ng. N\\u00f3 \\u0111i t\\u1eeb 1 \\u0111\\u1ebfn 6 \\u0111\\u1ebfn 16 khi b\\u1ea1n"}, {"index": 55, "start": 249.12, "end": 252.88, "text": "\\u0111i s\\u00e2u h\\u01a1n v\\u00e0o c\\u00e1c l\\u1edbp c\\u1ee7a m\\u1ea1ng. M\\u1ed9t m\\u1eabu kh\\u00e1c b\\u1ea1n th\\u1ea5y trong m\\u1ea1ng"}, {"index": 56, "start": 252.88, "end": 255.84, "text": "n\\u01a1-ron n\\u00e0y v\\u1eabn th\\u01b0\\u1eddng \\u0111\\u01b0\\u1ee3c l\\u1eb7p l\\u1ea1i ng\\u00e0y nay l\\u00e0 r\\u1eb1ng"}, {"index": 57, "start": 255.84, "end": 260.56, "text": "b\\u1ea1n c\\u00f3 th\\u1ec3 c\\u00f3 m\\u1ed9t ho\\u1eb7c nhi\\u1ec1u l\\u1edbp conf theo sau b\\u1edfi m\\u1ed9t l\\u1edbp k\\u00e9o"}, {"index": 58, "start": 260.56, "end": 264.0, "text": "v\\u00e0 sau \\u0111\\u00f3 l\\u00e0 m\\u1ed9t l\\u1edbp conf ho\\u1eb7c \\u0111\\u00f4i khi nhi\\u1ec1u l\\u1edbp conf"}, {"index": 59, "start": 264.0, "end": 267.76, "text": "theo sau b\\u1edfi m\\u1ed9t l\\u1edbp k\\u00e9o v\\u00e0 sau \\u0111\\u00f3 l\\u00e0 m\\u1ed9t s\\u1ed1 l\\u1edbp k\\u1ebft n\\u1ed1i \\u0111\\u1ea7y \\u0111\\u1ee7"}, {"index": 60, "start": 267.76, "end": 274.0, "text": "v\\u00e0 sau \\u0111\\u00f3 l\\u00e0 \\u0111\\u1ea7u ra. V\\u00ec v\\u1eady, lo\\u1ea1i s\\u1eafp x\\u1ebfp c\\u00e1c l\\u1edbp n\\u00e0y l\\u00e0 kh\\u00e1 ph\\u1ed5 bi\\u1ebfn."}, {"index": 61, "start": 274.0, "end": 278.0, "text": "Cu\\u1ed1i c\\u00f9ng, \\u0111\\u00e2y c\\u00f3 l\\u1ebd ch\\u1ec9 d\\u00e0nh cho nh\\u1eefng ai mu\\u1ed1n th\\u1eed \\u0111\\u1ecdc t\\u00e0i li\\u1ec7u."}, {"index": 62, "start": 278.0, "end": 280.96, "text": "C\\u00f3 m\\u1ed9t v\\u00e0i \\u0111i\\u1ec1u kh\\u00e1c m\\u00e0 \\u0111\\u00e3"}, {"index": 63, "start": 280.96, "end": 284.8, "text": "kh\\u00e1c bi\\u1ec7t. Ph\\u1ea7n c\\u00f2n l\\u1ea1i c\\u1ee7a slide n\\u00e0y t\\u00f4i s\\u1ebd"}, {"index": 64, "start": 284.8, "end": 289.36, "text": "n\\u00eau v\\u00e0i nh\\u1eadn x\\u00e9t n\\u00e2ng cao ch\\u1ec9 d\\u00e0nh cho nh\\u1eefng ai mu\\u1ed1n th\\u1eed"}, {"index": 65, "start": 289.36, "end": 294.8, "text": "\\u0111\\u1ecdc b\\u00e0i b\\u00e1o kinh \\u0111i\\u1ec3n n\\u00e0y. V\\u00e0 v\\u00ec v\\u1eady m\\u1ecdi th\\u1ee9 t\\u00f4i s\\u1ebd vi\\u1ebft b\\u1eb1ng m\\u00e0u \\u0111\\u1ecf"}, {"index": 66, "start": 294.8, "end": 299.76, "text": "c\\u00e1c b\\u1ea1n c\\u00f3 th\\u1ec3 an t\\u00e2m b\\u1ecf qua slide n\\u00e0y. V\\u00e0 \\u0111\\u00e2y c\\u00f3 th\\u1ec3 l\\u00e0 m\\u1ed9t \\u0111i\\u1ec3m th\\u00fa v\\u1ecb trong l\\u1ecbch s\\u1eed"}, {"index": 67, "start": 299.76, "end": 304.32, "text": "ch\\u00fa th\\u00edch m\\u00e0 kh\\u00f4ng sao n\\u1ebfu b\\u1ea1n kh\\u00f4ng theo d\\u00f5i ho\\u00e0n to\\u00e0n."}, {"index": 68, "start": 304.32, "end": 307.36, "text": "V\\u1eady h\\u00f3a ra r\\u1eb1ng n\\u1ebfu b\\u1ea1n \\u0111\\u1ecdc b\\u00e0i b\\u00e1o g\\u1ed1c,"}, {"index": 69, "start": 307.36, "end": 311.04, "text": "th\\u1eddi \\u0111\\u00f3 m\\u1ecdi ng\\u01b0\\u1eddi s\\u1eed d\\u1ee5ng h\\u00e0m sigmoid v\\u00e0 h\\u00e0m tanh."}, {"index": 70, "start": 311.04, "end": 314.32, "text": "H\\u1ecd kh\\u00f4ng s\\u1eed d\\u1ee5ng"}, {"index": 71, "start": 314.32, "end": 317.68, "text": "h\\u00e0m ReLU v\\u00e0o th\\u1eddi \\u0111i\\u1ec3m \\u0111\\u00f3. N\\u1ebfu b\\u1ea1n nh\\u00ecn v\\u00e0o b\\u00e0i b\\u00e1o, b\\u1ea1n s\\u1ebd th\\u1ea5y"}, {"index": 72, "start": 317.68, "end": 323.2, "text": "c\\u00f3 \\u0111\\u1ec1 c\\u1eadp \\u0111\\u1ebfn sigmoid v\\u00e0 tanh. V\\u00e0 c\\u0169ng c\\u00f3 m\\u1ed9t s\\u1ed1 c\\u00e1ch k\\u1ef3 l\\u1ea1 v\\u1ec1"}, {"index": 73, "start": 323.2, "end": 326.8, "text": "c\\u00e1ch m\\u00e0 m\\u1ea1ng n\\u00e0y \\u0111\\u01b0\\u1ee3c k\\u1ebft n\\u1ed1i. \\u00cdt nh\\u1ea5t l\\u00e0 k\\u1ef3 l\\u1ea1 theo ti\\u00eau chu\\u1ea9n hi\\u1ec7n \\u0111\\u1ea1i."}, {"index": 74, "start": 326.8, "end": 332.96, "text": "V\\u00ed d\\u1ee5, b\\u1ea1n \\u0111\\u00e3 th\\u1ea5y r\\u1eb1ng n\\u1ebfu b\\u1ea1n c\\u00f3 m\\u1ed9t m\\u1ea1ng v\\u1edbi k\\u00edch th\\u01b0\\u1edbc nhh x nww x ncc,"}, {"index": 75, "start": 332.96, "end": 339.28, "text": "v\\u1edbi ncc k\\u00eanh th\\u00ec b\\u1ea1n s\\u1eed d\\u1ee5ng b\\u1ed9 l\\u1ecdc k\\u00edch th\\u01b0\\u1edbc f x f x c\\u00f9ng ncc."}, {"index": 76, "start": 339.28, "end": 343.52, "text": "m\\u1ed7i b\\u1ed9 l\\u1ecdc nh\\u00ecn v\\u00e0o t\\u1eebng k\\u00eanh n\\u00e0y."}, {"index": 77, "start": 343.52, "end": 347.12, "text": "Nh\\u01b0ng th\\u1eddi \\u0111\\u00f3, m\\u00e1y t\\u00ednh ch\\u1eadm h\\u01a1n nhi\\u1ec1u,"}, {"index": 78, "start": 347.12, "end": 350.48, "text": "v\\u00ec v\\u1eady \\u0111\\u1ec3 ti\\u1ebft ki\\u1ec7m t\\u00ednh to\\u00e1n c\\u0169ng nh\\u01b0 c\\u00e1c tham s\\u1ed1,"}, {"index": 79, "start": 350.64, "end": 353.76, "text": "Lynette 5 g\\u1ed1c \\u0111\\u00e3 c\\u00f3 m\\u1ed9t c\\u00e1ch l\\u00e0m ph\\u1ee9c t\\u1ea1p k\\u1ef3 l\\u1ea1."}, {"index": 80, "start": 353.76, "end": 358.08, "text": "n\\u01a1i m\\u00e0 c\\u00e1c b\\u1ed9 l\\u1ecdc kh\\u00e1c nhau nh\\u00ecn v\\u00e0o c\\u00e1c k\\u00eanh kh\\u00e1c nhau c\\u1ee7a kh\\u1ed1i \\u0111\\u1ea7u v\\u00e0o."}, {"index": 81, "start": 358.08, "end": 361.92, "text": "V\\u00e0 do \\u0111\\u00f3, t\\u00e0i li\\u1ec7u \\u0111\\u1ec1 c\\u1eadp \\u0111\\u1ebfn nh\\u1eefng chi ti\\u1ebft \\u0111\\u00f3, nh\\u01b0ng tri\\u1ec3n khai hi\\u1ec7n \\u0111\\u1ea1i h\\u01a1n"}, {"index": 82, "start": 361.92, "end": 366.96, "text": "th\\u00ec b\\u1ea1n bi\\u1ebft \\u0111\\u1ea5y, s\\u1ebd kh\\u00f4ng c\\u00f3 lo\\u1ea1i \\u0111\\u1ed9 ph\\u1ee9c t\\u1ea1p \\u0111\\u00f3 v\\u00e0o ng\\u00e0y nay."}, {"index": 83, "start": 366.96, "end": 371.76, "text": "V\\u00e0 r\\u1ed3i m\\u1ed9t \\u0111i\\u1ec1u cu\\u1ed1i c\\u00f9ng \\u0111\\u01b0\\u1ee3c th\\u1ef1c hi\\u1ec7n v\\u00e0o th\\u1eddi \\u0111i\\u1ec3m \\u0111\\u00f3 t\\u00f4i \\u0111o\\u00e1n l\\u00e0 nh\\u01b0ng kh\\u00f4ng th\\u1ef1c s\\u1ef1"}, {"index": 84, "start": 371.76, "end": 375.12, "text": "th\\u1ef1c hi\\u1ec7n ngay b\\u00e2y gi\\u1edd l\\u00e0 Lynette 5 nguy\\u00ean b\\u1ea3n"}, {"index": 85, "start": 375.12, "end": 379.52, "text": "c\\u00f3 m\\u1ed9t t\\u00ednh kh\\u00f4ng tuy\\u1ebfn t\\u00ednh sau khi g\\u1ed9p."}, {"index": 86, "start": 379.68, "end": 383.04, "text": "V\\u00e0 t\\u00f4i ngh\\u0129 r\\u1eb1ng n\\u00f3 th\\u1ef1c s\\u1ef1 \\u0111\\u00e3 s\\u1eed d\\u1ee5ng m\\u1ed9t t\\u00ednh kh\\u00f4ng tuy\\u1ebfn t\\u00ednh sigmoid"}, {"index": 87, "start": 383.04, "end": 387.12, "text": "sau l\\u1edbp g\\u1ed9p. V\\u00ec v\\u1eady, n\\u1ebfu b\\u1ea1n \\u0111\\u1ecdc t\\u00e0i li\\u1ec7u n\\u00e0y"}, {"index": 88, "start": 387.12, "end": 390.56, "text": "v\\u00e0 \\u0111\\u00e2y l\\u00e0 m\\u1ed9t trong nh\\u1eefng t\\u00e0i li\\u1ec7u kh\\u00f3 \\u0111\\u1ecdc h\\u01a1n, n\\u00ean nh\\u1eefng c\\u00e1i kh\\u00e1c s\\u1ebd \\u0111\\u01b0\\u1ee3c \\u0111\\u1ec1 c\\u1eadp trong"}, {"index": 89, "start": 390.56, "end": 393.76, "text": "nh\\u1eefng video ti\\u1ebfp theo. Video ti\\u1ebfp theo c\\u00f3 th\\u1ec3 d\\u1ec5 d\\u00e0ng h\\u01a1n \\u0111\\u1ec3"}, {"index": 90, "start": 393.76, "end": 396.08, "text": "b\\u1eaft \\u0111\\u1ea7u v\\u1edbi. H\\u1ea7u h\\u1ebft c\\u00e1c \\u00fd t\\u01b0\\u1edfng tr\\u00ean slide n\\u00e0y l\\u00e0"}, {"index": 91, "start": 396.08, "end": 400.0, "text": "\\u0111\\u01b0\\u1ee3c m\\u00f4 t\\u1ea3 trong c\\u00e1c ph\\u1ea7n 2 v\\u00e0 3 c\\u1ee7a t\\u00e0i li\\u1ec7u."}, {"index": 92, "start": 400.0, "end": 404.56, "text": "V\\u00e0 c\\u00e1c ph\\u1ea7n sau c\\u1ee7a t\\u00e0i li\\u1ec7u \\u0111\\u1ec1 c\\u1eadp \\u0111\\u1ebfn m\\u1ed9t s\\u1ed1 \\u00fd t\\u01b0\\u1edfng kh\\u00e1c."}, {"index": 93, "start": 404.56, "end": 408.24, "text": "N\\u00f3 \\u0111\\u00e3 n\\u00f3i v\\u1ec1 m\\u1ed9t c\\u00e1i g\\u1ecdi l\\u00e0 m\\u1ea1ng bi\\u1ebfn \\u0111\\u1ed5i d\\u1ef1 th\\u1ea3o m\\u00e0 kh\\u00f4ng \\u0111\\u01b0\\u1ee3c"}, {"index": 94, "start": 408.24, "end": 410.96, "text": "s\\u1eed d\\u1ee5ng r\\u1ed9ng r\\u00e3i ng\\u00e0y nay. V\\u00ec v\\u1eady, n\\u1ebfu b\\u1ea1n c\\u1ed1 g\\u1eafng \\u0111\\u1ecdc t\\u00e0i li\\u1ec7u n\\u00e0y"}, {"index": 95, "start": 410.96, "end": 414.8, "text": "t\\u00f4i khuy\\u00ean b\\u1ea1n n\\u00ean t\\u1eadp trung th\\u1ef1c s\\u1ef1 v\\u00e0o ph\\u1ea7n 2, ph\\u1ea7n n\\u00f3i v\\u1ec1"}, {"index": 96, "start": 414.8, "end": 418.24, "text": "ki\\u1ebfn tr\\u00fac n\\u00e0y v\\u00e0 c\\u00f3 th\\u1ec3 nh\\u00ecn nhanh qua ph\\u1ea7n 3"}, {"index": 97, "start": 418.24, "end": 421.6, "text": "c\\u00f3 m\\u1ed9t lo\\u1ea1t c\\u00e1c k\\u1ebft qu\\u1ea3 th\\u00ed nghi\\u1ec7m r\\u1ea5t th\\u00fa v\\u1ecb."}, {"index": 98, "start": 421.6, "end": 425.2, "text": "V\\u00ed d\\u1ee5 th\\u1ee9 hai v\\u1ec1 m\\u1ed9t m\\u1ea1ng n\\u01a1-ron t\\u00f4i mu\\u1ed1n cho b\\u1ea1n xem l\\u00e0"}, {"index": 99, "start": 425.2, "end": 429.52, "text": "Alex Nett \\u0111\\u01b0\\u1ee3c \\u0111\\u1eb7t t\\u00ean theo Alex Trzejevsky, ng\\u01b0\\u1eddi l\\u00e0 t\\u00e1c gi\\u1ea3 \\u0111\\u1ea7u ti\\u00ean"}, {"index": 100, "start": 429.52, "end": 433.6, "text": "c\\u1ee7a b\\u00e0i b\\u00e1o m\\u00f4 t\\u1ea3 c\\u00f4ng tr\\u00ecnh n\\u00e0y. C\\u00e1c t\\u00e1c gi\\u1ea3 kh\\u00e1c l\\u00e0"}, {"index": 101, "start": 433.68, "end": 436.8, "text": "Saskever v\\u00e0 Jeffrey Hinton. V\\u1eady Alex Nett"}, {"index": 102, "start": 436.8, "end": 442.48, "text": "\\u0111\\u1ea7u v\\u00e0o b\\u1eaft \\u0111\\u1ea7u b\\u1eb1ng h\\u00ecnh \\u1ea3nh 227 x 227 x 3. \\u1ed2 v\\u00e0 n\\u1ebfu b\\u1ea1n \\u0111\\u1ecdc b\\u00e0i b\\u00e1o"}, {"index": 103, "start": 442.48, "end": 448.0, "text": "b\\u00e0i b\\u00e1o \\u0111\\u1ec1 c\\u1eadp \\u0111\\u1ebfn h\\u00ecnh \\u1ea3nh 224 x 224 x 3 nh\\u01b0ng n\\u1ebfu b\\u1ea1n nh\\u00ecn v\\u00e0o c\\u00e1c con s\\u1ed1"}, {"index": 104, "start": 448.0, "end": 453.12, "text": "t\\u00f4i ngh\\u0129 r\\u1eb1ng c\\u00e1c con s\\u1ed1 ch\\u1ec9 h\\u1ee3p l\\u00fd n\\u1ebfu th\\u1ef1c s\\u1ef1 l\\u00e0 227 x 227."}, {"index": 105, "start": 453.12, "end": 457.52, "text": "V\\u00e0 sau \\u0111\\u00f3, l\\u1edbp \\u0111\\u1ea7u ti\\u00ean \\u00e1p d\\u1ee5ng m\\u1ed9t t\\u1eadp h\\u1ee3p 96"}, {"index": 106, "start": 457.52, "end": 462.64, "text": "b\\u1ed9 l\\u1ecdc 11 x 11 v\\u1edbi b\\u01b0\\u1edbc nh\\u1ea3y 4 v\\u00e0 b\\u1edfi v\\u00ec n\\u00f3 s\\u1eed d\\u1ee5ng b\\u01b0\\u1edbc nh\\u1ea3y l\\u1edbn 4"}, {"index": 107, "start": 462.64, "end": 466.8, "text": "k\\u00edch th\\u01b0\\u1edbc gi\\u1ea3m xu\\u1ed1ng 55 x 55, v\\u00ec v\\u1eady x\\u1ea5p x\\u1ec9"}, {"index": 108, "start": 466.8, "end": 471.36, "text": "gi\\u1ea3m xu\\u1ed1ng c\\u00f2n 1/4 do b\\u01b0\\u1edbc nh\\u1ea3y l\\u1edbn"}, {"index": 109, "start": 471.36, "end": 478.0, "text": "v\\u00e0 sau \\u0111\\u00f3 \\u00e1p d\\u1ee5ng max pooling v\\u1edbi b\\u1ed9 l\\u1ecdc 3 x 3, v\\u1eady f b\\u1eb1ng 3 v\\u00e0 b\\u01b0\\u1edbc nh\\u1ea3y 2"}, {"index": 110, "start": 478.0, "end": 485.12, "text": "do \\u0111\\u00f3, \\u0111i\\u1ec1u n\\u00e0y gi\\u1ea3m th\\u1ec3 t\\u00edch xu\\u1ed1ng c\\u00f2n 27 x 27 x 96"}, {"index": 111, "start": 485.12, "end": 489.68, "text": "sau \\u0111\\u00f3, n\\u00f3 th\\u1ef1c hi\\u1ec7n ph\\u00e9p t\\u00edch ch\\u1eadp 5 x 5 v\\u1edbi c\\u00f9ng c\\u00e1ch pad"}, {"index": 112, "start": 489.76, "end": 496.72, "text": "do v\\u1eady b\\u1ea1n s\\u1ebd c\\u00f3 \\u0111\\u01b0\\u1ee3c k\\u00edch th\\u01b0\\u1edbc 27 x 27 x 276. L\\u1ea1i l\\u00e0 max pooling"}, {"index": 113, "start": 496.72, "end": 501.12, "text": "\\u0111i\\u1ec1u n\\u00e0y gi\\u1ea3m chi\\u1ec1u cao v\\u00e0 chi\\u1ec1u r\\u1ed9ng xu\\u1ed1ng c\\u00f2n 13 v\\u00e0 sau \\u0111\\u00f3 l\\u00e0 th\\u00eam m\\u1ed9t"}, {"index": 114, "start": 501.12, "end": 506.88, "text": "ph\\u00e9p t\\u00edch ch\\u1eadp t\\u01b0\\u01a1ng t\\u1ef1, v\\u1edbi c\\u00f9ng m\\u1ed9t c\\u00e1ch pad n\\u00ean b\\u00e2y gi\\u1edd l\\u00e0 13 x 13"}, {"index": 115, "start": 506.88, "end": 514.08, "text": "v\\u1edbi 384 b\\u1ed9 l\\u1ecdc v\\u00e0 sau \\u0111\\u00f3 l\\u1ea1i l\\u00e0 ph\\u00e9p t\\u00edch ch\\u1eadp 3 x 3 t\\u01b0\\u01a1ng t\\u1ef1"}, {"index": 116, "start": 514.08, "end": 519.6, "text": "s\\u1ebd cho b\\u1ea1n k\\u1ebft qu\\u1ea3, sau \\u0111\\u00f3 ph\\u00e9p t\\u00edch ch\\u1eadp 3 x 3 t\\u01b0\\u01a1ng t\\u1ef1 l\\u1ea1i cho b\\u1ea1n k\\u1ebft qu\\u1ea3"}, {"index": 117, "start": 519.76, "end": 526.48, "text": "sau \\u0111\\u00f3 max pool \\u0111\\u01b0a k\\u00edch th\\u01b0\\u1edbc xu\\u1ed1ng c\\u00f2n 6 x 6 x 256 n\\u1ebfu b\\u1ea1n nh\\u00e2n c\\u00e1c"}, {"index": 118, "start": 526.48, "end": 532.4, "text": "s\\u1ed1 n\\u00e0y: 6 nh\\u00e2n 6 nh\\u00e2n 256 th\\u00ec l\\u00e0 9216, v\\u00ec v\\u1eady ch\\u00fang ta"}, {"index": 119, "start": 532.4, "end": 537.52, "text": "s\\u1ebd gi\\u1ea3i n\\u00e9n \\u0111i\\u1ec1u n\\u00e0y th\\u00e0nh 9216 n\\u01a1-ron v\\u00e0 sau \\u0111\\u00f3"}, {"index": 120, "start": 537.52, "end": 541.68, "text": "Cu\\u1ed1i c\\u00f9ng, n\\u00f3 c\\u00f3 m\\u1ed9t v\\u00e0i l\\u1edbp k\\u1ebft n\\u1ed1i ho\\u00e0n to\\u00e0n v\\u00e0 sau \\u0111\\u00f3"}, {"index": 121, "start": 541.68, "end": 545.92, "text": "cu\\u1ed1i c\\u00f9ng s\\u1eed d\\u1ee5ng h\\u00e0m softmax \\u0111\\u1ec3 ch\\u1ecdn ra c\\u00e1i n\\u00e0o trong s\\u1ed1"}, {"index": 122, "start": 546.0, "end": 552.72, "text": "M\\u1ea1ng n\\u01a1-ron n\\u00e0y th\\u1ef1c s\\u1ef1 c\\u00f3 r\\u1ea5t nhi\\u1ec1u \\u0111i\\u1ec1u m\\u00e0 1000 \\u0111i\\u1ec3m giao c\\u1eaft \\u0111\\u1ed1i t\\u01b0\\u1ee3ng c\\u00f3 th\\u1ec3 mang l\\u1ea1i."}, {"index": 123, "start": 552.72, "end": 558.48, "text": "c\\u00e1c \\u0111i\\u1ec3m t\\u01b0\\u01a1ng \\u0111\\u1ed3ng v\\u1edbi m\\u1ea1ng nh\\u01b0ng n\\u00f3 l\\u1edbn h\\u01a1n r\\u1ea5t nhi\\u1ec1u"}, {"index": 124, "start": 558.48, "end": 563.36, "text": "n\\u00ean trong khi \\u0111\\u00f3 m\\u1ea1ng ho\\u1eb7c m\\u1ea1ng 5 t\\u1eeb"}, {"index": 125, "start": 563.36, "end": 566.8, "text": "trang tr\\u01b0\\u1edbc c\\u00f3 60 000, kho\\u1ea3ng 60 000"}, {"index": 126, "start": 566.8, "end": 570.4, "text": "c\\u00e1c tham s\\u1ed1, alex net n\\u00e0y c\\u00f3 kho\\u1ea3ng 60 tri\\u1ec7u"}, {"index": 127, "start": 570.4, "end": 574.32, "text": "c\\u00e1c tham s\\u1ed1 v\\u00e0 th\\u1ef1c t\\u1ebf l\\u00e0 \\u0111i\\u1ec1u \\u0111\\u00f3 c\\u00f3 th\\u1ec3 m\\u1ea5t th\\u1eddi gian b\\u1ea1n bi\\u1ebft"}, {"index": 128, "start": 574.32, "end": 578.64, "text": "c\\u00e1c kh\\u1ed1i x\\u00e2y d\\u1ef1ng c\\u01a1 b\\u1ea3n kh\\u00e1 t\\u01b0\\u01a1ng t\\u1ef1 nh\\u01b0ng c\\u00f3 nhi\\u1ec1u \\u0111\\u01a1n v\\u1ecb \\u1ea9n h\\u01a1n v\\u00e0"}, {"index": 129, "start": 578.64, "end": 582.48, "text": "\\u0111\\u00e0o t\\u1ea1o n\\u00f3 tr\\u00ean nhi\\u1ec1u d\\u1eef li\\u1ec7u h\\u01a1n, v\\u00ec v\\u1eady b\\u1ea1n s\\u1ebd \\u0111\\u00e0o t\\u1ea1o tr\\u00ean t\\u1eadp d\\u1eef li\\u1ec7u ImageNet"}, {"index": 130, "start": 582.48, "end": 586.24, "text": "\\u0111i\\u1ec1u n\\u00e0y cho ph\\u00e9p n\\u00f3 c\\u00f3 hi\\u1ec7u su\\u1ea5t th\\u1eadt s\\u1ef1 \\u0111\\u00e1ng kinh ng\\u1ea1c"}, {"index": 131, "start": 586.24, "end": 590.72, "text": "m\\u1ed9t kh\\u00eda c\\u1ea1nh kh\\u00e1c c\\u1ee7a ki\\u1ebfn tr\\u00fac n\\u00e0y \\u0111\\u00e3 gi\\u00fap n\\u00f3 t\\u1ed1t h\\u01a1n nhi\\u1ec1u so v\\u1edbi m\\u1ea1ng"}, {"index": 132, "start": 590.72, "end": 594.48, "text": "l\\u00e0 vi\\u1ec7c s\\u1eed d\\u1ee5ng h\\u00e0m k\\u00edch ho\\u1ea1t doanh thu v\\u00e0 m\\u1ed9t l\\u1ea7n n\\u1eefa"}, {"index": 133, "start": 594.48, "end": 598.56, "text": "n\\u1ebfu b\\u1ea1n \\u0111\\u1ecdc th\\u00eam v\\u1ec1 b\\u00e0i b\\u00e1o bay, s\\u1ebd c\\u00f3 m\\u1ed9t s\\u1ed1 chi ti\\u1ebft n\\u00e2ng cao m\\u00e0 b\\u1ea1n kh\\u00f4ng"}, {"index": 134, "start": 598.56, "end": 600.96, "text": "th\\u1ef1c s\\u1ef1 c\\u1ea7n ph\\u1ea3i lo l\\u1eafng n\\u1ebfu b\\u1ea1n kh\\u00f4ng \\u0111\\u1ecdc b\\u00e0i b\\u00e1o"}, {"index": 135, "start": 600.96, "end": 604.8, "text": "m\\u1ed9t v\\u1ea5n \\u0111\\u1ec1 l\\u00e0 khi b\\u00e0i b\\u00e1o n\\u00e0y \\u0111\\u01b0\\u1ee3c vi\\u1ebft, c\\u00e1c GPU c\\u00f2n"}, {"index": 136, "start": 604.8, "end": 608.48, "text": "ch\\u1eadm h\\u01a1n m\\u1ed9t ch\\u00fat n\\u00ean n\\u00f3 c\\u00f3 m\\u1ed9t ph\\u01b0\\u01a1ng ph\\u00e1p ph\\u1ee9c t\\u1ea1p"}, {"index": 137, "start": 608.48, "end": 614.88, "text": "\\u0111\\u1ec3 hu\\u1ea5n luy\\u1ec7n tr\\u00ean hai GPU v\\u00e0 \\u00fd t\\u01b0\\u1edfng c\\u01a1 b\\u1ea3n l\\u00e0 nhi\\u1ec1u l\\u1edbp n\\u00e0y"}, {"index": 138, "start": 614.88, "end": 618.8, "text": "th\\u1ef1c t\\u1ebf \\u0111\\u01b0\\u1ee3c chia ra gi\\u1eefa hai GPU kh\\u00e1c nhau v\\u00e0 c\\u00f3 m\\u1ed9t c\\u00e1ch"}, {"index": 139, "start": 618.8, "end": 623.44, "text": "suy ngh\\u0129 cho vi\\u1ec7c hai GPU s\\u1ebd giao ti\\u1ebfp v\\u1edbi nhau nh\\u01b0 th\\u1ebf n\\u00e0o"}, {"index": 140, "start": 623.44, "end": 627.44, "text": "v\\u00e0 t\\u00e0i li\\u1ec7u n\\u00e0y c\\u0169ng l\\u00e0 ki\\u1ebfn tr\\u00fac alex net g\\u1ed1c"}, {"index": 141, "start": 627.44, "end": 633.92, "text": "c\\u0169ng c\\u00f3 m\\u1ed9t lo\\u1ea1i l\\u1edbp kh\\u00e1c g\\u1ecdi l\\u00e0 chu\\u1ea9n h\\u00f3a ph\\u1ea3n h\\u1ed3i \\u0111\\u1ecba ph\\u01b0\\u01a1ng"}, {"index": 142, "start": 633.92, "end": 638.8, "text": "v\\u00e0 lo\\u1ea1i l\\u1edbp n\\u00e0y th\\u1ef1c s\\u1ef1 kh\\u00f4ng \\u0111\\u01b0\\u1ee3c s\\u1eed d\\u1ee5ng nhi\\u1ec1u, \\u0111\\u00f3 l\\u00e0 l\\u00fd do t\\u1ea1i sao t\\u00f4i kh\\u00f4ng n\\u00f3i v\\u1ec1 n\\u00f3"}, {"index": 143, "start": 638.8, "end": 643.04, "text": "nh\\u01b0ng \\u00fd t\\u01b0\\u1edfng c\\u01a1 b\\u1ea3n c\\u1ee7a chu\\u1ea9n h\\u00f3a ph\\u1ea3n h\\u1ed3i \\u0111\\u1ecba ph\\u01b0\\u01a1ng l\\u00e0 n\\u1ebfu b\\u1ea1n"}, {"index": 144, "start": 643.04, "end": 646.88, "text": "nh\\u00ecn v\\u00e0o m\\u1ed9t trong nh\\u1eefng kh\\u1ed1i ho\\u1eb7c th\\u1ec3 t\\u00edch m\\u00e0 ch\\u00fang ta c\\u00f3 \\u1edf tr\\u00ean"}, {"index": 145, "start": 646.88, "end": 650.88, "text": "gi\\u1ea3 s\\u1eed \\u0111\\u1ec3 lu\\u1eadn b\\u00e0n, c\\u00e1i n\\u00e0y b\\u1ea1n bi\\u1ebft 13 x 13"}, {"index": 146, "start": 650.88, "end": 654.48, "text": "v\\u1edbi 256, th\\u00ec vi\\u1ec7c chu\\u1ea9n h\\u00f3a ph\\u1ea3n h\\u1ed3i \\u0111\\u1ecba ph\\u01b0\\u01a1ng"}, {"index": 147, "start": 654.64, "end": 659.6, "text": "\\u0111\\u1ecbnh ngh\\u0129a c\\u1ee7a ch\\u00fang ta l\\u00e0 b\\u1ea1n nh\\u00ecn v\\u00e0o m\\u1ed9t v\\u1ecb tr\\u00ed, t\\u1ee9c l\\u00e0 m\\u1ed9t v\\u1ecb tr\\u00ed \\u0111\\u1ec3 t\\u0103ng c\\u01b0\\u1eddng"}, {"index": 148, "start": 659.6, "end": 664.56, "text": "v\\u00e0 nh\\u00ecn xu\\u1ed1ng to\\u00e0n b\\u1ed9 c\\u00e1c k\\u00eanh, nh\\u00ecn v\\u00e0o t\\u1ea5t c\\u1ea3 256"}, {"index": 149, "start": 664.56, "end": 668.64, "text": "s\\u1ed1 li\\u1ec7u v\\u00e0 chu\\u1ea9n h\\u00f3a ch\\u00fang, v\\u00e0 \\u0111\\u1ed9ng l\\u1ef1c cho \\u0111i\\u1ec1u n\\u00e0y"}, {"index": 150, "start": 668.64, "end": 671.92, "text": "chu\\u1ea9n h\\u00f3a ph\\u1ea3n h\\u1ed3i \\u0111\\u1ecba ph\\u01b0\\u01a1ng l\\u00e0 cho m\\u1ed7i v\\u1ecb tr\\u00ed"}, {"index": 151, "start": 671.92, "end": 676.56, "text": "trong h\\u00ecnh \\u1ea3nh 13 x 13 n\\u00e0y, c\\u00f3 th\\u1ec3 b\\u1ea1n kh\\u00f4ng mu\\u1ed1n"}, {"index": 152, "start": 676.56, "end": 680.08, "text": "qu\\u00e1 nhi\\u1ec1u n\\u01a1-ron v\\u1edbi k\\u00edch ho\\u1ea1t r\\u1ea5t cao"}, {"index": 153, "start": 680.08, "end": 684.56, "text": "nh\\u01b0ng sau \\u0111\\u00f3 nhi\\u1ec1u nh\\u00e0 nghi\\u00ean c\\u1ee9u \\u0111\\u00e3 ph\\u00e1t hi\\u1ec7n ra r\\u1eb1ng \\u0111i\\u1ec1u n\\u00e0y kh\\u00f4ng gi\\u00fap \\u00edch nhi\\u1ec1u"}, {"index": 154, "start": 684.56, "end": 688.96, "text": "v\\u00ec v\\u1eady \\u0111\\u00e2y l\\u00e0 m\\u1ed9t trong nh\\u1eefng \\u00fd t\\u01b0\\u1edfng m\\u00e0 t\\u00f4i \\u0111ang tr\\u00edch d\\u1eabn v\\u00e0 \\u0111\\u1ecdc v\\u00ec"}, {"index": 155, "start": 688.96, "end": 691.76, "text": "n\\u00f3 \\u00edt quan tr\\u1ecdng h\\u01a1n \\u0111\\u1ec3 b\\u1ea1n hi\\u1ec3u \\u0111i\\u1ec1u n\\u00e0y"}, {"index": 156, "start": 691.76, "end": 695.92, "text": "v\\u00e0 trong th\\u1ef1c t\\u1ebf, t\\u00f4i th\\u1ef1c s\\u1ef1 kh\\u00f4ng s\\u1eed d\\u1ee5ng chu\\u1ea9n h\\u00f3a ph\\u1ea3n h\\u1ed3i \\u0111\\u1ecba ph\\u01b0\\u01a1ng"}, {"index": 157, "start": 695.92, "end": 699.12, "text": "b\\u1ea1n bi\\u1ebft, th\\u1ef1c s\\u1ef1 trong c\\u00e1c m\\u1ea1ng m\\u00e0 t\\u00f4i s\\u1ebd \\u0111\\u00e0o t\\u1ea1o ng\\u00e0y h\\u00f4m nay, v\\u00ec v\\u1eady n\\u1ebfu b\\u1ea1n"}, {"index": 158, "start": 699.12, "end": 702.24, "text": "quan t\\u00e2m \\u0111\\u1ebfn l\\u1ecbch s\\u1eed c\\u1ee7a h\\u1ecdc s\\u00e2u, t\\u00f4i ngh\\u0129"}, {"index": 159, "start": 702.24, "end": 706.08, "text": "ngay c\\u1ea3 tr\\u01b0\\u1edbc alex net, h\\u1ecdc s\\u00e2u \\u0111\\u00e3 b\\u1eaft \\u0111\\u1ea7u thu h\\u00fat s\\u1ef1 ch\\u00fa \\u00fd"}, {"index": 160, "start": 706.08, "end": 708.88, "text": "trong nh\\u1eadn di\\u1ec7n gi\\u1ecdng n\\u00f3i \\u1edf m\\u1ed9t v\\u00e0i l\\u0129nh v\\u1ef1c kh\\u00e1c"}, {"index": 161, "start": 708.88, "end": 713.6, "text": "nh\\u01b0ng th\\u1ef1c s\\u1ef1 ch\\u00ednh b\\u00e0i b\\u00e1o n\\u00e0y \\u0111\\u00e3 thuy\\u1ebft ph\\u1ee5c r\\u1ea5t nhi\\u1ec1u ng\\u01b0\\u1eddi trong l\\u0129nh v\\u1ef1c th\\u1ecb gi\\u00e1c m\\u00e1y t\\u00ednh"}, {"index": 162, "start": 713.6, "end": 717.6, "text": "\\u0111\\u1ec3 h\\u1ecd nghi\\u00eam t\\u00fac xem x\\u00e9t h\\u1ecdc s\\u00e2u, \\u0111\\u1ec3 thuy\\u1ebft ph\\u1ee5c h\\u1ecd r\\u1eb1ng"}, {"index": 163, "start": 717.6, "end": 720.0, "text": "h\\u1ecdc s\\u00e2u th\\u1ef1c s\\u1ef1 hi\\u1ec7u qu\\u1ea3 trong th\\u1ecb gi\\u00e1c m\\u00e1y t\\u00ednh"}, {"index": 164, "start": 720.0, "end": 723.84, "text": "v\\u00e0 sau \\u0111\\u00f3 ch\\u00fang \\u0111\\u00e3 ph\\u00e1t tri\\u1ec3n \\u0111\\u1ec3 c\\u00f3 t\\u00e1c \\u0111\\u1ed9ng l\\u1edbn kh\\u00f4ng ch\\u1ec9 trong th\\u1ecb gi\\u00e1c m\\u00e1y t\\u00ednh m\\u00e0"}, {"index": 165, "start": 723.84, "end": 727.52, "text": "c\\u1ea3 v\\u01b0\\u1ee3t ra ngo\\u00e0i l\\u0129nh v\\u1ef1c th\\u1ecb gi\\u00e1c m\\u00e1y t\\u00ednh n\\u1eefa v\\u00e0 n\\u1ebfu b\\u1ea1n mu\\u1ed1n th\\u1eed \\u0111\\u1ecdc m\\u1ed9t s\\u1ed1"}, {"index": 166, "start": 727.52, "end": 731.68, "text": "c\\u00e1c b\\u00e0i b\\u00e1o n\\u00e0y th\\u00ec b\\u1ea1n th\\u1eadt s\\u1ef1 kh\\u00f4ng c\\u1ea7n ph\\u1ea3i l\\u00e0m \\u0111i\\u1ec1u \\u0111\\u00f3 cho kh\\u00f3a h\\u1ecdc n\\u00e0y"}, {"index": 167, "start": 731.68, "end": 735.6, "text": "nh\\u01b0ng n\\u1ebfu b\\u1ea1n mu\\u1ed1n th\\u1eed \\u0111\\u1ecdc m\\u1ed9t s\\u1ed1 b\\u00e0i b\\u00e1o n\\u00e0y th\\u00ec b\\u00e0i n\\u00e0y l\\u00e0 m\\u1ed9t trong s\\u1ed1"}, {"index": 168, "start": 735.68, "end": 739.36, "text": "nh\\u1eefng b\\u00e0i d\\u1ec5 \\u0111\\u1ecdc h\\u01a1n, v\\u00ec v\\u1eady \\u0111\\u00e2y c\\u00f3 th\\u1ec3 l\\u00e0 m\\u1ed9t b\\u00e0i t\\u1ed1t \\u0111\\u1ec3 xem"}, {"index": 169, "start": 739.36, "end": 743.28, "text": "n\\u00ean trong khi m\\u1ea1ng alex net c\\u00f3 ki\\u1ebfn tr\\u00fac t\\u01b0\\u01a1ng \\u0111\\u1ed1i ph\\u1ee9c t\\u1ea1p"}, {"index": 170, "start": 743.28, "end": 746.16, "text": "c\\u00f3 r\\u1ea5t nhi\\u1ec1u tham s\\u1ed1 si\\u00eau m\\u00e0 b\\u1ea1n bi\\u1ebft l\\u00e0"}, {"index": 171, "start": 746.16, "end": 752.0, "text": "t\\u1ea5t c\\u1ea3 nh\\u1eefng con s\\u1ed1 m\\u00e0 alex trusevsky v\\u00e0 c\\u00e1c \\u0111\\u1ed3ng t\\u00e1c gi\\u1ea3 c\\u1ee7a \\u00f4ng \\u0111\\u00e3"}, {"index": 172, "start": 752.0, "end": 755.2, "text": "ph\\u1ea3i \\u0111\\u01b0a ra, h\\u00e3y \\u0111\\u1ec3 t\\u00f4i cho b\\u1ea1n xem m\\u1ed9t v\\u00ed d\\u1ee5 th\\u1ee9 ba v\\u00e0 c\\u0169ng l\\u00e0 cu\\u1ed1i c\\u00f9ng"}, {"index": 173, "start": 755.2, "end": 758.88, "text": "trong video n\\u00e0y g\\u1ecdi l\\u00e0 vgg ho\\u1eb7c vgg 16"}, {"index": 174, "start": 758.88, "end": 763.52, "text": "v\\u00e0 m\\u1ed9t \\u0111i\\u1ec1u \\u0111\\u00e1ng ch\\u00fa \\u00fd v\\u1ec1 vgg 16"}, {"index": 175, "start": 763.52, "end": 767.36, "text": "l\\u00e0 h\\u1ecd \\u0111\\u00e3 n\\u00f3i thay v\\u00ec c\\u00f3 qu\\u00e1 nhi\\u1ec1u tham s\\u1ed1 si\\u00eau, h\\u00e3y"}, {"index": 176, "start": 767.36, "end": 771.84, "text": "s\\u1eed d\\u1ee5ng m\\u1ed9t m\\u1ea1ng \\u0111\\u01a1n gi\\u1ea3n h\\u01a1n, n\\u01a1i b\\u1ea1n ch\\u1ec9 t\\u1eadp trung v\\u00e0o vi\\u1ec7c c\\u00f3"}, {"index": 177, "start": 771.84, "end": 774.96, "text": "c\\u00e1c l\\u1edbp b\\u1ed9 l\\u1ecdc convolution ch\\u1ec9 l\\u00e0 b\\u1ed9 l\\u1ecdc 3x3 v\\u1edbi"}, {"index": 178, "start": 774.96, "end": 778.96, "text": "b\\u01b0\\u1edbc nh\\u1ea3y b\\u1eb1ng m\\u1ed9t v\\u00e0 lu\\u00f4n s\\u1eed d\\u1ee5ng padding gi\\u1ed1ng nhau"}, {"index": 179, "start": 778.96, "end": 782.24, "text": "v\\u00e0 l\\u00e0m cho t\\u1ea5t c\\u1ea3 c\\u00e1c l\\u1edbp max pooling c\\u1ee7a b\\u1ea1n l\\u00e0 2x2"}, {"index": 180, "start": 782.24, "end": 786.8, "text": "v\\u1edbi m\\u1ed9t b\\u01b0\\u1edbc nh\\u1ea3y hai v\\u00e0 m\\u1ed9t \\u0111i\\u1ec1u r\\u1ea5t t\\u1ed1t v\\u1ec1"}, {"index": 181, "start": 786.8, "end": 790.72, "text": "m\\u1ea1ng vgg l\\u00e0 n\\u00f3 th\\u1ef1c s\\u1ef1 \\u0111\\u01a1n gi\\u1ea3n h\\u00f3a nh\\u1eefng m\\u1ea1ng n\\u01a1-ron"}, {"index": 182, "start": 790.72, "end": 794.4, "text": "ki\\u1ebfn tr\\u00fac n\\u00e0y, v\\u1eady h\\u00e3y c\\u00f9ng xem x\\u00e9t ki\\u1ebfn tr\\u00fac"}, {"index": 183, "start": 794.4, "end": 797.84, "text": "b\\u1ea1n b\\u1eaft \\u0111\\u1ea7u v\\u1edbi m\\u1ed9t b\\u1ee9c \\u1ea3nh v\\u00e0 r\\u1ed3i hai l\\u1edbp \\u0111\\u1ea7u ti\\u00ean"}, {"index": 184, "start": 797.84, "end": 804.48, "text": "l\\u00e0 c\\u00e1c ph\\u00e9p bi\\u1ebfn \\u0111\\u1ed5i, do \\u0111\\u00f3 l\\u00e0 nh\\u1eefng b\\u1ed9 l\\u1ecdc ba tr\\u00ean ba"}, {"index": 185, "start": 804.48, "end": 808.32, "text": "v\\u00e0 sau \\u0111\\u00f3 \\u1edf hai l\\u1edbp \\u0111\\u1ea7u ti\\u00ean b\\u1ea1n s\\u1eed d\\u1ee5ng 64 b\\u1ed9 l\\u1ecdc \\u0111\\u1ec3 b\\u1ea1n c\\u00f3 \\u0111\\u01b0\\u1ee3c"}, {"index": 186, "start": 808.32, "end": 811.44, "text": "m\\u1ed9t k\\u00edch th\\u01b0\\u1edbc 224 tr\\u00ean 224 v\\u00ec b\\u1ea1n \\u0111ang s\\u1eed d\\u1ee5ng"}, {"index": 187, "start": 811.44, "end": 815.92, "text": "c\\u00e1c ph\\u00e9p bi\\u1ebfn \\u0111\\u1ed5i gi\\u1ed1ng nhau v\\u00e0 sau \\u0111\\u00f3 v\\u1edbi 64 k\\u00eanh"}, {"index": 188, "start": 815.92, "end": 819.2, "text": "v\\u00ec vgg 16 l\\u00e0 m\\u1ed9t m\\u1ea1ng t\\u01b0\\u01a1ng \\u0111\\u1ed1i s\\u00e2u"}, {"index": 189, "start": 819.2, "end": 823.76, "text": "t\\u00f4i s\\u1ebd kh\\u00f4ng v\\u1ebd t\\u1ea5t c\\u1ea3 c\\u00e1c th\\u1ec3 t\\u00edch \\u1edf \\u0111\\u00e2y v\\u00ec h\\u00ecnh \\u1ea3nh nh\\u1ecf n\\u00e0y"}, {"index": 190, "start": 823.76, "end": 827.6, "text": "\\u0111\\u01b0\\u1ee3c ch\\u1ec9 \\u0111\\u1ecbnh l\\u00e0 nh\\u1eefng g\\u00ec tr\\u01b0\\u1edbc \\u0111\\u00e2y ch\\u00fang ta \\u0111\\u00e3 v\\u1ebd nh\\u01b0 th\\u1ebf n\\u00e0y"}, {"index": 191, "start": 827.6, "end": 834.32, "text": "224 x 224 x 3 v\\u00e0 sau \\u0111\\u00f3 l\\u00e0 m\\u1ed9t ph\\u00e9p t\\u00ednh t\\u00edch ch\\u1eadp d\\u1eabn \\u0111\\u1ebfn"}, {"index": 192, "start": 834.32, "end": 840.56, "text": "T\\u00f4i \\u0111o\\u00e1n l\\u00e0 224 x 224 x 64 n\\u00ean s\\u1ebd \\u0111\\u01b0\\u1ee3c v\\u1ebd nh\\u01b0 m\\u1ed9t kh\\u1ed1i s\\u00e2u h\\u01a1n"}, {"index": 193, "start": 840.56, "end": 847.28, "text": "v\\u00e0 sau \\u0111\\u00f3 l\\u00e0 m\\u1ed9t l\\u1edbp kh\\u00e1c d\\u1eabn \\u0111\\u1ebfn b\\u1ea1n bi\\u1ebft \\u0111\\u1ea5y 224 x 224 x 64"}, {"index": 194, "start": 847.28, "end": 852.0, "text": "v\\u00ec v\\u1eady c\\u00e1i conv64 nh\\u00e2n 2 n\\u00e0y \\u0111\\u1ea1i di\\u1ec7n cho vi\\u1ec7c b\\u1ea1n \\u0111ang th\\u1ef1c hi\\u1ec7n"}, {"index": 195, "start": 852.0, "end": 855.68, "text": "hai l\\u1edbp, hai l\\u1edbp t\\u00edch ch\\u1eadp v\\u1edbi 64 b\\u1ed9 l\\u1ecdc"}, {"index": 196, "start": 855.68, "end": 859.36, "text": "v\\u00e0 nh\\u01b0 t\\u00f4i \\u0111\\u00e3 \\u0111\\u1ec1 c\\u1eadp tr\\u01b0\\u1edbc \\u0111\\u00f3, c\\u00e1c b\\u1ed9 l\\u1ecdc lu\\u00f4n"}, {"index": 197, "start": 859.36, "end": 863.12, "text": "c\\u00f3 k\\u00edch th\\u01b0\\u1edbc ba tr\\u00ean ba v\\u1edbi b\\u01b0\\u1edbc nh\\u1ea3y b\\u1eb1ng m\\u1ed9t v\\u00e0 ch\\u00fang lu\\u00f4n"}, {"index": 198, "start": 863.12, "end": 866.64, "text": "c\\u00f3 nh\\u1eefng \\u0111\\u00f3ng g\\u00f3p gi\\u1ed1ng nhau, v\\u00ec v\\u1eady thay v\\u00ec v\\u1ebd t\\u1ea5t c\\u1ea3 nh\\u1eefng th\\u1ec3 t\\u00edch n\\u00e0y, t\\u00f4i ch\\u1ec9"}, {"index": 199, "start": 866.64, "end": 871.6, "text": "s\\u1eed d\\u1ee5ng v\\u0103n b\\u1ea3n \\u0111\\u1ec3 \\u0111\\u1ea1i di\\u1ec7n cho m\\u1ea1ng n\\u00e0y, ti\\u1ebfp theo, n\\u00f3 s\\u1eed d\\u1ee5ng m\\u1ed9t l\\u1edbp pooling"}, {"index": 200, "start": 871.6, "end": 875.68, "text": "v\\u00ec v\\u1eady, l\\u1edbp pooling s\\u1ebd gi\\u1ea3m v\\u00e0 h\\u00e3y ngh\\u0129 v\\u1ec1 vi\\u1ec7c n\\u00f3 \\u0111i t\\u1eeb 224 x 224"}, {"index": 201, "start": 875.68, "end": 880.88, "text": "gi\\u1ea3m xu\\u1ed1ng c\\u00e1i g\\u00ec \\u0111\\u00fang t\\u01b0\\u01a1ng \\u1ee9ng v\\u1edbi 112 tr\\u00ean 112 tr\\u00ean 64"}, {"index": 202, "start": 880.88, "end": 886.8, "text": "v\\u00e0 sau \\u0111\\u00f3 n\\u00f3 c\\u00f3 th\\u00eam m\\u1ed9t v\\u00e0i l\\u1edbp t\\u00edch ch\\u1eadp n\\u1eefa, \\u0111i\\u1ec1u n\\u00e0y c\\u00f3 ngh\\u0129a l\\u00e0 n\\u00f3 c\\u00f3 m\\u1ed9t"}, {"index": 203, "start": 886.8, "end": 890.48, "text": "128 b\\u1ed9 l\\u1ecdc v\\u00e0 v\\u00ec \\u0111\\u00e2y l\\u00e0 nh\\u1eefng ph\\u00e9p t\\u00edch ch\\u1eadp gi\\u1ed1ng nhau"}, {"index": 204, "start": 890.48, "end": 893.6, "text": "h\\u00e3y xem k\\u00edch th\\u01b0\\u1edbc m\\u1edbi s\\u1ebd l\\u00e0 g\\u00ec, \\u0111\\u00fang kh\\u00f4ng, n\\u00f3 s\\u1ebd l\\u00e0"}, {"index": 205, "start": 893.6, "end": 898.64, "text": "112 x 112 x 128 \\u00b5m v\\u00e0 sau \\u0111\\u00f3 l\\u00e0 l\\u1edbp pooling"}, {"index": 206, "start": 898.64, "end": 902.16, "text": "v\\u00ec v\\u1eady b\\u1ea1n c\\u00f3 th\\u1ec3 t\\u00ecm ra chi\\u1ec1u m\\u1edbi \\u0111\\u00fang r\\u1eb1ng n\\u00f3 s\\u1ebd l\\u00e0 nh\\u01b0 th\\u1ebf n\\u00e0o"}, {"index": 207, "start": 902.16, "end": 907.36, "text": "v\\u00e0 b\\u00e2y gi\\u1edd l\\u00e0 ba l\\u1edbp t\\u00edch ch\\u1eadp v\\u1edbi b\\u1ed9 l\\u1ecdc 256 k\\u00edch th\\u01b0\\u1edbc"}, {"index": 208, "start": 907.36, "end": 912.48, "text": "256 b\\u1ed9 l\\u1ecdc, xin l\\u1ed7i, sau \\u0111\\u00f3 l\\u00e0 m\\u1ed9t l\\u1edbp gi\\u1ea3m d\\u1ea7n v\\u00e0 sau \\u0111\\u00f3"}, {"index": 209, "start": 912.48, "end": 919.44, "text": "th\\u00eam m\\u1ed9t v\\u00e0i l\\u1edbp t\\u00edch ch\\u1eadp, l\\u1edbp gi\\u1ea3m d\\u1ea7n, \\u1eeb, th\\u00eam nhi\\u1ec1u l\\u1edbp t\\u00edch ch\\u1eadp, l\\u1edbp gi\\u1ea3m d\\u1ea7n"}, {"index": 210, "start": 919.44, "end": 924.88, "text": "v\\u00e0 sau \\u0111\\u00f3 n\\u00f3 l\\u1ea5y, uh, con s\\u1ed1 cu\\u1ed1i c\\u00f9ng l\\u00e0 b\\u1ea3y nh\\u00e2n b\\u1ea3y nh\\u00e2n n\\u0103m 12"}, {"index": 211, "start": 924.88, "end": 928.08, "text": "cung c\\u1ea5p n\\u00f3 cho m\\u1ed9t l\\u1edbp k\\u1ebft n\\u1ed1i ho\\u00e0n to\\u00e0n, ho\\u00e0n to\\u00e0n k\\u1ebft n\\u1ed1i"}, {"index": 212, "start": 928.08, "end": 934.0, "text": "v\\u1edbi 4996 \\u0111\\u01a1n v\\u1ecb v\\u00e0 sau \\u0111\\u00f3 l\\u00e0 \\u0111\\u1ea7u ra softmax, m\\u1ed9t trong m\\u1ed9t ng\\u00e0n"}, {"index": 213, "start": 934.0, "end": 939.92, "text": "c\\u00e1c l\\u1edbp, v\\u00e0 nh\\u00e2n ti\\u1ec7n, con s\\u1ed1 16 trong t\\u00ean vg16"}, {"index": 214, "start": 939.92, "end": 943.68, "text": "\\u0111\\u1ec1 c\\u1eadp \\u0111\\u1ebfn th\\u1ef1c t\\u1ebf l\\u00e0 m\\u1ea1ng n\\u00e0y c\\u00f3 16 l\\u1edbp c\\u00f3"}, {"index": 215, "start": 943.68, "end": 947.68, "text": "tr\\u1ecdng s\\u1ed1, um, v\\u00e0 \\u0111\\u00e2y l\\u00e0 m\\u1ed9t m\\u1ea1ng kh\\u00e1 l\\u1edbn, m\\u1ea1ng n\\u00e0y"}, {"index": 216, "start": 947.68, "end": 952.56, "text": "c\\u00f3 t\\u1ed5ng c\\u1ed9ng kho\\u1ea3ng 138 tri\\u1ec7u tham s\\u1ed1"}, {"index": 217, "start": 952.56, "end": 955.68, "text": "v\\u00e0 \\u0111\\u00f3 l\\u00e0 kh\\u00e1 l\\u1edbn ngay c\\u1ea3 theo ti\\u00eau chu\\u1ea9n hi\\u1ec7n \\u0111\\u1ea1i"}, {"index": 218, "start": 955.68, "end": 959.28, "text": "nh\\u01b0ng s\\u1ef1 \\u0111\\u01a1n gi\\u1ea3n c\\u1ee7a ki\\u1ebfn tr\\u00fac vg16"}, {"index": 219, "start": 959.28, "end": 963.28, "text": "khi\\u1ebfn n\\u00f3 tr\\u1edf n\\u00ean kh\\u00e1 h\\u1ea5p d\\u1eabn, b\\u1ea1n c\\u00f3 th\\u1ec3 th\\u1ea5y r\\u1eb1ng ki\\u1ebfn tr\\u00fac n\\u00e0y th\\u1ef1c s\\u1ef1 kh\\u00e1"}, {"index": 220, "start": 963.28, "end": 967.92, "text": "\\u0110\\u1ed3ng nh\\u1ea5t c\\u00f3 m\\u1ed9t v\\u00e0i l\\u1edbp t\\u00edch ch\\u1eadp \\u0111\\u01b0\\u1ee3c theo sau b\\u1edfi m\\u1ed9t l\\u1edbp l\\u1ea5y m\\u1eabu, l\\u1edbp n\\u00e0y gi\\u1ea3m"}, {"index": 221, "start": 967.92, "end": 972.16, "text": "chi\\u1ec1u cao v\\u00e0 chi\\u1ec1u r\\u1ed9ng \\u0111\\u00fang kh\\u00f4ng, v\\u00ec v\\u1eady c\\u00e1c l\\u1edbp l\\u1ea5y m\\u1eabu gi\\u1ea3m \\u0111i"}, {"index": 222, "start": 972.16, "end": 975.76, "text": "chi\\u1ec1u cao v\\u00e0 chi\\u1ec1u r\\u1ed9ng b\\u1ea1n c\\u00f3 m\\u1ed9t v\\u00e0i \\u1edf \\u0111\\u00e2y"}, {"index": 223, "start": 975.76, "end": 978.96, "text": "nh\\u01b0ng sau \\u0111\\u00f3 n\\u1ebfu b\\u1ea1n nh\\u00ecn v\\u00e0o s\\u1ed1 l\\u01b0\\u1ee3ng b\\u1ed9 l\\u1ecdc"}, {"index": 224, "start": 978.96, "end": 982.48, "text": "trong c\\u00e1c l\\u1edbp t\\u00edch ch\\u1eadp \\u1edf \\u0111\\u00e2y b\\u1ea1n c\\u00f3 64 b\\u1ed9 l\\u1ecdc"}, {"index": 225, "start": 982.48, "end": 989.36, "text": "v\\u00e0 sau \\u0111\\u00f3 b\\u1ea1n g\\u1ea5p \\u0111\\u00f4i 128 th\\u00e0nh 256, g\\u1ea5p \\u0111\\u00f4i th\\u00e0nh 512, v\\u00e0 sau \\u0111\\u00f3 t\\u00f4i \\u0111o\\u00e1n r\\u1eb1ng"}, {"index": 226, "start": 989.36, "end": 993.2, "text": "t\\u00e1c gi\\u1ea3 ngh\\u0129 r\\u1eb1ng 512 l\\u00e0 \\u0111\\u1ee7 l\\u1edbn v\\u00e0 kh\\u00f4ng g\\u1ea5p \\u0111\\u00f4i l\\u1ee3i nhu\\u1eadn \\u1edf \\u0111\\u00e2y"}, {"index": 227, "start": 993.2, "end": 996.64, "text": "nh\\u01b0ng \\u0111i\\u1ec1u n\\u00e0y, b\\u1ea1n bi\\u1ebft \\u0111\\u1ea5y, ki\\u1ec3u nh\\u01b0 l\\u00e0 g\\u1ea5p \\u0111\\u00f4i m\\u1ed9t c\\u00e1ch \\u0111\\u1ea1i kh\\u00e1i \\u1edf m\\u1ed7i b\\u01b0\\u1edbc"}, {"index": 228, "start": 996.64, "end": 1000.56, "text": "ho\\u1eb7c g\\u1ea5p \\u0111\\u00f4i qua m\\u1ed7i t\\u1ea7ng c\\u1ee7a c\\u00e1c l\\u1edbp t\\u00edch ch\\u1eadp l\\u00e0 m\\u1ed9t nguy\\u00ean t\\u1eafc"}, {"index": 229, "start": 1000.56, "end": 1005.04, "text": "\\u0111\\u01a1n gi\\u1ea3n \\u0111\\u01b0\\u1ee3c s\\u1eed d\\u1ee5ng \\u0111\\u1ec3 thi\\u1ebft k\\u1ebf ki\\u1ebfn tr\\u00fac c\\u1ee7a m\\u1ea1ng n\\u00e0y"}, {"index": 230, "start": 1005.04, "end": 1009.52, "text": "v\\u00e0 v\\u00ec v\\u1eady t\\u00f4i ngh\\u0129 r\\u1eb1ng s\\u1ef1 \\u0111\\u1ed3ng nh\\u1ea5t t\\u01b0\\u01a1ng \\u0111\\u1ed1i c\\u1ee7a ki\\u1ebfn tr\\u00fac n\\u00e0y"}, {"index": 231, "start": 1009.52, "end": 1014.16, "text": "\\u0111\\u00e3 khi\\u1ebfn n\\u00f3 tr\\u1edf n\\u00ean kh\\u00e1 h\\u1ea5p d\\u1eabn \\u0111\\u1ed1i v\\u1edbi c\\u00e1c nh\\u00e0 nghi\\u00ean c\\u1ee9u, nh\\u01b0\\u1ee3c \\u0111i\\u1ec3m ch\\u00ednh l\\u00e0"}, {"index": 232, "start": 1014.16, "end": 1017.76, "text": "n\\u00f3 l\\u00e0 m\\u1ed9t m\\u1ea1ng l\\u01b0\\u1edbi l\\u1edbn v\\u1ec1 s\\u1ed1 l\\u01b0\\u1ee3ng tham s\\u1ed1 m\\u00e0 b\\u1ea1n ph\\u1ea3i"}, {"index": 233, "start": 1017.76, "end": 1021.28, "text": "\\u0111\\u00e0o t\\u1ea1o, \\u00f4i v\\u00e0 n\\u1ebfu b\\u1ea1n \\u0111\\u1ecdc t\\u00e0i li\\u1ec7u, b\\u1ea1n"}, {"index": 234, "start": 1021.28, "end": 1024.96, "text": "\\u0111\\u00f4i khi th\\u1ea5y m\\u1ecdi ng\\u01b0\\u1eddi n\\u00f3i v\\u1ec1 vgg19, \\u0111\\u00f3 l\\u00e0 m\\u1ed9t"}, {"index": 235, "start": 1024.96, "end": 1030.8, "text": "phi\\u00ean b\\u1ea3n l\\u1edbn h\\u01a1n c\\u1ee7a m\\u1ea1ng l\\u01b0\\u1edbi n\\u00e0y v\\u00e0 b\\u1ea1n c\\u00f3 th\\u1ec3 th\\u1ea5y chi ti\\u1ebft trong"}, {"index": 236, "start": 1030.8, "end": 1034.64, "text": "b\\u00e0i b\\u00e1o \\u0111\\u01b0\\u1ee3c tr\\u00edch d\\u1eabn \\u1edf d\\u01b0\\u1edbi b\\u1edfi Karen Simerian v\\u00e0 Andrew"}, {"index": 237, "start": 1034.64, "end": 1040.8, "text": "Zisserman nh\\u01b0ng v\\u00ec vgg16 ho\\u1ea1t \\u0111\\u1ed9ng g\\u1ea7n nh\\u01b0 t\\u1ed1t nh\\u01b0 vgg19"}, {"index": 238, "start": 1040.8, "end": 1046.0, "text": "n\\u00ean nhi\\u1ec1u ng\\u01b0\\u1eddi s\\u1ebd s\\u1eed d\\u1ee5ng vgg16, nh\\u01b0ng \\u0111i\\u1ec1u t\\u00f4i th\\u00edch nh\\u1ea5t v\\u1ec1 \\u0111i\\u1ec1u n\\u00e0y l\\u00e0"}, {"index": 239, "start": 1046.0, "end": 1051.12, "text": "\\u0111i\\u1ec1u n\\u00e0y t\\u1ea1o ra m\\u00f4 h\\u00ecnh r\\u1eb1ng khi b\\u1ea1n \\u0111i s\\u00e2u h\\u01a1n, chi\\u1ec1u cao v\\u00e0 chi\\u1ec1u r\\u1ed9ng gi\\u1ea3m \\u0111i."}, {"index": 240, "start": 1051.12, "end": 1054.64, "text": "ch\\u1ec9 gi\\u1ea3m \\u0111i m\\u1ed9t n\\u1eeda m\\u1ed7i l\\u1ea7n cho c\\u00e1c l\\u1edbp g\\u1ed9p"}, {"index": 241, "start": 1054.64, "end": 1059.44, "text": "trong khi s\\u1ed1 l\\u01b0\\u1ee3ng k\\u00eanh t\\u0103ng l\\u00ean v\\u00e0 \\u1edf \\u0111\\u00e2y b\\u1ea1n bi\\u1ebft n\\u00f3 t\\u0103ng l\\u00ean kho\\u1ea3ng"}, {"index": 242, "start": 1059.44, "end": 1062.16, "text": "m\\u1ed9t y\\u1ebfu t\\u1ed1 hai m\\u1ed7i khi b\\u1ea1n c\\u00f3 m\\u1ed9t b\\u1ed9 m\\u1edbi"}, {"index": 243, "start": 1062.16, "end": 1066.56, "text": "c\\u00e1c l\\u1edbp conv, v\\u00ec v\\u1eady b\\u1eb1ng c\\u00e1ch l\\u00e0m cho t\\u1ef7 l\\u1ec7 m\\u00e0 nh\\u1eefng c\\u00e1i n\\u00e0y"}, {"index": 244, "start": 1066.56, "end": 1071.04, "text": "gi\\u1ea3m xu\\u1ed1ng v\\u00e0 c\\u00e1i \\u0111\\u00f3 t\\u0103ng l\\u00ean r\\u1ea5t c\\u00f3 h\\u1ec7 th\\u1ed1ng, t\\u00f4i ngh\\u0129 b\\u00e0i b\\u00e1o n\\u00e0y r\\u1ea5t"}, {"index": 245, "start": 1071.04, "end": 1074.64, "text": "r\\u1ea5t h\\u1ea5p d\\u1eabn t\\u1eeb g\\u00f3c \\u0111\\u1ed9 \\u0111\\u00f3"}, {"index": 246, "start": 1074.64, "end": 1078.64, "text": "v\\u1eady l\\u00e0 \\u0111\\u1ee7 cho ba ki\\u1ebfn tr\\u00fac c\\u1ed5 \\u0111i\\u1ec3n, n\\u1ebfu b\\u1ea1n mu\\u1ed1n, b\\u1ea1n n\\u00ean"}, {"index": 247, "start": 1078.64, "end": 1082.4, "text": "th\\u1ef1c s\\u1ef1 \\u0111\\u1ecdc m\\u1ed9t s\\u1ed1 b\\u00e0i b\\u00e1o n\\u00e0y, t\\u00f4i khuy\\u00ean b\\u1ea1n n\\u00ean b\\u1eaft \\u0111\\u1ea7u v\\u1edbi b\\u00e0i b\\u00e1o alex"}, {"index": 248, "start": 1082.4, "end": 1085.76, "text": "net, ti\\u1ebfp theo l\\u00e0 b\\u00e0i b\\u00e1o vgg net v\\u00e0 sau \\u0111\\u00f3 l\\u00e0"}, {"index": 249, "start": 1085.76, "end": 1088.96, "text": "b\\u00e0i b\\u00e1o net th\\u00ec h\\u01a1i kh\\u00f3 \\u0111\\u1ecdc nh\\u01b0ng \\u0111\\u00e2y l\\u00e0 m\\u1ed9t t\\u00e1c ph\\u1ea9m kinh \\u0111i\\u1ec3n t\\u1ed1t m\\u00e0 b\\u1ea1n mu\\u1ed1n"}, {"index": 250, "start": 1088.96, "end": 1092.4, "text": "nh\\u00ecn v\\u00e0o, nh\\u01b0ng ti\\u1ebfp theo h\\u00e3y \\u0111i xa h\\u01a1n nh\\u1eefng ki\\u1ebfn tr\\u00fac c\\u1ed5 \\u0111i\\u1ec3n n\\u00e0y,"}, {"index": 251, "start": 1092.4, "end": 1096.08, "text": "v\\u00e0 nh\\u00ecn v\\u00e0o m\\u1ed9t s\\u1ed1 ki\\u1ebfn tr\\u00fac m\\u1ea1ng m\\u1edbi ti\\u00ean ti\\u1ebfn h\\u01a1n, m\\u1ea1nh m\\u1ebd h\\u01a1n"}, {"index": 252, "start": 1096.08, "end": 1100.56, "text": "h\\u00e3y ti\\u1ebfp t\\u1ee5c sang video ti\\u1ebfp theo"}], "segments_by_language": {"en": [{"index": 0, "start": 0.0, "end": 4.24, "text": "In this video, you'll learn about some of the classic neural network"}, {"index": 1, "start": 4.24, "end": 8.88, "text": "architectures, starting with the net5 and then AlexNet and then the VGNet."}, {"index": 2, "start": 8.88, "end": 13.76, "text": "Let's take a look. Here's the net5 architecture. You start off with an"}, {"index": 3, "start": 13.76, "end": 20.24, "text": "image, which say 32 by 32 by 1. And the goal of the net5 was to recognize"}, {"index": 4, "start": 20.24, "end": 26.8, "text": "handwritten digits, so maybe an image of a digit like that. And the net5 was"}, {"index": 5, "start": 26.8, "end": 32.0, "text": "trained on grayscale images, which is why it's 32 by 32 by 1."}, {"index": 6, "start": 32.0, "end": 35.28, "text": "This neural network architecture is actually quite similar"}, {"index": 7, "start": 35.28, "end": 41.28, "text": "to the last example you saw last week. In the first step, you use a set of"}, {"index": 8, "start": 41.28, "end": 46.88, "text": "6 5 by 5 filters with a stride of 1. Because you use 6 filters, you end up with a"}, {"index": 9, "start": 46.88, "end": 52.72, "text": "28 by 28 by 6 over there. And with a stride of 1 and no padding,"}, {"index": 10, "start": 52.72, "end": 57.04, "text": "the image dimensions reduces from 32 by 32 down to"}, {"index": 11, "start": 57.04, "end": 62.56, "text": "28 by 28. Then the neural network applies pooling."}, {"index": 12, "start": 62.56, "end": 65.6, "text": "And back then, when this paper was written, people use"}, {"index": 13, "start": 65.6, "end": 69.44, "text": "average pooling much more. If you're building a modern variant, you"}, {"index": 14, "start": 69.44, "end": 74.64, "text": "probably use max pooling instead. But in this example, your average pool"}, {"index": 15, "start": 74.64, "end": 78.64, "text": "and with a filter width of 2 and a stride of 2, you wind up"}, {"index": 16, "start": 78.64, "end": 82.64, "text": "reducing the dimensions, the height and width by a factor of 2."}, {"index": 17, "start": 82.64, "end": 90.08, "text": "So you now end up with a 14 by 14 by 6 volume. I guess the height and width of"}, {"index": 18, "start": 90.08, "end": 93.44, "text": "these volumes aren't entirely drawn to scale. Technically,"}, {"index": 19, "start": 93.44, "end": 96.64, "text": "if I were drawing these volumes to scale, the height and width would be shrunk"}, {"index": 20, "start": 96.64, "end": 101.2, "text": "by a factor of 2. Next, you apply another convolutional layer."}, {"index": 21, "start": 101.2, "end": 104.96, "text": "This time, you use a set of 16 filters, the 5 by 5."}, {"index": 22, "start": 104.96, "end": 108.88, "text": "So you end up with 16 channels to the next volume."}, {"index": 23, "start": 108.88, "end": 114.8, "text": "And back when this paper was written in 1998, people didn't really use padding or"}, {"index": 24, "start": 114.8, "end": 118.64, "text": "you're always using valid convolutions, which is why every time you apply a"}, {"index": 25, "start": 118.64, "end": 121.92, "text": "convolutional layer, the height and width shrinks."}, {"index": 26, "start": 121.92, "end": 126.64, "text": "So that's why here you go from 14 by 14 down to 10 by 10."}, {"index": 27, "start": 126.64, "end": 130.08, "text": "Then another pooling layer, so the reduces the height and width by a"}, {"index": 28, "start": 130.08, "end": 133.84, "text": "factor of 2 and you end up with 5 by 5 over here."}, {"index": 29, "start": 133.84, "end": 137.76, "text": "And if you multiply out these numbers, 5 by 5 by 16, this"}, {"index": 30, "start": 137.76, "end": 144.0, "text": "multiplies out to 400. That's 25 times 16 is 400."}, {"index": 31, "start": 144.0, "end": 147.92, "text": "And the next layer is then a fully connected layer"}, {"index": 32, "start": 147.92, "end": 154.16, "text": "that fully connects each of these 400 nodes with"}, {"index": 33, "start": 154.16, "end": 158.56, "text": "every one of 120 neurons. So there's a fully connected layer."}, {"index": 34, "start": 158.56, "end": 162.08, "text": "And sometimes that would draw out explicitly"}, {"index": 35, "start": 162.08, "end": 165.92, "text": "a layer with 400 nodes from skipping that here."}, {"index": 36, "start": 165.92, "end": 169.6, "text": "So there's a fully connected layer and then another fully connected layer."}, {"index": 37, "start": 169.6, "end": 174.0, "text": "And then the final step is it uses these essentially 84 features"}, {"index": 38, "start": 174.0, "end": 179.2, "text": "and uses it with one final output. I guess you could draw one more node here"}, {"index": 39, "start": 179.2, "end": 182.96, "text": "to make a prediction for y hat. And y hat took on"}, {"index": 40, "start": 182.96, "end": 187.28, "text": "10 possible values corresponding to recognizing each of the digits"}, {"index": 41, "start": 187.28, "end": 191.52, "text": "from 0 to 9. A modern version of this neural network"}, {"index": 42, "start": 191.52, "end": 197.28, "text": "would use a softmax layer with a 10-way classification output."}, {"index": 43, "start": 197.28, "end": 201.44, "text": "Although back then the Net5 actually used a different"}, {"index": 44, "start": 201.44, "end": 205.44, "text": "classifier at the output layer, one that's useless today."}, {"index": 45, "start": 205.44, "end": 209.12, "text": "So this neural network was small by modern standards."}, {"index": 46, "start": 209.12, "end": 214.0, "text": "It had about 60,000 parameters. And today you"}, {"index": 47, "start": 214.08, "end": 218.8, "text": "often see neural networks with anywhere from 10 million to 100 million"}, {"index": 48, "start": 218.8, "end": 221.76, "text": "parameters. And it's not unusual to see networks there."}, {"index": 49, "start": 221.76, "end": 225.28, "text": "They're literally about a thousand times bigger than this network."}, {"index": 50, "start": 225.28, "end": 230.08, "text": "But one thing you do see is that as you go deeper in the network, so as you go"}, {"index": 51, "start": 230.08, "end": 234.32, "text": "from left to right the height and width"}, {"index": 52, "start": 234.32, "end": 237.6, "text": "tend to go down. So you went from 30 by 32 to 28 to"}, {"index": 53, "start": 237.6, "end": 242.08, "text": "14 to 10 to 5. Whereas the number of channels"}, {"index": 54, "start": 242.08, "end": 249.12, "text": "tends to increase. It goes from 1 to 6 to 16 as you go"}, {"index": 55, "start": 249.12, "end": 252.88, "text": "deeper into the layers of the network. One other pattern you see in this"}, {"index": 56, "start": 252.88, "end": 255.84, "text": "neural network that's still often repeated today is that"}, {"index": 57, "start": 255.84, "end": 260.56, "text": "you might have some one or more conf layers followed by a pulling layer"}, {"index": 58, "start": 260.56, "end": 264.0, "text": "and then one or sometimes more than one conf layer"}, {"index": 59, "start": 264.0, "end": 267.76, "text": "followed by a pulling layer and then some fully connected layers"}, {"index": 60, "start": 267.76, "end": 274.0, "text": "and then the output. So this type of arrangement of layers is quite common."}, {"index": 61, "start": 274.0, "end": 278.0, "text": "Now finally this is maybe only for those of you that want to try reading the"}, {"index": 62, "start": 278.0, "end": 280.96, "text": "paper. There are a couple other things that were"}, {"index": 63, "start": 280.96, "end": 284.8, "text": "different. The rest of this slide I'm going to"}, {"index": 64, "start": 284.8, "end": 289.36, "text": "make a few more advanced comments only for those of you that want to try to"}, {"index": 65, "start": 289.36, "end": 294.8, "text": "read this classic paper. And so everything I'm going to write in red"}, {"index": 66, "start": 294.8, "end": 299.76, "text": "you can safely skip on this slide. And this may be an interesting historical"}, {"index": 67, "start": 299.76, "end": 304.32, "text": "footnote that is okay if you don't follow fully."}, {"index": 68, "start": 304.32, "end": 307.36, "text": "So it turns out that if you read the original paper"}, {"index": 69, "start": 307.36, "end": 311.04, "text": "back then people use sigmoid and tannage"}, {"index": 70, "start": 311.04, "end": 314.32, "text": "nonlinearities and people weren't using"}, {"index": 71, "start": 314.32, "end": 317.68, "text": "ReLU nonlinearities back then. So if you look at the paper you see"}, {"index": 72, "start": 317.68, "end": 323.2, "text": "sigmoid and tannage referred to. And there are also some funny ways about"}, {"index": 73, "start": 323.2, "end": 326.8, "text": "this network was wired. At least funny by modern standards."}, {"index": 74, "start": 326.8, "end": 332.96, "text": "So for example you've seen how if you have a nh by nw by nc"}, {"index": 75, "start": 332.96, "end": 339.28, "text": "network with nc channels then you use f by f by the same nc"}, {"index": 76, "start": 339.28, "end": 343.52, "text": "dimensional filter where every filter looks at every one of these"}, {"index": 77, "start": 343.52, "end": 347.12, "text": "channels. But back then computers were much slower"}, {"index": 78, "start": 347.12, "end": 350.48, "text": "and so to save on computation as well as on parameters"}, {"index": 79, "start": 350.64, "end": 353.76, "text": "the original Lynette 5 had some crazy complicated way"}, {"index": 80, "start": 353.76, "end": 358.08, "text": "where different filters look at different channels of the input block."}, {"index": 81, "start": 358.08, "end": 361.92, "text": "And so the paper talks about those details but the more modern implementation"}, {"index": 82, "start": 361.92, "end": 366.96, "text": "you know wouldn't have that type of complexity these days."}, {"index": 83, "start": 366.96, "end": 371.76, "text": "And then one last thing that was done back then I guess but isn't really"}, {"index": 84, "start": 371.76, "end": 375.12, "text": "done right now is that the original Lynette 5"}, {"index": 85, "start": 375.12, "end": 379.52, "text": "had a nonlinearity after pooling."}, {"index": 86, "start": 379.68, "end": 383.04, "text": "And I think it actually used a sigmoid nonlinearity"}, {"index": 87, "start": 383.04, "end": 387.12, "text": "after the pooling layer. So if you do read this paper"}, {"index": 88, "start": 387.12, "end": 390.56, "text": "and this is one of the harder ones to read so the ones will go over in the"}, {"index": 89, "start": 390.56, "end": 393.76, "text": "next few videos. The next one might be an easier one to"}, {"index": 90, "start": 393.76, "end": 396.08, "text": "start with. Most of the ideas on this slide are"}, {"index": 91, "start": 396.08, "end": 400.0, "text": "described in sections 2 and 3 of the paper."}, {"index": 92, "start": 400.0, "end": 404.56, "text": "And later sections of the paper talk about some other ideas."}, {"index": 93, "start": 404.56, "end": 408.24, "text": "It talked about something called the draft transformer network which isn't"}, {"index": 94, "start": 408.24, "end": 410.96, "text": "widely used today. So if you do try to read this paper"}, {"index": 95, "start": 410.96, "end": 414.8, "text": "I'd recommend focusing on really on section 2 which talks about this"}, {"index": 96, "start": 414.8, "end": 418.24, "text": "architecture and maybe take a quick look at section 3"}, {"index": 97, "start": 418.24, "end": 421.6, "text": "which has a bunch of experimental results which are pretty interesting."}, {"index": 98, "start": 421.6, "end": 425.2, "text": "The second example of a neural network I want to show you is"}, {"index": 99, "start": 425.2, "end": 429.52, "text": "Alex Nett named after Alex Trzejevsky who was the first author"}, {"index": 100, "start": 429.52, "end": 433.6, "text": "of the paper describing this work. The other authors were"}, {"index": 101, "start": 433.68, "end": 436.8, "text": "Saskever and Jeffrey Hinton. So Alex Nett"}, {"index": 102, "start": 436.8, "end": 442.48, "text": "input starts with 227 by 227 by 3 images. Oh and if you read the paper"}, {"index": 103, "start": 442.48, "end": 448.0, "text": "the paper refers to 224 by 224 by 3 images but if you look at the numbers"}, {"index": 104, "start": 448.0, "end": 453.12, "text": "I think the numbers make sense only of actually 227 by 227."}, {"index": 105, "start": 453.12, "end": 457.52, "text": "And then the first layer applies a set of 96"}, {"index": 106, "start": 457.52, "end": 462.64, "text": "11 by 11 filters with a stride of 4 and because it uses a large stride of 4"}, {"index": 107, "start": 462.64, "end": 466.8, "text": "the dimension shrinks to 55 by 55 so roughly"}, {"index": 108, "start": 466.8, "end": 471.36, "text": "going down by a factor of 4 because of the large stride"}, {"index": 109, "start": 471.36, "end": 478.0, "text": "and then applies max pooling with a 3 by 3 filter so f equals 3 and a stride of 2"}, {"index": 110, "start": 478.0, "end": 485.12, "text": "so this reduces the volume to 27 by 27 by 96"}, {"index": 111, "start": 485.12, "end": 489.68, "text": "and then it performs a 5 by 5 same convolution so we're padding"}, {"index": 112, "start": 489.76, "end": 496.72, "text": "so you end up with 27 by 27 by 276. Max pooling again this then"}, {"index": 113, "start": 496.72, "end": 501.12, "text": "reduces the heighten width to 13 and then another"}, {"index": 114, "start": 501.12, "end": 506.88, "text": "same convolution so same padding so it's 13 by 13 by now"}, {"index": 115, "start": 506.88, "end": 514.08, "text": "384 filters and then 3 by 3 same convolution again"}, {"index": 116, "start": 514.08, "end": 519.6, "text": "gives you that then 3 by 3 same convolution gives you that"}, {"index": 117, "start": 519.76, "end": 526.48, "text": "then max pool brings it down to 6 by 6 by 256 if you multiply out these"}, {"index": 118, "start": 526.48, "end": 532.4, "text": "numbers 6 times 6 times 256 that's 9216 so we're"}, {"index": 119, "start": 532.4, "end": 537.52, "text": "going to unroll this into 9216 nodes and then"}, {"index": 120, "start": 537.52, "end": 541.68, "text": "finally it has a few fully connected layers and then"}, {"index": 121, "start": 541.68, "end": 545.92, "text": "finally uses a softmax to output which one of"}, {"index": 122, "start": 546.0, "end": 552.72, "text": "1000 crosses the object could be so this neural network actually had a lot"}, {"index": 123, "start": 552.72, "end": 558.48, "text": "of similarities to the net but it was much"}, {"index": 124, "start": 558.48, "end": 563.36, "text": "bigger so whereas the net or the net 5 from"}, {"index": 125, "start": 563.36, "end": 566.8, "text": "the previous slide had 60 000 about 60 000"}, {"index": 126, "start": 566.8, "end": 570.4, "text": "parameters this alex net had about 60 million"}, {"index": 127, "start": 570.4, "end": 574.32, "text": "parameters and the fact that it could take you know"}, {"index": 128, "start": 574.32, "end": 578.64, "text": "pretty similar basic building blocks but have a lot more hidden units and"}, {"index": 129, "start": 578.64, "end": 582.48, "text": "train it on a lot more data so you train on the image net data set"}, {"index": 130, "start": 582.48, "end": 586.24, "text": "that allowed it to have just remarkable performance"}, {"index": 131, "start": 586.24, "end": 590.72, "text": "another aspect of this architecture that made it much better than the net"}, {"index": 132, "start": 590.72, "end": 594.48, "text": "was using the revenue activation function and then again"}, {"index": 133, "start": 594.48, "end": 598.56, "text": "just if you read the bay paper some more advanced details that you don't"}, {"index": 134, "start": 598.56, "end": 600.96, "text": "really need to worry about if you don't read the paper"}, {"index": 135, "start": 600.96, "end": 604.8, "text": "one is that when this paper was written GPUs were still"}, {"index": 136, "start": 604.8, "end": 608.48, "text": "a little bit slower so it had a complicated way"}, {"index": 137, "start": 608.48, "end": 614.88, "text": "of training on two GPUs and the basic idea was that a lot of these layers"}, {"index": 138, "start": 614.88, "end": 618.8, "text": "was actually split across two different GPUs and there was a"}, {"index": 139, "start": 618.8, "end": 623.44, "text": "thoughtful way for when the two GPUs would communicate with each other"}, {"index": 140, "start": 623.44, "end": 627.44, "text": "and the paper also the original alex net architecture"}, {"index": 141, "start": 627.44, "end": 633.92, "text": "also had another type of layer called a local response normalization"}, {"index": 142, "start": 633.92, "end": 638.8, "text": "and this type of layer isn't really used much which is why I didn't talk about it"}, {"index": 143, "start": 638.8, "end": 643.04, "text": "but the basic idea of local response normalization is if you"}, {"index": 144, "start": 643.04, "end": 646.88, "text": "look at one of these blocks one of these volumes that we have on top"}, {"index": 145, "start": 646.88, "end": 650.88, "text": "let's say for the sake of argument this one you know 13 by 13"}, {"index": 146, "start": 650.88, "end": 654.48, "text": "by 256 what local response normalization"}, {"index": 147, "start": 654.64, "end": 659.6, "text": "our end does is you look at one position so one position to heighten with"}, {"index": 148, "start": 659.6, "end": 664.56, "text": "and look down this across all the channels look at all 256"}, {"index": 149, "start": 664.56, "end": 668.64, "text": "numbers and normalize them and the motivation for this"}, {"index": 150, "start": 668.64, "end": 671.92, "text": "local response normalization was that for each position"}, {"index": 151, "start": 671.92, "end": 676.56, "text": "in this 13 by 13 image maybe you don't want"}, {"index": 152, "start": 676.56, "end": 680.08, "text": "too many neurons with a very high activation"}, {"index": 153, "start": 680.08, "end": 684.56, "text": "but subsequently many researchers have found that this doesn't help that much"}, {"index": 154, "start": 684.56, "end": 688.96, "text": "so this is one of those ideas that I'm drawing and read because"}, {"index": 155, "start": 688.96, "end": 691.76, "text": "it's less important for you to understand this one"}, {"index": 156, "start": 691.76, "end": 695.92, "text": "and in practice I don't really use local response normalizations"}, {"index": 157, "start": 695.92, "end": 699.12, "text": "you know really in the networks that I would train today so if you're"}, {"index": 158, "start": 699.12, "end": 702.24, "text": "interested in the history of deep learning I think"}, {"index": 159, "start": 702.24, "end": 706.08, "text": "even before alex net deep learning was starting to gain traction"}, {"index": 160, "start": 706.08, "end": 708.88, "text": "in speech recognition in a few other areas"}, {"index": 161, "start": 708.88, "end": 713.6, "text": "but it was really this paper that convinced a lot of the computer vision"}, {"index": 162, "start": 713.6, "end": 717.6, "text": "community to take a serious look at deep learning to convince them that"}, {"index": 163, "start": 717.6, "end": 720.0, "text": "deep learning really works in computer vision"}, {"index": 164, "start": 720.0, "end": 723.84, "text": "and then they grew on to have a huge impact not just in computer vision but"}, {"index": 165, "start": 723.84, "end": 727.52, "text": "beyond computer vision as well and if you want to try reading some of"}, {"index": 166, "start": 727.52, "end": 731.68, "text": "these papers yourself and you really don't have to for this course"}, {"index": 167, "start": 731.68, "end": 735.6, "text": "but if you want to try reading some of these papers this one is one of the"}, {"index": 168, "start": 735.68, "end": 739.36, "text": "easier ones to read so this might be a good one to take a look at"}, {"index": 169, "start": 739.36, "end": 743.28, "text": "so whereas alex net had a relatively complicated architecture"}, {"index": 170, "start": 743.28, "end": 746.16, "text": "there's just a lot of hyper parameters right where"}, {"index": 171, "start": 746.16, "end": 752.0, "text": "you know you have all these numbers that alex trusevsky and his co-authors had"}, {"index": 172, "start": 752.0, "end": 755.2, "text": "to come up with let me show you a third and final"}, {"index": 173, "start": 755.2, "end": 758.88, "text": "example in this video called the vgg or the vgg 16"}, {"index": 174, "start": 758.88, "end": 763.52, "text": "network and a remarkable thing about the vgg 16"}, {"index": 175, "start": 763.52, "end": 767.36, "text": "is that they said instead of having so many hyper parameters let's"}, {"index": 176, "start": 767.36, "end": 771.84, "text": "use a much simpler network where you focus on just having conf"}, {"index": 177, "start": 771.84, "end": 774.96, "text": "layers that are just b by three filters with a"}, {"index": 178, "start": 774.96, "end": 778.96, "text": "stride of one and always use a same padding"}, {"index": 179, "start": 778.96, "end": 782.24, "text": "and make all your max pooling layers two by two"}, {"index": 180, "start": 782.24, "end": 786.8, "text": "with a stride of two and so one very nice thing about the"}, {"index": 181, "start": 786.8, "end": 790.72, "text": "vgg network was it really simplified these neural network"}, {"index": 182, "start": 790.72, "end": 794.4, "text": "architectures so let's go through the architecture"}, {"index": 183, "start": 794.4, "end": 797.84, "text": "so you start up with an image and then the first two layers"}, {"index": 184, "start": 797.84, "end": 804.48, "text": "are convolutions which are therefore these three by three filters"}, {"index": 185, "start": 804.48, "end": 808.32, "text": "and then the first layers first two layers you use 64 filters so you end up"}, {"index": 186, "start": 808.32, "end": 811.44, "text": "with a 224 by 224 because you're using"}, {"index": 187, "start": 811.44, "end": 815.92, "text": "same convolutions and then with 64 channels"}, {"index": 188, "start": 815.92, "end": 819.2, "text": "so because vgg 16 is a relatively deep network"}, {"index": 189, "start": 819.2, "end": 823.76, "text": "I'm going to not draw all the volumes here so what this little picture"}, {"index": 190, "start": 823.76, "end": 827.6, "text": "denotes is what we would previously have drawn as this"}, {"index": 191, "start": 827.6, "end": 834.32, "text": "224 by 224 by 3 and then a convolution that results in"}, {"index": 192, "start": 834.32, "end": 840.56, "text": "I guess a 224 by 224 by 64 so be drawn as a deeper volume"}, {"index": 193, "start": 840.56, "end": 847.28, "text": "and then another layer that results in you know 224 by 224 by 64"}, {"index": 194, "start": 847.28, "end": 852.0, "text": "so this conv64 times 2 represents that you're doing"}, {"index": 195, "start": 852.0, "end": 855.68, "text": "two layers two conv layers with 64 filters"}, {"index": 196, "start": 855.68, "end": 859.36, "text": "and as I mentioned earlier the filters are always"}, {"index": 197, "start": 859.36, "end": 863.12, "text": "three by three with stride of one and they're always"}, {"index": 198, "start": 863.12, "end": 866.64, "text": "same contributions so rather than drawing all these volumes I'm just going to"}, {"index": 199, "start": 866.64, "end": 871.6, "text": "use text to represent this network next uh then uses a pooling layer"}, {"index": 200, "start": 871.6, "end": 875.68, "text": "so the pooling layer will reduce and think about it goes from 224 by 224"}, {"index": 201, "start": 875.68, "end": 880.88, "text": "down to what right goes to 112 by 112 by 64"}, {"index": 202, "start": 880.88, "end": 886.8, "text": "and then it has a couple more conv layers so this means it has a"}, {"index": 203, "start": 886.8, "end": 890.48, "text": "128 filters and because these are same convolutions"}, {"index": 204, "start": 890.48, "end": 893.6, "text": "let's see what's the new dimension right it'll be"}, {"index": 205, "start": 893.6, "end": 898.64, "text": "112 by 112 by 128 um and then pooling layer"}, {"index": 206, "start": 898.64, "end": 902.16, "text": "so you can figure out what's the new dimension right it'll be that"}, {"index": 207, "start": 902.16, "end": 907.36, "text": "and now three conv layers with 256 dimensional filters"}, {"index": 208, "start": 907.36, "end": 912.48, "text": "256 filters sorry then a pooling layer and then"}, {"index": 209, "start": 912.48, "end": 919.44, "text": "a few more conv layers pooling layer um more conv layers pooling layer"}, {"index": 210, "start": 919.44, "end": 924.88, "text": "and then it takes uh this final seven by seven by five 12"}, {"index": 211, "start": 924.88, "end": 928.08, "text": "feeds it to a fully connected layer fully connected"}, {"index": 212, "start": 928.08, "end": 934.0, "text": "with 4996 units and then a softmax output one of a thousand"}, {"index": 213, "start": 934.0, "end": 939.92, "text": "classes and the um by the way the 16 in the name vg16"}, {"index": 214, "start": 939.92, "end": 943.68, "text": "refers to the fact that this has 16 layers that have"}, {"index": 215, "start": 943.68, "end": 947.68, "text": "weights um and this is a pretty large network this"}, {"index": 216, "start": 947.68, "end": 952.56, "text": "network has a total of about 138 million parameters"}, {"index": 217, "start": 952.56, "end": 955.68, "text": "and that's pretty large even by modern standards"}, {"index": 218, "start": 955.68, "end": 959.28, "text": "but the simplicity of the vg16 architecture"}, {"index": 219, "start": 959.28, "end": 963.28, "text": "made it quite appealing you can tell this architecture is really quite"}, {"index": 220, "start": 963.28, "end": 967.92, "text": "uniform there's a few conv layers followed by a pooling layer which reduces"}, {"index": 221, "start": 967.92, "end": 972.16, "text": "the height and width right so the pooling layers reduce the"}, {"index": 222, "start": 972.16, "end": 975.76, "text": "height and width you have a few of them here"}, {"index": 223, "start": 975.76, "end": 978.96, "text": "but then also if you look at the number of filters"}, {"index": 224, "start": 978.96, "end": 982.48, "text": "in the conv layers here you have 64 filters"}, {"index": 225, "start": 982.48, "end": 989.36, "text": "and then you double the 128 double to 256 double to 512 and then I guess the"}, {"index": 226, "start": 989.36, "end": 993.2, "text": "author thought 512 was big enough and didn't double the gain here"}, {"index": 227, "start": 993.2, "end": 996.64, "text": "but this you know sort of roughly doubling on every step"}, {"index": 228, "start": 996.64, "end": 1000.56, "text": "or doubling through every stack of conv layers was another"}, {"index": 229, "start": 1000.56, "end": 1005.04, "text": "simple principle used to design the architecture of this network"}, {"index": 230, "start": 1005.04, "end": 1009.52, "text": "and so I think the relative uniformity of this architecture"}, {"index": 231, "start": 1009.52, "end": 1014.16, "text": "made it quite attractive to researchers the main downside was that"}, {"index": 232, "start": 1014.16, "end": 1017.76, "text": "it was a pretty large network in terms of the number of parameters you had to"}, {"index": 233, "start": 1017.76, "end": 1021.28, "text": "train oh and if you read the literature you"}, {"index": 234, "start": 1021.28, "end": 1024.96, "text": "sometimes see people talk about vgg19 that's an"}, {"index": 235, "start": 1024.96, "end": 1030.8, "text": "even bigger version of this network and you could see the details in the"}, {"index": 236, "start": 1030.8, "end": 1034.64, "text": "paper cited at the bottom by Karen Simerian and Andrew"}, {"index": 237, "start": 1034.64, "end": 1040.8, "text": "Zisserman but because vgg16 does almost as well as vgg19"}, {"index": 238, "start": 1040.8, "end": 1046.0, "text": "a lot of people will use vgg16 but the thing I liked most about this was that"}, {"index": 239, "start": 1046.0, "end": 1051.12, "text": "this made this pattern of how as you go deeper height and width goes down it"}, {"index": 240, "start": 1051.12, "end": 1054.64, "text": "just goes down by a factor of two each time for the pooling layers"}, {"index": 241, "start": 1054.64, "end": 1059.44, "text": "whereas the number of channels increases and here it you know roughly goes up by"}, {"index": 242, "start": 1059.44, "end": 1062.16, "text": "a factor of two every time you have a new set of"}, {"index": 243, "start": 1062.16, "end": 1066.56, "text": "conv layers so by making the rate at which these"}, {"index": 244, "start": 1066.56, "end": 1071.04, "text": "goes down and that goes up very systematic I thought this paper was"}, {"index": 245, "start": 1071.04, "end": 1074.64, "text": "very very attractive from that perspective"}, {"index": 246, "start": 1074.64, "end": 1078.64, "text": "so that's it for the three classic architectures if you want you should"}, {"index": 247, "start": 1078.64, "end": 1082.4, "text": "really now read some of these papers I recommend starting with the alex"}, {"index": 248, "start": 1082.4, "end": 1085.76, "text": "net paper followed by the vgg net paper and then the"}, {"index": 249, "start": 1085.76, "end": 1088.96, "text": "the net paper is a bit harder to read but it is a good classic you want to"}, {"index": 250, "start": 1088.96, "end": 1092.4, "text": "look at that but next let's go beyond these classic"}, {"index": 251, "start": 1092.4, "end": 1096.08, "text": "networks and look at some even more advanced even more powerful new"}, {"index": 252, "start": 1096.08, "end": 1100.56, "text": "network architectures let's go on to the next video"}], "vi": [{"index": 0, "start": 0.0, "end": 4.24, "text": "Trong video n\\u00e0y, b\\u1ea1n s\\u1ebd t\\u00ecm hi\\u1ec3u v\\u1ec1 m\\u1ed9t s\\u1ed1 ki\\u1ebfn tr\\u00fac m\\u1ea1ng n\\u01a1-ron c\\u1ed5 \\u0111i\\u1ec3n"}, {"index": 1, "start": 4.24, "end": 8.88, "text": "b\\u1eaft \\u0111\\u1ea7u v\\u1edbi net5 v\\u00e0 sau \\u0111\\u00f3 l\\u00e0 AlexNet v\\u00e0 VGNet."}, {"index": 2, "start": 8.88, "end": 13.76, "text": "H\\u00e3y c\\u00f9ng xem x\\u00e9t. \\u0110\\u00e2y l\\u00e0 ki\\u1ebfn tr\\u00fac c\\u1ee7a net5. B\\u1ea1n b\\u1eaft \\u0111\\u1ea7u v\\u1edbi m\\u1ed9t"}, {"index": 3, "start": 13.76, "end": 20.24, "text": "h\\u00ecnh \\u1ea3nh, c\\u00f3 k\\u00edch th\\u01b0\\u1edbc 32 x 32 x 1. V\\u00e0 m\\u1ee5c ti\\u00eau c\\u1ee7a net5 l\\u00e0 nh\\u1eadn di\\u1ec7n"}, {"index": 4, "start": 20.24, "end": 26.8, "text": "c\\u00e1c ch\\u1eef s\\u1ed1 vi\\u1ebft tay, c\\u00f3 th\\u1ec3 l\\u00e0 m\\u1ed9t h\\u00ecnh \\u1ea3nh c\\u1ee7a m\\u1ed9t ch\\u1eef s\\u1ed1 nh\\u01b0 v\\u1eady. V\\u00e0 net5 \\u0111\\u01b0\\u1ee3c"}, {"index": 5, "start": 26.8, "end": 32.0, "text": "hu\\u1ea5n luy\\u1ec7n tr\\u00ean c\\u00e1c h\\u00ecnh \\u1ea3nh \\u0111en tr\\u1eafng, \\u0111\\u00f3 l\\u00e0 l\\u00fd do t\\u1ea1i sao k\\u00edch th\\u01b0\\u1edbc l\\u00e0 32 x 32 x 1."}, {"index": 6, "start": 32.0, "end": 35.28, "text": "Ki\\u1ebfn tr\\u00fac m\\u1ea1ng n\\u01a1-ron n\\u00e0y th\\u1ef1c t\\u1ebf kh\\u00e1 gi\\u1ed1ng v\\u1edbi"}, {"index": 7, "start": 35.28, "end": 41.28, "text": "v\\u00ed d\\u1ee5 cu\\u1ed1i c\\u00f9ng m\\u00e0 b\\u1ea1n \\u0111\\u00e3 th\\u1ea5y tu\\u1ea7n tr\\u01b0\\u1edbc. \\u1ede b\\u01b0\\u1edbc \\u0111\\u1ea7u ti\\u00ean, b\\u1ea1n s\\u1eed d\\u1ee5ng m\\u1ed9t t\\u1eadp h\\u1ee3p"}, {"index": 8, "start": 41.28, "end": 46.88, "text": "6 b\\u1ed9 l\\u1ecdc 5 x 5 v\\u1edbi b\\u01b0\\u1edbc nh\\u1ea3y l\\u00e0 1. V\\u00ec b\\u1ea1n s\\u1eed d\\u1ee5ng 6 b\\u1ed9 l\\u1ecdc, b\\u1ea1n s\\u1ebd c\\u00f3"}, {"index": 9, "start": 46.88, "end": 52.72, "text": "k\\u00edch th\\u01b0\\u1edbc 28 x 28 x 6 \\u1edf \\u0111\\u00f3. V\\u00e0 v\\u1edbi b\\u01b0\\u1edbc nh\\u1ea3y l\\u00e0 1 v\\u00e0 kh\\u00f4ng c\\u00f3 padding,"}, {"index": 10, "start": 52.72, "end": 57.04, "text": "k\\u00edch th\\u01b0\\u1edbc h\\u00ecnh \\u1ea3nh gi\\u1ea3m t\\u1eeb 32 x 32 xu\\u1ed1ng"}, {"index": 11, "start": 57.04, "end": 62.56, "text": "28 x 28. Sau \\u0111\\u00f3, m\\u1ea1ng n\\u01a1-ron th\\u1ef1c hi\\u1ec7n vi\\u1ec7c l\\u1ea5y m\\u1eabu."}, {"index": 12, "start": 62.56, "end": 65.6, "text": "V\\u00e0 l\\u00fac \\u0111\\u00f3, khi b\\u00e0i b\\u00e1o n\\u00e0y \\u0111\\u01b0\\u1ee3c vi\\u1ebft, m\\u1ecdi ng\\u01b0\\u1eddi th\\u01b0\\u1eddng s\\u1eed d\\u1ee5ng"}, {"index": 13, "start": 65.6, "end": 69.44, "text": "l\\u1ea5y m\\u1eabu trung b\\u00ecnh nhi\\u1ec1u h\\u01a1n. N\\u1ebfu b\\u1ea1n x\\u00e2y d\\u1ef1ng m\\u1ed9t bi\\u1ebfn th\\u1ec3 hi\\u1ec7n \\u0111\\u1ea1i, b\\u1ea1n"}, {"index": 14, "start": 69.44, "end": 74.64, "text": "c\\u00f3 l\\u1ebd s\\u1ebd s\\u1eed d\\u1ee5ng l\\u1ea5y m\\u1eabu t\\u1ed1i \\u0111a thay th\\u1ebf. Nh\\u01b0ng trong v\\u00ed d\\u1ee5 n\\u00e0y, l\\u1ea5y m\\u1eabu trung b\\u00ecnh c\\u1ee7a b\\u1ea1n"}, {"index": 15, "start": 74.64, "end": 78.64, "text": "v\\u1edbi chi\\u1ec1u r\\u1ed9ng b\\u1ed9 l\\u1ecdc l\\u00e0 2 v\\u00e0 b\\u01b0\\u1edbc nh\\u1ea3y l\\u00e0 2, b\\u1ea1n s\\u1ebd c\\u00f3"}, {"index": 16, "start": 78.64, "end": 82.64, "text": "k\\u00edch th\\u01b0\\u1edbc gi\\u1ea3m, chi\\u1ec1u cao v\\u00e0 chi\\u1ec1u r\\u1ed9ng gi\\u1ea3m xu\\u1ed1ng c\\u00f2n m\\u1ed9t n\\u1eeda."}, {"index": 17, "start": 82.64, "end": 90.08, "text": "V\\u00ec v\\u1eady, b\\u00e2y gi\\u1edd b\\u1ea1n s\\u1ebd c\\u00f3 m\\u1ed9t kh\\u1ed1i 14 x 14 x 6. T\\u00f4i \\u0111o\\u00e1n r\\u1eb1ng chi\\u1ec1u cao v\\u00e0 chi\\u1ec1u r\\u1ed9ng c\\u1ee7a"}, {"index": 18, "start": 90.08, "end": 93.44, "text": "c\\u00e1c kh\\u1ed1i n\\u00e0y kh\\u00f4ng ho\\u00e0n to\\u00e0n \\u0111\\u01b0\\u1ee3c v\\u1ebd theo t\\u1ef7 l\\u1ec7. V\\u1ec1 l\\u00fd thuy\\u1ebft,"}, {"index": 19, "start": 93.44, "end": 96.64, "text": "n\\u1ebfu t\\u00f4i v\\u1ebd nh\\u1eefng kh\\u1ed1i n\\u00e0y theo t\\u1ef7 l\\u1ec7, chi\\u1ec1u cao v\\u00e0 chi\\u1ec1u r\\u1ed9ng s\\u1ebd b\\u1ecb thu nh\\u1ecf"}, {"index": 20, "start": 96.64, "end": 101.2, "text": "b\\u1eb1ng m\\u1ed9t h\\u1ec7 s\\u1ed1 2. Ti\\u1ebfp theo, b\\u1ea1n \\u00e1p d\\u1ee5ng m\\u1ed9t l\\u1edbp convolutional kh\\u00e1c."}, {"index": 21, "start": 101.2, "end": 104.96, "text": "L\\u1ea7n n\\u00e0y, b\\u1ea1n s\\u1eed d\\u1ee5ng m\\u1ed9t t\\u1eadp h\\u1ee3p 16 b\\u1ed9 l\\u1ecdc, k\\u00edch th\\u01b0\\u1edbc 5 x 5."}, {"index": 22, "start": 104.96, "end": 108.88, "text": "V\\u00ec v\\u1eady, b\\u1ea1n s\\u1ebd c\\u00f3 16 k\\u00eanh cho kh\\u1ed1i l\\u01b0\\u1ee3ng ti\\u1ebfp theo."}, {"index": 23, "start": 108.88, "end": 114.8, "text": "V\\u00e0 khi b\\u00e0i b\\u00e1o n\\u00e0y \\u0111\\u01b0\\u1ee3c vi\\u1ebft v\\u00e0o n\\u0103m 1998, m\\u1ecdi ng\\u01b0\\u1eddi th\\u1ef1c s\\u1ef1 kh\\u00f4ng s\\u1eed d\\u1ee5ng padding ho\\u1eb7c"}, {"index": 24, "start": 114.8, "end": 118.64, "text": "b\\u1ea1n lu\\u00f4n s\\u1eed d\\u1ee5ng c\\u00e1c convolution h\\u1ee3p l\\u1ec7, \\u0111\\u00f3 l\\u00e0 l\\u00fd do t\\u1ea1i sao m\\u1ed7i l\\u1ea7n b\\u1ea1n \\u00e1p d\\u1ee5ng m\\u1ed9t"}, {"index": 25, "start": 118.64, "end": 121.92, "text": "l\\u1edbp convolutional, chi\\u1ec1u cao v\\u00e0 chi\\u1ec1u r\\u1ed9ng s\\u1ebd thu nh\\u1ecf l\\u1ea1i."}, {"index": 26, "start": 121.92, "end": 126.64, "text": "V\\u00ec v\\u1eady, \\u0111\\u00f3 l\\u00e0 l\\u00fd do t\\u1ea1i sao \\u1edf \\u0111\\u00e2y b\\u1ea1n \\u0111i t\\u1eeb 14 x 14 xu\\u1ed1ng 10 x 10."}, {"index": 27, "start": 126.64, "end": 130.08, "text": "Sau \\u0111\\u00f3 l\\u00e0 m\\u1ed9t l\\u1edbp pooling kh\\u00e1c, v\\u00ec v\\u1eady n\\u00f3 gi\\u1ea3m chi\\u1ec1u cao v\\u00e0 chi\\u1ec1u r\\u1ed9ng theo"}, {"index": 28, "start": 130.08, "end": 133.84, "text": "h\\u1ec7 s\\u1ed1 2 v\\u00e0 b\\u1ea1n s\\u1ebd c\\u00f3 5 x 5 \\u1edf \\u0111\\u00e2y."}, {"index": 29, "start": 133.84, "end": 137.76, "text": "V\\u00e0 n\\u1ebfu b\\u1ea1n nh\\u00e2n c\\u00e1c s\\u1ed1 n\\u00e0y l\\u1ea1i, 5 x 5 x 16, th\\u00ec"}, {"index": 30, "start": 137.76, "end": 144.0, "text": "k\\u1ebft qu\\u1ea3 s\\u1ebd l\\u00e0 400. 25 nh\\u00e2n 16 l\\u00e0 400."}, {"index": 31, "start": 144.0, "end": 147.92, "text": "V\\u00e0 l\\u1edbp ti\\u1ebfp theo l\\u00e0 m\\u1ed9t l\\u1edbp k\\u1ebft n\\u1ed1i ho\\u00e0n to\\u00e0n"}, {"index": 32, "start": 147.92, "end": 154.16, "text": "k\\u1ebft n\\u1ed1i ho\\u00e0n to\\u00e0n t\\u1eebngnode n\\u00e0y v\\u1edbi"}, {"index": 33, "start": 154.16, "end": 158.56, "text": "m\\u1ed7i m\\u1ed9t trong 120 n\\u01a1-ron. V\\u1eady n\\u00ean c\\u00f3 m\\u1ed9t l\\u1edbp k\\u1ebft n\\u1ed1i ho\\u00e0n to\\u00e0n."}, {"index": 34, "start": 158.56, "end": 162.08, "text": "V\\u00e0 \\u0111\\u00f4i khi \\u0111i\\u1ec1u \\u0111\\u00f3 s\\u1ebd \\u0111\\u01b0\\u1ee3c v\\u1ebd ra m\\u1ed9t c\\u00e1ch r\\u00f5 r\\u00e0ng"}, {"index": 35, "start": 162.08, "end": 165.92, "text": "m\\u1ed9t l\\u1edbp v\\u1edbi 400 node, nh\\u01b0ng b\\u1ecf qua \\u0111i\\u1ec1u \\u0111\\u00f3 \\u1edf \\u0111\\u00e2y."}, {"index": 36, "start": 165.92, "end": 169.6, "text": "V\\u00ec v\\u1eady, c\\u00f3 m\\u1ed9t l\\u1edbp k\\u1ebft n\\u1ed1i ho\\u00e0n to\\u00e0n v\\u00e0 sau \\u0111\\u00f3 l\\u00e0 m\\u1ed9t l\\u1edbp k\\u1ebft n\\u1ed1i ho\\u00e0n to\\u00e0n n\\u1eefa."}, {"index": 37, "start": 169.6, "end": 174.0, "text": "V\\u00e0 b\\u01b0\\u1edbc cu\\u1ed1i c\\u00f9ng l\\u00e0 n\\u00f3 s\\u1eed d\\u1ee5ng nh\\u1eefng \\u0111\\u1eb7c tr\\u01b0ng c\\u01a1 b\\u1ea3n n\\u00e0y, 84"}, {"index": 38, "start": 174.0, "end": 179.2, "text": "v\\u00e0 s\\u1eed d\\u1ee5ng n\\u00f3 v\\u1edbi m\\u1ed9t \\u0111\\u1ea7u ra cu\\u1ed1i c\\u00f9ng. T\\u00f4i \\u0111o\\u00e1n b\\u1ea1n c\\u00f3 th\\u1ec3 v\\u1ebd th\\u00eam m\\u1ed9t node \\u1edf \\u0111\\u00e2y"}, {"index": 39, "start": 179.2, "end": 182.96, "text": "\\u0111\\u1ec3 t\\u1ea1o ra m\\u1ed9t d\\u1ef1 \\u0111o\\u00e1n cho y hat. V\\u00e0 y hat nh\\u1eadn gi\\u00e1 tr\\u1ecb"}, {"index": 40, "start": 182.96, "end": 187.28, "text": "10 gi\\u00e1 tr\\u1ecb kh\\u1ea3 d\\u0129 t\\u01b0\\u01a1ng \\u1ee9ng v\\u1edbi vi\\u1ec7c nh\\u1eadn di\\u1ec7n t\\u1eebng ch\\u1eef s\\u1ed1"}, {"index": 41, "start": 187.28, "end": 191.52, "text": "t\\u1eeb 0 \\u0111\\u1ebfn 9. M\\u1ed9t phi\\u00ean b\\u1ea3n hi\\u1ec7n \\u0111\\u1ea1i c\\u1ee7a m\\u1ea1ng n\\u01a1-ron n\\u00e0y"}, {"index": 42, "start": 191.52, "end": 197.28, "text": "s\\u1ebd s\\u1eed d\\u1ee5ng m\\u1ed9t l\\u1edbp softmax v\\u1edbi \\u0111\\u1ea7u ra ph\\u00e2n lo\\u1ea1i 10 chi\\u1ec1u."}, {"index": 43, "start": 197.28, "end": 201.44, "text": "M\\u1eb7c d\\u00f9 l\\u00fac \\u0111\\u00f3, Net5 th\\u1ef1c s\\u1ef1 s\\u1eed d\\u1ee5ng m\\u1ed9t lo\\u1ea1i ph\\u00e2n lo\\u1ea1i kh\\u00e1c"}, {"index": 44, "start": 201.44, "end": 205.44, "text": "t\\u1ea1i l\\u1edbp \\u0111\\u1ea7u ra, m\\u1ed9t lo\\u1ea1i kh\\u00f4ng c\\u00f2n h\\u1eefu \\u00edch ng\\u00e0y nay."}, {"index": 45, "start": 205.44, "end": 209.12, "text": "V\\u00ec v\\u1eady, m\\u1ea1ng n\\u01a1-ron n\\u00e0y nh\\u1ecf theo ti\\u00eau chu\\u1ea9n hi\\u1ec7n \\u0111\\u1ea1i."}, {"index": 46, "start": 209.12, "end": 214.0, "text": "N\\u00f3 c\\u00f3 kho\\u1ea3ng 60.000 tham s\\u1ed1. V\\u00e0 ng\\u00e0y nay b\\u1ea1n"}, {"index": 47, "start": 214.08, "end": 218.8, "text": "th\\u01b0\\u1eddng th\\u1ea5y c\\u00e1c m\\u1ea1ng n\\u01a1-ron v\\u1edbi s\\u1ed1 tham s\\u1ed1 t\\u1eeb 10 tri\\u1ec7u \\u0111\\u1ebfn 100 tri\\u1ec7u"}, {"index": 48, "start": 218.8, "end": 221.76, "text": "tham s\\u1ed1. V\\u00e0 kh\\u00f4ng c\\u00f3 g\\u00ec l\\u1ea1 khi th\\u1ea5y c\\u00e1c m\\u1ea1ng nh\\u01b0 v\\u1eady."}, {"index": 49, "start": 221.76, "end": 225.28, "text": "Ch\\u00fang th\\u1ef1c s\\u1ef1 l\\u1edbn h\\u01a1n m\\u1ea1ng n\\u00e0y kho\\u1ea3ng m\\u1ed9t ng\\u00e0n l\\u1ea7n."}, {"index": 50, "start": 225.28, "end": 230.08, "text": "Nh\\u01b0ng m\\u1ed9t \\u0111i\\u1ec1u b\\u1ea1n th\\u1ea5y l\\u00e0 khi b\\u1ea1n \\u0111i s\\u00e2u h\\u01a1n v\\u00e0o m\\u1ea1ng, t\\u1eeb tr\\u00e1i sang ph\\u1ea3i"}, {"index": 51, "start": 230.08, "end": 234.32, "text": "chi\\u1ec1u cao v\\u00e0 chi\\u1ec1u r\\u1ed9ng"}, {"index": 52, "start": 234.32, "end": 237.6, "text": "c\\u00f3 xu h\\u01b0\\u1edbng gi\\u1ea3m. B\\u1ea1n \\u0111\\u00e3 \\u0111i t\\u1eeb 30 x 32 xu\\u1ed1ng 28 \\u0111\\u1ebfn"}, {"index": 53, "start": 237.6, "end": 242.08, "text": "14, 10, \\u0111\\u1ebfn 5. Trong khi s\\u1ed1 k\\u00eanh"}, {"index": 54, "start": 242.08, "end": 249.12, "text": "c\\u00f3 xu h\\u01b0\\u1edbng t\\u0103ng. N\\u00f3 \\u0111i t\\u1eeb 1 \\u0111\\u1ebfn 6 \\u0111\\u1ebfn 16 khi b\\u1ea1n"}, {"index": 55, "start": 249.12, "end": 252.88, "text": "\\u0111i s\\u00e2u h\\u01a1n v\\u00e0o c\\u00e1c l\\u1edbp c\\u1ee7a m\\u1ea1ng. M\\u1ed9t m\\u1eabu kh\\u00e1c b\\u1ea1n th\\u1ea5y trong m\\u1ea1ng"}, {"index": 56, "start": 252.88, "end": 255.84, "text": "n\\u01a1-ron n\\u00e0y v\\u1eabn th\\u01b0\\u1eddng \\u0111\\u01b0\\u1ee3c l\\u1eb7p l\\u1ea1i ng\\u00e0y nay l\\u00e0 r\\u1eb1ng"}, {"index": 57, "start": 255.84, "end": 260.56, "text": "b\\u1ea1n c\\u00f3 th\\u1ec3 c\\u00f3 m\\u1ed9t ho\\u1eb7c nhi\\u1ec1u l\\u1edbp conf theo sau b\\u1edfi m\\u1ed9t l\\u1edbp k\\u00e9o"}, {"index": 58, "start": 260.56, "end": 264.0, "text": "v\\u00e0 sau \\u0111\\u00f3 l\\u00e0 m\\u1ed9t l\\u1edbp conf ho\\u1eb7c \\u0111\\u00f4i khi nhi\\u1ec1u l\\u1edbp conf"}, {"index": 59, "start": 264.0, "end": 267.76, "text": "theo sau b\\u1edfi m\\u1ed9t l\\u1edbp k\\u00e9o v\\u00e0 sau \\u0111\\u00f3 l\\u00e0 m\\u1ed9t s\\u1ed1 l\\u1edbp k\\u1ebft n\\u1ed1i \\u0111\\u1ea7y \\u0111\\u1ee7"}, {"index": 60, "start": 267.76, "end": 274.0, "text": "v\\u00e0 sau \\u0111\\u00f3 l\\u00e0 \\u0111\\u1ea7u ra. V\\u00ec v\\u1eady, lo\\u1ea1i s\\u1eafp x\\u1ebfp c\\u00e1c l\\u1edbp n\\u00e0y l\\u00e0 kh\\u00e1 ph\\u1ed5 bi\\u1ebfn."}, {"index": 61, "start": 274.0, "end": 278.0, "text": "Cu\\u1ed1i c\\u00f9ng, \\u0111\\u00e2y c\\u00f3 l\\u1ebd ch\\u1ec9 d\\u00e0nh cho nh\\u1eefng ai mu\\u1ed1n th\\u1eed \\u0111\\u1ecdc t\\u00e0i li\\u1ec7u."}, {"index": 62, "start": 278.0, "end": 280.96, "text": "C\\u00f3 m\\u1ed9t v\\u00e0i \\u0111i\\u1ec1u kh\\u00e1c m\\u00e0 \\u0111\\u00e3"}, {"index": 63, "start": 280.96, "end": 284.8, "text": "kh\\u00e1c bi\\u1ec7t. Ph\\u1ea7n c\\u00f2n l\\u1ea1i c\\u1ee7a slide n\\u00e0y t\\u00f4i s\\u1ebd"}, {"index": 64, "start": 284.8, "end": 289.36, "text": "n\\u00eau v\\u00e0i nh\\u1eadn x\\u00e9t n\\u00e2ng cao ch\\u1ec9 d\\u00e0nh cho nh\\u1eefng ai mu\\u1ed1n th\\u1eed"}, {"index": 65, "start": 289.36, "end": 294.8, "text": "\\u0111\\u1ecdc b\\u00e0i b\\u00e1o kinh \\u0111i\\u1ec3n n\\u00e0y. V\\u00e0 v\\u00ec v\\u1eady m\\u1ecdi th\\u1ee9 t\\u00f4i s\\u1ebd vi\\u1ebft b\\u1eb1ng m\\u00e0u \\u0111\\u1ecf"}, {"index": 66, "start": 294.8, "end": 299.76, "text": "c\\u00e1c b\\u1ea1n c\\u00f3 th\\u1ec3 an t\\u00e2m b\\u1ecf qua slide n\\u00e0y. V\\u00e0 \\u0111\\u00e2y c\\u00f3 th\\u1ec3 l\\u00e0 m\\u1ed9t \\u0111i\\u1ec3m th\\u00fa v\\u1ecb trong l\\u1ecbch s\\u1eed"}, {"index": 67, "start": 299.76, "end": 304.32, "text": "ch\\u00fa th\\u00edch m\\u00e0 kh\\u00f4ng sao n\\u1ebfu b\\u1ea1n kh\\u00f4ng theo d\\u00f5i ho\\u00e0n to\\u00e0n."}, {"index": 68, "start": 304.32, "end": 307.36, "text": "V\\u1eady h\\u00f3a ra r\\u1eb1ng n\\u1ebfu b\\u1ea1n \\u0111\\u1ecdc b\\u00e0i b\\u00e1o g\\u1ed1c,"}, {"index": 69, "start": 307.36, "end": 311.04, "text": "th\\u1eddi \\u0111\\u00f3 m\\u1ecdi ng\\u01b0\\u1eddi s\\u1eed d\\u1ee5ng h\\u00e0m sigmoid v\\u00e0 h\\u00e0m tanh."}, {"index": 70, "start": 311.04, "end": 314.32, "text": "H\\u1ecd kh\\u00f4ng s\\u1eed d\\u1ee5ng"}, {"index": 71, "start": 314.32, "end": 317.68, "text": "h\\u00e0m ReLU v\\u00e0o th\\u1eddi \\u0111i\\u1ec3m \\u0111\\u00f3. N\\u1ebfu b\\u1ea1n nh\\u00ecn v\\u00e0o b\\u00e0i b\\u00e1o, b\\u1ea1n s\\u1ebd th\\u1ea5y"}, {"index": 72, "start": 317.68, "end": 323.2, "text": "c\\u00f3 \\u0111\\u1ec1 c\\u1eadp \\u0111\\u1ebfn sigmoid v\\u00e0 tanh. V\\u00e0 c\\u0169ng c\\u00f3 m\\u1ed9t s\\u1ed1 c\\u00e1ch k\\u1ef3 l\\u1ea1 v\\u1ec1"}, {"index": 73, "start": 323.2, "end": 326.8, "text": "c\\u00e1ch m\\u00e0 m\\u1ea1ng n\\u00e0y \\u0111\\u01b0\\u1ee3c k\\u1ebft n\\u1ed1i. \\u00cdt nh\\u1ea5t l\\u00e0 k\\u1ef3 l\\u1ea1 theo ti\\u00eau chu\\u1ea9n hi\\u1ec7n \\u0111\\u1ea1i."}, {"index": 74, "start": 326.8, "end": 332.96, "text": "V\\u00ed d\\u1ee5, b\\u1ea1n \\u0111\\u00e3 th\\u1ea5y r\\u1eb1ng n\\u1ebfu b\\u1ea1n c\\u00f3 m\\u1ed9t m\\u1ea1ng v\\u1edbi k\\u00edch th\\u01b0\\u1edbc nhh x nww x ncc,"}, {"index": 75, "start": 332.96, "end": 339.28, "text": "v\\u1edbi ncc k\\u00eanh th\\u00ec b\\u1ea1n s\\u1eed d\\u1ee5ng b\\u1ed9 l\\u1ecdc k\\u00edch th\\u01b0\\u1edbc f x f x c\\u00f9ng ncc."}, {"index": 76, "start": 339.28, "end": 343.52, "text": "m\\u1ed7i b\\u1ed9 l\\u1ecdc nh\\u00ecn v\\u00e0o t\\u1eebng k\\u00eanh n\\u00e0y."}, {"index": 77, "start": 343.52, "end": 347.12, "text": "Nh\\u01b0ng th\\u1eddi \\u0111\\u00f3, m\\u00e1y t\\u00ednh ch\\u1eadm h\\u01a1n nhi\\u1ec1u,"}, {"index": 78, "start": 347.12, "end": 350.48, "text": "v\\u00ec v\\u1eady \\u0111\\u1ec3 ti\\u1ebft ki\\u1ec7m t\\u00ednh to\\u00e1n c\\u0169ng nh\\u01b0 c\\u00e1c tham s\\u1ed1,"}, {"index": 79, "start": 350.64, "end": 353.76, "text": "Lynette 5 g\\u1ed1c \\u0111\\u00e3 c\\u00f3 m\\u1ed9t c\\u00e1ch l\\u00e0m ph\\u1ee9c t\\u1ea1p k\\u1ef3 l\\u1ea1."}, {"index": 80, "start": 353.76, "end": 358.08, "text": "n\\u01a1i m\\u00e0 c\\u00e1c b\\u1ed9 l\\u1ecdc kh\\u00e1c nhau nh\\u00ecn v\\u00e0o c\\u00e1c k\\u00eanh kh\\u00e1c nhau c\\u1ee7a kh\\u1ed1i \\u0111\\u1ea7u v\\u00e0o."}, {"index": 81, "start": 358.08, "end": 361.92, "text": "V\\u00e0 do \\u0111\\u00f3, t\\u00e0i li\\u1ec7u \\u0111\\u1ec1 c\\u1eadp \\u0111\\u1ebfn nh\\u1eefng chi ti\\u1ebft \\u0111\\u00f3, nh\\u01b0ng tri\\u1ec3n khai hi\\u1ec7n \\u0111\\u1ea1i h\\u01a1n"}, {"index": 82, "start": 361.92, "end": 366.96, "text": "th\\u00ec b\\u1ea1n bi\\u1ebft \\u0111\\u1ea5y, s\\u1ebd kh\\u00f4ng c\\u00f3 lo\\u1ea1i \\u0111\\u1ed9 ph\\u1ee9c t\\u1ea1p \\u0111\\u00f3 v\\u00e0o ng\\u00e0y nay."}, {"index": 83, "start": 366.96, "end": 371.76, "text": "V\\u00e0 r\\u1ed3i m\\u1ed9t \\u0111i\\u1ec1u cu\\u1ed1i c\\u00f9ng \\u0111\\u01b0\\u1ee3c th\\u1ef1c hi\\u1ec7n v\\u00e0o th\\u1eddi \\u0111i\\u1ec3m \\u0111\\u00f3 t\\u00f4i \\u0111o\\u00e1n l\\u00e0 nh\\u01b0ng kh\\u00f4ng th\\u1ef1c s\\u1ef1"}, {"index": 84, "start": 371.76, "end": 375.12, "text": "th\\u1ef1c hi\\u1ec7n ngay b\\u00e2y gi\\u1edd l\\u00e0 Lynette 5 nguy\\u00ean b\\u1ea3n"}, {"index": 85, "start": 375.12, "end": 379.52, "text": "c\\u00f3 m\\u1ed9t t\\u00ednh kh\\u00f4ng tuy\\u1ebfn t\\u00ednh sau khi g\\u1ed9p."}, {"index": 86, "start": 379.68, "end": 383.04, "text": "V\\u00e0 t\\u00f4i ngh\\u0129 r\\u1eb1ng n\\u00f3 th\\u1ef1c s\\u1ef1 \\u0111\\u00e3 s\\u1eed d\\u1ee5ng m\\u1ed9t t\\u00ednh kh\\u00f4ng tuy\\u1ebfn t\\u00ednh sigmoid"}, {"index": 87, "start": 383.04, "end": 387.12, "text": "sau l\\u1edbp g\\u1ed9p. V\\u00ec v\\u1eady, n\\u1ebfu b\\u1ea1n \\u0111\\u1ecdc t\\u00e0i li\\u1ec7u n\\u00e0y"}, {"index": 88, "start": 387.12, "end": 390.56, "text": "v\\u00e0 \\u0111\\u00e2y l\\u00e0 m\\u1ed9t trong nh\\u1eefng t\\u00e0i li\\u1ec7u kh\\u00f3 \\u0111\\u1ecdc h\\u01a1n, n\\u00ean nh\\u1eefng c\\u00e1i kh\\u00e1c s\\u1ebd \\u0111\\u01b0\\u1ee3c \\u0111\\u1ec1 c\\u1eadp trong"}, {"index": 89, "start": 390.56, "end": 393.76, "text": "nh\\u1eefng video ti\\u1ebfp theo. Video ti\\u1ebfp theo c\\u00f3 th\\u1ec3 d\\u1ec5 d\\u00e0ng h\\u01a1n \\u0111\\u1ec3"}, {"index": 90, "start": 393.76, "end": 396.08, "text": "b\\u1eaft \\u0111\\u1ea7u v\\u1edbi. H\\u1ea7u h\\u1ebft c\\u00e1c \\u00fd t\\u01b0\\u1edfng tr\\u00ean slide n\\u00e0y l\\u00e0"}, {"index": 91, "start": 396.08, "end": 400.0, "text": "\\u0111\\u01b0\\u1ee3c m\\u00f4 t\\u1ea3 trong c\\u00e1c ph\\u1ea7n 2 v\\u00e0 3 c\\u1ee7a t\\u00e0i li\\u1ec7u."}, {"index": 92, "start": 400.0, "end": 404.56, "text": "V\\u00e0 c\\u00e1c ph\\u1ea7n sau c\\u1ee7a t\\u00e0i li\\u1ec7u \\u0111\\u1ec1 c\\u1eadp \\u0111\\u1ebfn m\\u1ed9t s\\u1ed1 \\u00fd t\\u01b0\\u1edfng kh\\u00e1c."}, {"index": 93, "start": 404.56, "end": 408.24, "text": "N\\u00f3 \\u0111\\u00e3 n\\u00f3i v\\u1ec1 m\\u1ed9t c\\u00e1i g\\u1ecdi l\\u00e0 m\\u1ea1ng bi\\u1ebfn \\u0111\\u1ed5i d\\u1ef1 th\\u1ea3o m\\u00e0 kh\\u00f4ng \\u0111\\u01b0\\u1ee3c"}, {"index": 94, "start": 408.24, "end": 410.96, "text": "s\\u1eed d\\u1ee5ng r\\u1ed9ng r\\u00e3i ng\\u00e0y nay. V\\u00ec v\\u1eady, n\\u1ebfu b\\u1ea1n c\\u1ed1 g\\u1eafng \\u0111\\u1ecdc t\\u00e0i li\\u1ec7u n\\u00e0y"}, {"index": 95, "start": 410.96, "end": 414.8, "text": "t\\u00f4i khuy\\u00ean b\\u1ea1n n\\u00ean t\\u1eadp trung th\\u1ef1c s\\u1ef1 v\\u00e0o ph\\u1ea7n 2, ph\\u1ea7n n\\u00f3i v\\u1ec1"}, {"index": 96, "start": 414.8, "end": 418.24, "text": "ki\\u1ebfn tr\\u00fac n\\u00e0y v\\u00e0 c\\u00f3 th\\u1ec3 nh\\u00ecn nhanh qua ph\\u1ea7n 3"}, {"index": 97, "start": 418.24, "end": 421.6, "text": "c\\u00f3 m\\u1ed9t lo\\u1ea1t c\\u00e1c k\\u1ebft qu\\u1ea3 th\\u00ed nghi\\u1ec7m r\\u1ea5t th\\u00fa v\\u1ecb."}, {"index": 98, "start": 421.6, "end": 425.2, "text": "V\\u00ed d\\u1ee5 th\\u1ee9 hai v\\u1ec1 m\\u1ed9t m\\u1ea1ng n\\u01a1-ron t\\u00f4i mu\\u1ed1n cho b\\u1ea1n xem l\\u00e0"}, {"index": 99, "start": 425.2, "end": 429.52, "text": "Alex Nett \\u0111\\u01b0\\u1ee3c \\u0111\\u1eb7t t\\u00ean theo Alex Trzejevsky, ng\\u01b0\\u1eddi l\\u00e0 t\\u00e1c gi\\u1ea3 \\u0111\\u1ea7u ti\\u00ean"}, {"index": 100, "start": 429.52, "end": 433.6, "text": "c\\u1ee7a b\\u00e0i b\\u00e1o m\\u00f4 t\\u1ea3 c\\u00f4ng tr\\u00ecnh n\\u00e0y. C\\u00e1c t\\u00e1c gi\\u1ea3 kh\\u00e1c l\\u00e0"}, {"index": 101, "start": 433.68, "end": 436.8, "text": "Saskever v\\u00e0 Jeffrey Hinton. V\\u1eady Alex Nett"}, {"index": 102, "start": 436.8, "end": 442.48, "text": "\\u0111\\u1ea7u v\\u00e0o b\\u1eaft \\u0111\\u1ea7u b\\u1eb1ng h\\u00ecnh \\u1ea3nh 227 x 227 x 3. \\u1ed2 v\\u00e0 n\\u1ebfu b\\u1ea1n \\u0111\\u1ecdc b\\u00e0i b\\u00e1o"}, {"index": 103, "start": 442.48, "end": 448.0, "text": "b\\u00e0i b\\u00e1o \\u0111\\u1ec1 c\\u1eadp \\u0111\\u1ebfn h\\u00ecnh \\u1ea3nh 224 x 224 x 3 nh\\u01b0ng n\\u1ebfu b\\u1ea1n nh\\u00ecn v\\u00e0o c\\u00e1c con s\\u1ed1"}, {"index": 104, "start": 448.0, "end": 453.12, "text": "t\\u00f4i ngh\\u0129 r\\u1eb1ng c\\u00e1c con s\\u1ed1 ch\\u1ec9 h\\u1ee3p l\\u00fd n\\u1ebfu th\\u1ef1c s\\u1ef1 l\\u00e0 227 x 227."}, {"index": 105, "start": 453.12, "end": 457.52, "text": "V\\u00e0 sau \\u0111\\u00f3, l\\u1edbp \\u0111\\u1ea7u ti\\u00ean \\u00e1p d\\u1ee5ng m\\u1ed9t t\\u1eadp h\\u1ee3p 96"}, {"index": 106, "start": 457.52, "end": 462.64, "text": "b\\u1ed9 l\\u1ecdc 11 x 11 v\\u1edbi b\\u01b0\\u1edbc nh\\u1ea3y 4 v\\u00e0 b\\u1edfi v\\u00ec n\\u00f3 s\\u1eed d\\u1ee5ng b\\u01b0\\u1edbc nh\\u1ea3y l\\u1edbn 4"}, {"index": 107, "start": 462.64, "end": 466.8, "text": "k\\u00edch th\\u01b0\\u1edbc gi\\u1ea3m xu\\u1ed1ng 55 x 55, v\\u00ec v\\u1eady x\\u1ea5p x\\u1ec9"}, {"index": 108, "start": 466.8, "end": 471.36, "text": "gi\\u1ea3m xu\\u1ed1ng c\\u00f2n 1/4 do b\\u01b0\\u1edbc nh\\u1ea3y l\\u1edbn"}, {"index": 109, "start": 471.36, "end": 478.0, "text": "v\\u00e0 sau \\u0111\\u00f3 \\u00e1p d\\u1ee5ng max pooling v\\u1edbi b\\u1ed9 l\\u1ecdc 3 x 3, v\\u1eady f b\\u1eb1ng 3 v\\u00e0 b\\u01b0\\u1edbc nh\\u1ea3y 2"}, {"index": 110, "start": 478.0, "end": 485.12, "text": "do \\u0111\\u00f3, \\u0111i\\u1ec1u n\\u00e0y gi\\u1ea3m th\\u1ec3 t\\u00edch xu\\u1ed1ng c\\u00f2n 27 x 27 x 96"}, {"index": 111, "start": 485.12, "end": 489.68, "text": "sau \\u0111\\u00f3, n\\u00f3 th\\u1ef1c hi\\u1ec7n ph\\u00e9p t\\u00edch ch\\u1eadp 5 x 5 v\\u1edbi c\\u00f9ng c\\u00e1ch pad"}, {"index": 112, "start": 489.76, "end": 496.72, "text": "do v\\u1eady b\\u1ea1n s\\u1ebd c\\u00f3 \\u0111\\u01b0\\u1ee3c k\\u00edch th\\u01b0\\u1edbc 27 x 27 x 276. L\\u1ea1i l\\u00e0 max pooling"}, {"index": 113, "start": 496.72, "end": 501.12, "text": "\\u0111i\\u1ec1u n\\u00e0y gi\\u1ea3m chi\\u1ec1u cao v\\u00e0 chi\\u1ec1u r\\u1ed9ng xu\\u1ed1ng c\\u00f2n 13 v\\u00e0 sau \\u0111\\u00f3 l\\u00e0 th\\u00eam m\\u1ed9t"}, {"index": 114, "start": 501.12, "end": 506.88, "text": "ph\\u00e9p t\\u00edch ch\\u1eadp t\\u01b0\\u01a1ng t\\u1ef1, v\\u1edbi c\\u00f9ng m\\u1ed9t c\\u00e1ch pad n\\u00ean b\\u00e2y gi\\u1edd l\\u00e0 13 x 13"}, {"index": 115, "start": 506.88, "end": 514.08, "text": "v\\u1edbi 384 b\\u1ed9 l\\u1ecdc v\\u00e0 sau \\u0111\\u00f3 l\\u1ea1i l\\u00e0 ph\\u00e9p t\\u00edch ch\\u1eadp 3 x 3 t\\u01b0\\u01a1ng t\\u1ef1"}, {"index": 116, "start": 514.08, "end": 519.6, "text": "s\\u1ebd cho b\\u1ea1n k\\u1ebft qu\\u1ea3, sau \\u0111\\u00f3 ph\\u00e9p t\\u00edch ch\\u1eadp 3 x 3 t\\u01b0\\u01a1ng t\\u1ef1 l\\u1ea1i cho b\\u1ea1n k\\u1ebft qu\\u1ea3"}, {"index": 117, "start": 519.76, "end": 526.48, "text": "sau \\u0111\\u00f3 max pool \\u0111\\u01b0a k\\u00edch th\\u01b0\\u1edbc xu\\u1ed1ng c\\u00f2n 6 x 6 x 256 n\\u1ebfu b\\u1ea1n nh\\u00e2n c\\u00e1c"}, {"index": 118, "start": 526.48, "end": 532.4, "text": "s\\u1ed1 n\\u00e0y: 6 nh\\u00e2n 6 nh\\u00e2n 256 th\\u00ec l\\u00e0 9216, v\\u00ec v\\u1eady ch\\u00fang ta"}, {"index": 119, "start": 532.4, "end": 537.52, "text": "s\\u1ebd gi\\u1ea3i n\\u00e9n \\u0111i\\u1ec1u n\\u00e0y th\\u00e0nh 9216 n\\u01a1-ron v\\u00e0 sau \\u0111\\u00f3"}, {"index": 120, "start": 537.52, "end": 541.68, "text": "Cu\\u1ed1i c\\u00f9ng, n\\u00f3 c\\u00f3 m\\u1ed9t v\\u00e0i l\\u1edbp k\\u1ebft n\\u1ed1i ho\\u00e0n to\\u00e0n v\\u00e0 sau \\u0111\\u00f3"}, {"index": 121, "start": 541.68, "end": 545.92, "text": "cu\\u1ed1i c\\u00f9ng s\\u1eed d\\u1ee5ng h\\u00e0m softmax \\u0111\\u1ec3 ch\\u1ecdn ra c\\u00e1i n\\u00e0o trong s\\u1ed1"}, {"index": 122, "start": 546.0, "end": 552.72, "text": "M\\u1ea1ng n\\u01a1-ron n\\u00e0y th\\u1ef1c s\\u1ef1 c\\u00f3 r\\u1ea5t nhi\\u1ec1u \\u0111i\\u1ec1u m\\u00e0 1000 \\u0111i\\u1ec3m giao c\\u1eaft \\u0111\\u1ed1i t\\u01b0\\u1ee3ng c\\u00f3 th\\u1ec3 mang l\\u1ea1i."}, {"index": 123, "start": 552.72, "end": 558.48, "text": "c\\u00e1c \\u0111i\\u1ec3m t\\u01b0\\u01a1ng \\u0111\\u1ed3ng v\\u1edbi m\\u1ea1ng nh\\u01b0ng n\\u00f3 l\\u1edbn h\\u01a1n r\\u1ea5t nhi\\u1ec1u"}, {"index": 124, "start": 558.48, "end": 563.36, "text": "n\\u00ean trong khi \\u0111\\u00f3 m\\u1ea1ng ho\\u1eb7c m\\u1ea1ng 5 t\\u1eeb"}, {"index": 125, "start": 563.36, "end": 566.8, "text": "trang tr\\u01b0\\u1edbc c\\u00f3 60 000, kho\\u1ea3ng 60 000"}, {"index": 126, "start": 566.8, "end": 570.4, "text": "c\\u00e1c tham s\\u1ed1, alex net n\\u00e0y c\\u00f3 kho\\u1ea3ng 60 tri\\u1ec7u"}, {"index": 127, "start": 570.4, "end": 574.32, "text": "c\\u00e1c tham s\\u1ed1 v\\u00e0 th\\u1ef1c t\\u1ebf l\\u00e0 \\u0111i\\u1ec1u \\u0111\\u00f3 c\\u00f3 th\\u1ec3 m\\u1ea5t th\\u1eddi gian b\\u1ea1n bi\\u1ebft"}, {"index": 128, "start": 574.32, "end": 578.64, "text": "c\\u00e1c kh\\u1ed1i x\\u00e2y d\\u1ef1ng c\\u01a1 b\\u1ea3n kh\\u00e1 t\\u01b0\\u01a1ng t\\u1ef1 nh\\u01b0ng c\\u00f3 nhi\\u1ec1u \\u0111\\u01a1n v\\u1ecb \\u1ea9n h\\u01a1n v\\u00e0"}, {"index": 129, "start": 578.64, "end": 582.48, "text": "\\u0111\\u00e0o t\\u1ea1o n\\u00f3 tr\\u00ean nhi\\u1ec1u d\\u1eef li\\u1ec7u h\\u01a1n, v\\u00ec v\\u1eady b\\u1ea1n s\\u1ebd \\u0111\\u00e0o t\\u1ea1o tr\\u00ean t\\u1eadp d\\u1eef li\\u1ec7u ImageNet"}, {"index": 130, "start": 582.48, "end": 586.24, "text": "\\u0111i\\u1ec1u n\\u00e0y cho ph\\u00e9p n\\u00f3 c\\u00f3 hi\\u1ec7u su\\u1ea5t th\\u1eadt s\\u1ef1 \\u0111\\u00e1ng kinh ng\\u1ea1c"}, {"index": 131, "start": 586.24, "end": 590.72, "text": "m\\u1ed9t kh\\u00eda c\\u1ea1nh kh\\u00e1c c\\u1ee7a ki\\u1ebfn tr\\u00fac n\\u00e0y \\u0111\\u00e3 gi\\u00fap n\\u00f3 t\\u1ed1t h\\u01a1n nhi\\u1ec1u so v\\u1edbi m\\u1ea1ng"}, {"index": 132, "start": 590.72, "end": 594.48, "text": "l\\u00e0 vi\\u1ec7c s\\u1eed d\\u1ee5ng h\\u00e0m k\\u00edch ho\\u1ea1t doanh thu v\\u00e0 m\\u1ed9t l\\u1ea7n n\\u1eefa"}, {"index": 133, "start": 594.48, "end": 598.56, "text": "n\\u1ebfu b\\u1ea1n \\u0111\\u1ecdc th\\u00eam v\\u1ec1 b\\u00e0i b\\u00e1o bay, s\\u1ebd c\\u00f3 m\\u1ed9t s\\u1ed1 chi ti\\u1ebft n\\u00e2ng cao m\\u00e0 b\\u1ea1n kh\\u00f4ng"}, {"index": 134, "start": 598.56, "end": 600.96, "text": "th\\u1ef1c s\\u1ef1 c\\u1ea7n ph\\u1ea3i lo l\\u1eafng n\\u1ebfu b\\u1ea1n kh\\u00f4ng \\u0111\\u1ecdc b\\u00e0i b\\u00e1o"}, {"index": 135, "start": 600.96, "end": 604.8, "text": "m\\u1ed9t v\\u1ea5n \\u0111\\u1ec1 l\\u00e0 khi b\\u00e0i b\\u00e1o n\\u00e0y \\u0111\\u01b0\\u1ee3c vi\\u1ebft, c\\u00e1c GPU c\\u00f2n"}, {"index": 136, "start": 604.8, "end": 608.48, "text": "ch\\u1eadm h\\u01a1n m\\u1ed9t ch\\u00fat n\\u00ean n\\u00f3 c\\u00f3 m\\u1ed9t ph\\u01b0\\u01a1ng ph\\u00e1p ph\\u1ee9c t\\u1ea1p"}, {"index": 137, "start": 608.48, "end": 614.88, "text": "\\u0111\\u1ec3 hu\\u1ea5n luy\\u1ec7n tr\\u00ean hai GPU v\\u00e0 \\u00fd t\\u01b0\\u1edfng c\\u01a1 b\\u1ea3n l\\u00e0 nhi\\u1ec1u l\\u1edbp n\\u00e0y"}, {"index": 138, "start": 614.88, "end": 618.8, "text": "th\\u1ef1c t\\u1ebf \\u0111\\u01b0\\u1ee3c chia ra gi\\u1eefa hai GPU kh\\u00e1c nhau v\\u00e0 c\\u00f3 m\\u1ed9t c\\u00e1ch"}, {"index": 139, "start": 618.8, "end": 623.44, "text": "suy ngh\\u0129 cho vi\\u1ec7c hai GPU s\\u1ebd giao ti\\u1ebfp v\\u1edbi nhau nh\\u01b0 th\\u1ebf n\\u00e0o"}, {"index": 140, "start": 623.44, "end": 627.44, "text": "v\\u00e0 t\\u00e0i li\\u1ec7u n\\u00e0y c\\u0169ng l\\u00e0 ki\\u1ebfn tr\\u00fac alex net g\\u1ed1c"}, {"index": 141, "start": 627.44, "end": 633.92, "text": "c\\u0169ng c\\u00f3 m\\u1ed9t lo\\u1ea1i l\\u1edbp kh\\u00e1c g\\u1ecdi l\\u00e0 chu\\u1ea9n h\\u00f3a ph\\u1ea3n h\\u1ed3i \\u0111\\u1ecba ph\\u01b0\\u01a1ng"}, {"index": 142, "start": 633.92, "end": 638.8, "text": "v\\u00e0 lo\\u1ea1i l\\u1edbp n\\u00e0y th\\u1ef1c s\\u1ef1 kh\\u00f4ng \\u0111\\u01b0\\u1ee3c s\\u1eed d\\u1ee5ng nhi\\u1ec1u, \\u0111\\u00f3 l\\u00e0 l\\u00fd do t\\u1ea1i sao t\\u00f4i kh\\u00f4ng n\\u00f3i v\\u1ec1 n\\u00f3"}, {"index": 143, "start": 638.8, "end": 643.04, "text": "nh\\u01b0ng \\u00fd t\\u01b0\\u1edfng c\\u01a1 b\\u1ea3n c\\u1ee7a chu\\u1ea9n h\\u00f3a ph\\u1ea3n h\\u1ed3i \\u0111\\u1ecba ph\\u01b0\\u01a1ng l\\u00e0 n\\u1ebfu b\\u1ea1n"}, {"index": 144, "start": 643.04, "end": 646.88, "text": "nh\\u00ecn v\\u00e0o m\\u1ed9t trong nh\\u1eefng kh\\u1ed1i ho\\u1eb7c th\\u1ec3 t\\u00edch m\\u00e0 ch\\u00fang ta c\\u00f3 \\u1edf tr\\u00ean"}, {"index": 145, "start": 646.88, "end": 650.88, "text": "gi\\u1ea3 s\\u1eed \\u0111\\u1ec3 lu\\u1eadn b\\u00e0n, c\\u00e1i n\\u00e0y b\\u1ea1n bi\\u1ebft 13 x 13"}, {"index": 146, "start": 650.88, "end": 654.48, "text": "v\\u1edbi 256, th\\u00ec vi\\u1ec7c chu\\u1ea9n h\\u00f3a ph\\u1ea3n h\\u1ed3i \\u0111\\u1ecba ph\\u01b0\\u01a1ng"}, {"index": 147, "start": 654.64, "end": 659.6, "text": "\\u0111\\u1ecbnh ngh\\u0129a c\\u1ee7a ch\\u00fang ta l\\u00e0 b\\u1ea1n nh\\u00ecn v\\u00e0o m\\u1ed9t v\\u1ecb tr\\u00ed, t\\u1ee9c l\\u00e0 m\\u1ed9t v\\u1ecb tr\\u00ed \\u0111\\u1ec3 t\\u0103ng c\\u01b0\\u1eddng"}, {"index": 148, "start": 659.6, "end": 664.56, "text": "v\\u00e0 nh\\u00ecn xu\\u1ed1ng to\\u00e0n b\\u1ed9 c\\u00e1c k\\u00eanh, nh\\u00ecn v\\u00e0o t\\u1ea5t c\\u1ea3 256"}, {"index": 149, "start": 664.56, "end": 668.64, "text": "s\\u1ed1 li\\u1ec7u v\\u00e0 chu\\u1ea9n h\\u00f3a ch\\u00fang, v\\u00e0 \\u0111\\u1ed9ng l\\u1ef1c cho \\u0111i\\u1ec1u n\\u00e0y"}, {"index": 150, "start": 668.64, "end": 671.92, "text": "chu\\u1ea9n h\\u00f3a ph\\u1ea3n h\\u1ed3i \\u0111\\u1ecba ph\\u01b0\\u01a1ng l\\u00e0 cho m\\u1ed7i v\\u1ecb tr\\u00ed"}, {"index": 151, "start": 671.92, "end": 676.56, "text": "trong h\\u00ecnh \\u1ea3nh 13 x 13 n\\u00e0y, c\\u00f3 th\\u1ec3 b\\u1ea1n kh\\u00f4ng mu\\u1ed1n"}, {"index": 152, "start": 676.56, "end": 680.08, "text": "qu\\u00e1 nhi\\u1ec1u n\\u01a1-ron v\\u1edbi k\\u00edch ho\\u1ea1t r\\u1ea5t cao"}, {"index": 153, "start": 680.08, "end": 684.56, "text": "nh\\u01b0ng sau \\u0111\\u00f3 nhi\\u1ec1u nh\\u00e0 nghi\\u00ean c\\u1ee9u \\u0111\\u00e3 ph\\u00e1t hi\\u1ec7n ra r\\u1eb1ng \\u0111i\\u1ec1u n\\u00e0y kh\\u00f4ng gi\\u00fap \\u00edch nhi\\u1ec1u"}, {"index": 154, "start": 684.56, "end": 688.96, "text": "v\\u00ec v\\u1eady \\u0111\\u00e2y l\\u00e0 m\\u1ed9t trong nh\\u1eefng \\u00fd t\\u01b0\\u1edfng m\\u00e0 t\\u00f4i \\u0111ang tr\\u00edch d\\u1eabn v\\u00e0 \\u0111\\u1ecdc v\\u00ec"}, {"index": 155, "start": 688.96, "end": 691.76, "text": "n\\u00f3 \\u00edt quan tr\\u1ecdng h\\u01a1n \\u0111\\u1ec3 b\\u1ea1n hi\\u1ec3u \\u0111i\\u1ec1u n\\u00e0y"}, {"index": 156, "start": 691.76, "end": 695.92, "text": "v\\u00e0 trong th\\u1ef1c t\\u1ebf, t\\u00f4i th\\u1ef1c s\\u1ef1 kh\\u00f4ng s\\u1eed d\\u1ee5ng chu\\u1ea9n h\\u00f3a ph\\u1ea3n h\\u1ed3i \\u0111\\u1ecba ph\\u01b0\\u01a1ng"}, {"index": 157, "start": 695.92, "end": 699.12, "text": "b\\u1ea1n bi\\u1ebft, th\\u1ef1c s\\u1ef1 trong c\\u00e1c m\\u1ea1ng m\\u00e0 t\\u00f4i s\\u1ebd \\u0111\\u00e0o t\\u1ea1o ng\\u00e0y h\\u00f4m nay, v\\u00ec v\\u1eady n\\u1ebfu b\\u1ea1n"}, {"index": 158, "start": 699.12, "end": 702.24, "text": "quan t\\u00e2m \\u0111\\u1ebfn l\\u1ecbch s\\u1eed c\\u1ee7a h\\u1ecdc s\\u00e2u, t\\u00f4i ngh\\u0129"}, {"index": 159, "start": 702.24, "end": 706.08, "text": "ngay c\\u1ea3 tr\\u01b0\\u1edbc alex net, h\\u1ecdc s\\u00e2u \\u0111\\u00e3 b\\u1eaft \\u0111\\u1ea7u thu h\\u00fat s\\u1ef1 ch\\u00fa \\u00fd"}, {"index": 160, "start": 706.08, "end": 708.88, "text": "trong nh\\u1eadn di\\u1ec7n gi\\u1ecdng n\\u00f3i \\u1edf m\\u1ed9t v\\u00e0i l\\u0129nh v\\u1ef1c kh\\u00e1c"}, {"index": 161, "start": 708.88, "end": 713.6, "text": "nh\\u01b0ng th\\u1ef1c s\\u1ef1 ch\\u00ednh b\\u00e0i b\\u00e1o n\\u00e0y \\u0111\\u00e3 thuy\\u1ebft ph\\u1ee5c r\\u1ea5t nhi\\u1ec1u ng\\u01b0\\u1eddi trong l\\u0129nh v\\u1ef1c th\\u1ecb gi\\u00e1c m\\u00e1y t\\u00ednh"}, {"index": 162, "start": 713.6, "end": 717.6, "text": "\\u0111\\u1ec3 h\\u1ecd nghi\\u00eam t\\u00fac xem x\\u00e9t h\\u1ecdc s\\u00e2u, \\u0111\\u1ec3 thuy\\u1ebft ph\\u1ee5c h\\u1ecd r\\u1eb1ng"}, {"index": 163, "start": 717.6, "end": 720.0, "text": "h\\u1ecdc s\\u00e2u th\\u1ef1c s\\u1ef1 hi\\u1ec7u qu\\u1ea3 trong th\\u1ecb gi\\u00e1c m\\u00e1y t\\u00ednh"}, {"index": 164, "start": 720.0, "end": 723.84, "text": "v\\u00e0 sau \\u0111\\u00f3 ch\\u00fang \\u0111\\u00e3 ph\\u00e1t tri\\u1ec3n \\u0111\\u1ec3 c\\u00f3 t\\u00e1c \\u0111\\u1ed9ng l\\u1edbn kh\\u00f4ng ch\\u1ec9 trong th\\u1ecb gi\\u00e1c m\\u00e1y t\\u00ednh m\\u00e0"}, {"index": 165, "start": 723.84, "end": 727.52, "text": "c\\u1ea3 v\\u01b0\\u1ee3t ra ngo\\u00e0i l\\u0129nh v\\u1ef1c th\\u1ecb gi\\u00e1c m\\u00e1y t\\u00ednh n\\u1eefa v\\u00e0 n\\u1ebfu b\\u1ea1n mu\\u1ed1n th\\u1eed \\u0111\\u1ecdc m\\u1ed9t s\\u1ed1"}, {"index": 166, "start": 727.52, "end": 731.68, "text": "c\\u00e1c b\\u00e0i b\\u00e1o n\\u00e0y th\\u00ec b\\u1ea1n th\\u1eadt s\\u1ef1 kh\\u00f4ng c\\u1ea7n ph\\u1ea3i l\\u00e0m \\u0111i\\u1ec1u \\u0111\\u00f3 cho kh\\u00f3a h\\u1ecdc n\\u00e0y"}, {"index": 167, "start": 731.68, "end": 735.6, "text": "nh\\u01b0ng n\\u1ebfu b\\u1ea1n mu\\u1ed1n th\\u1eed \\u0111\\u1ecdc m\\u1ed9t s\\u1ed1 b\\u00e0i b\\u00e1o n\\u00e0y th\\u00ec b\\u00e0i n\\u00e0y l\\u00e0 m\\u1ed9t trong s\\u1ed1"}, {"index": 168, "start": 735.68, "end": 739.36, "text": "nh\\u1eefng b\\u00e0i d\\u1ec5 \\u0111\\u1ecdc h\\u01a1n, v\\u00ec v\\u1eady \\u0111\\u00e2y c\\u00f3 th\\u1ec3 l\\u00e0 m\\u1ed9t b\\u00e0i t\\u1ed1t \\u0111\\u1ec3 xem"}, {"index": 169, "start": 739.36, "end": 743.28, "text": "n\\u00ean trong khi m\\u1ea1ng alex net c\\u00f3 ki\\u1ebfn tr\\u00fac t\\u01b0\\u01a1ng \\u0111\\u1ed1i ph\\u1ee9c t\\u1ea1p"}, {"index": 170, "start": 743.28, "end": 746.16, "text": "c\\u00f3 r\\u1ea5t nhi\\u1ec1u tham s\\u1ed1 si\\u00eau m\\u00e0 b\\u1ea1n bi\\u1ebft l\\u00e0"}, {"index": 171, "start": 746.16, "end": 752.0, "text": "t\\u1ea5t c\\u1ea3 nh\\u1eefng con s\\u1ed1 m\\u00e0 alex trusevsky v\\u00e0 c\\u00e1c \\u0111\\u1ed3ng t\\u00e1c gi\\u1ea3 c\\u1ee7a \\u00f4ng \\u0111\\u00e3"}, {"index": 172, "start": 752.0, "end": 755.2, "text": "ph\\u1ea3i \\u0111\\u01b0a ra, h\\u00e3y \\u0111\\u1ec3 t\\u00f4i cho b\\u1ea1n xem m\\u1ed9t v\\u00ed d\\u1ee5 th\\u1ee9 ba v\\u00e0 c\\u0169ng l\\u00e0 cu\\u1ed1i c\\u00f9ng"}, {"index": 173, "start": 755.2, "end": 758.88, "text": "trong video n\\u00e0y g\\u1ecdi l\\u00e0 vgg ho\\u1eb7c vgg 16"}, {"index": 174, "start": 758.88, "end": 763.52, "text": "v\\u00e0 m\\u1ed9t \\u0111i\\u1ec1u \\u0111\\u00e1ng ch\\u00fa \\u00fd v\\u1ec1 vgg 16"}, {"index": 175, "start": 763.52, "end": 767.36, "text": "l\\u00e0 h\\u1ecd \\u0111\\u00e3 n\\u00f3i thay v\\u00ec c\\u00f3 qu\\u00e1 nhi\\u1ec1u tham s\\u1ed1 si\\u00eau, h\\u00e3y"}, {"index": 176, "start": 767.36, "end": 771.84, "text": "s\\u1eed d\\u1ee5ng m\\u1ed9t m\\u1ea1ng \\u0111\\u01a1n gi\\u1ea3n h\\u01a1n, n\\u01a1i b\\u1ea1n ch\\u1ec9 t\\u1eadp trung v\\u00e0o vi\\u1ec7c c\\u00f3"}, {"index": 177, "start": 771.84, "end": 774.96, "text": "c\\u00e1c l\\u1edbp b\\u1ed9 l\\u1ecdc convolution ch\\u1ec9 l\\u00e0 b\\u1ed9 l\\u1ecdc 3x3 v\\u1edbi"}, {"index": 178, "start": 774.96, "end": 778.96, "text": "b\\u01b0\\u1edbc nh\\u1ea3y b\\u1eb1ng m\\u1ed9t v\\u00e0 lu\\u00f4n s\\u1eed d\\u1ee5ng padding gi\\u1ed1ng nhau"}, {"index": 179, "start": 778.96, "end": 782.24, "text": "v\\u00e0 l\\u00e0m cho t\\u1ea5t c\\u1ea3 c\\u00e1c l\\u1edbp max pooling c\\u1ee7a b\\u1ea1n l\\u00e0 2x2"}, {"index": 180, "start": 782.24, "end": 786.8, "text": "v\\u1edbi m\\u1ed9t b\\u01b0\\u1edbc nh\\u1ea3y hai v\\u00e0 m\\u1ed9t \\u0111i\\u1ec1u r\\u1ea5t t\\u1ed1t v\\u1ec1"}, {"index": 181, "start": 786.8, "end": 790.72, "text": "m\\u1ea1ng vgg l\\u00e0 n\\u00f3 th\\u1ef1c s\\u1ef1 \\u0111\\u01a1n gi\\u1ea3n h\\u00f3a nh\\u1eefng m\\u1ea1ng n\\u01a1-ron"}, {"index": 182, "start": 790.72, "end": 794.4, "text": "ki\\u1ebfn tr\\u00fac n\\u00e0y, v\\u1eady h\\u00e3y c\\u00f9ng xem x\\u00e9t ki\\u1ebfn tr\\u00fac"}, {"index": 183, "start": 794.4, "end": 797.84, "text": "b\\u1ea1n b\\u1eaft \\u0111\\u1ea7u v\\u1edbi m\\u1ed9t b\\u1ee9c \\u1ea3nh v\\u00e0 r\\u1ed3i hai l\\u1edbp \\u0111\\u1ea7u ti\\u00ean"}, {"index": 184, "start": 797.84, "end": 804.48, "text": "l\\u00e0 c\\u00e1c ph\\u00e9p bi\\u1ebfn \\u0111\\u1ed5i, do \\u0111\\u00f3 l\\u00e0 nh\\u1eefng b\\u1ed9 l\\u1ecdc ba tr\\u00ean ba"}, {"index": 185, "start": 804.48, "end": 808.32, "text": "v\\u00e0 sau \\u0111\\u00f3 \\u1edf hai l\\u1edbp \\u0111\\u1ea7u ti\\u00ean b\\u1ea1n s\\u1eed d\\u1ee5ng 64 b\\u1ed9 l\\u1ecdc \\u0111\\u1ec3 b\\u1ea1n c\\u00f3 \\u0111\\u01b0\\u1ee3c"}, {"index": 186, "start": 808.32, "end": 811.44, "text": "m\\u1ed9t k\\u00edch th\\u01b0\\u1edbc 224 tr\\u00ean 224 v\\u00ec b\\u1ea1n \\u0111ang s\\u1eed d\\u1ee5ng"}, {"index": 187, "start": 811.44, "end": 815.92, "text": "c\\u00e1c ph\\u00e9p bi\\u1ebfn \\u0111\\u1ed5i gi\\u1ed1ng nhau v\\u00e0 sau \\u0111\\u00f3 v\\u1edbi 64 k\\u00eanh"}, {"index": 188, "start": 815.92, "end": 819.2, "text": "v\\u00ec vgg 16 l\\u00e0 m\\u1ed9t m\\u1ea1ng t\\u01b0\\u01a1ng \\u0111\\u1ed1i s\\u00e2u"}, {"index": 189, "start": 819.2, "end": 823.76, "text": "t\\u00f4i s\\u1ebd kh\\u00f4ng v\\u1ebd t\\u1ea5t c\\u1ea3 c\\u00e1c th\\u1ec3 t\\u00edch \\u1edf \\u0111\\u00e2y v\\u00ec h\\u00ecnh \\u1ea3nh nh\\u1ecf n\\u00e0y"}, {"index": 190, "start": 823.76, "end": 827.6, "text": "\\u0111\\u01b0\\u1ee3c ch\\u1ec9 \\u0111\\u1ecbnh l\\u00e0 nh\\u1eefng g\\u00ec tr\\u01b0\\u1edbc \\u0111\\u00e2y ch\\u00fang ta \\u0111\\u00e3 v\\u1ebd nh\\u01b0 th\\u1ebf n\\u00e0y"}, {"index": 191, "start": 827.6, "end": 834.32, "text": "224 x 224 x 3 v\\u00e0 sau \\u0111\\u00f3 l\\u00e0 m\\u1ed9t ph\\u00e9p t\\u00ednh t\\u00edch ch\\u1eadp d\\u1eabn \\u0111\\u1ebfn"}, {"index": 192, "start": 834.32, "end": 840.56, "text": "T\\u00f4i \\u0111o\\u00e1n l\\u00e0 224 x 224 x 64 n\\u00ean s\\u1ebd \\u0111\\u01b0\\u1ee3c v\\u1ebd nh\\u01b0 m\\u1ed9t kh\\u1ed1i s\\u00e2u h\\u01a1n"}, {"index": 193, "start": 840.56, "end": 847.28, "text": "v\\u00e0 sau \\u0111\\u00f3 l\\u00e0 m\\u1ed9t l\\u1edbp kh\\u00e1c d\\u1eabn \\u0111\\u1ebfn b\\u1ea1n bi\\u1ebft \\u0111\\u1ea5y 224 x 224 x 64"}, {"index": 194, "start": 847.28, "end": 852.0, "text": "v\\u00ec v\\u1eady c\\u00e1i conv64 nh\\u00e2n 2 n\\u00e0y \\u0111\\u1ea1i di\\u1ec7n cho vi\\u1ec7c b\\u1ea1n \\u0111ang th\\u1ef1c hi\\u1ec7n"}, {"index": 195, "start": 852.0, "end": 855.68, "text": "hai l\\u1edbp, hai l\\u1edbp t\\u00edch ch\\u1eadp v\\u1edbi 64 b\\u1ed9 l\\u1ecdc"}, {"index": 196, "start": 855.68, "end": 859.36, "text": "v\\u00e0 nh\\u01b0 t\\u00f4i \\u0111\\u00e3 \\u0111\\u1ec1 c\\u1eadp tr\\u01b0\\u1edbc \\u0111\\u00f3, c\\u00e1c b\\u1ed9 l\\u1ecdc lu\\u00f4n"}, {"index": 197, "start": 859.36, "end": 863.12, "text": "c\\u00f3 k\\u00edch th\\u01b0\\u1edbc ba tr\\u00ean ba v\\u1edbi b\\u01b0\\u1edbc nh\\u1ea3y b\\u1eb1ng m\\u1ed9t v\\u00e0 ch\\u00fang lu\\u00f4n"}, {"index": 198, "start": 863.12, "end": 866.64, "text": "c\\u00f3 nh\\u1eefng \\u0111\\u00f3ng g\\u00f3p gi\\u1ed1ng nhau, v\\u00ec v\\u1eady thay v\\u00ec v\\u1ebd t\\u1ea5t c\\u1ea3 nh\\u1eefng th\\u1ec3 t\\u00edch n\\u00e0y, t\\u00f4i ch\\u1ec9"}, {"index": 199, "start": 866.64, "end": 871.6, "text": "s\\u1eed d\\u1ee5ng v\\u0103n b\\u1ea3n \\u0111\\u1ec3 \\u0111\\u1ea1i di\\u1ec7n cho m\\u1ea1ng n\\u00e0y, ti\\u1ebfp theo, n\\u00f3 s\\u1eed d\\u1ee5ng m\\u1ed9t l\\u1edbp pooling"}, {"index": 200, "start": 871.6, "end": 875.68, "text": "v\\u00ec v\\u1eady, l\\u1edbp pooling s\\u1ebd gi\\u1ea3m v\\u00e0 h\\u00e3y ngh\\u0129 v\\u1ec1 vi\\u1ec7c n\\u00f3 \\u0111i t\\u1eeb 224 x 224"}, {"index": 201, "start": 875.68, "end": 880.88, "text": "gi\\u1ea3m xu\\u1ed1ng c\\u00e1i g\\u00ec \\u0111\\u00fang t\\u01b0\\u01a1ng \\u1ee9ng v\\u1edbi 112 tr\\u00ean 112 tr\\u00ean 64"}, {"index": 202, "start": 880.88, "end": 886.8, "text": "v\\u00e0 sau \\u0111\\u00f3 n\\u00f3 c\\u00f3 th\\u00eam m\\u1ed9t v\\u00e0i l\\u1edbp t\\u00edch ch\\u1eadp n\\u1eefa, \\u0111i\\u1ec1u n\\u00e0y c\\u00f3 ngh\\u0129a l\\u00e0 n\\u00f3 c\\u00f3 m\\u1ed9t"}, {"index": 203, "start": 886.8, "end": 890.48, "text": "128 b\\u1ed9 l\\u1ecdc v\\u00e0 v\\u00ec \\u0111\\u00e2y l\\u00e0 nh\\u1eefng ph\\u00e9p t\\u00edch ch\\u1eadp gi\\u1ed1ng nhau"}, {"index": 204, "start": 890.48, "end": 893.6, "text": "h\\u00e3y xem k\\u00edch th\\u01b0\\u1edbc m\\u1edbi s\\u1ebd l\\u00e0 g\\u00ec, \\u0111\\u00fang kh\\u00f4ng, n\\u00f3 s\\u1ebd l\\u00e0"}, {"index": 205, "start": 893.6, "end": 898.64, "text": "112 x 112 x 128 \\u00b5m v\\u00e0 sau \\u0111\\u00f3 l\\u00e0 l\\u1edbp pooling"}, {"index": 206, "start": 898.64, "end": 902.16, "text": "v\\u00ec v\\u1eady b\\u1ea1n c\\u00f3 th\\u1ec3 t\\u00ecm ra chi\\u1ec1u m\\u1edbi \\u0111\\u00fang r\\u1eb1ng n\\u00f3 s\\u1ebd l\\u00e0 nh\\u01b0 th\\u1ebf n\\u00e0o"}, {"index": 207, "start": 902.16, "end": 907.36, "text": "v\\u00e0 b\\u00e2y gi\\u1edd l\\u00e0 ba l\\u1edbp t\\u00edch ch\\u1eadp v\\u1edbi b\\u1ed9 l\\u1ecdc 256 k\\u00edch th\\u01b0\\u1edbc"}, {"index": 208, "start": 907.36, "end": 912.48, "text": "256 b\\u1ed9 l\\u1ecdc, xin l\\u1ed7i, sau \\u0111\\u00f3 l\\u00e0 m\\u1ed9t l\\u1edbp gi\\u1ea3m d\\u1ea7n v\\u00e0 sau \\u0111\\u00f3"}, {"index": 209, "start": 912.48, "end": 919.44, "text": "th\\u00eam m\\u1ed9t v\\u00e0i l\\u1edbp t\\u00edch ch\\u1eadp, l\\u1edbp gi\\u1ea3m d\\u1ea7n, \\u1eeb, th\\u00eam nhi\\u1ec1u l\\u1edbp t\\u00edch ch\\u1eadp, l\\u1edbp gi\\u1ea3m d\\u1ea7n"}, {"index": 210, "start": 919.44, "end": 924.88, "text": "v\\u00e0 sau \\u0111\\u00f3 n\\u00f3 l\\u1ea5y, uh, con s\\u1ed1 cu\\u1ed1i c\\u00f9ng l\\u00e0 b\\u1ea3y nh\\u00e2n b\\u1ea3y nh\\u00e2n n\\u0103m 12"}, {"index": 211, "start": 924.88, "end": 928.08, "text": "cung c\\u1ea5p n\\u00f3 cho m\\u1ed9t l\\u1edbp k\\u1ebft n\\u1ed1i ho\\u00e0n to\\u00e0n, ho\\u00e0n to\\u00e0n k\\u1ebft n\\u1ed1i"}, {"index": 212, "start": 928.08, "end": 934.0, "text": "v\\u1edbi 4996 \\u0111\\u01a1n v\\u1ecb v\\u00e0 sau \\u0111\\u00f3 l\\u00e0 \\u0111\\u1ea7u ra softmax, m\\u1ed9t trong m\\u1ed9t ng\\u00e0n"}, {"index": 213, "start": 934.0, "end": 939.92, "text": "c\\u00e1c l\\u1edbp, v\\u00e0 nh\\u00e2n ti\\u1ec7n, con s\\u1ed1 16 trong t\\u00ean vg16"}, {"index": 214, "start": 939.92, "end": 943.68, "text": "\\u0111\\u1ec1 c\\u1eadp \\u0111\\u1ebfn th\\u1ef1c t\\u1ebf l\\u00e0 m\\u1ea1ng n\\u00e0y c\\u00f3 16 l\\u1edbp c\\u00f3"}, {"index": 215, "start": 943.68, "end": 947.68, "text": "tr\\u1ecdng s\\u1ed1, um, v\\u00e0 \\u0111\\u00e2y l\\u00e0 m\\u1ed9t m\\u1ea1ng kh\\u00e1 l\\u1edbn, m\\u1ea1ng n\\u00e0y"}, {"index": 216, "start": 947.68, "end": 952.56, "text": "c\\u00f3 t\\u1ed5ng c\\u1ed9ng kho\\u1ea3ng 138 tri\\u1ec7u tham s\\u1ed1"}, {"index": 217, "start": 952.56, "end": 955.68, "text": "v\\u00e0 \\u0111\\u00f3 l\\u00e0 kh\\u00e1 l\\u1edbn ngay c\\u1ea3 theo ti\\u00eau chu\\u1ea9n hi\\u1ec7n \\u0111\\u1ea1i"}, {"index": 218, "start": 955.68, "end": 959.28, "text": "nh\\u01b0ng s\\u1ef1 \\u0111\\u01a1n gi\\u1ea3n c\\u1ee7a ki\\u1ebfn tr\\u00fac vg16"}, {"index": 219, "start": 959.28, "end": 963.28, "text": "khi\\u1ebfn n\\u00f3 tr\\u1edf n\\u00ean kh\\u00e1 h\\u1ea5p d\\u1eabn, b\\u1ea1n c\\u00f3 th\\u1ec3 th\\u1ea5y r\\u1eb1ng ki\\u1ebfn tr\\u00fac n\\u00e0y th\\u1ef1c s\\u1ef1 kh\\u00e1"}, {"index": 220, "start": 963.28, "end": 967.92, "text": "\\u0110\\u1ed3ng nh\\u1ea5t c\\u00f3 m\\u1ed9t v\\u00e0i l\\u1edbp t\\u00edch ch\\u1eadp \\u0111\\u01b0\\u1ee3c theo sau b\\u1edfi m\\u1ed9t l\\u1edbp l\\u1ea5y m\\u1eabu, l\\u1edbp n\\u00e0y gi\\u1ea3m"}, {"index": 221, "start": 967.92, "end": 972.16, "text": "chi\\u1ec1u cao v\\u00e0 chi\\u1ec1u r\\u1ed9ng \\u0111\\u00fang kh\\u00f4ng, v\\u00ec v\\u1eady c\\u00e1c l\\u1edbp l\\u1ea5y m\\u1eabu gi\\u1ea3m \\u0111i"}, {"index": 222, "start": 972.16, "end": 975.76, "text": "chi\\u1ec1u cao v\\u00e0 chi\\u1ec1u r\\u1ed9ng b\\u1ea1n c\\u00f3 m\\u1ed9t v\\u00e0i \\u1edf \\u0111\\u00e2y"}, {"index": 223, "start": 975.76, "end": 978.96, "text": "nh\\u01b0ng sau \\u0111\\u00f3 n\\u1ebfu b\\u1ea1n nh\\u00ecn v\\u00e0o s\\u1ed1 l\\u01b0\\u1ee3ng b\\u1ed9 l\\u1ecdc"}, {"index": 224, "start": 978.96, "end": 982.48, "text": "trong c\\u00e1c l\\u1edbp t\\u00edch ch\\u1eadp \\u1edf \\u0111\\u00e2y b\\u1ea1n c\\u00f3 64 b\\u1ed9 l\\u1ecdc"}, {"index": 225, "start": 982.48, "end": 989.36, "text": "v\\u00e0 sau \\u0111\\u00f3 b\\u1ea1n g\\u1ea5p \\u0111\\u00f4i 128 th\\u00e0nh 256, g\\u1ea5p \\u0111\\u00f4i th\\u00e0nh 512, v\\u00e0 sau \\u0111\\u00f3 t\\u00f4i \\u0111o\\u00e1n r\\u1eb1ng"}, {"index": 226, "start": 989.36, "end": 993.2, "text": "t\\u00e1c gi\\u1ea3 ngh\\u0129 r\\u1eb1ng 512 l\\u00e0 \\u0111\\u1ee7 l\\u1edbn v\\u00e0 kh\\u00f4ng g\\u1ea5p \\u0111\\u00f4i l\\u1ee3i nhu\\u1eadn \\u1edf \\u0111\\u00e2y"}, {"index": 227, "start": 993.2, "end": 996.64, "text": "nh\\u01b0ng \\u0111i\\u1ec1u n\\u00e0y, b\\u1ea1n bi\\u1ebft \\u0111\\u1ea5y, ki\\u1ec3u nh\\u01b0 l\\u00e0 g\\u1ea5p \\u0111\\u00f4i m\\u1ed9t c\\u00e1ch \\u0111\\u1ea1i kh\\u00e1i \\u1edf m\\u1ed7i b\\u01b0\\u1edbc"}, {"index": 228, "start": 996.64, "end": 1000.56, "text": "ho\\u1eb7c g\\u1ea5p \\u0111\\u00f4i qua m\\u1ed7i t\\u1ea7ng c\\u1ee7a c\\u00e1c l\\u1edbp t\\u00edch ch\\u1eadp l\\u00e0 m\\u1ed9t nguy\\u00ean t\\u1eafc"}, {"index": 229, "start": 1000.56, "end": 1005.04, "text": "\\u0111\\u01a1n gi\\u1ea3n \\u0111\\u01b0\\u1ee3c s\\u1eed d\\u1ee5ng \\u0111\\u1ec3 thi\\u1ebft k\\u1ebf ki\\u1ebfn tr\\u00fac c\\u1ee7a m\\u1ea1ng n\\u00e0y"}, {"index": 230, "start": 1005.04, "end": 1009.52, "text": "v\\u00e0 v\\u00ec v\\u1eady t\\u00f4i ngh\\u0129 r\\u1eb1ng s\\u1ef1 \\u0111\\u1ed3ng nh\\u1ea5t t\\u01b0\\u01a1ng \\u0111\\u1ed1i c\\u1ee7a ki\\u1ebfn tr\\u00fac n\\u00e0y"}, {"index": 231, "start": 1009.52, "end": 1014.16, "text": "\\u0111\\u00e3 khi\\u1ebfn n\\u00f3 tr\\u1edf n\\u00ean kh\\u00e1 h\\u1ea5p d\\u1eabn \\u0111\\u1ed1i v\\u1edbi c\\u00e1c nh\\u00e0 nghi\\u00ean c\\u1ee9u, nh\\u01b0\\u1ee3c \\u0111i\\u1ec3m ch\\u00ednh l\\u00e0"}, {"index": 232, "start": 1014.16, "end": 1017.76, "text": "n\\u00f3 l\\u00e0 m\\u1ed9t m\\u1ea1ng l\\u01b0\\u1edbi l\\u1edbn v\\u1ec1 s\\u1ed1 l\\u01b0\\u1ee3ng tham s\\u1ed1 m\\u00e0 b\\u1ea1n ph\\u1ea3i"}, {"index": 233, "start": 1017.76, "end": 1021.28, "text": "\\u0111\\u00e0o t\\u1ea1o, \\u00f4i v\\u00e0 n\\u1ebfu b\\u1ea1n \\u0111\\u1ecdc t\\u00e0i li\\u1ec7u, b\\u1ea1n"}, {"index": 234, "start": 1021.28, "end": 1024.96, "text": "\\u0111\\u00f4i khi th\\u1ea5y m\\u1ecdi ng\\u01b0\\u1eddi n\\u00f3i v\\u1ec1 vgg19, \\u0111\\u00f3 l\\u00e0 m\\u1ed9t"}, {"index": 235, "start": 1024.96, "end": 1030.8, "text": "phi\\u00ean b\\u1ea3n l\\u1edbn h\\u01a1n c\\u1ee7a m\\u1ea1ng l\\u01b0\\u1edbi n\\u00e0y v\\u00e0 b\\u1ea1n c\\u00f3 th\\u1ec3 th\\u1ea5y chi ti\\u1ebft trong"}, {"index": 236, "start": 1030.8, "end": 1034.64, "text": "b\\u00e0i b\\u00e1o \\u0111\\u01b0\\u1ee3c tr\\u00edch d\\u1eabn \\u1edf d\\u01b0\\u1edbi b\\u1edfi Karen Simerian v\\u00e0 Andrew"}, {"index": 237, "start": 1034.64, "end": 1040.8, "text": "Zisserman nh\\u01b0ng v\\u00ec vgg16 ho\\u1ea1t \\u0111\\u1ed9ng g\\u1ea7n nh\\u01b0 t\\u1ed1t nh\\u01b0 vgg19"}, {"index": 238, "start": 1040.8, "end": 1046.0, "text": "n\\u00ean nhi\\u1ec1u ng\\u01b0\\u1eddi s\\u1ebd s\\u1eed d\\u1ee5ng vgg16, nh\\u01b0ng \\u0111i\\u1ec1u t\\u00f4i th\\u00edch nh\\u1ea5t v\\u1ec1 \\u0111i\\u1ec1u n\\u00e0y l\\u00e0"}, {"index": 239, "start": 1046.0, "end": 1051.12, "text": "\\u0111i\\u1ec1u n\\u00e0y t\\u1ea1o ra m\\u00f4 h\\u00ecnh r\\u1eb1ng khi b\\u1ea1n \\u0111i s\\u00e2u h\\u01a1n, chi\\u1ec1u cao v\\u00e0 chi\\u1ec1u r\\u1ed9ng gi\\u1ea3m \\u0111i."}, {"index": 240, "start": 1051.12, "end": 1054.64, "text": "ch\\u1ec9 gi\\u1ea3m \\u0111i m\\u1ed9t n\\u1eeda m\\u1ed7i l\\u1ea7n cho c\\u00e1c l\\u1edbp g\\u1ed9p"}, {"index": 241, "start": 1054.64, "end": 1059.44, "text": "trong khi s\\u1ed1 l\\u01b0\\u1ee3ng k\\u00eanh t\\u0103ng l\\u00ean v\\u00e0 \\u1edf \\u0111\\u00e2y b\\u1ea1n bi\\u1ebft n\\u00f3 t\\u0103ng l\\u00ean kho\\u1ea3ng"}, {"index": 242, "start": 1059.44, "end": 1062.16, "text": "m\\u1ed9t y\\u1ebfu t\\u1ed1 hai m\\u1ed7i khi b\\u1ea1n c\\u00f3 m\\u1ed9t b\\u1ed9 m\\u1edbi"}, {"index": 243, "start": 1062.16, "end": 1066.56, "text": "c\\u00e1c l\\u1edbp conv, v\\u00ec v\\u1eady b\\u1eb1ng c\\u00e1ch l\\u00e0m cho t\\u1ef7 l\\u1ec7 m\\u00e0 nh\\u1eefng c\\u00e1i n\\u00e0y"}, {"index": 244, "start": 1066.56, "end": 1071.04, "text": "gi\\u1ea3m xu\\u1ed1ng v\\u00e0 c\\u00e1i \\u0111\\u00f3 t\\u0103ng l\\u00ean r\\u1ea5t c\\u00f3 h\\u1ec7 th\\u1ed1ng, t\\u00f4i ngh\\u0129 b\\u00e0i b\\u00e1o n\\u00e0y r\\u1ea5t"}, {"index": 245, "start": 1071.04, "end": 1074.64, "text": "r\\u1ea5t h\\u1ea5p d\\u1eabn t\\u1eeb g\\u00f3c \\u0111\\u1ed9 \\u0111\\u00f3"}, {"index": 246, "start": 1074.64, "end": 1078.64, "text": "v\\u1eady l\\u00e0 \\u0111\\u1ee7 cho ba ki\\u1ebfn tr\\u00fac c\\u1ed5 \\u0111i\\u1ec3n, n\\u1ebfu b\\u1ea1n mu\\u1ed1n, b\\u1ea1n n\\u00ean"}, {"index": 247, "start": 1078.64, "end": 1082.4, "text": "th\\u1ef1c s\\u1ef1 \\u0111\\u1ecdc m\\u1ed9t s\\u1ed1 b\\u00e0i b\\u00e1o n\\u00e0y, t\\u00f4i khuy\\u00ean b\\u1ea1n n\\u00ean b\\u1eaft \\u0111\\u1ea7u v\\u1edbi b\\u00e0i b\\u00e1o alex"}, {"index": 248, "start": 1082.4, "end": 1085.76, "text": "net, ti\\u1ebfp theo l\\u00e0 b\\u00e0i b\\u00e1o vgg net v\\u00e0 sau \\u0111\\u00f3 l\\u00e0"}, {"index": 249, "start": 1085.76, "end": 1088.96, "text": "b\\u00e0i b\\u00e1o net th\\u00ec h\\u01a1i kh\\u00f3 \\u0111\\u1ecdc nh\\u01b0ng \\u0111\\u00e2y l\\u00e0 m\\u1ed9t t\\u00e1c ph\\u1ea9m kinh \\u0111i\\u1ec3n t\\u1ed1t m\\u00e0 b\\u1ea1n mu\\u1ed1n"}, {"index": 250, "start": 1088.96, "end": 1092.4, "text": "nh\\u00ecn v\\u00e0o, nh\\u01b0ng ti\\u1ebfp theo h\\u00e3y \\u0111i xa h\\u01a1n nh\\u1eefng ki\\u1ebfn tr\\u00fac c\\u1ed5 \\u0111i\\u1ec3n n\\u00e0y,"}, {"index": 251, "start": 1092.4, "end": 1096.08, "text": "v\\u00e0 nh\\u00ecn v\\u00e0o m\\u1ed9t s\\u1ed1 ki\\u1ebfn tr\\u00fac m\\u1ea1ng m\\u1edbi ti\\u00ean ti\\u1ebfn h\\u01a1n, m\\u1ea1nh m\\u1ebd h\\u01a1n"}, {"index": 252, "start": 1096.08, "end": 1100.56, "text": "h\\u00e3y ti\\u1ebfp t\\u1ee5c sang video ti\\u1ebfp theo"}]}}, "summary": ["- Video gi\\u1edbi thi\\u1ec7u ki\\u1ebfn tr\\u00fac m\\u1ea1ng n\\u01a1-ron c\\u1ed5 \\u0111i\\u1ec3n, b\\u1eaft \\u0111\\u1ea7u t\\u1eeb Net5, sau \\u0111\\u00f3 l\\u00e0 AlexNet v\\u00e0 VGNet.", "- Net5 nh\\u1eadn di\\u1ec7n ch\\u1eef s\\u1ed1 vi\\u1ebft tay v\\u1edbi h\\u00ecnh \\u1ea3nh k\\u00edch th\\u01b0\\u1edbc 32 x 32 x 1, hu\\u1ea5n luy\\u1ec7n tr\\u00ean h\\u00ecnh \\u1ea3nh \\u0111en tr\\u1eafng.", "- S\\u1eed d\\u1ee5ng 6 b\\u1ed9 l\\u1ecdc 5 x 5 \\u0111\\u1ec3 gi\\u1ea3m k\\u00edch th\\u01b0\\u1edbc h\\u00ecnh \\u1ea3nh xu\\u1ed1ng c\\u00f2n 28 x 28 x 6.", "- \\u00c1p d\\u1ee5ng l\\u1ea5y m\\u1eabu trung b\\u00ecnh, l\\u00e0m k\\u00edch th\\u01b0\\u1edbc gi\\u1ea3m xu\\u1ed1ng c\\u00f2n 14 x 14 x 6.", "- Ti\\u1ebfp t\\u1ee5c v\\u1edbi l\\u1edbp convolutional kh\\u00e1c s\\u1eed d\\u1ee5ng 16 b\\u1ed9 l\\u1ecdc, gi\\u1ea3m k\\u00edch th\\u01b0\\u1edbc xu\\u1ed1ng c\\u00f2n 10 x 10.", "- L\\u1edbp pooling k\\u1ebf ti\\u1ebfp gi\\u1ea3m k\\u00edch th\\u01b0\\u1edbc xu\\u1ed1ng c\\u00f2n 5 x 5 x 16, t\\u1ed5ng s\\u1ed1 node l\\u00e0 400.", "- C\\u00f3 hai l\\u1edbp k\\u1ebft n\\u1ed1i ho\\u00e0n to\\u00e0n v\\u1edbi t\\u1ed5ng s\\u1ed1 kho\\u1ea3ng 60.000 tham s\\u1ed1.", "- S\\u1ed1 tham s\\u1ed1 c\\u1ee7a Net5 nh\\u1ecf h\\u01a1n nhi\\u1ec1u so v\\u1edbi c\\u00e1c m\\u1ea1ng hi\\u1ec7n nay (th\\u01b0\\u1eddng t\\u1eeb 10 tri\\u1ec7u \\u0111\\u1ebfn 100 tri\\u1ec7u tham s\\u1ed1).", "- Chi\\u1ec1u cao v\\u00e0 chi\\u1ec1u r\\u1ed9ng h\\u00ecnh \\u1ea3nh gi\\u1ea3m d\\u1ea7n, trong khi s\\u1ed1 k\\u00eanh t\\u0103ng l\\u00ean khi \\u0111i s\\u00e2u v\\u00e0o m\\u1ea1ng.", "- S\\u1eafp x\\u1ebfp c\\u00e1c l\\u1edbp th\\u01b0\\u1eddng l\\u00e0 l\\u1edbp convolutional theo sau b\\u1edfi l\\u1edbp pooling v\\u00e0 c\\u00e1c l\\u1edbp k\\u1ebft n\\u1ed1i \\u0111\\u1ea7y \\u0111\\u1ee7.", "- M\\u1ed9t s\\u1ed1 th\\u00f4ng tin n\\u00e2ng cao c\\u00f3 trong slide cu\\u1ed1i c\\u00f9ng cho nh\\u1eefng ai mu\\u1ed1n t\\u00ecm hi\\u1ec3u th\\u00eam v\\u1ec1 b\\u00e0i b\\u00e1o kinh \\u0111i\\u1ec3n."], "timeline": [{"time": "00:00", "title": "Gi\\u1edbi thi\\u1ec7u v\\u1ec1 ki\\u1ebfn tr\\u00fac m\\u1ea1ng n\\u01a1-ron c\\u1ed5 \\u0111i\\u1ec3n"}, {"time": "00:08", "title": "Chi ti\\u1ebft v\\u1ec1 ki\\u1ebfn tr\\u00fac Net5"}, {"time": "03:11", "title": "So s\\u00e1nh v\\u1edbi m\\u1ea1ng n\\u01a1-ron hi\\u1ec7n \\u0111\\u1ea1i"}, {"time": "04:34", "title": "Nh\\u1eefng \\u0111i\\u1ec3m th\\u00fa v\\u1ecb v\\u1ec1 l\\u1ecbch s\\u1eed c\\u1ee7a Net5"}, {"time": "07:01", "title": "Gi\\u1edbi thi\\u1ec7u v\\u1ec1 AlexNet"}], "highlights": [{"time": "00:20", "reason": "M\\u1ee5c ti\\u00eau c\\u1ee7a Net5", "context": "M\\u1ee5c ti\\u00eau c\\u1ee7a Net5 l\\u00e0 nh\\u1eadn di\\u1ec7n c\\u00e1c ch\\u1eef s\\u1ed1 vi\\u1ebft tay."}, {"time": "03:34", "reason": "Tham s\\u1ed1 m\\u1ea1ng n\\u01a1-ron", "context": "M\\u1ea1ng n\\u01a1-ron n\\u00e0y nh\\u1ecf theo ti\\u00eau chu\\u1ea9n hi\\u1ec7n \\u0111\\u1ea1i, c\\u00f3 kho\\u1ea3ng 60.000 tham s\\u1ed1."}, {"time": "04:11", "reason": "Thay \\u0111\\u1ed5i trong k\\u1ebft n\\u1ed1i m\\u1ea1ng", "context": "Th\\u1eddi \\u0111\\u00f3, m\\u1ea1ng s\\u1eed d\\u1ee5ng h\\u00e0m sigmoid v\\u00e0 t